window.SPELLDATA = {"books":{"ll":{"t":"Legends & Legacies","s":"Kibbles' Compendium of Legends & Legacies"},"llb":{"t":"Legends & Legacies","s":"Kibbles' Compendium of Legends & Legacies — Blood Magic"},"cc":{"t":"Craft and Creation","s":"Kibbles' Compendium of Craft and Creation"},"retia":{"t":"Lyre's Guide to Retia","s":"Lyre's Guide to Retia — Land of Industry"}},"groups":{"Altissima-Cor’s Arcane Arts":"Crystal-born arcana out of Altissima-Cor.","Blood of Cineris":"Magic paid for in blood, after the manner of Cineris.","Chromatic Convocation":"Draconic colour magic.","Daemoturgy":"Fiend-craft — power borrowed from below.","Eidomancy":"Soul magic. Eidomancy spells hit harder than their level suggests; treat them as a tier above.","Epic of Duality":"Paired magic, working on two things at once.","Legacy of Gold":"The gilded tradition.","Nine Branch Arts":"The nine-branch school.","Ossenheimer’s Memoirs":"Spells recorded in Ossenheimer's memoirs.","Sky-Keeper’s Arcana":"Storm and sky magic of the Sky-Keepers.","Whisperwood Tome":"Spells out of the Whisperwood tome.","Skulker’s Grimoire":"Used on fourteen spells but never defined in the book's Spell Groups section.","Sky-Keeper’s Grimoire":"Printed on this one spell only, and on no other. The book's Spell Groups section defines no such group — it is most likely a misprint for Sky-Keeper's Arcana or Skulker's Grimoire, and the book does not say which."},"spells":[{"k":"sp-absorbenergy","n":"Absorb Energy","l":1,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":534,"ct":"1 reaction, which you take when you take acid, cold, fire, lightning, or thunder damage","rg":"Self","cp":"S","d":"1 round","b":[["p","The spell captures some of the incoming energy, lessening its effect on you and storing it for your next melee attack. You have resistance to the triggering damage type until the start of your next turn. Additionally, the first time you hit with a melee attack on your next turn, the target takes an extra 1d6 damage of the triggering type, and the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can choose from the following effects for to account for slot levels above 1st:"],["li","(1 slot level) The extra damage increases by 1d6."],["li","(2 slot levels) Your resistance becomes immunity instead."],["li","(3 slot levels) Your resistance becomes partial absorption instead - instead of taking damage, you gain temporary hit points equal to half the damage you take of the triggering damage type."]],"leg":1},{"k":"sp-acceleration","n":"Acceleration","l":2,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":534,"ct":"1 action","rg":"15 feet","cp":"V, S","d":"Concentration, up to 10 minutes","b":[["p","Choose one creature within range. Their movement speed increases by 30 feet. This increase is considered separately from any effects that multiply or divide a creature’s movement speed."]],"h":[["p","At Higher Levels. When this spell is cast at 3rd level or higher, you may choose one of the following effects for each slot level above 2nd:"],["li","You may choose one additional target."],["li","The movement speed of your targets increases by an extra 5 feet."]],"con":1,"g":["Sky-Keeper’s Arcana"]},{"k":"sp-acidarrow","n":"Acid Arrow","l":2,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":534,"ct":"1 action","rg":"90 feet","cp":"V, S, M (powdered rhubarb leaf and an adder’s stomach)","d":"Instantaneous","b":[["p","A shimmering green arrow streaks toward a target within range and bursts in a spray of acid. Make a ranged spell attack against the target: on a hit, the target takes 4d4 acid damage immediately and 2d4 acid damage at the end of their next turn, on a miss, the arrow splashes the target with acid for half as much of the initial damage and no damage at the end of their next turn."]],"h":[["p","At Higher Levels. When you cast this spell at 3rd level or higher, you can choose one of the following effects for each slot level above 2nd:"],["li","The initial and secondary damage increase by 1d4 each."],["li","You may choose an additional target within range."],["li","When the arrow misses and splashes for half damage, it also forces all creatures within 5 feet of its initial target to make a Dexterity saving throw, taking the same half damage on a failure."]],"leg":1},{"k":"sp-acidbubble","n":"Acid Bubble","l":1,"s":"Conjuration","sa":"CON","c":["Druid","Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":207,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You create a bubble of acid that floats to the target point before bursting in a shower of acid. Each creature and object within 5 feet must make a Dexterity saving throw. On a failure, it takes 3d4 acid damage, or half as much on a success."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 2d4 for each slot level above 1st."]],"ms":["arcane","primal"]},{"k":"sp-acidrain","n":"Acid Rain","l":5,"s":"Conjuration","sa":"CON","c":["Druid","Occultist","Spellblade","Wizard"],"bk":"ll","p":207,"ct":"1 action","rg":"300 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","Acid rain begins falling within a 40-foot-radius, 60-foot-high cylinder centered on a point you choose within range. When a creature moves into the spell’s area for the first time on a turn or starts its turn there, it must make a Dexterity saving throw. On a failure, it takes 6d4 acid damage and is covered in acid. On a success, a creature takes half the initial damage and is not covered in acid."],["p","A creature takes 3d4 acid damage if it ends its turn while covered in acid. The target or a creature within 5 feet of it can end this damage by using its action to clear away the acid."]],"con":1,"ms":["arcane","primal"],"also":[["cc",128]]},{"k":"sp-acidicpit","n":"Acidic Pit","l":3,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":207,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","You open a pit filled with acid at a point within range. Each creature within 10 feet of the point must make a Dexterity saving throw. On a failure, it falls 5 feet into a pit of acid below, taking 6d4 + 6 acid damage. On a success, a creature takes half as much damage from the flooding acid and can use its reaction to move up to its movement speed to the closest point outside of the area. If it cannot take a reaction or reach a safe space, it automatically fails its saving throw."],["p","When a creature ends its turn in the pit, it takes 2d4 acid damage. The acid in the pit remains potent for 1 minute, after which it turns to vile sludge that deals no further damage. The pit remains filled with sludge until filled or cleared."]],"ms":["arcane","primal"]},{"k":"sp-aerobarrage","n":"Aero Barrage","l":4,"s":"Transmutation","sa":"TRA","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":207,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","You create four lances of rapidly spinning condensed wind and hurl them at targets within range. You can direct the lances at one target or different ones."],["p","Make a ranged spell attack for each lance. On a hit, the target takes 2d8 slashing damage and is knocked 10 feet backwards."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you create one additional lance for each slot level above 4th."]],"ms":["arcane","primal"],"also":[["cc",128]]},{"k":"sp-aetherlance","n":"Aether Lance","l":3,"s":"Evocation","sa":"EVO","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":207,"ct":"1 action","rg":"Self (30-foot line)","cp":"V, S","d":"Instantaneous","b":[["p","You gather raw aether in your hand and expel it in a lance of power, forming a line 30 feet long and 5 feet wide. Each creature in the line takes 8d4 force damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d4 for each slot level above 3rd."]],"ms":["arcane"],"also":[["cc",128]]},{"k":"sp-aetherstorm","n":"Aether Storm","l":5,"s":"Evocation","sa":"EVO","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":208,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You conjure a storm of aether, erupting from a point of your choice within range. The aether storm fills a 10-foot radius, 40-foot-high cylinder. When the storm appears, each creature within its area takes 8d4 force damage. When a creature enters the storm or moves within it, it takes 2d4 force damage for every 5 feet it travels, and whenever a creature ends its turn in the storm it takes an additional 8d4 force damage."],["p","As a bonus action on your subsequent turns, you can move the storm up to 15 feet in any direction and cause it to fling forth a hail of force bolts that seek out up to 3 targets of your choice within 15 feet of the storm. Each target takes 3d4 + 3 force damage from the bolts."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the damage dealt when the storm is cast, when a creature ends its turn in the storm, or when a creature is struck by a force bolt increases by 1d4 for each slot level above 5th."]],"con":1,"ms":["arcane"],"also":[["cc",128]]},{"k":"sp-agitatedpulse","n":"Agitated Pulse","l":3,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":534,"ct":"1 action","rg":"Self","cp":"S","d":"Concentration, up to 1 minute","b":[["p","A swirling wave of force protects you, occupying a 5-foot radius centered on you. When a hostile creature starts their turn there or enters into that space for the first time on their turn they must make a Strength saving throw. On a failed save they are repelled to the nearest unoccupied space outside the spell’s range and take 4d6 force damage. A creature shunted this way cannot attempt to enter that area again on that turn, and if they teleport into range, get stuck within it and are unable to move, or are forced in by another effect, they are knocked prone and restrained as long as they are in it until the start of their next turn."],["p","Attacks made against you from outside your protective wave of force have disadvantage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can choose one of the following effects for each slot level above 3rd:"],["li","The radius of the wave increases by 5 feet."],["li","The spell’s force damage increases by 2d6"]],"con":1,"g":["Skulker’s Grimoire"]},{"k":"sp-alacrity","n":"Alacrity","l":2,"s":"Transmutation","sa":"TRA","c":["Bard","Occultist","Ranger","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":208,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"1 round","b":[["p","Until the start of your next turn, your speed is doubled, you gain a +2 bonus to AC, you have advantage on Dexterity saving throws, and you gain an additional action. That action can be used only to take the Attack (one weapon attack only), Dash, Disengage, Hide, or Use an Object action."],["p","If you are under the effect of haste, you gain no benefit from this spell."]],"ms":["arcane"],"also":[["cc",128]]},{"k":"sp-aldricorselementalrebuke","n":"Aldricor's Elemental Rebuke","l":1,"s":"Evocation","sa":"EVO","c":["Druid","Ranger","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":208,"ct":"1 reaction, which you take when you take acid, cold, fire, lightning, or thunder damage","rg":"Self","cp":"S","d":"Instantaneous","b":[["p","You manipulate some of the incoming elemental energy, harnessing its power in your hand. The damage you take from the triggering attack or effect is cut in half. You can then hurl the energy back at the creature that damaged you if it is within 60 feet of you. The creature must make a Dexterity saving throw, taking 1d8 damage of the triggering type on a failed save, or half as much damage on a successful one."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."],["p","TAG Credit"],["p","Aldricor's Elemental Rebuke is drawn from TheArenaGuy's"],["p","(Spectre Creations) Caliya's Chronicle of Runes."]],"ms":["arcane"]},{"k":"sp-angelicslash","n":"Angelic Slash","l":3,"s":"Evocation","sa":"EVO","c":["Cleric","Paladin"],"bk":"ll","p":208,"ct":"1 action","rg":"Self (30-foot line)","cp":"V, S","d":"Instantaneous","b":[["p","You summon a giant spectral angel that appears around you before crashing its greatsword down in a line. All creatures in a line 30 feet long and 5 feet wide in a direction of your choice must make a Dexterity saving throw. A target takes 5d8 radiant damage on a failed save, or half as much damage on a successful one. A creature takes an additional 1d8 damage if it is undead or a fiend."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each level above 3rd."]],"ms":["divine"]},{"k":"sp-angeroftheskykeeper","n":"Anger of the Sky-Keeper","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":535,"ct":"1 action","rg":"20-foot radius","cp":"V, S, M (an obsidian rod at least a foot long)","d":"Concentration, up to 1 minue","b":[["p","The area surrounding you begins to haze and crackle with red lightning. This effect spreads around you in a 20-foot radius sphere, and follows you when you move. All creatures within this space are heavily obscured, but you gain blindsight out to the edges of the effect. All ranged attacks made against you are made with disadvantage."],["p","You can use a bonus action on your turn to evoke one of the following effects:"],["li","Storm Surge. All creatures (except you) within the spell’s range are assailed by crimson lightning and must make a Dexterity saving throw, taking 3d6 lightning damage on a failed save, or half as much damage on a successful one."],["li","Lightning Spear. Lightning gathers together in your hand, and you can hurl it at a creature who is within twice the spell’s range from the center. You make a ranged spell attack against the target, who takes 3d10 lightning damage on a hit. If the creature is within the spell’s range, you have advantage on the attack roll."]],"h":[["p","At Higher Levels. When you cast this spell at 6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","The spell’s range increases by 10 feet."],["li","The damage for storm surge and lightning spear increase by 1d6 and 1d10, respectively."],["li","The number of creatures you can target with the lightning spear increases by one."],["li","If cast using a spell slot of 7th level or higher, creatures who end their turn within the spell’s sphere take damage equal to half of storm surge’s damage dice."]],"con":1,"g":["Sky-Keeper’s Arcana"]},{"k":"sp-animalcommune","n":"Animal Commune","l":1,"s":"Divination","sa":"DIV","c":[],"bk":"retia","p":534,"ct":"1 action","rg":"Touch","cp":"V, S, M (a bit of fur wrapped in a cloth)","d":"Concentration, up to 10 minutes","b":[["p","You establish a telepathic link with one beast you touch that is friendly to you or charmed by you. The spell fails if the beast’s Intelligence score is 4 or higher. Until the spell ends, the link is active while you and the beast are in line of sight of each other."],["p","53 4 Through the link, the beast can understand your telepathic messages to it, and it can telepathically communicate simple emotions and concepts back to you. While the link is active, the beast gains advantage on attack rolls against any creature within 5 feet of you that you can see."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd level or higher, you may choose one of the following effects for each slot level above 1st:"],["li","The beast gains 5 temporary hit points."],["li","(2 slot levels) You may target an additional beast within range."],["li","The spell’s duration increases each time you select this option, in order of increasing to 1 hour, 8 hours, 24 hours and 1 week."],["li","The link remains in place even if you and the beast do not have line of sight. The range of this effect is 60 feet, which doubles each time you select this option."]],"con":1,"leg":1,"g":["Whisperwood Tome"]},{"k":"sp-animateshadow","n":"Animate Shadow","l":3,"s":"Illusion","sa":"ILL","c":["Occultist"],"bk":"ll","p":208,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a smoke stained mirror)","d":"Concentration, up to 1 hour","b":[["p","Targeting a creature you can see within range, you bring its shadow to life under your control. If the creature has a challenge rating above 3 or has no shadow (either due to its nature or from the lack of a light source to cast one) the spell fails. Creatures without a challenge rating are immune to this spell."],["p","Otherwise, a copy of the creature is created using its game statistics in a space adjacent to the creature (on the opposite side as the nearest bright light). The shadow has no legendary actions, legendary resistance, and cannot cast spells. The shadow has hit points equal to half the target’s hit points, and it looks like a mirrored version of the creature it was summoned from, formed from inky black smoke. The shadow is resistant to bludgeoning, piercing, and slashing damage from non-magical sources while in darkness. The shadow is vulnerable to all damage while in bright light, and always vulnerable to fire, lightning, and radiant damage. If the shadow is killed, the target creature it was summoned from casts no shadows for the next 8 hours."],["p","The shadow acts immediately after the target's turn, and without further direction it attempts to follow and takes the Attack action against the target. As a reaction to the shadow starting its turn, you can exert control over it and cause it to move and take its action as you direct."]],"h":[["p","At Higher Levels. When you cast this spell using a 5th- or 6th-level spell slot, the maximum challenge rating of the target increases to 4. When you cast it using a 7th- or 8th-level spell slot, the maximum challenge rating increases to 5. When you cast it using a 9th-level spell slot, the maximum challenge rating increases to CR 6."]],"con":1,"ms":["arcane"]},{"k":"sp-antigravityzone","n":"Antigravity Zone","l":1,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":535,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","Choose a point you can see within range. From that point expands a 15-foot radius sphere that remains for the spell’s duration. The area within this sphere is treated as a zero-gravity environment or a low-gravity environment (you choose when casting the spell)."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd level or higher, you can choose one of the following for each slot level above 1st:"],["li","The radius of the sphere doubles in order of 30 feet (2nd), 60 feet (3rd), 120 feet (4th), 240 feet (5th), 480 feet (6th), 960 feet (7th), 1920 feet (8th), 3840 feet (9th)."],["li","The spell’s duration increases in order of 1 hour, 10 hours, 1 day, 30 days, 1 year, permanent."],["li","The spell does not require concentration, and you can end it at any time as an action."],["li","You can choose one additional point within range to create an additional antigravity bubble, from which another sphere emerges. Each time this effect is used the radius of each individual sphere is halved (rounded up to the nearest increment of 10 feet)."]],"con":1,"rit":1},{"k":"sp-anvildrop","n":"Anvil Drop","l":5,"s":"Conjuration","sa":"CON","c":["Spellblade","Wizard"],"bk":"ll","p":209,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"1 round","b":[["p","You conjure an anvil 500 feet above a point you can see. At initiative count 0 (losing ties) on the next round, the anvil hits the ground. Each creature within 5 feet of the target point must make a Dexterity saving throw. On a success, it moves to the closest unoccupied space outside of the radius. If no space is available or a creature cannot move, it automatically fails. On a failure, a creature takes 10d10 + 10 bludgeoning damage. Creatures within 20 feet of the target point take 4d4 thunder damage."],["p","If the path of the anvil (directly above the target point) is interrupted, the creature or object above it is hit first. If the creature or object is killed or destroyed, the anvil continues, though the damage dealt is subtracted from the final impact damage of the anvil."],["p","If the anvil deals less than 80 damage, the anvil survives the impact, and is an anvil of moderate quality."]],"h":[["p","At Higher Levels. When cast with a 9th-level spell slot, the range of the spell becomes 120 miles, though you must still be able to see the target (such as via scrying)."]],"ms":["arcane"]},{"k":"sp-aphrisfixedgaze","n":"Aphris’ Fixed Gaze","l":4,"s":"Divination","sa":"DIV","c":[],"bk":"retia","p":535,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a small silver locket)","d":"Concentration, up to 1 day","b":[["p","You become fixated on any creatures you choose within range as long as you can see them. Until the spell ends, you always know the direction of and distance to those creatures, and if they are within 120 feet you can sense their exact location. Those creatures cannot benefit from the effects of invisibility or hiding against you."],["p","If you choose only one target, in addition to this spell’s usual effects they must make a Charisma saving throw. On a failure, they become cursed by your adoration for the spell’s duration. Until the spell ends, all attack rolls and saving throws you make against them have advantage, and no effects or conditions can give you disadvantage on those rolls."]],"con":1},{"k":"sp-arbitraryadaptation","n":"Arbitrary Adaptation","l":4,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":535,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You and up to three other creatures of your choice within the spell’s range gain a +1 bonus to their armor class and saving throws against one creature you designate within 120 feet - the bodies and instincts of the selected creatures specifically adapt to the movements and weaponry of that target. Each creature may choose to use their reaction to end this effect on themselves when the target hits them with a weapon attack or they fail a saving throw against the target. If they do so, they may roll a d20 and replace the attack roll/saving throw’s d20 result with whichever would be more beneficial for them"]],"h":[["p","At Higher Levels. When you cast this spell at 5th-level or higher, you can pick one of the following effects for each slot level above 4th:"],["li","The bonus to the target’s armor class increases by 1. Every two times this option is selected, the bonus to their saving throws increases by 1 as well."],["li","You can target one additional creature to benefit from this spell’s protective effects."],["li","You can choose one additional target for this spell’s protection to grant its bonuses against."]],"con":1,"g":["Blood of Cineris"]},{"k":"sp-arcanaabjurative","n":"Arcana Abjurative","l":3,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":536,"ct":"1 action","rg":"10 feet","cp":"V, S, M (a spell scroll containing a spell of 3rd level or higher, which this spell consumes)","d":"1 hour","b":[["p","Choose one creature within the spell’s range: for the spell’s duration they have advantage on saving throws against spells and magical effects."]],"h":[["p","At Higher Levels. When you cast this spell at 4th-level or higher, you can choose one additional creature within range for each slot level above 3rd."]],"g":["Sky-Keeper’s Arcana"]},{"k":"sp-arcaneablation","n":"Arcane Ablation","l":1,"s":"Transmutation","sa":"TRA","c":["Inventor","Spellblade"],"bk":"ll","p":209,"ct":"1 action","rg":"Touch","cp":"V, S","d":"1 hour","b":[["p","You touch a piece of worn armor or clothing and imbue it with magic. For the duration, the wearer gains 4 temporary hit points. If these temporary hit points are exhausted, the creature gains 1 fewer temporary hit points at the start of its next turn. When the temporary hit points would reach 0, the spell ends. Temporary hit points gained from this spell are lost when the spell ends."]],"h":[["p","At Higher Levels. The initial temporary hit points increase by 1 for each slot level above 1st."]],"ms":["arcane"],"also":[["cc",129]]},{"k":"sp-arcaneconduit","n":"Arcane Conduit","l":2,"s":"Transmutation","sa":"TRA","c":["Sorcerer"],"bk":"ll","p":209,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You tap directly into the arcane weave. For the duration, you have resistance to all damage from magical sources besides force damage."],["p","At the start of each of your turns while tapped into this power, you and all creatures with 5 feet of you take 1d6 Force damage. The damage increases by 1d6 each turn to a maximum of 4d6 damage."]],"con":1,"ms":["arcane"]},{"k":"sp-arcaneinfusion","n":"Arcane Infusion","l":2,"s":"Transmutation","sa":"TRA","c":["Inventor"],"bk":"cc","p":129,"ct":"1 minute","rg":"Self","cp":"V, S, M (spare parts that could form the upgrade selected worth at least 1 sp)","d":"1 hour","b":[["p","You use arcane power to briefly bring to power or modify your inventions. For the duration, you gain the effects of one unrestricted upgrade. All normal prerequisite apply (including subclass and level requirements). The creation is magical, held together and formed of magic and spare parts, taking the form of the upgrade or empowering an existing upgrade with temporary new features. Casting this spell again ends the effects of any previous castings of this spell."]],"h":[["p","At Higher Levels. When you cast this spell with a 3rd-level spell slot or higher, you can infuse the effects of an upgrade that requires 5th level. When you cast this spell using a spell slot of 4th level or higher, you can infuse the effects of an upgrade that requires 9th level. When you cast this spell with a 5th-level spell slot or higher, you can infuse the effects of an upgrade that requires 11th level."]]},{"k":"sp-arcanelucubration","n":"Arcane Lucubration","l":2,"s":"Divination","sa":"DIV","c":[],"bk":"retia","p":536,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"1 hour","b":[["p","You recall information necessary to cast spells you don’t currently have access to. Choose two spells you are capable of preparing over a long rest but you don’t currently have prepared. For the spell’s duration, you can cast those spells as if you had prepared them."]],"h":[["p","At Higher Levels. When you cast this spell at 3rd level or higher, you can choose one additional spell to prepare for each slot level above 2nd."]],"g":["Ossenheimer’s Memoirs"]},{"k":"sp-arcaneweapon","n":"Arcane Weapon","l":1,"s":"Transmutation","sa":"TRA","c":["Inventor","Spellblade"],"bk":"ll","p":210,"ct":"1 bonus action","rg":"Touch","cp":"V, S","d":"1 hour","b":[["p","You touch a weapon and imbue it with magic. For the duration, the weapon counts as a magical weapon and all damage dealt by it becomes force damage. When you cast this on a weapon with the ammunition property, the weapon doesn't consume ammunition when fired, and does not need to be reloaded."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd or 4th level, the duration becomes 8 hours. When you use a spell slot of 5th level or higher, the duration becomes 24 hours."]],"ms":["arcane"],"also":[["cc",129]]},{"k":"sp-arcanistssword","n":"Arcanist’s Sword","l":7,"s":"Conjuration","sa":"CON","c":["Bard","Wizard"],"bk":"ll","p":210,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a miniature platinum sword with a grip and pommel of copper and zinc, worth 250 gp)","d":"1 minute","b":[["p","You create a glowing sword-shaped plane of force that hovers within range for the duration. When the sword appears and as a bonus action on subsequent turns, you can give the sword one of the following commands."],["li","Attack: The sword moves up to 20 feet toward a creature and makes a melee spell attack against it. On a hit, the target takes force damage equal to 3d10 + your spellcasting ability modifier."],["li","Guard: The sword moves up 20 feet into a creature’s space and grants the creature half cover as it attempts to deflect incoming attacks. The first time a hostile creature comes within 5 feet of the sword, the sword makes a melee spell attack against that creature. On a hit, the target takes force damage equal to 3d10 + your spellcasting ability modifier. The sword cannot attack again until you command it again"],["li","Whirl: The sword moves up to 20 feet toward a point and then begins to spin in a deadly whirl. A"],["p","creature that starts in the sword’s space or passes within 5 feet of the sword on its turn must succeed on a Dexterity saving throw or take 3d10 force damage."],["p","Caius’ Notes: The Lost True Version The true version of an infamous wizard’s knock-off floating magic sword. Tragically, most sources of the spell list an incomplete version—presumably copied by an apprentice unable to fully understand the spell. Lesser versions of the spell require concentration and lack some key functions."]],"ms":["arcane"]},{"k":"sp-archfiendstep","n":"Archfiend Step","l":6,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":536,"ct":"1 action","rg":"50 feet","cp":"V, S, M (a small bag of charcoal dust and a single match)","d":"1 round","b":[["p","You erupt into chromatic energy, and teleport up to an unoccupied space adjacent to a creature within range, then make a melee spell attack against that target. On a hit, the creature takes 10d12 chromatic energy damage. Your body then sheds this energy, and becomes ethereal to regular weaponry until the start of your next turn, rendering you immune to piercing, slashing and bludgeoning damage that isn’t eidolic. During this time you have disadvantage on attack rolls."]],"g":["Chromatic Convocation"]},{"k":"sp-arcticaura","n":"Arctic Aura","l":3,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":210,"ct":"1 action","rg":"Self (20-foot radius)","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","For the duration you unleash a freezing aura. Any creature starting its turn within 20 feet of you must make a Constitution saving throw. On a failure, it takes 2d8 cold damage and its speed is reduced to 0 until the start of its next turn. On a success, a creature takes half as much damage and its speed halved."],["p","As a bonus action on each of your turns for the duration, you can actively control the aura, excluding a number of creatures in the area up to your spellcasting modifier from the effects until the end of your next turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each slot level above 3rd."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-arcticbreath","n":"Arctic Breath","l":1,"s":"Conjuration","sa":"CON","c":["Druid","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":210,"ct":"1 action","rg":"Self (30 foot line)","cp":"V, S","d":"Instantaneous","b":[["p","A line of freezing arctic wind 30 feet long and 5 feet wide blasts out from you in a direction of your choice. Each creature in the line must make a Dexterity saving throw. On a failure, a creature takes 2d8 cold damage and its speed is reduced by 10 feet until the end of its next turn. On a success, a creature takes half as much damage and isn't slowed."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."]],"ms":["arcane","primal"],"also":[["cc",129]]},{"k":"sp-arteminashuntingbow","n":"Artemina’s Hunting Bow","l":9,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":536,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 hour","b":[["p","You conjure into existence a longbow made of twisting vines and branches functioning as a magical longbow that only you can use for the spell’s duration. As an action on your turn (and once when you conjure the bow), you can draw the bowstring and conjure three mithril arrows, each of which you can fire at a creature within 600 feet as a ranged spell attack. On a hit, each arrow deals 4d10 piercing damage and 4d10 poison damage."],["p","The first time a creature is hit by one of these arrows on their turn, they must make a Strength saving throw. On a failure, vines erupt from the arrow and bind them in place, and the target is restrained until the spell ends. If a creature is Huge or larger, it must be hit by two arrows on the same turn before it must make the Strength save."],["p","Creatures restrained this way may attempt to escape as an action, making a Strength check against your spell DC."]],"con":1},{"k":"sp-ashcoat","n":"Ash Coat","l":0,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":536,"ct":"1 bonus action","rg":"Self","cp":"S","d":"Concentration, up to 1 minute","b":[["p","You trace a pattern of ashen Elvish characters into your skin, from which a layer of ash erupts and remains for the spell’s duration. While the ash is present, the first melee attack you make that hits a creature each turn ignites, dealing 1d6 fire damage in addition to its usual damage."],["p","The spell’s damage increases to 1d8 when you reach 5th-level, to 1d10 at 11th-level, then to 1d12 at 17th-level."],["p","53 6"]],"con":1,"g":["Blood of Cineris"]},{"k":"sp-auraofreturningglory","n":"Aura of Returning Glory","l":4,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":537,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"1 minute","b":[["p","You surround yourself in a shimmering aura of bravery, which appears as a swirling crimson fire. While you have this aura you gain the following benefits:"],["li","At the start of each of your turns, as long as you are conscious, you gain temporary hit points equal to half the damage you’ve taken since your previous turn started (rounded down). If this would be none, you gain 2d10 temporary hit points instead."],["li","You automatically succeed saving throws made to resist being frightened, charmed or stunned."],["li","When you take damage, you can choose to use your reaction to end this spell and be immune to the triggering instance of damage instead."]],"g":["Legacy of Gold"]},{"k":"sp-avalanche","n":"Avalanche","l":6,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Warlock","Wizard"],"bk":"ll","p":211,"ct":"1 action","rg":"Self (60 foot line)","cp":"V, S","d":"Instantaneous","b":[["p","You cause the earth to ripple, triggering an avalanche of rock and stone to surge forward in a line 60 feet long and 15 feet wide. The length of the line is doubled if cast on a steeply sloped surface. Each creature caught in the surging tumble of rocks must make a Dexterity saving throw. On a failure, a creature takes 6d10 bludgeoning damage and is knocked prone. On a failure by 5 or more, it is stunned until the end of its next turn, and on a failure by 10 or more it is moved to the closest free space at the end of the line created by the spell. On a successful save, a creature takes half as much damage and suffers none of the spell’s other effects."],["p","The spell creates a 15 by 15 foot area of difficult terrain at the end of the line created by the spell."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 7th level or higher, the damage increases by 1d10 for each slot level above 6th."]],"ms":["arcane","primal"]},{"k":"sp-avernatefocus","n":"Avernate Focus","l":4,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":537,"ct":"1 action","rg":"Self","cp":"V, S, M (a finely cut obsidian gemstone with Dra-conic sigils carved into it, worth at least 500 gp, which the spell consumes)","d":"Concentration, up to 8 hours","b":[["p","You strengthen your magic against effects that would dispel or counteract it. For the purposes of effects that consider the level your spells are cast at (such as dispel magic, counterspell, etc.,), your spells are treated as if they were cast at the same level as this spell plus two (maximum 9th), unless it is already higher. This does not interact with the “at higher levels” effects of spells."],["p","If you have an arcane focus that is not an artifact or legendary item, this spell puts undue stress on it. If you lose concentration on this spell due to damage or external effects, roll 1d100. On a result of 51 or higher the backlash from the spell destroys that spell focus."],["p","53 7"]],"con":1,"g":["Chromatic Convocation"]},{"k":"sp-awakenrope","n":"Awaken Rope","l":1,"s":"Transmutation","sa":"TRA","c":["Bard","Inventor","Occultist","Ranger","Wizard"],"bk":"ll","p":211,"ct":"1 action","rg":"Touch","cp":"V, S, M (10 to 60 feet of cord or rope, worth at least 1 cp)","d":"Instantaneous","b":[["p","As an action, you can touch a rope of 10 to 60 feet in length and issue it a single command, selecting from the following options."],["li","Bind. The rope attempts to bind a creature of your choice within 20 feet of you. The creature must make a Dexterity saving throw or become restrained until it is freed. A creature can use its action to make a DC 10 Strength check, freeing itself or another creature within its reach on a success. Dealing 5 slashing damage to the rope (AC 10) also frees the creature without harming it, ending the effect and destroying the rope."],["li","Fasten. The rope flies up 60 feet and ties one end of itself to an object or surface that a rope could be tied to, before becoming inanimate again, hanging from the object."],["li","Grab. The rope lashes out at an object within its length and grabs one Small or smaller object that is not being worn by a creature, pulling it back to your hand. If the object is being carried by a creature, the creature can make a Strength saving throw. On a success, the object is not pulled."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can target a chain instead of a rope. It has the same available actions, but it has a DC 15, an AC of 15, and resistance to slashing damage when taking the Bind action."],["p","When cast with a spell slot of 3rd level or higher targeting a rope, that rope is magically imbued for 1 minute, gaining an DC of 15, an AC 20, and 20 hit points."]],"ms":["arcane"],"also":[["cc",129]]},{"k":"sp-babaswalkinghut","n":"Baba’s Walking Hut","l":6,"s":"Transmutation","sa":"TRA","c":["Occultist"],"bk":"ll","p":211,"ct":"10 minutes","rg":"Touch","cp":"V, S, M (a chicken leg)","d":"24 hours","b":[["p","You touch a hut, cabin, or other building no more than 15 feet by 15 feet by 10 feet. On completion of the spell, the building grows legs large enough to support it, as well as the structural integrity needed stand and move, and becomes a gargantuan creature. It has 250 hit points, an AC of 12, and a walking speed of 20 feet. If it drops to 0 hit points, the spell ends."],["p","On your turn, you can direct it to move (no action required) and it will continue to move as directed until you direct it to stop or reaches its destination. It can take no actions, but if it walks over a Large or smaller creature, you can direct it to attempt to step on that creature, and that creature must succeed a Dexterity saving throw, or take 2d10 bludgeoning damage and be knocked prone."],["p","If you cast this spell on the same building every day for a year, the spell lasts until dispelled, or you cast it on another building."]],"ms":["primal"]},{"k":"sp-badblood","n":"Bad Blood","l":1,"s":"Necromancy","sa":"NEC","c":["Druid","Occultist","Spellblade","Warlock","Wizard"],"bk":"ll","p":212,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a piece of rotten meat)","d":"Concentration, up to 1 minute","b":[["p","You attempt to corrupt the blood of a creature you can see within range. Creatures without blood are immune to this effect. The target must make a Constitution saving throw. On a failure, it takes 1d12 poison damage and becomes poisoned for the duration."],["p","At the end of each of its turns, the target can make another Constitution saving throw. On a success, the spell ends on the target. On a failure, it takes an additional 1d4 poison damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can target an additional creature for each slot level above 2nd. All targets must be within 30 feet of each other when you target them."]],"con":1,"ms":["arcane","primal"],"also":[["cc",130]]},{"k":"sp-beamofannihilation","n":"Beam of Annihilation","l":6,"s":"Evocation","sa":"EVO","c":["Sorcerer","Wizard"],"bk":"ll","p":212,"ct":"1 action","rg":"Self (60 foot line)","cp":"S","d":"Concentration, up to 3 rounds","b":[["p","You unleash a beam of pure energy, creating a line of power 60 feet long and 10 feet wide, which persists until the start of your next turn. When you cast the spell, choose between cold, fire, force, or lightning damage for the beam. Any creature starting its turn in the beam must make a Dexterity saving throw. It takes 8d8 damage of the beam’s type on a failure or half as much on a success."],["p","While you are concentrating on this spell, your speed is 0. At the start of each of your turns, you can use your action to maintain the beam in place or redirect it, rotating it up to 90 degrees in any direction. Any creature the beam passes through completely in this rotation must succeed on a Dexterity saving throw or take 4d8 damage of the beam's type."],["p","If you do not use your action to maintain or redirect the beam, the spell ends."]],"con":1,"ms":["arcane"],"also":[["cc",130]]},{"k":"sp-becomefire","n":"Become Fire","l":2,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":212,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"1 round","b":[["p","You become a burst of elemental flames. Until the start of your next turn, you gain the following benefits:"],["li","You gain resistance to fire damage and to bludgeoning, piercing, and slashing damage from nonmagical attacks."],["li","You can move through the space of other creatures and ignore difficult terrain. The first time you enter another creature’s space on a turn, it takes 1d6 fire damage."],["li","Any time you are hit by a melee attack, the attacker takes 1d6 fire damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, it lasts for 1 additional round for each level above 2nd."]],"ms":["arcane","primal"]},{"k":"sp-becomestone","n":"Become Stone","l":2,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":212,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"1 round","b":[["p","You solidify into stone. Until the start of your next turn, you gain the following benefits."],["li","You are petrified (granting you resistance to all damage)."],["li","Your AC becomes 20."],["li","You gain 15 temporary hit points. Any remaining temporary hit points fade when the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you gain an additional 5 temporary hit points for each level above 2nd."]],"ms":["arcane","primal"]},{"k":"sp-becomewater","n":"Become Water","l":2,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":213,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"1 round","b":[["p","You become a burst of elemental water. Until the start of your next turn, you gain the following benefits."],["li","You gain resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks."],["li","You can move through the space of other creatures and ignore difficult terrain. The first time you move through a Large or smaller creature on a turn, it must succeed on a Strength saving throw or be knocked prone."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, it lasts for 1 additional round for each level above 2nd."]],"ms":["arcane","primal"]},{"k":"sp-becomewind","n":"Become Wind","l":2,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":213,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"1 round","b":[["p","You become a burst of elemental wind. Until the start of the next turn, you gain the following benefits."],["li","You gain resistance to lightning damage and bludgeoning, piercing, and slashing damage from nonmagical attacks."],["li","You gain a flying speed of 30 feet, can move through the space of other creatures, and ignore difficult terrain, but will fall if you are in the air when the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, it lasts for 1 additional round for each level above 2nd."]],"ms":["arcane","primal"]},{"k":"sp-befuddlingcurse","n":"Befuddling Curse","l":1,"s":"Enchantment","sa":"ENC","c":["Occultist"],"bk":"ll","p":213,"ct":"1 action","rg":"60 feet","cp":"V, S, M (something from the target creature—such as blood, hair, or scales—which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You befuddle a creature’s mind, causing it to believe two similarly-sized objects or creatures it can see have been swapped. The target creature must make a Wisdom saving throw. On a failure, it believes the two things have been swapped."],["p","Each time the creature interacts with, attacks, or is attacked by a swapped target, it can repeat the saving throw, ending the spell on a success."]],"con":1,"ms":["arcane"],"also":[["cc",130]]},{"k":"sp-bestialravage","n":"Bestial Ravage","l":0,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":537,"ct":"1 action","rg":"Self","cp":"S","d":"Instantaneous","b":[["p","You channel primal magic to cause your teeth or fingernails to sharpen, ready to deliver a corrosive attack. Make a melee spell attack against one creature within 5 feet of you. On a hit, the target takes 1d10 acid damage. After you make the attack, your teeth or fingernails return to normal."],["p","The spell’s damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10)."]],"leg":1},{"k":"sp-bestowexpertise","n":"Bestow Expertise","l":5,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":537,"ct":"1 action","rg":"Touch","cp":"V, S","d":"Concentration, up to 1 hour","b":[["p","Your magic deepens a creature’s understanding of their own talent. You touch one willing creature and give them Expertise in one skill of your choice, which they must already be proficient in."]],"con":1,"leg":1},{"k":"sp-bilebeam","n":"Bile Beam","l":4,"s":"Evocation","sa":"EVO","c":["Spellblade","Sorcerer","Wizard"],"bk":"ll","p":213,"ct":"1 action","rg":"Self (100-foot line)","cp":"V, S, M","d":"Instantaneous","b":[["p","You unleash a beam of acid in a line 5 feet wide and 100 feet long, which stops early if it impacts a creature, Large or larger object, or solid surface. If the beam hits a creature, the creature must make a Dexterity saving throw. On a failure, it takes 12d4 acid damage and an additional 4d4 acid damage at the end of its next turn. On a success, it takes half as much initial acid damage and no additional damage."],["p","If a creature or object is killed or destroyed by the beam, the beam continues until it impacts another creature or object."]],"h":[["p","At Higher Levels. When you cast the spell using a spell slot of 5th level or higher, the initial damage increases by 1d4 for each level above 4th."]],"ms":["arcane"]},{"k":"sp-bindingcurse","n":"Binding Curse","l":1,"s":"Enchantment","sa":"ENC","c":["Occultist"],"bk":"ll","p":214,"ct":"1 action","rg":"60 feet","cp":"V, S, M (something from the target creature—such as blood, hair, or scales—which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You bind a creature to a point within 5 feet of it, causing glowing chains of light to connect it to that point. For the duration of the spell, if the creature attempts to move away from the point, it must succeed on a Wisdom saving throw or be unable to move more than 5 feet away from the point until the start of its next turn."],["p","If the target starts its turn more than 10 feet from the binding point, it must succeed on a Strength saving throw or be dragged 5 feet toward the binding point."]],"con":1,"ms":["arcane"],"also":[["cc",130]]},{"k":"sp-bindingmadness","n":"Binding Madness","l":2,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":538,"ct":"1 action","rg":"120 feet","cp":"V S","d":"Concentration, up to 1 minute","b":[["p","One humanoid of your choice that you can see within range must succeed on a Wisdom saving throw or become charmed by you for the duration. While the target is charmed in this way, a twisted crown of jagged iron appears on their head, and a madness glows in their eyes."],["p","On each of its turns, the charmed target must use their action before moving to make a melee attack against a creature other than themself that you mentally choose."],["p","The target can act normally on their turn if you choose no creature or if none are within their reach."],["p","On your subsequent turns, you must use your action to maintain control over the target, or the spell ends. Also, the target can make a Wisdom saving throw at the end of each of their turns. On a success, the spell ends."]],"h":[["p","At Higher Levels. If you cast this spell at 3rd level or higher, you can choose one of the following effects for each slot level above 2nd:"],["li","You may target one additional creature within range. If you have a creature attack another under this effect, the effect ends on the target being attacked."],["li","(3 slot levels) You can select creature types apart from humanoids."]],"con":1,"leg":1},{"k":"sp-bitingcurse","n":"Biting Curse","l":3,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":538,"ct":"1 action","rg":"Touch","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You touch a creature, and that creature must succeed on a Wisdom saving throw or become cursed for the duration of the spell. When you cast this spell, choose one of the following options to dictate the nature of the curse:"],["li","Choose one ability score. While cursed, the target has disadvantage on ability checks and saving throws made with that ability score."],["li","While cursed, the target has disadvantage on attack rolls against you."],["li","While cursed, the target must make a Wisdom saving throw at the start of each of their turns. If they fail, they waste their action that turn doing nothing."],["li","While the target is cursed, your attacks and spells deal an extra 1d8 necrotic damage to the target."],["li","While the target is cursed they are blinded to anything 30 feet or further away from themselves regardless of their senses."],["li","While cursed, the target receives only half as much healing as it normally would, and any effect that would restore 10 or fewer hit points to them restores none instead."],["p","A remove curse spell ends this effect. Its effects cannot be removed by spells that normally remove or dispel magical effects unless they also target curses. Your GM may allow you to create additional curse effects in addition or in place of those listed above."]],"h":[["p","At Higher Levels. If you cast this spell at 4th-level or higher, you may choose one of the following bonuses for each slot level above 3rd:"],["li","You may concentrate on the spell for up to 10 minutes, up to 8 hours (2 slot levels), up to 24 hours (4 slot levels), or have it be permanent unless dispelled (6 slot levels). If the spell lasts 8 or more hours it does not require concentration."],["li","You may choose one additional target, who suffers the same effects."],["li","(2 slot levels) You may choose an additional effect to apply to the spell’s target."]],"con":1,"leg":1},{"k":"sp-blacktentacles","n":"Black Tentacles","l":4,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":538,"ct":"1 action","rg":"90 feet","cp":"V, S, M (a piece of tentacle from a giant octopus or a giant squid)","d":"Concentration, up to 1 minute","b":[["p","Squirming, ebony tentacles fill a 20-foot square on ground that you can see within range. For the duration, these tentacles turn the ground in the area into difficult terrain."],["p","When a creature enters the affected area for the first time on a turn or starts its turn there, the creature must succeed on a Dexterity saving throw or take 3d6 bludgeoning damage and be restrained by the tentacles until the spell ends. A creature that starts its turn in the area and is already restrained by the tentacles takes 3d6 bludgeoning damage."],["p","A creature restrained by the tentacles can use its action to make a Strength or Dexterity check (its choice) against your spell save DC. On a success, it frees itself."]],"con":1},{"k":"sp-blackhole","n":"Blackhole","l":9,"s":"Transmutation","sa":"TRA","c":["Sorcerer","Wizard"],"bk":"ll","p":214,"ct":"1 action","rg":"300 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You create a miniature black hole at a point within range. An event horizon forms in a 15-foot radius around the point, engulfing anything (including light, sound, and magical effects) in the area."],["p","When the black hole appears, each creature within 15 feet of the point must make a Dexterity saving throw to avoid being engulfed. On a success, it can move up to its movement speed out of the event horizon of the black hole. If it cannot move to a safe space outside of the event horizon, it automatically fails the save and is engulfed."],["p","An engulfed creature is compressed into the point at the center of the spell, taking 12d12 bludgeoning damage at the start of each of its turns while engulfed. Its speed is 0, and it is blinded, deafened, and restrained while engulfed. As an action, an engulfed creature can attempt to forcibly exit the black hole by making a Strength ability check against your spell save DC. On a success, the creature appears in an empty space at the edge of the event horizon."],["p","Any spells, effects, terrain, or items that are not being worn or carried that are engulfed within the event horizon vanish and are destroyed. Magical items of Legendary or Artifact rarity are not destroyed, instead reappearing on the ground where the sphere was when the spell ends."],["p","While the spell persists, all movement away from it while within 120 feet of it is considered difficult terrain. All ranged attacks that pass within 120 feet of it have disadvantage. When a creature starts its turn within 120 feet of the black hole, it is pulled 5 feet toward the black hole. At the start of the caster’s turn, all objects within 120 feet of the black hole that weigh less than 1000 pounds, are not being worn or carried, and are not attached to the ground are pulled 20 feet toward the black hole."]],"con":1,"ms":["arcane"]},{"k":"sp-blademirage","n":"Blade Mirage","l":1,"s":"Illusion","sa":"ILL","c":["Bard","Occultist","Ranger","Spellblade","Sorcerer","Wizard"],"bk":"ll","p":214,"ct":"1 bonus action","rg":"Self","cp":"V, S, M (a melee weapon worth at least 1 sp)","d":"Concentration, up to 1 minute.","b":[["p","You twist illusions around a melee weapon you are holding. When you cast the spell, and as a bonus action on your subsequent turns for the duration, you can feint with the illusory blades, distracting a creature within 5 feet of you and giving you advantage on the next weapon attack against it before the end of the turn. The spell ends early if you let go of the weapon."],["p","As an action, a creature that can see you can make an Intelligence (Investigation) check against your spell save DC. On a success, it becomes immune to the spell's effects."]],"con":1,"ms":["arcane"]},{"k":"sp-bladevortex","n":"Blade Vortex","l":3,"s":"Conjuration","sa":"CON","c":["Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":215,"ct":"1 action","rg":"Self","cp":"V, S, M (a spinning top)","d":"1 round","b":[["p","You fill the air in a 10-foot radius around you with spinning blades until the start of your next turn. When the creature enters the area for the first time on a turn or starts its turn there, it takes 4d4 slashing damage. Until the spell ends, you have half cover against all ranged attacks."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level higher, the damage increases by 1d4 for each level above 3rd."]],"ms":["arcane"]},{"k":"sp-blastwave","n":"Blastwave","l":5,"s":"Evocation","sa":"EVO","c":["Spellblade","Sorcerer","Wizard"],"bk":"ll","p":215,"ct":"1 action","rg":"Self","cp":"V, S","d":"Instantaneous","b":[["p","You unleash a fiery blast of power outward in all directions. Each creature of your choice within 30 feet of you must make a Dexterity saving throw. On a failure, a creature takes 4d8 thunder damage and 4d8 fire damage and is knocked back 10 feet. On a success, it takes half as much and is not knocked back"]],"ms":["arcane"]},{"k":"sp-blazingbeacon","n":"Blazing Beacon","l":2,"s":"Evocation","sa":"EVO","c":["Cleric","Paladin","Warlock"],"bk":"ll","p":215,"ct":"1 Action","rg":"Self","cp":"V, S","d":"Concentration, Up to 1 minute","b":[["p","You are bathed in holy light, shedding bright light up to 30 feet and dim light for additional 30 feet."],["p","Any creature that targets you with an attack roll or spell that requires them to see you must make a Constitution saving throw. On a failure, they are blinded until the start of their next turn. A creature with darkvision makes this roll with disadvantage. A creature without eyes automatically passes their saving throw."]],"con":1,"ms":["divine"]},{"k":"sp-blessedcircle","n":"Blessed Circle","l":5,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":537,"ct":"1 action","rg":"Self (30 feet)","cp":"V, S, M (a paper charm with gold lettering, signify-ing good luck)","d":"Concentration, up to 10 minutes","b":[["p","A sphere of radiant energy pours from you, extending out 30 feet in every direction. For the spell’s duration, gasses and liquids in the environment that you do not wish to enter this space cannot do so. Breathable gas of moderate temperature passes through, allowing all creatures in this space to breathe safely. If submerged in liquid, you fall until you hit a solid surface."],["p","Elementals, fey, and yokai (except you) are warded from entering this space. When they enter the space for the first time on their turn, target creatures within the space with attacks or spells, or start their turn within it, they must succeed on a Charisma saving throw or be forced to move to the nearest unoccupied space outside, and be unable to target creatures within it with any effects until their next turn. Such creatures unable to move out of its range take 3d10 psychic damage on a failed save."],["p","If you willingly move into a space where the range overlaps with a creature it may affect, and you end your turn there, you must make a Concentration check against a DC set by the highest CR or level of all warded creatures within range. On a failure, this spell ends immediately."]],"h":[["p","At Higher Levels. When you cast this spell using a slot of 6th-level or higher, the spell’s radius doubles for each slot level above 5th."]],"con":1,"g":["Nine Branch Arts"]},{"k":"sp-blizzard","n":"Blizzard","l":6,"s":"Evocation","sa":"EVO","c":["Druid","Sorcerer","Warlock","Wizard"],"bk":"ll","p":215,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You conjure a howling blizzard of swirling clouds of ice and snow which fills a 30-foot-radius, 40-foot-high cylinder centered at a point you can see within range. The area becomes heavily obscured and difficult terrain. Any creature that starts its turn within the area or enters it for the first time on its turn must make a Constitution saving throw. A creature takes 6d8 cold damage on a failed saving throw, or half as much on a successful one."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 7th level or higher, the damage increases by 1d8 for each slot level above 6th."]],"con":1,"ms":["primal"]},{"k":"sp-bloodbolt","n":"Blood Bolt","l":0,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":290,"ct":"1 action","rg":"60 feet","cp":"S, M (a drop of your blood worth at least 1 hit point, which the spell consumes)","d":"Instantaneous","b":[["p","You transmute a drop of blood into a crimson dart and launch it at creatures within range, making a ranged spell attack. On hit, the target takes 1d6 piercing damage and 1d6 necrotic damage."],["p","The piercing and necrotic damage both increase by 1d6 at 5th level (2d6), 11th level (3d6), and 17th level (4d6). The blood consumed also increases when the damage increases at 5th (2), 11th (3), and 17th (4)."]],"bm":1},{"k":"sp-blooddiagnosis","n":"Blood Diagnosis","l":1,"s":"Divination","sa":"DIV","c":["Occultist","Wizard"],"bk":"llb","p":291,"ct":"1 minute","rg":"Touch","cp":"S, M (a drop of your blood worth 1 hit point and a drop of any creature's blood, both of which the spell consumes)","d":"Instantaneous","b":[["p","You spill a drop of your blood and mix it with a sample of any creature's blood. You learn the following information about the sample:"],["li","The type of creature it came from"],["li","If that creature was poisoned or diseased when the blood sample was given"],["li","Any medical information related to the creature's blood (blood type, general health, malnutrition, etc.)"],["li","If the creature is a blood relative of any other creature whose blood you've previously cast this spell on"]],"rit":1,"bm":1},{"k":"sp-blooddivination","n":"Blood Divination","l":2,"s":"Divination","sa":"DIV","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":291,"ct":"1 action","rg":"Touch","cp":"S, M (a drop of your blood worth at least 2 hit points which the spell consumes, and another creature’s blood)","d":"Instantaneous","b":[["p","You mix a drop of your blood into a bloodstain or blood sample from another creature and create a magical resonance. You learn the creature’s current condition (alive, wounded, or dead), its creature type, its general distance from you (nearby, distant, or very far), and its general direction."],["p","If the blood is more than 24 hours old, the spell becomes more difficult, and you must succeed on a DC 10 spellcasting check to gain any information. The DC increases to 15 if the blood is more than a week old, and 20 if the blood is more than a month old."]],"bm":1},{"k":"sp-bloodfrenzy","n":"Blood Frenzy","l":4,"s":"Enchantment","sa":"ENC","c":["Druid","Occultist","Wizard"],"bk":"llb","p":291,"ct":"1 action","rg":"Touch","cp":"S, M (a splash of your blood worth at least 4 hit points, which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You touch a willing creature, launching it into an empowered frenzy. For the duration, all attacks against the target creature have advantage, but the target gains the following benefits:"],["li","The target is immune to the charmed and frightened conditions."],["li","The target has advantage on its melee weapon attacks."],["li","When taking damage would reduce the creature to 0 hit points, it must make a Constitution saving throw with the DC equal to half the damage taken. On a success, it is reduced to 1 hit point instead."],["p","If you target yourself, you cannot lose concentration on this spell as a result of taking damage."]],"con":1,"bm":1},{"k":"sp-bloodofcineris","n":"Blood of Cineris","l":1,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":538,"ct":"1 action","rg":"Self (10-foot radius)","cp":"S","d":"1 round","b":[["p","You conjure up the burning blood of Cineris Clade, splashing it in a ring around yourself onto all creatures within the spell’s range. Each creature in that area must make a Dexterity saving throw, taking 2d6 fire damage on a failed save, or half as much damage on a successful one. Any creature that fails is poisoned until the start of your next turn."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd-level or higher, you can choose on of the following effects for each slot level above 1st:"],["li","The spell’s radius increases by 5 feet."],["li","The initial damage increases by 1d6."],["li","If cast at 6th-level or higher, any creature that fails is poisoned for 1 minute and takes 1d6 fire damage at the start of each of their turns while poisoned this way. They can attempt a Constitution saving throw at the end of each of their turns, ending the effect on a success."]],"g":["Blood of Cineris"]},{"k":"sp-bloodslash","n":"Blood Slash","l":1,"s":"Transmutation","sa":"TRA","c":["Sorcerer","Warlock","Wizard"],"bk":"llb","p":291,"ct":"1 action","rg":"60 feet","cp":"S, M (a splash of your blood worth up to 2 hit points, which the spell consumes)","d":"Instantaneous","b":[["p","You create a blade of blood and fling it at a creature you can see within range. Make a ranged spell attack. On a hit, the creature takes 2d6 slashing damage and 2d6 necrotic damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the slashing damage increases by 1d6 for each slot level above 1st."]],"bm":1},{"k":"sp-bloodstorm","n":"Blood Storm","l":2,"s":"Transmutation","sa":"TRA","c":["Occultist","Warlock","Wizard"],"bk":"llb","p":292,"ct":"1 action","rg":"Self or 60 feet","cp":"S, M (a splash of your blood worth at least 2 hit points, which the spell consumes)","d":"Instantaneous","b":[["p","You create a slicing vortex of swirling blood in a 15-foot radius around you or a point you choose within range. Each creature in the area must make a Dexterity saving throw. On failure, it takes 3d8 slashing damage. On a success, it takes half as much damage. If you center the spell on yourself, you are immune to its effects."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd."]],"bm":1},{"k":"sp-bloodtransfusion","n":"Blood Transfusion","l":1,"s":"Necromancy","sa":"NEC","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":292,"ct":"1 action","rg":"Touch","cp":"S, M (a splash of your blood worth 5 hit points, which the spell consumes)","d":"Instantaneous","b":[["p","You infuse a creature you touch with life drawn from the blood used in the material component of the spell. The target regains hit points equal to twice the amount expended."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the amount of hit points consumed by the spell increases by 5 for each slot level above 1st."]],"bm":1},{"k":"sp-bloodwave","n":"Blood Wave","l":2,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"llb","p":292,"ct":"1 action","rg":"Self (15-foot cone)","cp":"V, S, M (a splash of your blood worth at least 4 hit points, which the spell consumes)","d":"Instantaneous","b":[["p","You release a wave of magical blood that spreads out in a 15-foot cone. Creatures in the area must make a Strength saving throw. On a failure, a creature takes 2d6 bludgeoning damage and 2d6 necrotic damage and is knocked prone. On a success, it takes half as much damage and is not knocked prone."],["p","If the wave kills a creature or passes over a corpse that has died within the last minute, it grows, increasing its size by 5 feet (e.g. it becomes a 20-foot cone). It can increase to up to twice its original size. Creatures without blood don't trigger this effect."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the spell’s range increases by 5 feet and the necrotic damage increases by 1d6 damage for each slot level above 2nd."]],"bm":1},{"k":"sp-bloodyburst","n":"Bloody Burst","l":2,"s":"Necromancy","sa":"NEC","c":["Occultist","Sorcerer","Wizard"],"bk":"llb","p":290,"ct":"1 action","rg":"60 feet","cp":"S, M (a drop of your blood worth at least 2 hit points, which the spell consumes)","d":"Instantaneous","b":[["p","You cause a creature’s blood to erupt outward in a violent spray. The target must make a Constitution saving throw. On a failure, it takes 4d6 necrotic damage, and every other creature within 10 feet of the target must succeed on a Dexterity saving throw or take 2d6 necrotic damage from the blood spray. On a successful save, the target takes half as much damage and the blood spray does not occur. A creature without blood is immune to this spell."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, both the damage against the main target increase by 2d6 as well as the spray increasing by 1d6 for each spell level above 2nd."]],"bm":1},{"k":"sp-boilblood","n":"Boil Blood","l":2,"s":"Necromancy","sa":"NEC","c":["Occultist","Spellblade"],"bk":"ll","p":215,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You point at a creature that has taken slashing or piercing damage within the last minute and make its blood heat to boiling. The target must succeed on a Constitution saving throw or its blood overheats. At the start of each of its turns, it takes 3d4 fire damage and is crippled with agony, turning all terrain into difficult terrain for it."],["p","At the end of each of its turns, the target can make another Constitution saving throw. On a success, the spell ends on the target."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 2d4 for each slot level above 2nd."]],"con":1,"ms":["arcane"]},{"k":"sp-bonditem","n":"Bond Item","l":1,"s":"Conjuration","sa":"CON","c":["Inventor"],"bk":"ll","p":216,"ct":"1 minute","rg":"Touch","cp":"V, S","d":"8 hours","b":[["p","You touch an item weighing no more than 100 pounds and form a link with it. Until the spell ends, you can recall it to your hand as a bonus action."],["p","If another creature is holding or wearing the item when you try to recall it, it can attempt a Charisma saving throw to retain possession of the item. On a success, the spell ends. The creature makes this save with advantage if it has possessed the item for more than 1 minute."]],"ms":["arcane"],"also":[["cc",131]]},{"k":"sp-boomerangweapon","n":"Boomerang Weapon","l":2,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":539,"ct":"1 bonus action","rg":"Touch","cp":"S","d":"10 minutes","b":[["p","You touch one weapon that has the thrown property, held either by you or a willing creature, and for the spell’s duration that weapon counts as magical. Any time that weapon is used for a thrown weapon attack and misses, either you or the attacker can use their reaction to cause the weapon to swerve in the air and fly at another creature within its normal thrown attack range, in proximity to the initial target. The creature who threw it then rolls another attack roll against the new target. If this attack misses, you or the attacker can use their reaction to use this effect again."],["p","After an attack is made with the weapon, it swerves in the air and returns to the creature that threw it as long as they are still within the item’s long range."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th-level or higher, the normal and long range of the thrown weapon doubles, then doubles again for every two slot levels above 4th."]],"g":["Skulker’s Grimoire"]},{"k":"sp-bramblebarrier","n":"Bramble Barrier","l":3,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Ranger"],"bk":"ll","p":216,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You create a line of low brambles that erupts from a space on the ground you can see within range. This line is 30 feet long and 5 feet wide, made up of six 5-foot squares of brambles. Each patch must connect to another patch and be placed on the ground. The bramble patches are difficult terrain and any creature entering a square of brambles takes 4d4 piercing damage and must make a Constitution saving throw. On a failure, its speed becomes 0 until the end of its turn."],["p","The brambles wither and die after 1 day if the area isn’t suitable for them to grow. A creature can clear a 5-foot square with 1 minute of labor, or instantly by inflicting at least 5 points of fire damage. The brambles crumble to dust immediately if you cast this spell again."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can create two additional 5-foot squares of brambles for each slot level above 3rd."]],"ms":["primal"]},{"k":"sp-bramblebinding","n":"Bramble Binding","l":1,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Ranger"],"bk":"ll","p":216,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","Brambles burst from your hand, lashing out at a target within range. The target must make a Dexterity saving throw. On a failure, it takes 4d4 piercing damage and, if it is Large or smaller, becomes entangled by brambles. While entangled by brambles, it can’t move, but it can free itself as an action (taking no additional damage) or rip itself free using half of its movement and taking an additional 2d4 piercing damage. On a success, it takes half as much damage and isn't entangled by brambles."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, both the initial damage and the damage taken ripping free of the brambles increases by 1d4 for each slot level above 1st."]],"ms":["primal"]},{"k":"sp-brilliantblade","n":"Brilliant Blade","l":3,"s":"Evocation","sa":"EVO","c":["Cleric","Paladin"],"bk":"ll","p":216,"ct":"1 bonus action","rg":"Self (20 foot radius)","cp":"V, S, M (a melee weapon worth at least 1 sp)","d":"Instantaneous","b":[["p","You brandish the weapon used in this spell’s casting, holding it aloft as it flashes with brilliant light. Each creature within 20 feet of you must make a Constitution saving throw. On a failure, a creature is blinded until the end of your next turn. On a success, it is blinded until the end of your current turn."]],"ms":["divine"]},{"k":"sp-burdenedblood","n":"Burdened Blood","l":1,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":539,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","One creature you choose is given enhanced fortitude, gaining an amount of temporary hit points equal to 2d6 + your spellcasting ability modifier. These temporary hit points disappear after 1 minute."],["p","Every time this creature makes an attack roll, they can choose to lose 5 of these temporary hit points to give that attack advantage, and/or 5 to negate any disadvantage they would have had."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the temporary hit points gained increases by 1d6 for each slot level above 1st."]],"g":["Daemoturgy"]},{"k":"sp-burialbarrage","n":"Burial Barrage","l":5,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":217,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You unearth five heavy chunks of earth or stone and hurl them at targets within range. You can hurl them at one target or several. Make a ranged spell attack for each hurled object. On a hit, a target takes 1d12 + 1 bludgeoning damage, and if it is Large or smaller, falls prone. Attacks made as part of this spell have advantage against prone targets, and ignore disadvantage for making a ranged attack against a prone target farther than 5 feet away."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you can hurl one additional object for each slot level above 5th."]],"ms":["arcane","primal"]},{"k":"sp-burn","n":"Burn","l":0,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Warlock"],"bk":"ll","p":217,"ct":"1 action","rg":"Touch","cp":"V, S","d":"Instantaneous","b":[["p","You ignite a brilliant flame around your hand that sears anything you touch. Make a melee spell attack against a creature or object within range. On a hit, the target takes 1d12 fire damage."],["p","The spell’s damage increases by 1d12 when you reach 5th level (2d12), 11th level (3d12), and 17th level (4d12)."]],"ms":["arcane","primal"],"also":[["cc",130]]},{"k":"sp-burningammunition","n":"Burning Ammunition","l":3,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":539,"ct":"1 action","rg":"90 feet","cp":"V, S","d":"Concentration, up to 1 hour","b":[["p","You touch an ammunition container or belt containing arrows or bolts. When a target is hit by a ranged weapon attack using a piece of ammunition drawn from the container or belt, the target takes an extra 1d6 fire damage. The spell’s magic ends on a piece of ammunition when it hits or misses, and the spell ends when twelve pieces of ammunition have been drawn."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, you may choose one of the following effects for each slot level above 3rd:"],["li","The number of pieces of ammunition you can affect with 53 9"],["p","this spell increases by 2."],["li","The extra fire damage becomes 1d8 (1 slot level), 1d10 (2 additional slot levels), 1d12 (3 slot levels), or 2d8 (4 slot levels)."]],"con":1,"leg":1},{"k":"sp-burningstrike","n":"Burning Strike","l":2,"s":"Transmutation","sa":"TRA","c":["Paladin","Ranger","Spellblade"],"bk":"ll","p":217,"ct":"1 bonus action","rg":"Touch","cp":"V, S, M (a piece of ammunition or a weapon worth at least 1 cp)","d":"1 round","b":[["p","You touch a weapon or a piece of ammunition, imbuing it with licking flames. The next time you attack with the empowered item, it bursts into brilliant fire. On a hit, the target takes an additional 4d4 fire damage and begins to burn. On a miss, the target takes half as much damage and does not start to burn. A burning target sheds bright light in a 10-foot radius and dim light for an additional 10 feet, and takes 1d4 fire damage at the end of each of its turns. The target or another creature within 5 feet can use an action to extinguish the flames."],["p","If you target a weapon with the light property, you can immediately make a single weapon attack with it as part of the same action as casting the spell. Once you make one attack with the targeted item, the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, both the initial and ongoing burn damage are increased by 1d4 damage."]],"ms":["primal"]},{"k":"sp-burningweb","n":"Burning Web","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":539,"ct":"1 action","rg":"90 feet","cp":"V, S, M (silver thread that is burned during casting)","d":"Concentration, up to 1 minute","b":[["p","You conjure a web of burning threads that fill a 20-foot-cube centered on a point you choose within the spell’s range, and this burning web remains for the spell’s duration. Any creature that starts their turn in that space or enters it for the first time on their turn takes 3d6 fire damage and must make a Dexterity saving throw. On a failure, the creature is restrained until they succeed the save or start their turn outside the web."]],"h":[["p","At Higher Levels. When you cast this spell at 6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","The spell’s damage increases by 1d6."],["li","The cube’s sides each increase by 10 feet."]],"con":1,"g":["Blood of Cineris"]},{"k":"sp-carnivorousgarden","n":"Carnivorous Garden","l":4,"s":"Transmutation","sa":"TRA","c":["Druid"],"bk":"ll","p":217,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a dried carnivorous plant)","d":"Concentration, up to 1 minute","b":[["p","You summon clinging plant growth in four 15-foot squares you can see within range, and a snarling carnivorous plant in the central space of each area. Each 15-foot square is difficult terrain. When you cast the spell, each plant makes one attack against a creature of your choice within 5 feet of it. The plants make melee spell attacks with your spell attack modifier, dealing 2d8 piercing damage on hit."],["p","If a creature ends its turn within 5 feet of one or more of the carnivorous plants, the plants automatically attack that creature unless you use your reaction to prevent them from doing so."],["p","The plants have AC 14 and 30 hit points, and have vulnerability to fire and slashing damage. Each plant regains all its hit points at the start of your turn if it has at least 1 hit point, and dies if it is reduced to zero hit points. When the spell ends, the difficult terrain disappears, except where the plants themselves were. This difficult terrain also disappears if the plant was killed with fire damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can summon 1 additional carnivorous plant for each slot level above 4th."]],"con":1,"ms":["primal"]},{"k":"sp-catastrophicshield","n":"Catastrophic Shield","l":5,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":539,"ct":"1 reaction taken when damage would reduce you to 0 hit points or fewer","rg":"Self","cp":"S","d":"Concentration, up to 1 round","b":[["p","When damage would trigger this spell, you summon a spherical barrier of orange and red arcane symbols. For its duration, you cannot be reduced lower than 1 hit point by any source of damage you take. If damage would reduce you to 0 hit points, you are reduced to 1 instead. You must still make concentration checks as if you had taken the full damage, but you are protected against those sources of damage even if you fail the concentration check that provoked them."]],"con":1,"g":["Nine Branch Arts"]},{"k":"sp-causticresolution","n":"Caustic Resolution","l":3,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":539,"ct":"bonus action","rg":"120 feet","cp":"V, S, M (a small carving of a head with a nail through it)","d":"Concentration, up to 1 minute","b":[["p","If a creature is concentrating on a spell or benefiting from a magical effect that targets only them, you may attempt to cause the build-up of magical energy to burn away at their flesh. The target must succeed on a Constitution saving throw. On a failure, at the start of each turn when the creature is concentrating on a spell or benefiting from a magical effect from a spell, they take 1d6 acid damage. During this time, the creature has disadvantage on concentration checks. If they lose concentration or they benefit from no magical effects, this spell ends immediately."]],"h":[["p","At Higher Levels. When you cast this spell at 5th level or higher, the damage the target takes increases by 1d6 for every two spell slot levels above 3rd."]],"con":1,"g":["Daemoturgy"]},{"k":"sp-ceremonialrite","n":"Ceremonial Rite","l":1,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":540,"ct":"1 hour","rg":"Touch","cp":"V, S, M (25 gp worth of powdered silver, which the spell consumes)","d":"Instantaneous","b":[["p","You perform a special religious ceremony that is infused with magic. When you cast the spell, choose one of the following rites, the target of which must be within 10 feet of you throughout the casting."],["p","Atonement. You touch one willing creature whose alignment has been changed, and you make a DC 20 Wisdom (Insight) check. On a successful check, you restore the target to their original alignment."],["p","Awaken. You touch one creature who is at 0 hit points but stable. They awaken, regaining hit points equal to 2d8 x the level this spell was cast at, and immediately benefit from a Short Rest."],["p","Bless Water. You touch one vial of water and cause it to become holy water."],["p","Coming of Age. You touch one humanoid who is a young adult. For the next 24 hours, whenever the target makes an ability check, it can roll a d4 and add the number rolled to the ability check. A creature can benefit from this rite only once."],["p","Dedication. You touch one humanoid who wishes to be dedicated to your god’s service. For the next 24 hours, whenever the target makes a saving throw, it can roll a d4 and add the number rolled to the save. A creature can benefit from this rite only once."],["p","Funeral Rite. You touch one corpse, and for the next 7 days, the target can’t become undead by any means short of a wish spell."],["p","Sanctify. You spend the spell’s casting time focusing on a cube equal to 10 feet x the level the spell is cast at, centered on you. Once you complete the spell, invisible undead within that cube can be plainly seen for 24 hours, and undead in the ethereal plane can be interacted with as if on the Material Plane."],["p","Treatment. You touch one vial of water while within 10 feet of a sickened creature suffering from poison or a disease. The water in the vial becomes a medicinal drink, and once consumed a creature has advantage on saving throws made against that poison or disease for 7 days."],["p","Wedding. You touch adult humanoids willing to be bonded together in marriage. For the next 7 days, each target gains a +2 bonus to AC while they are within 30 feet of each other. A creature can benefit from this rite again only if widowed, and for the purposes of the spell those individuals are considered married."]],"leg":1},{"k":"sp-cernunnoseye","n":"Cernunnos Eye","l":1,"s":"Divination","sa":"DIV","c":[],"bk":"retia","p":540,"ct":"1 bonus action","rg":"60 feet","cp":"S, M (an emerald worth at least 100 gp)","d":"Instantaneous","b":[["p","You can gaze through the spell’s material component at a creature within 60 feet in an attempt to glean information on them. Choose one of the following options:"],["li","Condition immunities"],["li","Current armor class"],["li","Current hit points (rounded to the nearest multiple of 25)"],["li","Damage vulnerabilities"],["li","Damage immunities and resistances"],["li","Movement types and speeds"],["li","Proficiency bonus"],["li","Saving throw proficiencies (not modifiers)"],["li","Skill proficiencies (not modifier)"],["li","Special senses"],["p","The target must then make a Charisma saving throw. If they fail their save, you learn those properties about your target."]],"h":[["p","At Higher Levels. When casting this spell at 2nd level or higher, you can choose one additional option from the list to learn for each slot level above 1st."]]},{"k":"sp-chainfield","n":"Chainfield","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":541,"ct":"1 action","rg":"120 feet","cp":"V, S, M (a dagger with an obsidian blade, worth at least 300 gp)","d":"10 minutes","b":[["p","Choose five points you can see within the spell’s range. At each point, a 10-foot-long stake of obsidian and fire erupts from rips in space, each wrapped in blood-red burning chains. Each creature within 5 feet of each stake when it appears must make a Dexterity saving throw, taking 6d6 fire damage on a failed save, or half as much on a successful one. These stakes then remain until the spell ends or you cast it again."],["p","While the stakes remain, each time a creature attempts to move out of their range - a 5 foot radius - for the first time on that turn, the chains surrounding them attempt to latch onto the creature, forcing them to succeed a Strength saving throw or be restrained until the start of their next turn. Creatures that end their turn within 5 feet of a stake or are restrained by one at the end of their turn take 2d6 fire damage."],["p","A creature that succeeds their Strength saving throw against one of the stakes by 5 or more points, or rolls a natural 20 on their saving throw automatically destroys that stake, rendering it useless."]],"h":[["p","At Higher Levels. If you cast this spell at 6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","You create one additional stake."],["li","Each stake’s initial damage upon appearing increases by 1d6."],["li","The area affected by each stake’s initial appearance increases by 5 feet."]],"g":["Daemoturgy","Eidomancy"]},{"k":"sp-chaosburst","n":"Chaos Burst","l":1,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":541,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","You hurl an undulating, warbling mass of chaotic energy at one creature in range. Make a ranged spell attack against the target: on a hit, the target takes 2d8 + 1d6 damage. After rolling, choose one of the d8s. The number rolled on that die determines the attack’s damage type, as shown below."],["tbl",[["d8","Damage Type"],["1","Acid"],["2","Cold"],["3","Fire"],["4","Force"],["5","Lightning"],["6","Poison"],["7","Psychic"],["8","Thunder"]]],["p","If you roll the same number on both d8s, the chaotic energy leaps from the target to a different creature of your choice within 30 feet of it. Make a new attack roll against the new target, and make a new damage roll, which could cause the chaotic energy to leap again."],["p","A creature can be targeted only once by each casting of this spell."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can choose from the following effects for each slot level above 1st:"],["li","1d6 extra damage of the type rolled."],["li","You may roll an additional d8 - it is not added to the damage, but you may use the result to determine the damage type."],["li","The spell targets one additional creature, firing an additional bolt toward them. This second bolt requires its own damage roll and may have a different damage type."]],"rv":1,"leg":1},{"k":"sp-chromaticarrow","n":"Chromatic Arrow","l":1,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":541,"ct":"1 action","rg":"90 feet","cp":"V, S, M (a diamond worth at least 50 gp)","d":"Instantaneous","b":[["p","You hurl a 4-inch-diameter sphere of energy at a creature that you can see within range. You choose acid, cold, fire, lightning, poison, or thunder for the type of orb you create, and then make a ranged spell attack against the target. If the attack hits, the creature takes 3d8 damage of the type you chose."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd level or higher, you can choose one of the following effects for each slot level above 1st:"],["li","The spell’s damage increases by 1d8."],["li","You may choose one additional target within range, and may use a different energy type for each target."],["li","If a target is resistant or immune to the damage type you deal to them, you become aware of it and can use your reaction to change the damage type to a different one at the last second."],["li","The spell’s range is increased by 90 feet."]],"leg":1},{"k":"sp-chromaticbreath","n":"Chromatic Breath","l":2,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":218,"ct":"1 bonus action","rg":"Touch","cp":"V, S, M (a fragment of a dragon’s scale)","d":"Concentration, up to 1 minute","b":[["p","You touch a willing creature that has a mouth and can breathe, imbuing it with the power to expel elemental energy. When you cast the spell, select one of the following damage types: acid, cold, fire, lightning, or poison. Until the spell ends, the target can use its action to exhale a powerful elemental gust in a 15-foot cone. Each creature in that cone must make a Dexterity saving throw. On a failure, a creature takes 3d6 damage of the selected type. On a success, it takes half as much damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each level above 2nd."]],"con":1,"ms":["arcane"]},{"k":"sp-chromaticward","n":"Chromatic Ward","l":5,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":541,"ct":"1 action","rg":"Self","cp":"V, S, M (a bronze ring with a diamond, ruby, pearl, sapphire and emerald set into it, worth a least 500 gp)","d":"1 minute","b":[["p","Arcane sigils cover your skin, weaving into complex patterns. You become immune to all types of chromatic energy damage. The first time you take damage from any chromatic energy type, these immunities become resistances for the spell’s duration, and each time you take damage of that triggering type of chromatic energy type you take 10 fewer points of damage from it. Furthermore, until the spell ends, each time you hit a creature with a weapon attack you deal 10 points of that chromatic energy type."]],"g":["Chromatic Convocation"]},{"k":"sp-chronoconjunction","n":"Chrono Conjunction","l":6,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"ll","p":218,"ct":"1 reaction, which you take when a creature you can see within 60 feet rolls a save, ability check, or attack roll.","rg":"60 feet","cp":"V, S, M (something from the past or future)","d":"Instantaneous","b":[["p","As a reaction to a creature rolling a save, ability check, or attack roll, you search all possible timelines and merge the outcome you desire with reality. Select a value from 1 to 20 as the outcome of the roll. An unwilling creature can attempt to resist by making a Charisma saving throw; on a success, the spell has no effect."],["p","Once you cast this spell, you cannot cast it again until 24 hours have passed."]],"ms":["arcane"]},{"k":"sp-chughlihnsinkvoid","n":"Chughlihn’s Ink Void","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":542,"ct":"1 action","rg":"150 feet","cp":"V, S","d":"Instantaneous","b":[["p","A small glob of ink appears at your fingertips, then flies at a point within range that you choose. It explodes in a 30-foot radius sphere of pitch-black ink and writhing vermin, which sticks to their skin like adhesive paint. All creatures within range must make a Constitution saving throw, taking 10d6 poison damage and are blinded on a failed save, or half as much damage on a successful save. At the end of each blinded creature’s turn, they can reattempt the Constitution saving throw, ending the effect on a success. Any creature who rolls a d20 result of 5 or lower on either Constitution save, and fails, suffers one level of exhaustion."]],"h":[["p","At Higher Levels. When you cast this spell at 6th level or higher, choose one of the following options for each slot level above 5th:"],["li","The poison damage increases by 1d6."],["li","The sphere’s radius increases by 10 feet."]]},{"k":"sp-circleofinverseevolution","n":"Circle of Inverse Evolution","l":6,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":542,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a black diamond worth at least 1,000 gp)","d":"Concentration, up to 1 minute","b":[["p","Choose one point you can see within the spell’s range and choose one of the following d20 roll types: attack rolls, ability checks or saving throws. A circle of influence sprouts from that point, filling a sphere with a 30-foot radius. Each time a creature enters that sphere or starts their turn in it, they must make a Charisma saving throw. On a failure, they subtract your proficiency bonus from the selected d20 roll type, except saves made to resist this spell, until the next time they start their turn outside the sphere."]],"h":[["p","At Higher Levels. When you cast this spell at 7th level or higher, you can choose one of the following effects for every slot level above 6th:"],["li","Increase the spell’s duration to 10 minutes (1 slot level), 1 hour (2 slot levels) or 24 hours (3 slot levels)."],["li","You can choose one additional type of d20 roll."],["li","Increase the radius of the sphere by 15 feet."]],"con":1,"g":["Blood of Cineris"]},{"k":"sp-claytouch","n":"Clay Touch","l":2,"s":"Transmutation","sa":"TRA","c":["Druid","Inventor","Occultist","Ranger","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":218,"ct":"1 action","rg":"Touch","cp":"V, S, M (a small clump of clay)","d":"Concentration, up to 1 minute","b":[["p","You reach to a creature within range and attempt to turn its armor to soft clay. The target must make a Dexterity saving throw. On a failure, the target’s armor (including natural or magical defenses)"],["p","becomes soft and malleable, though retaining its form, and provides no protection against attacks, reducing the target’s AC to 10 + its Dexterity modifier for the duration."],["p","Alternatively, you can touch a nonmagical object that isn’t being worn or carried and is no larger than 2 feet in any dimension, reducing its AC and the DCs of any Strength checks to damage it to 5 for the duration of the spell."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-cloudcanvas","n":"Cloud Canvas","l":2,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":542,"ct":"1 action","rg":"Sight","cp":"V, S","d":"Concentration, up to 1 hour","b":[["p","You cause up to ten words to form in a part of the sky you can see. The words appear to be made of clouds and remain in place for the spell’s duration. The words dissipate when the spell ends, or a strong wind can disperse the clouds and end the spell prematurely. You can also use this spell to form the clouds into a limited design, such as a holy symbol or crest."]],"con":1,"rit":1,"leg":1},{"k":"sp-coldsnap","n":"Cold Snap","l":2,"s":"Evocation","sa":"EVO","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":218,"ct":"1 action","rg":"90 ft (5-foot radius)","cp":"S","d":"Instantaneous","b":[["p","With a snap of your fingers, a swirling burst of freezing wind erupts at a point you choose within range. Each creature in a 5-foot-radius sphere centered must make a Constitution saving throw. On a failure, a creature takes 3d8 cold damage and becomes coated in ice, reducing its speed by 10 feet until the start of your next turn. On a success, it takes half as much damage and is not slowed."],["p","The ground in the area is covered with slick ice and snow, making it difficult terrain until the start of your next turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd."]],"ms":["arcane","primal"],"also":[["cc",131]]},{"k":"sp-commandment","n":"Commandment","l":4,"s":"Enchantment","sa":"ENC","c":["Cleric","Paladin"],"bk":"ll","p":219,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You issue a divine order to another creature you can see within range that can hear and understand you, invoking divine authority to compel them. If the target intentionally violates the issued order, it takes 4d6 radiant damage. Once a creature takes damage this way, they cannot take damage again from it until the start of your next turn."],["p","Some examples of orders you can issue would include ordering the target not to attack, not to move, or not to breathe. If you issue an impossible order, the spell ends immediately."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can target one additional creature for each slot level above 4th."]],"con":1,"ms":["divine"]},{"k":"sp-compelledconvulsion","n":"Compelled Convulsion","l":2,"s":"Necromancy","sa":"NEC","c":["Occultist","Sorcerer","Wizard"],"bk":"llb","p":292,"ct":"1 action","rg":"30 feet","cp":"S, M (a drop of your blood worth at least 2 hit points, which the spell consumes)","d":"Instantaneous","b":[["p","You attempt to briefly take control of the blood of a creature you can see within range. The target must make a Constitution saving throw. On a failure, you can force it to use its reaction to move up to 15 feet (or its movement speed, whichever is less) and make a single weapon attack against a target of your choice within reach. Creatures without blood are immune to this effect."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you can target an additional creature for each level above 2nd level."]],"bm":1},{"k":"sp-compelledquery","n":"Compelled Query","l":1,"s":"Psionic","sa":"PSI","c":["Psion"],"bk":"cc","p":131,"ct":"1 action","rg":"60 feet","cp":"S","d":"Instantaneous","b":[["p","You focus your telepathic powers on a creature and ask it a simple question. It must make an Intelligence saving throw, or it conjures a short mental thought or image that answers your question to the best of its ability that you can perceive telepathically. A creature gains a +5 to the saving throw against this spell for each time it has been used on them in the past 24 hours."]],"ci":1},{"k":"sp-conjurebestialecho","n":"Conjure Bestial Echo","l":2,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":543,"ct":"1 action","rg":"90 feet","cp":"V, S, M (a feather, tuft of fur, and fish tail inside a gilded acorn worth at least 200 gp)","d":"Concentration, up to 1 hour","b":[["p","You call forth a bestial echo which manifests in an unoccupied space that you can see within range. This corporeal form uses the Bestial Echo stat block. When you cast the spell, choose an environment: Air, Land, or Water. The creature resembles an animal of your choice that is native to the chosen environment, which determines certain traits in its stat block. The creature disappears when they drop to 0 hit points or when the spell ends."],["p","Bestial Echo Template Small beast, unaligned"],["p","AC 11 + the spell level"],["p","HP 30 (plus 5 for each spell level above 2nd)"],["p","Speed 30 ft., climb 30 ft. (land only), fly 60 ft. (air only), swim 30"],["p","ft. (water only)"],["tbl",[["Str 18","+4","-","Dex 11","-","-","Con 16","+3","-"],["Int 4","-3","-","Wis 14","+2","-","Cha 5","-3","-"]]],["p","Skills"],["p","Resistances"],["p","Vulnerabilities"],["p","Immunities"],["p","Senses darkvision 60 ft., passive Perception 12"],["p","Languages understands the languages you speak"],["p","Proficiency Bonus equal to caster’s The creature is an ally to you and your companions. In combat, the creature shares your initiative count, but takes their turn immediately after yours. They obey your verbal commands (no action required by you). If you don’t issue any, they take the Dodge action and uses their move to avoid danger."],["p","If the echo is killed while outside your range of vision, you see through its senses briefly and get a momentary glimpse of what happened when they died (unless you are unconscious)."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, use the higher level wherever the spell’s level appears in the stat block."],["p","Traits"],["p","Flyby (Air Only). The beast doesn’t provoke opportunity attacks when it flies out of an enemy’s reach."],["p","Pack Tactics (Land and Water Only). The beast has advantage on an attack roll against a creature if at least one of the beast’s allies is within 5 feet of the creature and the ally isn’t incapacitated."],["p","Water Breathing (Water Only). The beast can breathe only underwater."],["p","Actions Multiattack. The beast makes a number of attacks equal to half this spell’s level (rounded down)."],["p","Maul. Melee Weapon Attack: your spell attack modifier to hit, reach 5 ft., one target. Hit: 1d8 + 4 + the spell’s level piercing damage."]],"rv":1,"con":1,"leg":1},{"k":"sp-conjuredraconicecho","n":"Conjure Draconic Echo","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":544,"ct":"1 action","rg":"60 feet","cp":"V, S, M (an object with the image of a dragon en-graved on it, worth at least 500 gp)","d":"Concentration, up to 1 hour","b":[["p","You call forth a draconic echo: a semblance of another dragon you are familiar with or one from a reality bordering your own. It manifests in an unoccupied space that you can see within range. This corporeal form uses the Draconic Echo stat block. When you cast this spell, choose a family of dragon: chromatic, gem, or metallic. The creature resembles a dragon of the chosen family, which determines certain traits in its stat block. The creature disappears when they drop to 0 hit points or when the spell ends."],["p","The creature is an ally to you and your companions. In combat, the creature shares your initiative count, but takes their turn immediately after yours. It obeys your verbal commands (no action required by you). If you don’t issue any, they take the Dodge action and uses their move to avoid danger."],["p","If your draconic echo is reduced to 0 hit points while outside your vision, you see a momentary flash of its final moments as though through its own senses, seeing what they saw for a split second (unless you are unconscious). You then become aware that the spell has ended."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, use the higher level wherever the spell’s level appears in the stat block."],["p","Draconic Echo Large dragon, neutral"],["p","AC 14 + the spell level"],["p","HP 50 (plus 10 for each slot level above 5th"],["p","Speed 30 ft., fly 60 ft., swim 30 ft."],["tbl",[["Str 19","+4","-","Dex 14","+2","-","Con 17","+3","-"],["Int 10","-","-","Wis 14","+2","-","Cha 14","+2","-"]]],["p","Resistances (Chromatic & Metallic) acid, cold, fire, lightning,"],["p","poison"],["p","Resistances (Gem) force, necrotic, psychic, radiant, thunder"],["p","Vulnerabilities"],["p","Immunities charmed, frightened, poisoned"],["p","Senses blindsight 30 ft., darkvision 60 ft., passive Perception 12"],["p","Languages Draconic, understands the languages you speak"],["p","Proficiency Bonus equal to caster’s Traits"],["p","Shared Resistance. When you summon the dragon, choose one of its damage resistances. You have resistance to the chosen damage type until the spell ends."],["p","Actions Multiattack. The dragon makes a number of Rend attacks equal to half the spell’s level (rounded down), and it uses Breath Weapon."],["p","Rend. Melee Weapon Attack: your spell attack modifier to hit, reach 10 ft., one target. Hit: 1d6 + 4 + the spell’s level piercing damage."],["p","Breath Weapon. The dragon exhales destructive energy in a 30-foot cone. Each creature in that area must make a Dexterity saving throw against your spell save DC. A creature takes 2d6 damage of a type this dragon has resistance to (your choice) on a failed save, or half as much damage on a successful one."]],"rv":1,"con":1,"leg":1},{"k":"sp-conjuremajorsteed","n":"Conjure Major Steed","l":4,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":545,"ct":"10 minutes","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","You summon a spirit that assumes the form of a loyal, majestic mount. Appearing in an unoccupied space within range, the spirit takes on a form you choose from the following:"],["li","A giant spider"],["li","A giant eagle"],["li","A griffon"],["li","A pegasus"],["li","A peryton"],["li","A dire wolf"],["li","A rhinoceros"],["li","A saber-toothed tiger"],["p","The creature has the statistics provided in the Monster Manual for the chosen form, though they are a celestial, a fey, or a fiend (your choice) instead of their normal creature type. Additionally, if they have an Intelligence score of 5 or lower, their Intelligence becomes 6, and they gain the ability to understand one language of your choice that you speak."],["p","If it wasn’t already, the mount is always summoned at least one size category larger than you. This has no effect on its statistics unless they are explicitly size-dependent."],["p","You control the mount in combat. While the mount is within 1 mile of you, you can communicate with it telepathically. While mounted on it, you can make any spell you cast that targets only you also target the mount."],["p","The mount disappears temporarily when it drops to 0 hit points or when you dismiss it as an action. Casting this spell again re-summons the bonded mount, with all its hit points restored and any conditions removed."],["p","You can’t have more than one mount bonded by this spell or find steed at the same time. As an action, you can release a mount from its bond, causing it to disappear permanently."],["p","Whenever the mount disappears, it leaves behind any objects it was wearing or carrying."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can summon a greater beast instead based on the list below, as long as the slot level is equal to or higher than the one it is listed with:"],["li","Ankylosaurus (6th)"],["li","Barghest (8th)"],["li","Bulette (8th)"],["li","Chimera (9th)"],["li","Giant Crocodile (7th)"],["li","Killer Whale (6th)"],["li","Manticore (7th)"],["li","Nightmare (7th)"],["li","Phase Spider (5th)"],["li","Stegosaurus (7th)"],["li","Triceratops (8th)"],["li","Winter Wolf (6th)"],["li","Young Dragon (9th)"],["li","Wyvern (9th)"]],"leg":1,"g":["Whisperwood Tome"]},{"k":"sp-conqueringwinds","n":"Conquering Winds","l":5,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":545,"ct":"1 action","rg":"300 feet","cp":"V, S","d":"Concentration, up to 1 hour","b":[["p","You take control of the air in a 100-foot cube that you can see within range. Choose one of the following effects when you cast the spell. The effect lasts for the spell’s duration, unless you use your action on a later turn to switch to a different effect. You can also use your action to temporarily halt the effect or to restart one you’ve halted."],["p","Barrier. The wind pushes toward the center of the cube, attempting to contain any creature within it. Each time a creature within the cube attempts to leave its borders, they must succeed a Strength saving throw. On a failure they are pulled (1d4 x 5) + 5 feet toward the opposite side of the cube and their movement speed is reduced to 0. A creature that succeeds can move out of the effect."],["p","Downdraft. You cause a sustained blast of strong wind to blow downward from the top of the cube. Ranged weapon attacks that pass through the cube or that are made against targets within it have disadvantage on their attack rolls. A creature must make a Strength saving throw if they fly into the cube for the first time on a turn or start their turn there flying. On a failed save, the creature is knocked prone."],["p","Gusts. A wind picks up within the cube, continually blowing in a horizontal direction you designate. You choose the intensity of the wind: calm, moderate, or strong. If the wind is moderate or strong, all ranged weapon attacks that enter, or pass through the cube have disadvantage on their attack rolls. If the wind is strong, any creature moving against the wind must spend 1 extra foot of movement for each foot moved."],["p","Howling. A roaring wind picks up, making it hard to communicate. Creatures within the effect attempting to speak loud enough to communicate over the sound of the wind must succeed on a Constitution check. On a failure they aren’t heard; on a success they can communicate for the remainder of the turn as they normally would."],["p","Suffocation. The air within the space becomes difficult to breathe, as the wind pulls it from the lungs of creatures. Each creature that starts their turn within the effect must succeed a Constitution saving throw or be unable to breath (if they had to). They repeat this save each turn they begin within the effect, but with disadvantage if their last save was a failure. On a success, they can breathe on that turn."],["p","Updraft. You cause a sustained updraft within the cube, rising upward from the cube’s base. Creatures that end a fall within the cube take only half damage from the fall. When a creature in the cube makes a vertical jump, the creature can jump up to 10 feet higher than normal."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, choose one of the following effects for each slot level above 5th:"],["li","The cube you control increases in size by 50 feet."],["li","The spell’s range increases by 100 feet."],["li","You can split the effect into multiple instances of the effects above - these are each a 50-foot cube, which cannot overlap with each other. You may combine multiple 50 feet cubes, adding their size together into a larger cube. You can choose a different effect for each cube. The total size of all cubes you create must add up to the original size the cube would have been otherwise."]],"con":1,"leg":1},{"k":"sp-corpseexplosion","n":"Corpse Explosion","l":3,"s":"Necromancy","sa":"NEC","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":292,"ct":"1 action","rg":"60 feet","cp":"S, M (a splash of your blood worth at least 3 hit points, which the spell consumes)","d":"Instantaneous","b":[["p","You cause an eruption of blood from the corpse of a Small or larger creature that had blood and was slain within the last minute. Each creature within 15 feet of the corpse must make a Dexterity saving throw. On a failure, it takes 3d8 necrotic damage and 3d8 thunder damage. On a success, it takes half as much damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can target one additional corpse for each slot level above 3rd. A creature affected by multiple corpse explosions makes its saving throw at disadvantage, but only takes damage once."]],"bm":1},{"k":"sp-corrosivesmite","n":"Corrosive Smite","l":3,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":542,"ct":"1 bonus action","rg":"Self","cp":"V","d":"Concentration, up to 1 minute","b":[["p","The next time you hit with a melee weapon attack during this spell’s duration, your attack deals an extra 3d8 acid damage. Additionally, if the target is a creature, they must make a Constitution saving throw. On a failure they are poisoned until the spell ends. While poisoned, the target repeats the Constitution saving throw at the end of each of their turns, ending the spell on a success."],["p","Liante Elgloven Alussfaen"],["p","channeling the power of"],["p","Cineris Clade"]],"con":1,"g":["Whisperwood Tome"]},{"k":"sp-crackle","n":"Crackle","l":2,"s":"Evocation","sa":"EVO","c":["Druid","Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":219,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You create three arcs of lightning striking targets in range. You can direct them at one target or several. Make a ranged spell attack for each arc. On a hit, a target takes 1d12 lightning damage. If three or more arcs hit a single target, it must make a Constitution saving throw or become shocked, stunning it until the start of its next turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you create one additional arc for each slot level above 2nd."]],"ms":["arcane","primal"],"also":[["cc",131]]},{"k":"sp-crashingice","n":"Crashing Ice","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":546,"ct":"1 action","rg":"Self (50-foot line)","cp":"V, S","d":"Instantaneous","b":[["p","With a sweep of your hand, a torrent of freezing water and ice explodes forth from you in a 50-foot-long, 10-foot-wide, 10-foottall line. All creatures in range must make a Dexterity saving throw, taking 4d8 bludgeoning damage and 4d8 cold damage on a failed save, or half as much on a successful one. Creatures who succeed may choose to move out of the range of the line, emerging in the nearest unoccupied space."],["p","Afterward, the water and ice freezes in place. Creatures who failed their saving throw are partially embedded and restrained in the ice, requiring a successful Strength check against your spell DC as an action to escape."]],"h":[["p","At Higher Levels. When you cast this spell at 6th level or higher, the bludgeoning and cold damage each increase by 1d8 for every slot level about 5th."]],"g":["Altissima-Cor’s Arcane Arts"]},{"k":"sp-crashingwave","n":"Crashing Wave","l":1,"s":"Conjuration","sa":"CON","c":["Druid","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":219,"ct":"1 action","rg":"Self (15-foot cone)","cp":"V, S","d":"Instantaneous","b":[["p","A wave of water sweeps out from you. Each creature in a 15-foot cone must make a Strength saving throw. On a failed save, a creature takes 2d6 bludgeoning damage and is knocked 10 feet away from you. If a creature is knocked into a wall, another creature, or fails by 5 or more, it is additionally knocked prone. On a successful save, the creature takes half as much damage and is not knocked back. If there is a source of water of at least 5 cubic feet within 5 feet of you when you cast the spell, you can displace that water, increasing the range of the spell to a 30 foot cone."]],"h":[["p","At Higher Levels. When you cast this spell using a spell lot of 2nd level or higher, the damage increases by 1d6 for each level above 1st."]],"ms":["arcane","primal"],"also":[["cc",131]]},{"k":"sp-createpit","n":"Create Pit","l":1,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Wizard"],"bk":"ll","p":219,"ct":"1 action","rg":"60 feet (10-foot square)","cp":"V, S","d":"Instantaneous","b":[["p","You choose a 10-foot square area on the ground in an area of dirt or natural stone you can see. The ground buckles and opens into a 10-foot deep pit. If the surface is not large enough to contain the pit, the spell fails. Each creature in the area must make a Dexterity saving throw. On a success, a creature jumps to a space 5 feet outside the spell's radius. On a failure, a creature falls to the bottom of the pit (taking normal falling damage). The sides of the pit are rough, and can be climbed. A creature that saves but cannot locate an empty space to move to falls prone, hanging from the edge of the pit, and cannot stand until it moves out of the pit area or drops into it. The pit remains until filled."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the pit is 5 feet deeper for each slot level above 1st, to a maximum of 20 feet deep."],["p","Limitations"],["p","The spell may fail if the pit would breach another opening"],["p","(such as a room or cavern below), as that would be failing"],["p","to contain the pit. The GM has wide discretion on what"],["p","surfaces are valid targets for this spell."]],"ms":["arcane","primal"]},{"k":"sp-crescentwindslash","n":"Crescent Wind Slash","l":2,"s":"Evocation","sa":"EVO","c":["Bard","Ranger","Spellblade","Sorcerer","Wizard"],"bk":"ll","p":220,"ct":"1 action","rg":"60 feet","cp":"S, M (a melee weapon worth at least 1 sp)","d":"Instantaneous","b":[["p","You make a series of three slashes, each one magically releasing a razor-sharp blast of wind at a target within range. You can launch them at one target or several."],["p","Make a weapon attack with the weapon used in the casting of this spell for each slash. On hit, the target takes slashing damage equal to 1d6 + the ability modifier used for the attack."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you can create one additional slash for each slot level above 2nd."]],"ms":["arcane","primal"]},{"k":"sp-crimsonpoison","n":"Crimson Poison","l":1,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":293,"ct":"1 bonus action","rg":"Self","cp":"S, M (a melee weapon worth at least 1 sp and a splash of your blood worth up to 5 hit points, which the spell consumes)","d":"1 minute","b":[["p","You invest your life force into an ichorous crimson coating on a weapon you are holding. The next 3 times you hit a creature with the weapon, you deal additional acid damage equal to the hit points expended. The spell then ends. If you don't hit a creature 3 times within the spell's duration, the blood dries, becoming nonmagical and harmless."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can expend 1 additional point for each slot level above 1st, up to a maximum of 10 hit points at 6th level."]],"bm":1},{"k":"sp-crimsontide","n":"Crimson Tide","l":3,"s":"Conjuration","sa":"CON","c":["Occultist","Wizard"],"bk":"llb","p":293,"ct":"1 action","rg":"Self (15-foot radius)","cp":"S, M (a splash of your blood worth at least 10 hit points, which the spell consumes)","d":"1 round","b":[["p","You unleash a sweeping tide of blood along the ground, transforming the terrain into difficult terrain for all creatures but yourself until the start of your next turn. Each creature in the area when you cast the spell must make a Dexterity saving throw. A creature takes 6d6 necrotic damage on a failure or half as much on a success."],["p","At the start of your next turn, the tide recedes as the spell ends, collecting the blood and returning it to you, restoring the 10 hit points used to cast the spell."]],"bm":1},{"k":"sp-cripplingagony","n":"Crippling Agony","l":1,"s":"Necromancy","sa":"NEC","c":["Occultist","Spellblade"],"bk":"ll","p":220,"ct":"1 action.","rg":"60 feet","cp":"V, S, M (a joint bone)","d":"Concentration, up to 1 minute","b":[["p","You can inflict crippling agony on one creature you can see within range. The target must succeed on a Constitution saving throw or become crippled with horrific pain. Whenever the target moves more than half of its speed or takes any action, it takes 1d6 necrotic damage."],["p","The target can repeat the saving throw, ending the spell on a success."]],"con":1,"ms":["arcane"],"also":[["cc",131]]},{"k":"sp-cruelpuppetry","n":"Cruel Puppetry","l":3,"s":"Necromancy","sa":"NEC","c":["Occultist"],"bk":"ll","p":220,"ct":"1 action","rg":"120 feet","cp":"V, S, M (a small humanoid doll worth at least 5 gp and something from the target creature—such as blood, hair, or scales—both of which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You attempt to bind a creature's soul to a doll, forging a sympathetic link between the two. The target must make a Charisma saving throw. On a failure, the creature becomes bound to the doll. On a success, the creature is not bound and the spell ends."],["p","When a target first fails its save and as an action on subsequent turns for the duration, you can perform one of the following actions:"],["li","Restrain. Hold the doll still, causing the creature to be restrained until start of your next turn."],["li","Move. Force the doll to move, causing the creature to move 15 feet in a direction of your choice it is able to move."],["li","Attack. Force the doll to swing its arm, causing the creature to make a melee weapon attack against a creature of your choice within its reach."],["li","Stab! Stab the doll, dealing 4d6 piercing damage to the target."],["li","Rip! Rip the doll in half, dealing 4d12 necrotic damage to the target, destroying the doll, and ending the spell."],["p","Each time you use your action to manipulate the doll, the target can repeat its saving throw afterward at disadvantage. On a success, the spell ends. Once a creature has been targeted by this spell, it cannot be targeted again for 24 hours."]],"h":[["p","At Higher Levels. When cast with a spell slot of 5th level or higher, the range of the spell becomes unlimited, as long as the target is on the same plane as the caster."]],"con":1,"ms":["arcane"],"also":[["cc",132]]},{"k":"sp-crushingsingularity","n":"Crushing Singularity","l":3,"s":"Transmutation","sa":"TRA","c":["Spellblade","Wizard"],"bk":"ll","p":220,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"1 round","b":[["p","You create an overwhelming gravitational singularity at a point within range, lasting until the start of your next turn. When you cast this spell, each creature within 15 feet of the point must make a Strength saving throw. On a failure, a creature is pulled to the closest available space adjacent to the singularity and takes 6d6 bludgeoning damage. On a success, it takes half damage and is not pulled."],["p","While within 15 feet of the singularity, any attempt to move away costs twice as much movement. If a creature ends its turn within 15 feet of the singularity, it must make a Strength saving throw. On a failure, it takes 2d6 bludgeoning damage and is dragged back to the closest available spot adjacent to the singularity."]],"h":[["p","At Higher Levels. When you cast this spell using a spell lot of 4th level or higher, the damage increases by 1d6 for each level above 3rd."]],"ms":["arcane"],"also":[["cc",132]]},{"k":"sp-crystalgate","n":"Crystal Gate","l":7,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":546,"ct":"10 minutes","rg":"20 feet","cp":"V, S, M (an item or a willing creature from the destination)","d":"6 hours","b":[["p","You and up to eight willing creatures within range fall unconscious for the spell’s duration and experience visions of another world. This can have two outcomes depending on the nature of the other world:"],["li","The target world is another reality, divested from the Material Plane, connected to Somnus Domina through the threads of time. This can be an alternate world layer such as the Cauldron or Radiant Spiral."],["li","The target world can be the same as yours, but at another point in time - the object or person used to cast it must be displaced in time, and this spell results in its targets being adjusted to the target’s relative correct place in time."],["li","The target world is another plane within Somnus Domina’s cosmology, which might be barred from entry by some means."],["li","If the spell reaches its full duration, the visions conclude with each of you witnessing the shattering of a crystal veil separating realities. The spell then ends with you mentally and physically transported to the world that was in the visions."],["p","To cast this spell, you must have a magic item or object of importance that originated from the world you wish to reach. If it is another reality, you must be aware of the world’s existence, even if you don’t know the world’s name. Your destination in the other world is a safe location within 1 mile of where the item was created or somewhere relevant to it. Alternatively, you can cast the spell if one of the affected creatures was born on the other world, which causes your destination to be a safe location within 1 mile of where that creature was born."],["p","The spell ends early for a creature if that creature takes any damage, and the creature isn’t transported to the destination. If you take any damage, the spell ends for you and all the other creatures, with none of you being transported."],["p","If you fail the eidomancy burn caused by casting this spell, the spell also ends without effect."]],"leg":1,"g":["Eidomancy"]},{"k":"sp-crystalnightmare","n":"Crystal Nightmare","l":9,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":546,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a gemstone worth at least 1500 gp, which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","Choose one creature within range, who you attempt to trap in a demiplane made of complex crystal formations and maddening infinite reflections. They must make a Charisma saving throw: on a failed save, they are banished to this demiplane, where they are suspended in mid-air and all magical effects on or originating from them end or are suppressed, and each time they attempt to cast a spell you may roll an ability check against them as if you had cast counterspell to prevent it."],["p","While within this dimension they must make an Intelligence saving throw at the start of each of their turns, taking 4d10 psychic damage on a failed save from the maddening environment. Creatures with an Intelligence score equal to or less than half of yours automatically fail this save. A creature that succeeds this save three times is released from the spell and transported back. A creature is also freed if they target themselves with the banishment spell or the area around them with any spell that negates or nullifies magic (such as dispel magic or an antimagic field). Spells that allow teleportation or planar transport have a 50% chance of automatically failing. Otherwise, a creature is only freed when the spell ends or they are reduced to 0 hit points."],["p","When a creature returns from this demiplane they reappear in the same location they vanished from, or in the closest unoccupied space. A creature that returns due to being reduced to 0 hit points is put in a state of suspended animation and trapped in a fist-sized gemstone in your possession, which only breaks and releases the creature if you use an action to do so or a spell such as dispel magic negates it (as if it were a 9th-level spell). While in possession of this gemstone, once per day you may touch it and ask the creature’s mind a question, and the creature must make an Intelligence saving throw. On a failure you learn everything the creature knows that may have been used as an answer."]],"con":1,"g":["Altissima-Cor’s Arcane Arts"]},{"k":"sp-curse","n":"Curse","l":1,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":547,"ct":"1 bonus action","rg":"90 feet","cp":"V, S, M (the petrified eye of a newt)","d":"Concentration, up to 1 hour","b":[["p","You place a curse on a creature that you can see within range, who is cursed for the spell’s duration. While cursed this way you deal an extra 1d6 necrotic damage to the target whenever you hit them with an attack."],["p","Also, choose one of the following debilitation options when you cast the spell:"],["li","Choose one ability when you cast the spell. The target has disadvantage on ability checks made with the chosen ability."],["li","Choose one ability score when you cast the spell. The first time a target makes a saving throw of that type after being targeted by the spell, they have disadvantage on the roll."],["li","Choose melee or ranged attacks. The target has disadvantage on the first instance they make an attack of your chosen type each turn."],["p","If the target drops to 0 hit points before this spell ends, you can use a bonus action on a subsequent turn of yours to curse a new creature."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd level or higher, choose one of the following effects for each slot level above 2nd:"],["li","You may choose one additional debilitation option. All targets suffer the same debilitation option choices."],["li","(2 slot levels) You may choose one additional target within range to be affected by this spell. The bonus action used to move the curse to a new creature can reassign any instances of the curse not currently targeting a creature."],["li","(2 slot levels) The spell’s duration increases to 8 hours."],["li","(4 slot levels) The spell’s duration increases to 24 hours."]],"con":1,"leg":1},{"k":"sp-curseofimpotence","n":"Curse of Impotence","l":5,"s":"Enchantment","sa":"ENC","c":["Occultist"],"bk":"ll","p":221,"ct":"1 action","rg":"60 feet","cp":"V, S, M (something from the target creature—such as blood, hair, or scales—which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You curse a target creature, causing an overwhelming sense of powerlessness to wash over it. Any time it attempts any action which would deal damage, it must make a Wisdom saving throw. On a success, it takes action as normal. On a failure, it completes the action, but the action deals no damage to any targets."]],"con":1,"ms":["arcane"]},{"k":"sp-curseddragonspears","n":"Cursed Dragon Spears","l":3,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":547,"ct":"1 bonus action","rg":"Self","cp":"V, S, M (a small bar of obsidian coated in charcoal powder)","d":"10 minutes","b":[["p","You summon a series of glowing spears made of ash and obsidian that float around you for the duration of the spell. These spears are intangible until you reach for them. Once when you conjure them, and again on each of your turns as a bonus action, you can use them to make a melee spell attack against a creature within 5 feet of you, or a ranged spell attack against a target within 30 feet. On a hit, the target takes piercing damage equal to 2d8 plus your spellcasting ability modifier."],["p","Also, when you hit with one of these spears, you can invoke one of the following effects (which you choose for each hit). Any of these effects can be removed by spells and effects that remove curses:"],["p","Armor Break. If the creature has a bonus to AC caused by armor that isn’t natural armor, their bonus to AC from that armor suffers a -1 penalty for 1 hour. This effect can be inflicted multiple times."],["p","Burst Flare. The attack from the spear deals an extra 2d8 points of chromatic energy damage."],["p","Clumsy Step. The target’s movement speed is reduced to half until the start of your next turn."],["p","Strength Burn. The target must succeed a Strength saving throw or have disadvantage on attack rolls until the end of their next turn."],["p","Spell Skewer. If the target is concentrating on a spell, they must make a Concentration check against your spell save DC. On a failure, they lose concentration."],["p","Weakening Curse. The target must succeed a Charisma saving throw or be cursed for 1 minute. You have resistance to damage dealt by a creature cursed this way. A creature cursed by this effect can repeat the save at the end of each of their turns, ending the effect on a success."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, you can choose one of the following effects for each slot level above 3rd:"],["li","The spears gain a +1 enhancement bonus. You can take this effect up to four times, increasing the bonus by +1 each time after the first."],["li","(2 slot levels) When you make an attack with one of these spears, you make one additional attack with them as well."]],"g":["Chromatic Convocation"]},{"k":"sp-cursedtalon","n":"Cursed Talon","l":8,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":547,"ct":"1 action","rg":"Self","cp":"V, S, M (a crow’s claw with obsidian talons, which costs at least 500 gp)","d":"Concentration, up to 1 minute","b":[["p","You twist and mutate one of your arms to become demonic, complete with a large monstrous claw in place of your hand. Once on each of your turns as a bonus action, you can make a melee spell attack using your twisted arm to attack a creature within 10 feet of you, dealing 4d10 slashing damage and 4d10 psychic damage on a successful hit. These attacks score a critical hit on an attack roll of 19 or 20. When you hit a creature with this attack, you regain hit points equal to the psychic damage you deal."]],"con":1,"g":["Daemoturgy"]},{"k":"sp-dancingobject","n":"Dancing Object","l":2,"s":"Transmutation","sa":"TRA","c":["Bard","Inventor","Occultist","Sorcerer","Wizard"],"bk":"ll","p":221,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You bring a Tiny nonmagical object that is not being worn or carried to life. The object uses the following stats:"],["p","Dancing Object"],["p","Tiny Construct"],["p","Armor Class 18"],["p","Hit Points 20"],["p","Speed 30 ft., fly 30 ft. (hover)"],["tbl",[["STR","DEX","CON","INT","WIS","CHA"],["4 (-3)","18 (+4) 10 (+0) 3 (-4)","3 (-4)","1 (-5)"]]],["p","Actions"],["p","Slam. Melee Weapon Attack: your spellcasting attack modifier"],["p","to hit, reach 5 ft., one target. Hit: 1d4 + your spellcasting"],["p","modifier damage."],["p","If the object is a weapon, it deals the weapon’s damage dice + your Spellcasting modifier of the weapon’s damage type instead. The spell can only animate one-handed weapons without the special property this way."],["p","As a bonus action, you can mentally command the animated object as long as it is within 60 feet of you. You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete."],["p","If the object is securely attached to a surface or a larger object, such as a chain bolted to a wall, its speed is 0. It has blindsight with a radius of 30 feet and is blind beyond that distance. When the animated object drops to 0 hit points, it reverts to its original object form, and any remaining damage carries over to its original object form."]],"rv":1,"con":1,"ms":["arcane"],"also":[["cc",128]]},{"k":"sp-dancingwave","n":"Dancing Wave","l":2,"s":"Conjuration","sa":"CON","c":["Druid","Occultist","Sorcerer","Wizard"],"bk":"ll","p":221,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You summon a surging mass of water into existence at a point on the ground or in water within range. The mass of water remains cohesive and fills a 5-foot radius, though it is only 3 feet deep. The area is difficult terrain for any creature without a swimming speed."],["p","As a bonus action for the duration, you can move the wave up to 30 feet along the surface in any direction. If it enters a creature's space, that creature must make a Strength saving throw or take 2d6 bludgeoning damage and be knocked prone. A creature automatically fails this saving throw if it is already prone. The wave can only slam into one creature on a turn."]],"con":1,"ms":["arcane","primal"],"also":[["cc",132]]},{"k":"sp-deadlytarget","n":"Deadly Target","l":3,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":547,"ct":"1 action","rg":"Touch (60 feet)","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You touch one willing creature (apart from yourself) and choose one target within the spell’s range. The creature you touched is granted a bonus equal to your spellcasting ability modifier on all attack rolls they make against the target you choose until the start of your next turn. On each of your turns, you can use your bonus action to designate a new target."]],"con":1,"g":["Sky-Keeper’s Arcana"]},{"k":"sp-decayingtouch","n":"Decaying Touch","l":0,"s":"Necromancy","sa":"NEC","c":["Druid","Occultist","Sorcerer","Spellblade","Warlock"],"bk":"ll","p":222,"ct":"1 action","rg":"Touch","cp":"V, S, M (powdered remains of a dead animal)","d":"Instantaneous","b":[["p","You wreath your hand in necrotic decay, causing anything you touch to wither and die. Make a melee spell attack against a creature or object within range. On a hit, the target takes 1d6 necrotic damage and starts to flake and decay. The first time it takes damage from another source before the start of your next turn, it takes an additional 1d6 necrotic damage. Targets immune to diseases are immune to this effect."],["p","The both the initial and secondary damage of the spell increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6)."]],"ms":["arcane"]},{"k":"sp-dedicatedenemy","n":"Dedicated Enemy","l":1,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":548,"ct":"1 bonus action","rg":"30 feet","cp":"V","d":"Concentration, up to 1 minute","b":[["p","You attempt to compel a creature into a duel. One creature that you can see within range must make a Wisdom saving throw. On a failed save, the creature is drawn to you, compelled by your divine demand. For the duration, they have disadvantage on attack rolls against creatures other than you, and must make a Wisdom saving throw each time they attempt to move to a space that is more than 30 feet away from you. If they succeed this Wisdom saving throw, this spell doesn’t restrict the target’s movement for that turn."],["p","The spell ends if you attack any other creature, if you cast a spell that targets a hostile creature other than the target, if a creature friendly to you hits the target or casts a harmful spell against them, or if you end your turn more than 30 feet away from the target."]],"con":1,"leg":1},{"k":"sp-deflect","n":"Deflect","l":0,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":548,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"1 round","b":[["p","You extend your hand and trace a sigil of warding in the air. Until the end of your next turn, you have resistance against bludgeoning, piercing, and slashing damage dealt by weapon attacks."]],"leg":1},{"k":"sp-deglovecreature","n":"Deglove Creature","l":5,"s":"Necromancy","sa":"NEC","c":["Occultist","Spellblade"],"bk":"ll","p":222,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a finger bone)","d":"Instantaneous","b":[["p","You point at a creature within range, and attempt to make its skeleton rip free of its body. The creature must make a Constitution saving throw. The target takes 7d10 + 7 necrotic damage on a failed save, or half as much damage on a successful one."],["p","If this damage kills the target, its flesh sloughs of its skeleton, collapsing into a pile. Its skeleton emerges and becomes a Skeleton (Basic Rules, pg. 152), hostile to all living creatures, and attacks the closest target."]],"ms":["arcane"]},{"k":"sp-delvemind","n":"Delve Mind","l":3,"s":"Psionic","sa":"PSI","c":["Psion"],"bk":"cc","p":132,"ct":"1 action","rg":"60 feet","cp":"S","d":"Concentration, up to 1 minute","b":[["p","You delve into a creature’s mind, forcing it to make an Intelligence saving throw. On a failure, for the duration or until you end the spell you gain access to its memories from the past 12 hours, and are able to recall things it remembers as if they are your own memories, but these memories contain only things the target creature remembers."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can delve an additional 12 hours further back in the creature’s memories for each slot level above 3rd."]],"con":1,"ci":1},{"k":"sp-desperateretreat","n":"Desperate Retreat","l":7,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":548,"ct":"1 reaction taken when you are hit by an attack you can see, before damage is rolled","rg":"60 feet","cp":"V","d":"Instantaneous","b":[["p","In response to the triggering attack, you cause your body to be covered in flames and violently explode, causing everything within 20 feet of your body to make a Dexterity saving throw, taking 10d8 fire damage on a failed save, and half as much on a successful one. Meanwhile, you teleport unharmed to an unoccupied space you can see within 60 feet, and are stunned until the end of the current turn. You do not take damage from the triggering hit, but must choose to use this spell before damage is rolled or effects provoked by being hit are resolved."]],"g":["Nine Branch Arts"]},{"k":"sp-devourshadow","n":"Devour Shadow","l":4,"s":"Necromancy","sa":"NEC","c":["Occultist","Spellblade","Warlock","Wizard"],"bk":"ll","p":222,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to a minute.","b":[["p","Your shadow elongates into a horrifying abomination and attempts to consume the shadow of a creature you choose in range. The target must make a Charisma saving throw. On a failure, the target's shadow is devoured. It takes 6d6 necrotic damage and is magically weakened, subtracting 1d4 from its attack rolls, saving throws, and ability checks for the duration, and adding 1d4 to your attack rolls, saving throws, and ability checks for the duration. On a success, the target takes half as much damage and suffers no other effects."],["p","If either you or the target has no shadow, the spell fails. If the target's shadow is consumed, they have no shadow until the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell with a 5th-level spell slot or higher, you can target an additional creature for each spell slot level above 4th. The bonus you gain from consuming shadows does not increase beyond 1d4, even if you consume multiple shadows."]],"con":1,"ms":["arcane"]},{"k":"sp-devouringdarkness","n":"Devouring Darkness","l":5,"s":"Necromancy","sa":"NEC","c":["Occultist","Spellblade","Warlock","Wizard"],"bk":"ll","p":222,"ct":"1 action","rg":"Self (20-foot radius)","cp":"V, S","d":"Instantaneous","b":[["p","Dark tendrils burst out from you in all directions. Each creature of your choice within 20 feet must make a Constitution saving throw. On a failure, a creature takes 6d8 necrotic damage, and you can pull them in a straight line to an empty space within 5 feet of you. On a success, it takes half as much damage and is not pulled."],["p","You regain hit points equal to one quarter (rounded down) of the necrotic damage taken by all targets affected by the spell."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th."]],"ms":["arcane"],"also":[["cc",132]]},{"k":"sp-devouringmist","n":"Devouring Mist","l":7,"s":"Necromancy","sa":"NEC","c":["Occultist","Warlock","Wizard"],"bk":"llb","p":293,"ct":"1 action","rg":"60 feet","cp":"S, M (a splash of your blood worth at least 15 hit points, which the spell consumes)","d":"1 round","b":[["p","You transform into a swirling mist of blood with a 15-foot radius. While in this form, you cannot take any actions, but you gain the following benefits:"],["li","You have a flying speed of 60 feet, with hover."],["li","You can enter and occupy other creatures' spaces, and do not treat them as difficult terrain."],["li","You can pass through small gaps and cracks without squeezing."],["li","You have resistance to all damage except radiant, force, and psychic damage."],["p","The first time you move into a creature's space, it must make a Constitution saving throw. On a failure, it takes 6d8 necrotic damage and you regain 10 hit points. On a success, it takes half as much damage, and you regain only 5 hit points. You can regain a total of 50 hit points through this spell, after which you no longer regain hit points from this effect."],["p","At the start of your next turn, you return to your previous form. You fall if still aloft unless you have a way to stop your fall."]],"bm":1},{"k":"sp-dig","n":"Dig","l":3,"s":"Transmutation","sa":"TRA","c":["Druid","Wizard"],"bk":"ll","p":222,"ct":"1 action","rg":"Self","cp":"V, S, M (a mole's claw)","d":"1 round","b":[["p","Until the end of your turn, you gain a burrowing speed of 30 feet. You can move through dirt, sand, or clay with this movement, and leave behind a tunnel equal to your size that remains stable for 1 minute (after which it may remain or collapse based on the properties of the ground moved through). You cannot move through stone (natural or constructed) with this movement."]],"ms":["arcane","primal"]},{"k":"sp-dimensioncutter","n":"Dimension Cutter","l":4,"s":"Conjuration","sa":"CON","c":["Ranger","Spellblade","Wizard"],"bk":"ll","p":223,"ct":"1 action","rg":"Self (15-foot cone)","cp":"V, S, M (a melee weapon with which you are proficient worth at least 1 sp)","d":"Instantaneous","b":[["p","You flourish the weapon used in the casting and sweep it through the air, slicing a rift through dimensions. Each creature in a 15-foot cone takes 6d6 force damage. This ignores total cover and strikes creatures in the ethereal plane as well as the material plane."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th Level or higher, it deals an additional 1d6 damage to each target for each slot level above 4th."]],"also":[["cc",133]]},{"k":"sp-direrestraints","n":"Dire Restraints","l":9,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":548,"ct":"1 bonus action","rg":"Self (30 feet)","cp":"V, S, M (a bracelet made of ivory chain links worth at least 5,000 gp)","d":"Concentration, up to 10 minutes","b":[["p","You create several winding snake-like sharpened chains of ivory that curl around you for the spell’s duration, the tips of which form long white blades. You can use your bonus action to command these chains to make three melee spell attacks against creatures of your choice within 30 feet of you. On a hit, a creature takes 3d10 piercing damage and 3d12 cold damage."],["p","If you target the same creature with two chains and hit with the first, then rather than make a spell attack with the second, in its place the target must make a Strength saving throw. On a failure, they are restrained, and a new chain is created to accommodate further attacks while the first is occupied. A restrained creature can attempt to break free by using their action to make a Strength check against your spell save DC, breaking free on a success.A creature that breaks free of these restraints or succeeds its Strength save cannot be bound by them again from this instance of the spell."],["p","You can only deal damage to a given creature once per turn using these spell attacks."]],"con":1,"g":["Altissima-Cor’s Arcane Arts"]},{"k":"sp-discombobulation","n":"Discombobulation","l":5,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":548,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","You choose a point within range and cause psychic energy to explode there. Each creature in a 20-foot radius sphere centered on that point must make an Intelligence saving throw. A creature with an Intelligence score of 2 or lower can’t be affected by this spell. A target takes 8d6 psychic damage on a failed save, or half as much damage on a successful one."],["p","After a failed save, a target has muddled thoughts for 1 minute. During that time, they roll a d6 and subtract the number rolled from all its attack rolls and ability checks, as well as its Constitution saving throws to maintain concentration. The target can make an Intelligence saving throw at the end of each of their turns, ending the effect on themself on a success."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","The damage increases by 1d6."],["li","The radius of the sphere increases by 10 feet."],["li","(2 slot levels) The die subtracted from attack rolls, ability checks, and concentration checks becomes a d8."]],"leg":1},{"k":"sp-disorient","n":"Disorient","l":2,"s":"Illusion","sa":"ILL","c":["Bard","Occultist","Spellblade","Wizard"],"bk":"ll","p":223,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a möbius strip)","d":"1 minute","b":[["p","You point at a creature you can see and flip its perception of reality. The target must pass a Wisdom saving throw or become disoriented. A disoriented creature has disadvantage on all attack rolls, and at the start of each of its turns, it moves 10 feet (up to its speed) in a random direction. Its speed then becomes zero until the start of its next turn."],["p","At the end of each of its turns, the target can make another Wisdom saving throw. On a success, the spell ends, but if the target fails by 5 or more, it falls prone."]],"ms":["arcane"],"also":[["cc",133]]},{"k":"sp-disorientingscatter","n":"Disorienting Scatter","l":3,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":548,"ct":"1 action","rg":"30 feet (60 feet)","cp":"V, S","d":"Instantaneous","b":[["p","Choose any number of willing creatures within 30 feet of you. Those creatures are teleported to an unoccupied space of your choice within 60 feet of you, and if they are paralyzed, restrained, or grappled, those effects end. You do not have to be able to see the targets or spaces they teleport to as long as you know they are there. If something occupies the space you choose, the target is shunted to the nearest unoccupied space."],["p","Creatures who are teleported must succeed on a Constitution saving throw with a DC equal to 8 + the level you cast the spell at. On a failure, they are stunned until the end of their next turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the 30 foot and 60 foot ranges double at each slot level above 3rd (becoming 60/120 ft. at 4th, 120/240 ft. at 5th, etc.,)."]],"g":["Nine Branch Arts"]},{"k":"sp-dispelconstruct","n":"Dispel Construct","l":3,"s":"Abjuration","sa":"ABJ","c":["Inventor"],"bk":"ll","p":224,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"1 minute","b":[["p","You attempt to purge the magic animating a construct within range, rendering it inert. The target takes 4d10 force damage and must make a Constitution saving throw. On a failure, it becomes stunned for the duration, and if it has less than 50 hit points remaining, it is reduced to 0 hit points."],["p","At the end of each of its turns, the target can make another Constitution saving throw. On a success, the spell ends on the target."]],"ms":["arcane"],"also":[["cc",133]]},{"k":"sp-divideself","n":"Divide Self","l":5,"s":"Illusion","sa":"ILL","c":["Occultist","Sorcerer","Wizard"],"bk":"ll","p":224,"ct":"1 bonus action","rg":"Self","cp":"S","d":"Concentration, 1 minute","b":[["p","You create an exact duplicate of yourself in an empty space you can see within 30 feet. At the start of each of your turns for the duration, you can switch places with your duplicate."],["p","The duplicate has all of your stats, abilities, and equipment (including magic items). It acts on your initiative and takes its own actions. You and the duplicate share concentration on this spell, and if either of you lose concentration, the spell ends."],["p","Your current hit points are divided between you and the duplicate, and you share all other resources and abilities (including limited-use items). Usage by either you or the duplicate depletes a resource for both of you."],["p","Your duplicate can take any action you can take, but it can deal a maximum of 15 damage on its turn. Any additional damage is reduced to 0, and damage applied to multiple targets is split between them equally until the maximum is reached."],["p","If either you or the duplicate is reduced to 0 hit points, the spell ends and you become the surviving copy. If you and the duplicate are both present when the spell ends, you decide which copy you become, and the other vanishes. Any items duplicated by the spell vanish."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you and the duplicate both start with 15 additional hit points (up to your current hit points prior to casting), and the maximum damage the duplicate can do during its turn increases by 10 for each slot level above 5th."]],"con":1,"ms":["arcane","psionic"],"also":[["cc",133]]},{"k":"sp-divinearmor","n":"Divine Armor","l":7,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":549,"ct":"1 action","rg":"Self","cp":"V","d":"1 minute","b":[["p","Your body is immediately reinforced by a layer of ice which is comfortable and flexible to you, but rigid and protective against others. You gain 15d10 temporary hit points. If the result is greater than your hit point maximum, you gain a number of temporary hit points equal to that instead."],["p","While you have these temporary hit points you are resistant to piercing, slashing, and bludgeoning damage, and the first time each turn a creature hits you with a melee weapon attack they take 2d10 cold damage. You are, however, vulnerable to fire damage while under this effect."],["p","This effect ends when you lose these temporary hit points, and they automatically vanish when the spell’s duration ends."]],"g":["Altissima-Cor’s Arcane Arts"]},{"k":"sp-divinedescent","n":"Divine Descent","l":8,"s":"Evocation","sa":"EVO","c":["Cleric"],"bk":"ll","p":223,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Concentration, up to 3 rounds","b":[["p","You call down a spectral angelic avatar which slowly descends from the sky toward a target point within range. The avatar fills a 30-foot-radius, 60-foot high cylinder with bright light. When you cast the spell and at the start of your next turn, you can choose to either heal all creatures within the light, restoring 4d8 hit points to creatures of your choice that are not undead or fiends within it, or burn all creatures within the light, forcing each one to make a Constitution saving throw, taking 4d8 radiant damage on a failed save or half as much on a success."],["p","At the start of your turn on the third and final turn of the spell, the spell's effects are doubled, either restoring 8d8 hit points or dealing 8d8 radiant damage."]],"con":1,"ms":["divine"]},{"k":"sp-divinefrost","n":"Divine Frost","l":5,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":549,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a preserved or frozen water lily)","d":"Concentration, up to 1","b":[["p","minute Choose one creature within range."],["p","Their body and weapons become coated in a radiant layer of frost, pouring like smoke from their body. For the spell’s duration, that creature’s weapon attacks deal an extra 2d10 cold damage, and they become immune to cold and radiant damage. The target cannot be grappled or restrained for the duration, and any creature who attempts to do so automatically fails. Any creature that ends their turn in direct contact with the target during the spell’s duration takes 2d10 cold damage."]],"h":[["p","At Higher Levels. When you cast this spell at 7th level or higher, you can target one additional creature within range for every two slot levels above 5th."],["p","54 9"]],"con":1,"g":["Altissima-Cor’s Arcane Arts"]},{"k":"sp-divinejudgment","n":"Divine Judgment","l":2,"s":"Evocation","sa":"EVO","c":["Cleric","Paladin"],"bk":"ll","p":223,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","A brilliant sword of radiant energy forms above the target point and slams down in an explosion of divine power. Each creature in a 10-foot-radius, 30-foot high cylinder centered on the target point must make a Dexterity saving throw. On a failure, a creature takes 2d8 radiant damage, and 2d8 additional radiant damage if it is an undead or fiend. On a success, it takes half as much damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the base damage increases by 1d8 for each slot level above 2nd."],["p","Alignment Powers"],["p","If your DM uses alignment for creatures, they can optionally"],["p","rule that the bonus damage applies all creature types as long"],["p","as the creature is of the opposite moral alignment of the"],["p","caster (evil to good or good to evil). As not all settings use"],["p","strict alignment, this is a variant rule at the GM’s discretion."]],"ms":["divine"]},{"k":"sp-divineweapon","n":"Divine Weapon","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":549,"ct":"1 bonus action","rg":"Touch","cp":"V, S","d":"Concentration, up to 1 hour","b":[["p","You imbue a weapon you touch with holy power. Until the spell ends, the weapon emits bright light in a 30-foot radius and dim light for an additional 30 feet. In addition, weapon attacks made with it deal an extra 2d8 radiant damage on a hit. If the weapon isn’t already a magical weapon, it becomes one for the duration."],["p","As a bonus action on your turn, you can dismiss this spell and cause the weapon to emit a burst of radiance. Each creature of your choice that you can see within 30 feet of the weapon must make a Constitution saving throw. On a failed save, the creature takes 4d8 radiant damage and is blinded for 1 minute. On a successful save, the creature takes half as much damage and isn’t blinded. At the end of each of their turns, a blinded creature can make a Constitution saving throw, ending the effect on themself on a success."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of"],["p","6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","The spell’s duration increases to 8 hours (1 slot level) or 24 hours (2 slot levels)."],["li","(2 slot levels) The spell’s additional radiant damage increases by 1d8, and its radiant damage from its burst of radiance increases"],["p","by 2d6."],["li","The first time each round that the enchanted weapon deals damage to a fiend, it deals an additional 1d8 radiant damage."]],"con":1,"leg":1},{"k":"sp-dragonsurge","n":"Dragon Surge","l":2,"s":"Transmutation","sa":"TRA","c":["Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":224,"ct":"1 action","rg":"Self","cp":"V, S","d":"Instantaneous","b":[["p","You channel elemental power to form draconic wings, selecting one of the following damage types: acid, cold, fire, lightning, or poison. Each creature within 10 feet of you must make a Dexterity saving throw as the wings manifest, taking 2d8 damage of that chosen type on a failure, or half as much on a success. You gain a flying speed of 30 feet until the end of your turn, after which the wings fade away."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 and the flying speed increases by 10 feet for each slot level above 2nd."]],"ms":["arcane","primal"]},{"k":"sp-dragonskin","n":"Dragonskin","l":3,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":550,"ct":"1 action","rg":"Self","cp":"V, S, M (the scale of a dragon who shares the resis-tance you wish to gain)","d":"Concentration, up to 1 hour","b":[["p","Your skin becomes coated in draconic scales of a type you choose. Until the spell ends, your AC cannot be less than 16, regardless of what armor you’re wearing. Depending on the type of dragon scales you choose, you gain resistance to the corresponding damage type. Furthermore, if you are subjected to the breath weapon of a dragon matching the scale type you choose, you may use your reaction to automatically succeed on your saving throws against that breath weapon."],["tbl",[["Color","Resistance"],["Amethyst","Force"],["Black, copper","Acid"],["Blue, bronze","Lightning"],["Brass, gold, red","Fire"],["Skull, topaz","Necrotic"],["Emerald","Psychic"],["Green","Poison"],["Crystal, moonstone, platinum","Radiant"],["Sapphire","Thunder"],["Silver, white","Cold"]]]],"rv":1,"con":1},{"k":"sp-dreadsurge","n":"Dread Surge","l":5,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":550,"ct":"1 action","rg":"60 feet","cp":"V, M (a broken bone and a square of black silk)","d":"Isntantaneous","b":[["p","You send ribbons of negative energy at one creature you can see within range. Unless the target is undead, they must make a Constitution saving throw, taking 5d12 necrotic damage on a failed save, or half as much damage on a successful one. A target killed by this damage rises up as a zombie at the start of your next turn. The zombie pursues whatever creature they can see that is closest to them. Statistics for the zombie are in the Monster Manual."],["p","If you target an undead with this spell, the target doesn’t make a saving throw. Instead, roll 5d12. The target gains half the total as temporary hit points."]],"h":[["p","At Higher Levels. If you cast this spell using a slot level of 6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","If the target is undead they are still affected, but take half as much damage. This damage is unaffected by resistances or immunities. An undead killed by this effect still rises as a zombie, but under your thrall as described."],["li","The necrotic damage increases by 1d12 (as does the amount an undead would gain as temporary hit points.)"],["li","(2 slot levels) You can target one additional creature within range."]],"leg":1},{"k":"sp-dreamwalk","n":"Dream Walk","l":6,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":550,"ct":"1 hour","rg":"Self","cp":"V, S, M (a dreamcatcher made of silver and gold thread, worth at least 500 gp)","d":"7 hours","b":[["p","You fall into a deep sleep, remaining unconscious for the duration, from which you cannot be awakened easily. While asleep, your spirit separates from your body, appearing within 50 feet, and can move about freely. Your spirit form cannot take actions except the Hide and Disengage action, and checks made to resist being grappled or restrained. Your spirit form’s AC is equal to 10 + your Dexterity + your spellcasting ability modifier, and is capable of moving up to your movement speed each round. It exists on the Ethereal Plane but is able to see and hear anything on the Material Plane around it, and can pass through nonmagical objects and walls at will. While in spirit form you always know the distance and direction of your body, and can use your action to project your senses back to it - hearing, smelling and feeling anything it is feeling (but not seeing unless its eyes are opened)."],["p","Creatures that can see into the Ethereal Plane, can see magical auras, or can see invisible creatures, are able to see and interact with your spirit form, even from the Material Plane."],["p","If your body or spirit form takes damage, you must make a Concentration check as if concentrating on this spell. On a failure, the spell ends. All damage your spirit form takes is taken as psychic damage by your body and mind. If the spell ends this way, your spirit shunts back to your body and you awaken as the spell ends, taking 1d10 psychic damage for every 100 feet between your body and spirit form. If you are reduced to 0 hit points while in spirit form, the spell ends and your spirit snaps back to your body, instantly causing you to fail one death save."],["p","If the spell’s duration runs its course, your spirit is pulled back to your body without issue and you continue your period of rest until you would naturally awaken, with this spell’s duration counting as time spent resting. If you are pulled back by force, the rest you were trying to take is interrupted."],["p","If you are separated from your body, you can spend 10 minutes concentrating on returning to it by engaging in an uninterrupted meditation. Upon completion the spell ends harmlessly and your body awakens, your spirit having returned to it."]]},{"k":"sp-drowningwave","n":"Drowning Wave","l":3,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":551,"ct":"1 action","rg":"120 feet","cp":"V, S, M (a drop of water)","d":"Instantaneous","b":[["p","You conjure up a wave of water that crashes down on an area within range. The area can be up to 30 feet long, up to 10 feet wide, and up to 10 feet tall. Each creature in that area must make a Dexterity saving throw. On a failed save, a creature takes 4d8 bludgeoning damage and is knocked prone. On a successful save, a creature takes half as much damage and isn’t knocked prone. The water then spreads out across the ground in all directions, extinguishing unprotected flames in its area and within 30 feet of it, and then it vanishes."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can choose one of the following effects for each slot level above 3rd:"],["li","The damage increases by 1d8."],["li","The wave’s length, height, or width increases by 10 feet."]],"leg":1},{"k":"sp-dustcyclone","n":"Dust Cyclone","l":2,"s":"Conjuration","sa":"CON","c":["Druid","Ranger","Sorcerer","Wizard"],"bk":"ll","p":224,"ct":"1 action","rg":"60 feet (5-foot radius)","cp":"V, S, M (a pinch of dust)","d":"Concentration, up to 1 minute","b":[["p","A small cyclone whips up at a point you can see on the ground within range. The cyclone is a 5-foot-radius, 30-foot-high cylinder centered on that point."],["p","Any creature that starts its turn within the radius of the dust cyclone or enters its radius for the first time during its turn must make a Strength saving throw. On a failed save, the creature takes 1d12 bludgeoning damage is pushed 5 feet away from the center. On a successful save, the creature takes half as much damage isn’t pushed."],["p","As a bonus action, you can move the dust cyclone up 30 feet in any direction. The first time you pass the dust cyclone’s radius through a creature, that creature must make the saving throw against the dust cyclone’s damage and are pushed out its way on failure. You can continue to move the dust cyclone, but its strength is exhausted until the end of your turn and subsequent creatures an unaffected by it passing through them."],["p","If the dust cyclone moves over sand, dust, loose dirt, or small gravel, it sucks up the material and heavily obscures its radius until the start of your next turn."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-earthgeyser","n":"Earth Geyser","l":3,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":551,"ct":"1 action","rg":"120 feet","cp":"V, S, M (a piece of obsidian)","d":"Instantaneous","b":[["p","Choose a point you can see on the ground within range. A fountain of churned earth and stone erupts in a 20-foot cube centered on that point. Each creature in that area must make a Dexterity saving throw. A creature takes 3d12 bludgeoning damage on a failed save, or half as much damage on a successful one. Additionally, the ground in that area becomes difficult terrain until cleared. Each 5-foot square portion of the area requires at least 1 minute to clear by hand."]],"h":[["p","At Higher Levels. When you you cast this spell at 4th level or higher, you can choose one of the following effects for each slot level above 3rd:"],["li","The size of the cube increases by 5 feet."],["li","The spell’s damage increases by 1d12."]],"leg":1},{"k":"sp-earthripple","n":"Earth Ripple","l":2,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":225,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You cause the earth to deform at a point you can see within range. Every creature within 10 feet must make a Dexterity saving throw. Choose one of the effects below, affecting each creature which fails its save."],["li","Sink. A creature is pulled into the earth, taking 1d8 bludgeoning damage and reducing its movement speed to zero until it or another creature within 5 feet spends an action to dig it free."],["li","Slam. A creature is pushed 5 feet in a direction of your choice by a wave of earth, taking 2d8 bludgeoning damage and falling prone."],["li","Impale. A creature takes 4d8 piercing damage."]],"ms":["arcane","primal"],"also":[["cc",133]]},{"k":"sp-eartheneruption","n":"Earthen Eruption","l":1,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":551,"ct":"1 action","rg":"10 feet","cp":"V, S","d":"Instantaneous","b":[["p","You cause a tremor in the ground within range. Each creature other than you in that area must make a Dexterity saving throw. On a failed save, a creature takes 1d6 bludgeoning damage and is knocked prone. If the ground in that area is loose earth or stone, it becomes difficult terrain until cleared, with each 5-foot square requiring at least 1 minute to clear by hand."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can choose one of the following options for each slot level above 1st:"],["li","The damage increases by 1d6."],["li","The spell’s range increases by 10 feet."],["li","Each creature that fails their saving throw is knocked 5 feet away from the center of the spell’s effects."]],"leg":1,"g":["Whisperwood Tome"]},{"k":"sp-earthengrasp","n":"Earthen Grasp","l":2,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":551,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a miniature hand sculpted from claw)","d":"Concentration, up to 1 minute","b":[["p","You choose a 5-foot square unoccupied space on the ground that you can see within range. A Medium hand made from compacted soil rises there and reaches for one creature you can see within 5 feet of it. The target must make a Strength saving throw. On a failed save, the target takes 2d6 bludgeoning damage and is restrained for the spell’s duration."],["p","As an action, you can cause the hand to crush the restrained target, which must make a Strength saving throw. The target takes 2d6 bludgeoning damage on a failed save, or half as much damage on a successful one."],["p","To break out, the restrained target can use their action to make a Strength check against your spell save DC. On a success, the target escapes and is no longer restrained by the hand."],["p","As an action, you can cause the hand to reach for a different creature or to move to a different unoccupied space within range. In either case, the hand releases a restrained target."]],"con":1,"leg":1},{"k":"sp-echoinglance","n":"Echoing Lance","l":4,"s":"Evocation","sa":"EVO","c":["Bard","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":225,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You emit a targeted burst of intense sonic energy at a creature within range. The target must make a Constitution saving throw. On a failure, it takes 3d8 thunder damage and is stunned for the duration. On a success, it takes half as much damage and isn’t stunned."],["p","At the end of each of its turns, the target can make another Constitution saving throw. On a success, the spell ends. On a failure, it takes an additional 1d8 thunder from the ongoing echoes of the sound."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the initial damage increases by 1d8 for each slot level above 4th."]],"con":1,"ms":["arcane"],"also":[["cc",133]]},{"k":"sp-eidomanticfeedback","n":"Eidomantic Feedback","l":4,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":552,"ct":"1 reaction, taken when a creature within range casts a spell","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","Your target experiences feedback from the spell they’re casting, causing their body to be wracked with pain. The target must make a Charisma saving throw. On a failure, they take 2d10 psychic damage, plus an extra 1d8 psychic damage for every level the spell was cast at above 1st. On a success they take half as much damage. If the spell they are casting requires concentration, this damage provokes a concentration check from them after the spell’s immediate effects resolve."]],"h":[["p","At Higher Levels. When you cast this spell at 5th level or higher, you can choose one additional creature within 60 feet of the target for each slot level above 4th. Each of these creatures makes a Dexterity saving throw, taking the same damage as your initial target on a failure, or none on a success."]],"g":["Sky-Keeper’s Arcana"]},{"k":"sp-eidomanticweapon","n":"Eidomantic Weapon","l":3,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":551,"ct":"1 bonus action","rg":"Touch","cp":"V, S","d":"Concentration, up to 10 minutes","b":[["p","You touch a nonmagical weapon and fill it with eidomantic energy, turning it into a magical weapon with a +2 bonus to attack and damage rolls. For the spell’s duration the weapon deals one additional damage die, its damage (and damage done by its ammunition) is considered eidolic and magical, and if you are wielding the weapon you can make one attack with it as a bonus action."],["p","You can also cast this spell on a magical weapon, but when you do the bonus to attack and damage rolls is reduced by 2."]],"h":[["p","At Higher Levels. When you cast this spell at 5th level or higher, you can choose one of the following effects for every two slot levels above 3rd:"],["li","The bonus to attack and damage rolls increases by 1 (to a maximum +4)"],["li","You can target one additional weapon you can touch."],["li","The weapon deals an additional damage die on a successful hit."]],"con":1,"g":["Eidomancy"]},{"k":"sp-electricarc-ll","n":"Electric Arc","l":0,"s":"Evocation","sa":"EVO","c":["Occultist","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":225,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You shoot a jolt of lightning at a creature you can see within range. Make a ranged spell attack against the target. On hit, the target takes 1d8 primary lightning damage and an arc of lightning jumps from the target to another creature within 15 feet, using the same attack roll, dealing 1d4 secondary lightning damage on hit."],["p","This spell’s damage increases by 1d8 primary and 1d4 secondary damage when you reach 5th level (2d8 and 2d4), 11th level (3d8 and 3d4), and 17th level (4d8 and 4d4)."]],"ms":["arcane"]},{"k":"sp-electricarc-retia","n":"Electric Arc","l":4,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":552,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a glass rod and piece of fur)","d":"Instantaneous","b":[["p","Electrical energy arcs from your fingertips at four creatures you choose within range who must each make a Dexterity saving throw. On a failure, they take 7d8 lightning damage."]],"h":[["p","At Higher Levels. When you cast this spell at 5th level or higher, you may target one additional creature for each slot level above 4th."]],"g":["Ossenheimer’s Memoirs"]},{"k":"sp-electricchain","n":"Electric Chain","l":0,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":552,"ct":"1 action","rg":"Self (15-foot radius)","cp":"V","d":"Instantaneous","b":[["p","You create a binding chain of lightning energy that strikes at one creature of your choice that you can see within 15 feet of you. The target must succeed on a Strength saving throw or be pulled up to 10 feet in a straight line toward you and then take 1d8 lightning damage if it is within 5 feet of you."],["p","This spell’s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8). The spell’s range also increases by 5 feet at each of these points (20 feet at 5th level, 25 feet at 11th level, and 30 feet at 17th level). At 11th level the chain can pull creatures 15 feet closer instead of 10."]],"leg":1},{"k":"sp-electrify","n":"Electrify","l":1,"s":"Evocation","sa":"EVO","c":["Occultist","Ranger","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":225,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"1 round","b":[["p","You channel lightning into your hands. The next time you hit a creature with a melee attack (including a melee spell attack) before the start of your next turn, the target takes 1d12 lightning damage and must make a Constitution saving throw. On a failed save, the target becomes stunned until the start of their next turn."],["p","The spell ends after dealing damage, or at the start of your next turn, whichever occurs first."]],"ms":["arcane","primal"],"also":[["cc",134]]},{"k":"sp-electrocute","n":"Electrocute","l":3,"s":"Evocation","sa":"EVO","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":226,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","A massive arc of lightning leaps from your hand to a target you can see within range. The target must make a Constitution saving throw. On a failed save, the target takes 4d12 lightning damage and is stunned until the start of your next turn. On a successful save, the target takes half as much damage and isn’t stunned."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d12 for each slot level above 3rd."]],"ms":["arcane","primal"],"also":[["cc",134]]},{"k":"sp-elementalbarrage","n":"Elemental Barrage","l":2,"s":"Transmutation","sa":"TRA","c":["Ranger","Spellblade"],"bk":"ll","p":226,"ct":"1 bonus action","rg":"Touch","cp":"V, M (a piece of ammunition)","d":"1 round","b":[["p","You touch of piece of ammunition and infuse it with chaotic elemental power. If that piece of ammunition is fired before the start of your next turn, it transforms into three elemental bolts, one each dealing fire, cold, and lightning damage."],["p","Make a weapon attack roll for each elemental bolt. You can fire all three at the same target or at different targets within the weapon's range. On a hit, each bolt deals elemental damage equal to the attack's normal damage, but of its elemental damage type."]],"ms":["arcane","primal"]},{"k":"sp-elementalexhalation","n":"Elemental Exhalation","l":2,"s":"Evocation","sa":"EVO","c":["Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":226,"ct":"1 action","rg":"20 foot cone","cp":"V, S, M (a fragment of a dragon’s scale)","d":"Instantaneous","b":[["p","You gather elemental power in your lungs, selecting one damage type out of acid, cold, fire, lightning, or poison, and then exhale it in a mighty gust of energy."],["p","Each creature in a 20-foot cone must make a Dexterity saving throw. On a failed save, a creature takes 3d8 damage of the chosen type, or half as much damage on a successful save."],["p","If you cannot breathe, have no mouth, or your mouth is currently covered, the spell fails."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each level above 2nd."]],"ms":["arcane","primal"]},{"k":"sp-elementalorb","n":"Elemental Orb","l":1,"s":"Evocation","sa":"EVO","c":["Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":226,"ct":"1 action","rg":"90 feet","cp":"V, S","d":"Instantaneous","b":[["p","You form an orb of power, molding it into an element of your choice. Select one damage type from acid, cold, fire, lightning, or poison. Make a ranged spell attack against a target you can see within range. On hit, the target takes 3d8 damage of the selected damage type."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."]],"ms":["arcane"]},{"k":"sp-elstrakinsinstantbounty","n":"Elstrakin’s Instant Bounty","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":552,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a silver chalice worth at least 1000 gp, which the spell consumes)","d":"Instantaneous","b":[["p","You cause the bodies of all creatures you choose within range to become healthy and renewed. All targets are immediately cured of any exhaustion or poison that is plaguing them, are fully fed, and if they are prone they may use their reaction to stand immediately. Additionally, all creatures you choose have advantage on saving throws until the start of your next turn."]],"g":["Skulker’s Grimoire"]},{"k":"sp-elstrakinslovingembrace","n":"Elstrakin’s Loving Embrace","l":7,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":552,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"1 day","b":[["p","A deceptive illusion of someone or something dear to a target you choose within range appears, only to them, and takes them in their arms. The target must make a Charisma saving throw. If they fail, the illusion causes them to become docile and relaxed. The creature becomes paralyzed for the spell’s duration, unable to focus on anything except the illusion. The creature can reattempt their saving throw at the end of each of their turns, ending the effect on a successful save."]],"g":["Skulker’s Grimoire"]},{"k":"sp-embeddedmessage","n":"Embedded Message","l":2,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":552,"ct":"1 minute","rg":"30 feet","cp":"V, S, M (a small bit of honeycomb and jade dust worth at least 10 gp, which the spell consumes)","d":"Until dispelled","b":[["p","You implant a message within an object in range; a message that is uttered when a trigger condition is met. Choose an object that you can see and that isn’t being worn or carried by another creature. Speak the message, which must be 25 words or less, though it can be delivered over as long as 10 minutes. Finally, determine the circumstance that will trigger the spell to deliver your message."],["p","When that circumstance occurs, a voice from the object recites the message in your voice (a mouth can appear to speak it) and at the same volume you spoke. If the object you chose has a mouth or something that looks like a mouth (for example, the mouth of a statue), the magical mouth appears there so that the words appear to come from the object’s mouth. When you cast this spell, you can have the spell end after it delivers its message, or it can remain and repeat its message whenever the trigger occurs."],["p","Alternatively, when the spell’s target would speak their message you can choose to have it be spoken telepathically (the target hears it mentally in your voice, in the language you use) to a creature within 30 feet. You must have the trigger specify who should hear it in this circumstance."],["p","The triggering circumstance can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 feet of the object. For example, you could instruct the mouth to speak when any creature moves within 30 feet of the object or when a silver bell rings within 30 feet of it."]],"h":[["p","At Higher Levels. When you cast this spell using a slot level of 3rd or higher, you can choose one of the following effects for each slot level above 2nd:"],["li","The number of words in the message is doubled."],["li","The spell’s range is doubled, as are the ranges of triggers, creatures the message can speak to, and other instances of distance listed in the spell."]],"rit":1,"leg":1},{"k":"sp-enamor","n":"Enamor","l":2,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":553,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"1 minute","b":[["p","You weave a distracting string of words, causing creatures of your choice that you can see within range and that can hear you to make a Wisdom saving throw. Any creature that can’t be charmed succeeds on this saving throw automatically, and if you or your companions are fighting the creature, it has advantage on the save. On a failed save, the target has disadvantage on Wisdom (Perception) checks made to perceive any creature other than you until the spell ends or until the target can no longer hear you. The spell ends if you are incapacitated or can no longer speak."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the number of creatures you can target is doubled for each slot level above 2nd."]],"leg":1},{"k":"sp-enamormonster","n":"Enamor Monster","l":4,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":553,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"1 hour","b":[["p","You attempt to charm a creature you can see within range. It must make a Wisdom saving throw, and it does so with advantage if you or your companions are fighting it. If it fails the saving throw, it is charmed by you until the spell ends or until you or your companions do anything harmful to it. The charmed creature is friendly to you. When the spell ends, the creature knows it was charmed by you."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can choose one of the following effects for each slot level above 4th:"],["li","The number of creatures you can target doubles for each slot level spent this way. Each target must be within the spell’s range."],["li","The spell’s range increases by 30 feet."],["li","When the spell ends, creatures are not aware they have been charmed by you unless it was made obvious by outside factors."]],"leg":1},{"k":"sp-energyscourge","n":"Energy Scourge","l":4,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":553,"ct":"1 action","rg":"90 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","Choose one creature you can see within range, and choose one of the following damage types: acid, cold, fire, lightning, or thunder. The target must succeed on a Constitution saving throw or be affected by the spell for its duration. The first time each turn the affected target takes damage of the chosen type, the target takes an extra 2d6 damage of that type. Moreover, the target loses any resistance to that damage type until the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can choose one of the following effects for each slot level above 4th:"],["li","You can target one additional creature. The creatures must be within 30 feet of each other when you target them."],["li","This effect applies to the first and second time the creature takes this damage each turn."],["li","If the target is immune to the damage type, they are only resistant instead."],["li","The damage from this spell increases by 1d6."]],"con":1,"leg":1},{"k":"sp-enlargereduce","n":"Enlarge/Reduce","l":2,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":553,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a pinch of powdered iron)","d":"Concentration, up to 1 minute","b":[["p","You cause a creature or an object you can see within range to grow larger or smaller for the duration. Choose either a creature or an object that is neither worn nor carried. If the target is unwilling, they can make a Constitution saving throw. On a success, the spell has no effect."],["p","If the target is a creature, everything they are wearing and carrying changes size with them. Any item dropped by an affected creature returns to normal size at once."],["p","Enlarge The target’s size doubles in all dimensions, and its weight is multiplied by eight. This effect increases its size by one category (from Medium to Large, for example). If there isn’t enough room for the target to double its size, the creature or object attains the maximum possible size in the space available. Until the spell ends, the target has advantage on Strength checks and Strength saving throws. The target’s weapons also grow to match its new size, and while these weapons are enlarged, the target’s attacks with them deal 1d4 extra damage."],["p","Reduce The target’s size is halved in all dimensions, and its weight is reduced to one-eighth of normal. This reduction decreases its size by one category (from Medium to Small, for example). Until the spell ends, the target has disadvantage on Strength checks and Strength saving throws. The target’s weapons also shrink to match its new size, and while these weapons are reduced, the target’s attacks with them deal 1d4 less damage (this can’t reduce the damage below 1)."]],"h":[["p","At Higher Levels. When casting this spell at a higher level than 3rd, you can choose to apply whichever effect below (enlarge or reduce) you picked when casting the spell an additional time for every two slot levels above 2nd (4th, 6th and 8th). If you do, it yields the following effects:"],["p","Enlarge. The creature’s dimensions double, their resulting weight is multiplied by eight again, and they increase another size category (if possible). The creature’s weapons and equipment grow with them, and for each size category they increase by, their attacks deal 1d4 additional damage."],["p","Reduce. The creature’s size is reduced by half again, its weight reduced to one-eighth of its resulting weight, and they decrease by one size category. This effect can only be applied enough to reduce a creature to be Tiny, then has no further effect. For each size category they are reduced by, their attacks deal 1d4 less damage (minimum 1)."]],"con":1,"leg":1},{"k":"sp-entomb","n":"Entomb","l":1,"s":"Transmutation","sa":"TRA","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":226,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You attempt to encase a Medium or smaller creature you can see within ice. The target must succeed on a Strength saving throw or become restrained in ice for the duration. At the end of each of its turns, it takes 1d8 cold damage and can make another Strength saving throw. On success, the spell ends."],["p","If the creature suffers an instance of at least 5 fire or bludgeoning damage while restrained, the ice breaks and the target is freed, ending the spell."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."]],"con":1,"ms":["arcane"],"also":[["cc",134]]},{"k":"sp-entrap","n":"Entrap","l":1,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":554,"ct":"1 minute","rg":"Touch","cp":"S, M (25 feet of rope, which the spell consumes)","d":"8 hours","b":[["p","As you cast this spell, you use the rope to create a circle with a 5-foot radius on the ground or the floor. When you finish casting, the rope disappears and the circle becomes a magic trap. This trap is nearly invisible, requiring a successful Intelligence (Investigation) check against your spell save DC to be discerned."],["p","The trap triggers when a creature moves onto the ground or the floor in the spell’s radius, as long as the spell’s radius occupies at least half the amount of spaces on the ground that it does. That creature must succeed on a Dexterity saving throw or be magically hoisted into the air, leaving them hanging upside down 3 feet above the ground or the floor. The creature is restrained there until the spell ends."],["p","A restrained creature can make a Dexterity saving throw at the end of each of its turns, ending the effect on a success. Alternatively, the creature or someone else who can reach it can use an action to make an Intelligence (Arcana) check against your spell save DC. On a success, the restrained effect ends."],["p","After the trap is triggered, the spell ends when no creature is restrained by it."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 1st level or higher, you can choose one of the following effects for each slot level above 1st:"],["li","The radius of the trap increases by 5 feet."],["li","An additional trap is created within 10 feet of another you create."]],"leg":1},{"k":"sp-entropicshield","n":"Entropic Shield","l":4,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":554,"ct":"1 reaction, which you take when you are hit by an attack","rg":"Self","cp":"V","d":"1 round","b":[["p","A barrier of freezing energy appears between yourself and your attacker. Until the start of your next turn, you have three-quarters cover, including against the triggering attack. If an attack hits you the shield shatters and the effect ends; if the attacker is within 30 feet its energy assaults them, forcing them to make a Constitution saving throw. On a failure they take 4d10 cold damage and are incapacitated until the start of your next turn."]],"h":[["p","At Higher Levels. When you cast this spell at 5th level or higher, for every slot level above 4th you can choose one of the following benefits:"],["li","The shield grants you a +1 bonus to your armor class."],["li","The spell’s cold damage increases by 2d10."]],"g":["Altissima-Cor’s Arcane Arts"]},{"k":"sp-erode","n":"Erode","l":3,"s":"Conjuration","sa":"CON","c":["Occultist","Spellblade","Wizard"],"bk":"ll","p":227,"ct":"1 action","rg":"20 feet","cp":"V, S","d":"Instantaneous","b":[["p","You blast a creature or object within range with a glob of acid. The target must make a Dexterity saving throw. On a failure, it takes 8d4 acid damage immediately and is covered in acid. On a success, the target takes half as much damage and is not covered in acid. While covered in acid, the target takes 2d4 acid damage at the end of each of its turns. The target or a creature within 5 feet of it can end this damage by using its action to clear away the acid."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage (both initial and later) increases by 1d4 for each slot level above 3rd."]],"ms":["arcane"],"also":[["cc",134]]},{"k":"sp-etherealimmolation","n":"Ethereal Immolation","l":2,"s":"Evocation","sa":"EVO","c":["Occultist","Sorcerer","Spellblade"],"bk":"ll","p":227,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You shroud a target in a luminous ethereal shroud which reacts violently to the presence of magic. For the duration, if the target casts a spell, it takes 2d4 force damage. This damage increases by 1d4 for each spell level of the spell cast (no additional damage for cantrips)."],["p","Additionally, if the target ends its turn while concentrating on a spell, it takes 1d4 force damage."]],"con":1,"ms":["arcane"]},{"k":"sp-everestsisolatedundoing","n":"Everest’s Isolated Undoing","l":5,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":554,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 10 minutes","b":[["p","You are phased out of the Material Plane slightly and granted special protection against widespread attacks. If you are targeted by an effect that requires a saving throw and targets or affects more than one creature at the same time (such as a fireball), you can use your reaction to be ignored by the effect as if you aren’t present, phasing through its effects harmlessly. If you are within an ongoing effect that lingers in an area (such as cloudkill), you are ignored by its effects as long as at least one other creature is being affected by it."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you can choose one additional creature other than you for it to affect for each slot level above 5th. Those creatures must be within range to touch when you cast the spell. If ever this spell’s effects would apply to every target of a single effect, it offers no protection to them."]],"con":1,"g":["Skulker’s Grimoire"]},{"k":"sp-eviscerate","n":"Eviscerate","l":3,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":554,"ct":"1 reaction, taken when a creature within range dies","rg":"60 feet","cp":"S","d":"Instantaneous","b":[["p","When a creature in range dies, their blood and physical tissue become explosive, and their body detonates in a wave of necrotic energy. Creatures within 10 feet of them must make a Dexterity saving throw, taking 8d6 necrotic damage on a failed save, or half as much on a successful one. If this blast kills another creature, roll 1d100 for each. On a result of 61 or higher, their body also explodes with necrotic energy, except it only affects creatures within 5 feet. Creatures who fail their Dexterity save against it only take 2d6 necrotic damage on a failed save, and none on a successful one. Creatures who failed the first saving throw are excluded from the second."],["p","This spell can only affect creatures that are Small, Medium or Large. For every size category above Medium the target hits, the range of the detonation increases by 10 feet (or 5 feet, for the secondary detonations)."],["p","A body destroyed by this spell is treated as having been dead for a full day, due to being withered and blasted apart."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, you can choose one of the following effects for each slot level above 3rd:"],["li","The size of creature you can target increases by one size category."],["li","The primary and secondary necrotic damage of this spell increase by 1d6."]],"g":["Sky-Keeper’s Grimoire"]},{"k":"sp-explodeheart","n":"Explode Heart","l":5,"s":"Necromancy","sa":"NEC","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":293,"ct":"1 action","rg":"30 feet","cp":"S, M (a splash of your blood worth at least 6 hit points, which the spell consumes)","d":"Instantaneous","b":[["p","You point at a creature and attempt to make its heart explode in a violent spasm. If the target has fewer than 20 hit points, its heart explodes and it immediately dies. If it has more than 20 hit points, it must make a Constitution saving throw. On a failure, it takes 10d6 necrotic damage and is stunned until the start of your next turn. On a success, it takes half as much damage and is not stunned. If this damage reduces the target to 0 hit points, it dies."],["p","Creatures without a heart are immune to this spell, though at your DM’s discretion similar organs or components (for example, a golem’s magic core) may qualify as a heart."]],"bm":1},{"k":"sp-explosivedeflection","n":"Explosive Deflection","l":1,"s":"Evocation","sa":"EVO","c":["Sorcerer","Wizard"],"bk":"ll","p":227,"ct":"1 reaction, which you take when you are hit by an attack","rg":"Self","cp":"V, S, M (a pinch of black powder)","d":"Instantaneous","b":[["p","You release an explosive blast of energy to deflect an attack. Roll 2d6 and reduce the attack's damage by the result. If the attack's damage was reduced to 0, and it was a melee attack, the attacker takes the remainder of your dice roll as thunder damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the dice rolled increase by 1d6 for each slot level above 2nd."]],"ms":["arcane"]},{"k":"sp-expungepoison","n":"Expunge Poison","l":1,"s":"Transmutation","sa":"TRA","c":["Cleric","Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":294,"ct":"1 reaction, which you can take when a creature within range fails a saving throw against becoming poisoned","rg":"60 feet","cp":"V, S, M (a splash of your blood worth at least 1 hit points, which the spell consumes)","d":"Instantaneous","b":[["p","You point at a willing creature that has just become poisoned, and expel its tainted blood. The target takes 5 necrotic damage and is no longer poisoned."]],"bm":1},{"k":"sp-exsanguinate","n":"Exsanguinate","l":4,"s":"Necromancy","sa":"NEC","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":294,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a splash of your blood worth at least 4 hit points, which the spell consumes)","d":"Instantaneous","b":[["p","You drain a creature of blood, tearing its vital energy away. The target must make a Constitution saving throw. On a failure, its current and maximum hit points are reduced by 6d6. On a success, its current hit points are reduced by half as much, and its maximum hit points are not reduced. If the target was below half its maximum hit points before the spell was cast, its current hit points are reduced by an additional 6d6 hit points, regardless of the save result."],["p","Any maximum hit point reduction caused by this spell lasts until the target finishes a long rest or is targeted with greater restoration. A creature without blood is immune to this spell."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the hit point reduction on a failed saving throw is increased by 1d6 for each level over 4th."]],"bm":1},{"k":"sp-eyeoferadication","n":"Eye of Eradication","l":9,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":555,"ct":"1bonus action","rg":"Self","cp":"V, S, M (a dried demon eye)","d":"Concentration, up to 1 minute","b":[["p","For the spell’s duration one of your eyes becomes infused with concentrated fiendish energy that tears at the minds of those who see it, granting you devilsight out to 120 feet. One creature of your choice that you can see within that range must succeed on a Charisma saving throw or take 10d10 psychic damage. If that target fails their save by 5 points or more, they are frightened of you until the start of your next turn."],["p","On each of your subsequent turns while under this effect, you may use a bonus action to choose one more creature who can see you within 120 feet and repeat the effect above."],["p","If you fail a concentration check caused by a weapon attack and this spell ends as a result, you can use your reaction to force the creature who made that attack and each creature you choose within 15 feet of them to make the Charisma save against the effect above as the spell ends."],["p","If any effect from this spell causes a creature to die, their body is left withered and curls in terror, preventing them from being revived by any spell except true resurrection or divine intervention."]],"con":1,"g":["Daemoturgy"]},{"k":"sp-eyesofimmolation","n":"Eyes of Immolation","l":1,"s":"Evocation","sa":"EVO","c":["Druid","Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":227,"ct":"1 action","rg":"30 feet","cp":"S","d":"Instantaneous","b":[["p","Your eyes glow with fiery light before focusing on a creature you can see within range, causing a beam of fire to shoot from your eyes. The target creature must make a Dexterity saving throw. On a failed save, it takes 3d6 fire damage and is set ablaze, taking 1d6 damage at the end of each of its turns until it or another creature within 5 feet of it spends an action to douse the flames. On a successful save, the creature takes half as much damage and is not set ablaze."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the initial damage increases by 1d6 for each slot level above 1st."]],"ms":["arcane","primal"]},{"k":"sp-faithfulhound","n":"Faithful Hound","l":4,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":555,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a tiny silver whistle, a piece of bone, and a thread)","d":"8 hours","b":[["p","You conjure a phantom watchdog in an unoccupied space that you can see within range, where it remains for the duration, until you dismiss it as an action, or until you move more than 100 feet away from it."],["p","The hound is invisible to all creatures except you and can’t be harmed. When a Small or larger creature comes within 30 feet of it without first speaking the password that you specify when you cast this spell, the hound starts barking loudly. The hound sees invisible creatures and can see into the Ethereal Plane. It ignores illusions."],["p","At the start of each of your turns, the hound attempts to bite one creature within 5 feet of it that is hostile to you. The hound’s attack bonus is equal to your spellcasting ability modifier + your proficiency bonus. On a hit, it deals 4d8 piercing damage."]],"leg":1,"g":["Ossenheimer’s Memoirs"]},{"k":"sp-fall","n":"Fall","l":1,"s":"Transmutation","sa":"TRA","c":["Inventor","Sorcerer","Wizard"],"bk":"ll","p":227,"ct":"1 action","rg":"Self","cp":"V, S","d":"Instantaneous","b":[["p","You alter gravity for yourself, reorienting which way is down for you until the end of your turn. You can pick any direction to fall (as if under the effect of gravity), falling up to 500 feet before the spell ends."],["p","If you collide with something during this time, you take falling damage as normal. You can control your fall as you would normally by holding onto objects, or move along a surface according to your new orientation until your turn ends and gravity returns to normal."]],"ms":["arcane"],"also":[["cc",134]]},{"k":"sp-fallingmeteor","n":"Falling Meteor","l":2,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":555,"ct":"1 reaction, taken when you fall 10 feet or more RangeSelf (15-foot radius)","rg":"Self (15-foot radius)","cp":"S","d":"1 minute","b":[["p","When falling from a height greater than 10 feet, you conjure a fiery ward around yourself and become a meteor of pure force that plummets downward. You can choose to land in an unoccupied space by controlling your fall (falling twice as quickly as you normally would)."],["p","This space can be any distance away from where you would normally land, up to half the number of feet you will descend (rounded down) away. When you land, you unleash a wave of energy that hits everything within 15 feet of you, including you. Creatures in range must make a Constitution saving throw, taking the amount of falling damage you would have taken from the fall on a failed save as force damage instead, or half as much on a successful one. Any creature that fails the save, including you, is knocked prone. The spell then ends."],["p","The damage this spell deals cannot exceed your maximum hit points. If a creature casts feather fall on you while falling under this effect, you must make a Concentration check against their spell save DC. On a failure, this spell’s effects end. On a success you ignore feather fall."]],"h":[["p","At Higher Levels. If you cast this spell at 3rd level or higher, the range of the blast increases by 10 feet for each slot level above 2nd. If you cast this spell at 5th level or higher, you automatically succeed your Constitution save."]],"g":["Legacy of Gold"]},{"k":"sp-fieldofstars","n":"Field of Stars","l":5,"s":"Evocation","sa":"EVO","c":["Druid","Occultist","Sorcerer","Wizard"],"bk":"ll","p":228,"ct":"1 action","rg":"Self (60-foot radius)","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You cause 5 star-like motes of light to spring forth at points you can see within range. Each mote of light sheds bright light in a 10-foot radius and dim light for an additional 10 feet. If a creature moves within 5 feet of a mote on a turn or ends its turn within 5 feet of one, the mote explodes in a brilliant flash, dealing 4d12 radiant damage to all creatures within 5 feet of it before fading away. If multiple motes explode at once, a creature hit by more than one only takes damage once."],["p","For the duration of the spell, while you have any motes of light remaining, you can use your action to rearrange the remaining motes, placing them anywhere within range. This movement cannot cause them to detonate."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the range increases by 10 feet and you create one additional mote of light for each slot level about 5th."]],"con":1,"ms":["arcane"]},{"k":"sp-fiendishaspect","n":"Fiendish Aspect","l":0,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":555,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","Your body is altered to gain the properties it needs to adapt to a type of movement of your choice. Choose between swimming, climbing, or one effect/aspect of the environment causing there to be difficult terrain. Your base movement speed becomes that type of movement, and if you choose an effect or environmental element then it does not count as difficult terrain."],["p","If moving through any area using these newly acquired movement types or through the designated effect/environment would automatically cause damage to you, you ignore that damage until the start of your next turn."]],"con":1,"g":["Daemoturgy"]},{"k":"sp-finalflame","n":"Final Flame","l":6,"s":"Evocation","sa":"EVO","c":["Cleric"],"bk":"ll","p":228,"ct":"1 action","rg":"Touch","cp":"V, S, M (a phoenix’s feather)","d":"8 hours","b":[["p","You place an ember of divine flame within a creature, which lies dormant until it is triggered. It activates if its carrier is reduced to 0 hit points or uses its bonus action to activate it."],["p","When the ember is activated, it explodes, causing all creatures within 20 feet except the carrier to make a Dexterity saving throw. On a failure, a creature takes 8d6 radiant damage. On a success, it takes half as much damage. The ember's carrier regains 8d6 hit points."]],"ms":["divine"]},{"k":"sp-findthepath","n":"Find the Path","l":6,"s":"Divination","sa":"DIV","c":[],"bk":"retia","p":556,"ct":"1 minute","rg":"Self","cp":"V, S, M (a set of divinatory tools - such as bones, ivory sticks, cards,teeth, or carved runes - worth 100 gp and an object from the location you wish to find)","d":"Concentration, up to 1 day","b":[["p","This spell allows you to find the shortest, most direct physical route to a specific fixed location that you are familiar with on the same plane of existence. If you name a destination on another plane of existence, a destination that moves (such as a mobile fortress), or a destination that isn’t specific (such as “a green dragon’s lair”), the spell fails."],["p","For the duration, as long as you are on the same plane of existence as the destination, you know how far it is and in what direction it lies. While you are traveling there, whenever you are presented with a choice of paths along the way, you automatically determine which path is the shortest and most direct route (but not necessarily the safest route) to the destination."],["p","When using this spell to travel toward your selected destination for longer than an hour, you and those traveling under your guidance cover 1.5 times the distance you would normally be able to travel by exploiting optimal paths and shortcuts. This does not allow you to bypass anything that would interrupt your travel unless the spell would otherwise provide an alternate path that avoids it entirely."]],"con":1,"leg":1},{"k":"sp-firecyclone","n":"Fire Cyclone","l":3,"s":"Conjuration","sa":"CON","c":["Druid","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":228,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a pinch of ashes from a forest fire)","d":"Concentration, up to 1 minute","b":[["p","You whip up a cyclone of roaring flame at a point on the ground you can see, occupying a 10-foot-radius, 30-foot-high cylinder. Any creature inside the spell when you cast it or entering its area for first time on a turn must make a Strength saving throw. On a failure, it takes 3d6 fire damage and is flung up to half the cyclone's height, landing 15 feet outside the cyclone in a randomly determined horizontal direction. On a successful save, a creature takes half as much damage and is not flung."],["p","When a creature starts its turn outside the cyclone but within 30 feet of its center, it feels the cyclone's pull and must spend 2 feet (or 3 feet if it is flying) of movement for every 1 foot it moves away from the cyclone."],["p","For the duration of the spell, you can use your action to move the cyclone up to 30 feet in any direction along the ground."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the cyclone's damage increases by 1d6 and its height increases by 5 feet for each level above 3rd."]],"con":1,"ms":["arcane","primal"],"also":[["cc",135]]},{"k":"sp-firewhip","n":"Fire Whip","l":2,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":556,"ct":"1 action","rg":"15 feet","cp":"S, M (a strip of burnt leather)","d":"Instantaneous","b":[["p","You create a flaming whip that strikes one target within range as a melee spell attack. On a hit, the target takes 3d8 fire damage and must make a Strength saving throw. On a failure, you may pull them into any unoccupied space within the spell’s range, where they land prone. Movement taken within the spell’s range is not counted for falling damage."]],"h":[["p","At Higher Levels. When you cast this spell at 3rd level or higher, you can choose one of the following effects for each slot level above 2nd:"],["li","The damage increases by 1d10."],["li","The spell’s range increases by 5 feet."],["li","You may choose one additional target within range, who is affected by a separate fire whip. All creatures you target and move must land in spaces adjacent to one another, otherwise they are not pulled at all."]],"g":["Blood of Cineris"]},{"k":"sp-fireball","n":"Fireball","l":3,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":556,"ct":"1 action","rg":"150 feet","cp":"V, S, M (a tiny ball of bat guano and sulfur)","d":"Instantaneous","b":[["p","A bright streak flashes from your pointing finger to a point you choose within range and then blossoms with a low roar into an explosion of flame. Each creature in a 20-foot radius sphere centered on that point must make a Dexterity saving throw. A target takes 8d6 fire damage on a failed save, or half as much damage on a successful one."],["p","The fire spreads around corners, igniting flammable objects in the area that aren’t being worn or carried."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, you can choose one of the following effects for each slot level above 3rd:"],["li","The spell’s damage increases by 1d6."],["li","The spell’s spherical radius/range increase by 10 feet."],["li","Each creature that fails the saving throw is ignited (as per the condition)"]],"leg":1},{"k":"sp-fireburstmine","n":"Fireburst Mine","l":3,"s":"Abjuration","sa":"ABJ","c":["Inventor"],"bk":"ll","p":228,"ct":"1 minute","rg":"Touch","cp":"V, S, M (a tiny nonmagical item, which is destroyed when the spell ends)","d":"8 hours","b":[["p","You set a magical trap, infusing explosive magic into an object. You can set the item to detonate when someone comes within 5 feet of it, or at a verbal command by you. You can issue this command as an action or as a reaction when you see a creature move within 20 feet of a mine, detonating every mine keyed to the verbal command simultaneously."],["p","When the magic trap detonates, each creature in a 20-foot-radius sphere centered on the item must make a Dexterity saving throw. A creature takes 5d8 fire damage on a failure, or half as much damage on a success. If a creature is in the area of effect of more than one fireburst mine during a turn, it takes half damage from any mines beyond the first."],["p","A magical mine must be set at least 5 feet away from every other mine, and cannot be moved once placed; any attempt to move it results in it detonating. The caster can permanently disarm a mine as an action."]],"ms":["arcane"],"also":[["cc",135]]},{"k":"sp-firesagerobe","n":"Firesage Robe","l":6,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":556,"ct":"1 bonus action","rg":"Self","cp":"V, S, M (a jade stone worth at least 1000 gp, which the spell consumes)","d":"Concentration, up to 1 hour","b":[["p","You are wreathed in a cloak of red and emerald flames, and gain the following benefits for the spell’s duration:"],["li","Your AC becomes 8 + your spellcasting ability modifier + your proficiency bonus (if it wasn’t already higher)."],["li","You gain darkvision out to 240 feet."],["li","You are immune to fire damage."],["li","If a creature within 5 feet of you hits you with a melee attack they take 1d10 fire damage."],["li","You cannot be charmed or frightened."],["li","Your weapon attacks deal an additional 1d6 fire damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 7th level or higher, the 1d6 fire damage and 1d10 fire damage increase by 1d6 and 1d10 respectively for every two slot levels above 5th."]],"con":1,"g":["Nine Branch Arts"]},{"k":"sp-fissure","n":"Fissure","l":5,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":229,"ct":"1 action","rg":"Self (60-foot line)","cp":"V, S","d":"Instantaneous","b":[["p","You rend the earth asunder in a 60-foot long, 5-foot wide line, targeting an area of dirt, sand, or rock at least 10 feet deep."],["p","Each creature within that line must make a Dexterity saving throw. On a failure, a creature falls into the crevice, which snaps shut and begins to crush it. The creature takes 6d10 bludgeoning damage and is buried in 10 feet of rubble. A creature without a burrowing speed can spend 25 feet of movement to dig itself out, reappearing at the location it stood before the spell. A creature that ends its turn buried takes an additional 1d10 bludgeoning damage."]],"ms":["primal"],"also":[["cc",135]]},{"k":"sp-fistsoffire","n":"Fists of Fire","l":0,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Warlock"],"bk":"ll","p":229,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"1 minute","b":[["p","You cause your fists to erupt in flames. For the duration, your fists become a set of simple natural weapons that deal 1d6 fire damage. You are proficient in these weapons, and they have the Light property. For the duration, any flammable object you attempt to hold catches fire. If you end your turn grappling another creature with your hands, it takes 1d4 fire damage. You can end the spell early (no action required)."],["p","The damage this spell does to grappled targets increases by 1d4 at 5th level (2d4), 11th level (3d4), and 17th level (4d4)"]],"ms":["arcane","primal"]},{"k":"sp-flamethrower","n":"Flamethrower","l":3,"s":"Evocation","sa":"EVO","c":["Sorcerer","Warlock","Wizard"],"bk":"ll","p":229,"ct":"1 action","rg":"Self (30-foot line)","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You release a stream of fire from your hands, filling a 30-foot long, 10-foot wide line with a continual gout of flame. Any creature in the area when you cast the spell or entering the area before the start of your next turn must make a Dexterity saving throw, taking 4d6 fire damage on a failure or half as much on a success."],["p","As an action on your subsequent turns for the duration, you can release a new line of fire with the same effect."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd."]],"con":1,"ms":["arcane"]},{"k":"sp-flashcure","n":"Flash Cure","l":4,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":556,"ct":"1 bonus action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","Choose a number of creatures within the spell’s range equal to the level this spell was cast at. Those targets regain hit points equal to 1d4 plus your spellcasting ability modifier, and if they are poisoned, paralyzed, stunned or incapacitated by an effect that involves an ongoing save, they may immediately make those saving throws again with advantage, ending those effects on a success."]]},{"k":"sp-flashfreeze","n":"Flash Freeze","l":3,"s":"Evocation","sa":"EVO","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":229,"ct":"1 action","rg":"Self (30-foot cone)","cp":"V, S","d":"Instantaneous","b":[["p","A freezing wind ripples outward. Each creature in a 30-foot cone must make a Constitution saving throw. On a failure, a creature takes 4d8 cold damage and is restrained by ice until the start of your next turn. On a success, it takes half as much damage and isn’t restrained."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each slot level above 3rd."]],"ms":["arcane"],"also":[["cc",135]]},{"k":"sp-flicker","n":"Flicker","l":1,"s":"Psionic","sa":"PSI","c":["Psion"],"bk":"cc","p":135,"ct":"1 reaction, when you would take damage","rg":"Self","cp":"S","d":"1 round","b":[["p","You flicker between the material and ethereal planes. Until the start of your next turn, each time you would take damage, including the triggering attack, roll a d4. On a 2, you gain resistance to that instance of damage. On a 4, you don’t take any damage."]],"ci":1},{"k":"sp-flickeringstrikes","n":"Flickering Strikes","l":5,"s":"Conjuration","sa":"CON","c":["Ranger","Spellblade","Wizard"],"bk":"ll","p":230,"ct":"1 action","rg":"Self (30-foot radius)","cp":"V, S, M (a melee weapon you are proficient with worth at least 1 sp)","d":"Instantaneous","b":[["p","You brandish the weapon used in the casting before disappearing, instantly teleporting to and striking up to 5 targets within range. Make a melee weapon attack against each target. On a hit, a target takes the normal weapon damage from the attack, plus an additional 6d6 force damage."],["p","You can then teleport to an unoccupied space you can see within 5 feet of any target of the spell."]],"ms":["arcane","psionic"],"also":[["cc",136]]},{"k":"sp-fling","n":"Fling","l":2,"s":"Transmutation","sa":"TRA","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":230,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","You manipulate gravity around one Large or smaller creature. The target must make a Strength saving throw. On a failure, you can fling it 40 feet straight up or 20 feet in any other direction."],["p","If you fling the target upward, it immediately falls, taking 4d6 falling damage and landing prone. If you fling it in any other direction, it takes 2d6 damage and lands prone. If this movement would be stopped early by a creature or object, both the target and whatever it collides with takes 3d6 bludgeoning damage."]],"ms":["arcane"],"also":[["cc",136]]},{"k":"sp-floatingdisc","n":"Floating Disc","l":1,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":557,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a drop of mercury)","d":"1 hour","b":[["p","This spell creates a circular, horizontal plane of force, 3 feet in diameter and 1 inch thick, that floats 3 feet above the ground in an unoccupied space of your choice that you can see within range. The disk remains for the duration, and can hold up to 500 pounds. If more weight is placed on it the spell ends, and everything on the disk falls to the ground."],["p","The disk is immobile while you are within 20 feet of it. If you move more than 20 feet away from it, the disk follows you so that it remains within 20 feet of you. It can move across uneven terrain, up or down stairs, slopes and the like, but it can’t cross an elevation change of 10 feet or more. For example, the disk can’t move across a 10-foot-deep pit, nor could it leave such a pit if it was created at the bottom."],["p","If you move more than 100 feet from the disk (typically because it can’t move around an obstacle to follow you), the spell ends."]],"leg":1},{"k":"sp-forceblade","n":"Force Blade","l":4,"s":"Evocation","sa":"EVO","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":230,"ct":"1 bonus action","rg":"Self (10 feet)","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You create an oversized blade of scintillating energy in your hand. For the duration, you can sweep the blade as an action through one or two adjacent creatures within range, automatically dealing force damage equal to 2d12 + your spellcasting modifier."]],"h":[["p","At Higher Levels. When you cast it using a 5th- or 6th-level spell slot, the damage increases to 3d12. When you cast it using a spell slot of 7th level or higher, the damage increases to 4d12."]],"con":1,"ms":["arcane"],"also":[["cc",136]]},{"k":"sp-forcebolt","n":"Force Bolt","l":0,"s":"Evocation","sa":"EVO","c":["Sorcerer","Spellblade"],"bk":"ll","p":230,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","You hurl a mote of arcane energy at a creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 2d4 force damage."],["p","This spell’s damage increases by 2d4 when you reach 5th level (4d4), 11th level (6d4), and 17th level (8d4)."]],"ms":["arcane"],"also":[["cc",136]]},{"k":"sp-forcemissile","n":"Force Missile","l":4,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":557,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","You conjure up a large missile of force energy and fire it at a point you can see within range where it explodes in a 5-foot radius sphere. All creatures within range take 5d6 force damage. Any effect capable of nullifying, negating, or protecting from magic missiles can treat this spell the same way. This spell deals double damage to structures."]],"h":[["p","At Higher Levels. If cast at 5th level or higher, you can create an additional missile for each slot level above 4th. Each missile can be fired at a different point within range. The area of no two missiles can overlap (i.e., if the same creature is caught in multiple areas of the effect they are only damaged once)."]],"g":["Ossenheimer’s Memoirs"]},{"k":"sp-forgelordschains","n":"Forgelord’s Chains","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":557,"ct":"1 bonus action","rg":"Self","cp":"V","d":"Concentration, up to 10 minutes","b":[["p","White-hot chains appear on a weapon that you choose, wrapping around them and your arm. Until the spell ends you cannot be disarmed of this weapon, and if it is up to 30 feet away from you, you can use your reaction to pull it back to your hand. While these chains bind it, the weapon deals an extra 2d8 fire damage on a hit."],["p","Once per turn, when you hit a creature with this weapon you can force that creature to make a Strength saving throw, as these chains appear and bind them in place. On a failure they take 4d10 fire damage and are restrained until the start of your next turn. If one or more creatures are bound this way at the start of your turn, you can use your bonus action to force them to make the save again, taking another 2d10 fire damage on a fail with the effect continuing to the start of your next turn."]],"con":1},{"k":"sp-formoffamiliar","n":"Form of Familiar","l":2,"s":"Transmutation","sa":"TRA","c":["Occultist","Wizard"],"bk":"ll","p":230,"ct":"1 minute","rg":"Self","cp":"V, S, M (a piece of your familiar such as fur, feathers, or scales, which the spell consumes)","d":"1 hour","b":[["p","You assume the form of the familiar that provided the material component to the spell. This transformation lasts for the duration or until you drop to 0 hit points or die. Your game statistics are replaced by the statistics of the chosen creature, though you retain your alignment and Intelligence, Wisdom, and Charisma scores."],["p","You assume the hit points and hit dice of the new form. When you revert to your normal form, you return to the number of hit points you had before you transformed. If you revert as a result of dropping to 0 hit points, any excess damage carries over to your normal form. As long as the excess damage doesn’t reduce your normal form to 0 hit points, you aren’t knocked unconscious. You can use an action to revert to your normal form at any time."],["p","You are limited in the actions you can perform by the nature of your new form, and you can’t speak, cast spells, or take any other action that requires hands or speech. Your gear melds into the new form. You cannot activate, use, wield, or otherwise benefit from any of your equipment."]],"ms":["arcane"]},{"k":"sp-formoffire","n":"Form of Fire","l":6,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Warlock","Wizard"],"bk":"ll","p":231,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 10 minutes","b":[["p","You become elemental fire, shedding bright light in a 30-foot radius and dim light for an additional 30 feet. Until the spell ends, you gain the following benefits:"],["li","You are immune to fire damage."],["li","You can move through the space of other creatures and ignore difficult terrain. The first time on a turn you enter the space of another creature, it takes 2d6 fire damage."],["li","If a creature within 5 feet hits you with a melee attack, it takes 2d6 fire damage."],["li","You can use your action to create a line of fire 30 feet long and 5 feet wide extending from you in a direction of your choice. Each creature in the line must make a Dexterity saving throw. A creature takes 6d6 fire damage on a failed save, or half as much damage on a successful one."],["li","During your turn, if you roll fire damage, you can maximize one die of the fire damage dealt."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-formofice","n":"Form of Ice","l":6,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Warlock","Wizard"],"bk":"ll","p":231,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 10 minutes","b":[["p","You freeze over, taking on a form of elemental ice. Until the spell ends, you gain the following benefits:"],["li","You are immune to cold damage."],["li","You can move across difficult terrain created by ice or snow without spending extra movement."],["li","The ground in a 15-foot radius around you is icy and is difficult terrain for creatures other than you. The radius moves with you."],["li","You can use your action to create a 30-foot cone of freezing wind extending from your outstretched hand in a direction you choose. Each creature in the cone must make a Constitution saving throw. A creature takes 4d8 cold damage on a failed save, or half as much damage on a successful one. A creature that fails its save against this effect has its speed halved until the start of your next turn."],["li","During your turn, if you roll cold damage, you gain temporary hit points equal to one die rolled (your choice)."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-formofstone","n":"Form of Stone","l":6,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Warlock","Wizard"],"bk":"ll","p":231,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 10 minutes","b":[["p","You become made of stone. Until the spell ends, you gain the following benefits:"],["li","You have resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks."],["li","You can move across difficult terrain made of earth or stone without spending extra movement. You can move through solid earth or stone as if it was air and without destabilizing it, but you can’t end your movement there. If you do so, you are ejected to the nearest unoccupied space, this spell ends, and you are stunned until the end of your next turn."],["li","You can use your action to call spikes of stone to raise from the ground. All creatures of your choice within 15 feet of you must make a Dexterity saving throw. A creature takes 4d8 piercing damage on a failed save, or half as much on a successful one. Its space becomes difficult terrain either way."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-formoftheelements","n":"Form of the Elements","l":9,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Warlock","Wizard"],"bk":"ll","p":231,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 10 minutes","b":[["p","For the duration of the spell, you gain the benefits of the form of fireK, form of iceK, form of stoneK, form of waterK, and form of windK spells."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-formofwater","n":"Form of Water","l":6,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Warlock","Wizard"],"bk":"ll","p":232,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 10 minutes","b":[["p","You become a surge of elemental water. Until the spell ends, you gain the following benefits:"],["li","You have resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks."],["li","You can move through the space of other creatures and ignore difficult terrain; the first time you move through a Large or smaller creature, it must pass a Strength saving throw or be knocked prone."],["li","You can use your action to unleash a blast of water 15 feet long and 5 feet wide extending from you in a direction of your choice. Each creature in the line must make a Strength saving throw. A creature takes 5d6 bludgeoning damage and is knocked prone on a failed save, or half as much and isn’t knocked prone on a successful one."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-formofwind","n":"Form of Wind","l":6,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Warlock","Wizard"],"bk":"ll","p":232,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 10 minutes","b":[["p","You become a gust of elemental wind. Until the spell ends, you gain the following benefits:"],["li","You have a flying speed of 60 feet."],["li","You can move through and occupy the space of other creatures, and you ignore difficult terrain."],["li","You are invisible."],["li","You can use your action to unleash a powerful blast of wind in a 30 foot cone. Each creature in the cone must make a Strength saving throw. A creature takes 4d8 bludgeoning damage and is knocked 15 feet away from you on a failed save, or takes half as much damage and isn’t knocked backward on a successful one."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-foxfire","n":"Foxfire","l":2,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":557,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","A flurry of psychic flames sprouts up around three creatures you can see within the spell’s range. Those creatures must make a Dexterity saving throw, taking 1d8 fire damage and 1d8 psychic damage on a failed save, or half as much on a successful one. The burning creatures who fail their saving throw continue to burn, and on subsequent turns you can use your action to force those remaining creatures to make the save again, following the same damage rules. On a success, the flames are extinguished."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd-level or higher, you can choose one of the following effects for each slot level above 2nd:"],["li","You may choose one additional target."],["li","The fire and psychic damage dealt each increases by 1d8."]],"con":1,"g":["Skulker’s Grimoire"]},{"k":"sp-freemeadow","n":"Free Meadow","l":3,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":557,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 10 minutes","b":[["p","You choose a point within range, and every surface within a 30-foot radius centered on it is covered in soft grass and roots, except for liquid surfaces and ones that would cause fire or necrotic damage upon contact. For the duration of the spell, the area remains this way, removing the effects of difficult terrain and allowing all creatures to climb vertical surfaces as if they had a climb speed equal to their base movement speed."],["p","Any effect that is modifying the physical properties of the terrain within range is suppressed. If those changes are the result of a spell, they are suppressed only if they were created by a spell with a level lower than the slot level used to cast this spell."],["p","When the spell ends, the grass and roots harmlessly disappear. Any fire damage dealt to or in the space destroys the spell’s effect there."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, the affected radius increases by 15 feet for every slot level above 5th."]],"con":1,"g":["Skulker’s Grimoire"]},{"k":"sp-freeze","n":"Freeze","l":0,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Spellblade","Warlock"],"bk":"ll","p":232,"ct":"1 action","rg":"Touch","cp":"V, S","d":"Instantaneous","b":[["p","You instill a deadly chill into your hand. Make a melee spell attack against a creature you can reach. On a hit, the target takes 1d8 cold damage, and its speed is reduced by 10 feet until the end of its next turn."],["p","The spell’s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."]],"ms":["arcane","primal"]},{"k":"sp-freezingshell","n":"Freezing Shell","l":1,"s":"Abjuration","sa":"ABJ","c":["Warlock"],"bk":"cc","p":136,"ct":"1 action","rg":"Self","cp":"V, S","d":"1 hour","b":[["p","A freezing shell shrouds you, forming an icy barrier. You gain 5 temporary hit points for the duration of the spell. If a creature hits you with a melee attack while you have these temporary hit points, the attacker takes 5 cold damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, both the temporary hit points and the cold damage increase by 5 for each slot level above 1st."]]},{"k":"sp-friendasfoe","n":"Friend as Foe","l":3,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":557,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You reach into the mind of one creature you can see and force them to make an Intelligence saving throw. A creature automatically succeeds if it is immune to being frightened. On a failed save, the target loses the ability to distinguish friend from foe, regarding all creatures they can see as enemies until the spell ends. Each time the target takes damage, they can repeat the saving throw, ending the effect on themself on a success."],["p","Whenever the affected creature chooses another creature as a target, they must choose the target at random from among the creatures they can see within range of the attack, spell, or other ability they’re using. If an enemy provokes an opportunity attack from the affected creature, the creature must make that attack if they are able to."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can choose one of the following effects for each slot level above 3rd:"],["li","You may target one additional character."],["li","You can designate one more creature within the spell’s range - creatures under the spell’s effects do not include that creature in their randomized selection of targets if there is an option to attack a different creature."],["li","When one of the creatures whose ability to distinguish targets would use its reaction to make an opportunity attack while you can see them, you can choose to have them not do so instead."]],"con":1,"leg":1,"g":["Epic of Duality"]},{"k":"sp-frighten","n":"Frighten","l":1,"s":"Necromancy","sa":"NEC","c":["Occultist","Warlock","Wizard"],"bk":"cc","p":136,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You invoke a sudden fear within a creature you can see within range. The target creature must succeed a Wisdom saving throw, or become frightened for the duration. The frightened target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."]],"h":[["p","At Higher Levels. When you cast this spell using a 2nd level or higher, you can target one additional creature for each slot above 1st."]],"con":1},{"k":"sp-frigidbanishment","n":"Frigid Banishment","l":8,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":558,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","Choose up to ten creatures within range who you attempt to force into a prison demiplane where time is slowed and senses are dulled. Each creature must make a Charisma saving throw. On a failed save, they are banished to a demiplane that is empty aside from an infinite cold tundra, where they are blinded by a permanent storm. While there, they take 2d8 cold damage at the start of each of their turns but are still able to take their turns."],["p","Creatures attempting to teleport from their prison plane must make a spellcasting ability check against your spell save DC, otherwise their attempt to do so fails. Creatures may escape their prison plane by casting banishment on themselves, or by targeting themselves or the area around them with dispel magic (or any magic-nullifying spell) and successfully dispelling its effects. When they return, they enter the nearest unoccupied space relative to where they vanished."],["p","Creatures banished this way may reattempt the saving throw at the end of each of their turns, ending the effect on a success."],["p","A creature that dies in their prison plane remains there until you wish to conjure their frozen, statue-like remains in a space within 30 feet of you (or you die, and they reappear where they vanished)."]],"con":1,"g":["Altissima-Cor’s Arcane Arts"]},{"k":"sp-futureinsight","n":"Future Insight","l":1,"s":"Psionic","sa":"PSI","c":["Psion"],"bk":"cc","p":136,"ct":"1 action","rg":"Self","cp":"S","d":"10 minutes","b":[["p","Your roll 3d4 or 1d12 (your choice) and record the results. During the duration, you can expend one of these dice to add or subtract them from any attack roll, saving throw, or ability check made by a creature within 60 feet of you until the dice are exhausted or the spell ends. You must expend the die after the roll is made, but before you know the outcome of the roll."]],"ci":1},{"k":"sp-gaiusavatar","n":"Gaius Avatar","l":4,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":558,"ct":"1 bonus action","rg":"Self","cp":"V","d":"Concentration, up to 1 minute","b":[["p","A nature spirit answers your call and transforms you into a powerful guardian. The transformation lasts until the spell ends. You choose one of the following forms to assume: Primal Beast or Great Tree."],["p","Primal Beast. Bestial fur covers your body, your facial features become feral, and you gain the following benefits:"],["li","Your walking speed increases by 10 feet."],["li","You gain darkvision with a range of 120 feet."],["li","You make Strength-based attack rolls with advantage."],["li","Your melee weapon attacks deal an extra 1d6 force damage on a hit."],["p","Great Tree. Your skin appears barky, leaves sprout from your hair, and you gain the following benefits:"],["li","You gain 10 temporary hit points."],["li","You make Constitution saving throws with advantage."],["li","You make Dexterity and Wisdom-based attack rolls with advantage."],["li","While you are on the ground, the ground within 15 feet of you is difficult terrain for your enemies."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you gain one of the following effects for each slot level above 4th:"],["li","(Primal Beast) Your walking speed increases by an additional 5 feet."],["li","(Primal Beast) The extra damage die for your weapons increases for each time you take this effect, in order of increasing to 1d8, to 1d10, to 2d6, to 2d8, then to 2d10."],["li","(Primal Beast or Great Tree) You make all attack rolls with advantage."],["li","(Great Tree) You gain an additional 10 temporary hit points."],["li","(Great Tree) You also make Strength saving throws with advantage."],["li","(Great Tree) The radius of difficult terrain around you increases by 5 feet."],["li","(4 slot levels) You gain the benefits of both Primal Beast and Great Tree simultaneously."]],"con":1,"leg":1,"g":["Whisperwood Tome"]},{"k":"sp-galebolt","n":"Gale Bolt","l":1,"s":"Evocation","sa":"EVO","c":["Druid","Occultist","Ranger","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":232,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","A blast of concentrated wind streaks toward a creature of your choice within range. Make a ranged spell attack against the target. On a hit, it takes 2d8 bludgeoning damage, and if it is Large or smaller, it is knocked 10 feet away from you."]],"h":[["p","At Higher Levels. When you cast this spell using a spell lot of 2nd level or higher, the damage increases by 1d8 for each level above 1st."]],"ms":["arcane","primal"],"also":[["cc",137]]},{"k":"sp-galeshot","n":"Gale Shot","l":4,"s":"Transmutation","sa":"TRA","c":["Ranger"],"bk":"ll","p":232,"ct":"1 bonus action","rg":"Touch","cp":"V, S, M (a piece of ammunition or a weapon worth at least 1 cp)","d":"1 round","b":[["p","You touch a piece of ammunition or weapon with the thrown property, imbuing it with the power of a hurricane for the duration. The first time you attack with the empowered item, it is propelled with hurricane force. On a hit, the target takes an additional 4d8 damage from the attack and is knocked backwards 30 feet. Any creature the target collides with takes 2d8 bludgeoning damage. On a miss, the target takes half as much damage and is not knocked back."],["p","Once an attack has been made with the piece of ammunition or weapon, the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level, the shot deals an additional 1d8 damage and the target is knocked backwards an additional 10 feet."]],"ms":["primal"]},{"k":"sp-gatestep","n":"Gatestep","l":8,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":558,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You gain the ability to warp around for the spell’s duration. As a bonus action you can open a gate and step through it, teleporting to an unoccupied space you can see within 120 feet. You may increase this range by an amount of feet up to your remaining movement, from which those extra feet are deducted."],["p","When a creature makes a weapon attack against you, you can use your reaction to open a gate to redirect the attack to a creature other than you within 60 feet, forcing the attacker to make a Dexterity saving throw to prevent it. If they fail, the other creature becomes the new target, using the attacker’s attack roll and statistics to attack them."]],"con":1,"g":["Sky-Keeper’s Arcana"]},{"k":"sp-geyser","n":"Geyser","l":4,"s":"Conjuration","sa":"CON","c":["Druid","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":233,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","You cause a massive eruption of water to blast upwards from the ground at a point within range. Each creature within 10 feet must make a Dexterity saving throw. On a failure, it takes 4d6 bludgeoning damage and is knocked 60 feet up into the air. On a successful save, a creature takes half as much damage, and is instead knocked either 10 feet away from the point or 10 feet upward (its choice)."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d6 for each level above 4th."]],"ms":["arcane","primal"],"also":[["cc",137]]},{"k":"sp-ghoststep","n":"Ghost Step","l":3,"s":"Transmutation","sa":"TRA","c":["Occultist","Spellblade","Sorcerer","Warlock","Wizard"],"bk":"ll","p":233,"ct":"1 action","rg":"Self","cp":"V, S","d":"1 round","b":[["p","You become briefly ethereal and intangible. For the duration, you can move in any direction and do not fall. You can move through creatures, objects, walls, terrain, and effects as if they were not there. You can only pass through magical objects if they do not block ethereal transit. While you are intangible, you are immune to all damage except force damage."],["p","At the start of your next turn, you become tangible again in your current space. If the space is occupied, you are shunted to the nearest unoccupied space and take force damage equal to twice the number of feet you are forced to move. If you are in the air and cannot fly, you fall to the ground."]],"ms":["arcane"]},{"k":"sp-glacialcrash","n":"Glacial Crash","l":7,"s":"Evocation","sa":"EVO","c":["Druid","Sorcerer","Wizard"],"bk":"ll","p":233,"ct":"1 action","rg":"300 feet","cp":"V, S","d":"Instantaneous","b":[["p","A huge chunk of ice appears in the sky before crashing down at a point within range before shattering into an explosion of ice. Creatures within 30 feet of the point must make a Dexterity saving throw. On failure, a creature takes 6d6 cold damage, and if it was within 10 feet of the target point, it takes an additional 6d8 bludgeoning damage. On success, a creature takes half as much cold damage, and half as much bludgeoning damage (if applicable)."],["p","The spell’s area of effect becomes difficult terrain until the end of your next turn."]],"ms":["primal","arcane"]},{"k":"sp-glimpsethefuture","n":"Glimpse the Future","l":2,"s":"Psionic","sa":"PSI","c":["Psion"],"bk":"cc","p":137,"ct":"1 action","rg":"60 feet","cp":"S","d":"10 minutes","b":[["p","You give a creature within range a glimpse of their future. Roll a d4 to determine outcome:"],["p","d4 Effect The target foresees an action to come. Roll a d20 and record the value. Until the duration of the spell"],["p","ends, they can replace one of their d20 rolls with the value rolled."],["p","The target sees their own death. If they are reduced to zero hit points by an attack or failing a save throw during the duration, they instead evade"],["p","the attack or pass the saving throw if they are not"],["p","otherwise incapacitated prior to being reduced to zero."],["p","They see a future victory, growing confident. They"],["p","gain 10 temporary hit points and are immune to"],["p","the frightened condition for the duration of the spell."],["p","The target sees an ambush or surprise, the first time they would be surprised they are not, or the 4 first time an attack would be made against them with advantage, it is instead made with disadvantage."],["p","Once any of the events foreseen occur, the spell ends."]],"h":[["p","At Higher Levels. When cast using 3 or more psi points, you can select the effect instead of rolling a d4."],["p","The Unavoidable Death"],["p","In the case of number 2, passing the save will not always be enough"],["p","to make them not be reduced to zero hit points. Sometimes they"],["p","are reduced to zero by something like falling damage that has no"],["p","save or attack. Sometimes life’s a bummer that way."]],"rv":1,"ci":1},{"k":"sp-goldenspiral","n":"Golden Spiral","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":559,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You target one creature within range, and golden energy swirls around your limb (or your body), twisting into a massive arcane drill that you blast forward at your target, tearing through the landscape and enemies in your path. Your target and all creatures you choose in a 15-foot-wide line between you and them must make a Dexterity saving throw. On a failure, your primary target takes 8d6 force damage, or half as much on a successful save. Your secondary targets take half that much damage on a failed save, and no damage on a successful one. This spell deals double damage to constructs and objects."],["p","If this spell reduces any of its targets to 0 hit points, some of the spell’s energy returns to you, and you gain 1d10 temporary hit points for each creature triggering this effect. These temporary hit points disappear at the end of your next turn."],["p","When you cast this spell, you can choose to either remain where you are, or teleport to a space within 10 feet of your primary target."]],"h":[["p","At Higher Levels. If you cast this spell using a spell slot of 6th level or higher, the force damage it deals increases by 2d6 for each slot level above 5th."]],"g":["Legacy of Gold"]},{"k":"sp-gorydoom","n":"Gory Doom","l":2,"s":"Necromancy","sa":"NEC","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":294,"ct":"1 reaction, which you can take when a creature is reduced to 0 hit points within 60 feet of you.","rg":"60 feet","cp":"V, S, M (a splash of your blood worth at least 2 hit points, which the spell consumes)","d":"Instantaneous","b":[["p","When a creature that has flesh, blood, or bone that you can see is reduced to 0 hit points, you can attempt to make it explode in a shower of gore. If the target is still alive and merely unconscious, it must make a Constitution saving throw. On a success, it does not explode, but suffers one death saving throw failure if applicable."],["p","If the target is dead or fails its saving throw, it violently explodes in shards of flesh, blood, and bone. Each creature within 10 feet must make a Dexterity saving throw. A creature takes 3d6 necrotic damage on a failure or half as much damage on a success."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each level above 2nd."]],"bm":1},{"k":"sp-grandaspectofflames","n":"Grand Aspect of Flames","l":7,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":559,"ct":"1 action","rg":"Self","cp":"V, S, M (a ceremonial dagger made of volcanic glass worth at least 1,000 gp, which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You bathe your body in the arcane radiation of Cineris Clade, which takes the form of raging flames that do not harm you. For the spell’s duration you gain the following benefits:"],["li","When you would take fire damage you take none, and instead you gain temporary hit points equal to the damage you would have taken. This damage cannot originate from you."],["li","You gain a fly (hover) speed equal to your base movement speed."],["li","Any creature that hits you with a weapon attack from within 10 feet of you takes 1d12 fire damage."],["li","Fire damage that you deal ignores resistances, and treats immunity to fire damage as a resistance instead (and so deals half damage)."],["li","One each round, as a bonus action, you cause a detonation of flame that fills a 10-foot radius, centered on a point you can see within 60 feet. Each creature in range must make a Dexterity saving throw, taking 4d12 fire damage on a failed save, or half as much damage on a successful one."],["p","You can choose to dismiss this spell as a bonus action."]],"con":1,"g":["Blood of Cineris","Eidomancy"]},{"k":"sp-graspingroots","n":"Grasping Roots","l":1,"s":"Transmutation","sa":"TRA","c":["Druid","Ranger"],"bk":"ll","p":234,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","A twisting burst of roots launch from your hand, reaching to grab a Large or smaller target. The target must make a Strength saving throw. On a failure, it is pulled 20 feet in a direction of your choice. On a success, the target is only pulled 5 feet. A creature can choose to fail this save."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you move a creature an additional 5 feet for each slot level above 1st."]],"ms":["primal"]},{"k":"sp-gravitybind","n":"Gravity Bind","l":2,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":559,"ct":"1 action","rg":"300 feet","cp":"V","d":"Concentration, up to 1 minute","b":[["p","Choose one creature you can see within range. Yellow strips of magical energy loop around the creature. You can choose to use one of the following effects on the target of the spell:"],["p","Plummet. The target’s high and long jump speeds are reduced to half (rounded down), and any falling damage they take is doubled."],["p","Tether. If the target is in a zero-gravity environment, they are drawn to the nearest surface they can stand on, which they walk on with ease as if it was the floor under regular gravity. A creature this effect is applied to can activate and deactivate it at will when moving."],["p","Wingbind. The target must succeed a Strength saving throw, or their flying and 0-G acceleration speeds (if any) are reduced to 0 feet for the spell’s duration. An airborne creature affected by this spell safely descends at 60 feet per round until they reach the ground or the spell ends (if they are also targeted by the plummet effect, they fall at a normal rate instead)."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you can choose one of the following effects for each slot level above 2nd:"],["li","You can apply two of the effects of the spell to its targets."],["li","You can target one additional creature. Your choice of effect may differ between targets."],["li","The spell’s duration increases to 10 minutes (1 slot level), 1 hour (2 slot levels), 24 hours (3 slot levels) or until dispelled (4 slot levels). If the spell lasts 24 hours or more it doesn’t require concentration."]],"con":1,"leg":1},{"k":"sp-gravitysurge","n":"Gravity Surge","l":2,"s":"Transmutation","sa":"TRA","c":["Spellblade","Wizard"],"bk":"ll","p":233,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You create a crushing field of gravity in a 15 radius sphere. Each creature within the area must make a Strength saving throw. On a failure, a creature takes 2d6 bludgeoning damage and falls prone. On a success, it takes half as much damage and is not knocked prone. Creatures that are not on the ground make this save with disadvantage."]],"ms":["arcane"]},{"k":"sp-greatwyrmsstride","n":"Greatwyrm’s Stride","l":3,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":559,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","The billowing flames of a dragon blast from your feet, granting you explosive speed. For the duration, your speed increases by 20 feet and moving doesn’t provoke opportunity attacks."],["p","When you move within 5 feet of a creature or an object that isn’t being worn or carried, it takes 1d6 fire damage from your trail of heat. A creature or object can take this damage only once per turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, increase your speed by 5 feet for each spell slot level above 3rd. The spell deals an additional 1d6 fire damage for each slot level above 3rd."]],"con":1,"leg":1},{"k":"sp-gripofthedead","n":"Grip of the Dead","l":1,"s":"Necromancy","sa":"NEC","c":["Occultist","Spellblade"],"bk":"ll","p":234,"ct":"1 action","rg":"Touch","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You channel unholy strength into your hand as you attempt to grab a creature you can reach. The target must succeed on a Strength saving throw or become restrained by your deathly grasp. As an action on its turn, it can attempt to escape using a Strength (Athletics) or Dexterity (Acrobatics) check against your Spell Save DC."],["p","At the start of the creature's turn while you maintain the grip and the spell, it takes 1d8 necrotic damage. You regain hit points equal to half the damage dealt."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."]],"con":1,"ms":["arcane"],"also":[["cc",137]]},{"k":"sp-handoftheblackwind","n":"Hand of the Blackwind","l":3,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":560,"ct":"1 bonus action","rg":"Self","cp":"S","d":"Concentration, up to 1 minute","b":[["p","Your hands ignite with shadowy energy, granting them the ability to strike the target’s mind as well as their body. For the spell’s duration, your unarmed strikes deal 2d8 psychic damage in addition to their normal damage, and when you make an unarmed strike you can use your spellcasting ability modifier for the attack and damage roll. Additionally, when you make an unarmed strike using the Attack action, you can make two attacks instead of one as long as they are both unarmed strikes."],["p","When the damage from your unarmed strikes force a creature to make a concentration check, the DC for those checks is always at least equal to your spell save DC."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the psychic damage it deals increases by 1d8 for every two slot levels above 3rd. If cast using a slot level of 7th or higher, when you take the Attack action and make only unarmed strikes, you can strike three times instead of once."]],"con":1,"g":["Daemoturgy"]},{"k":"sp-hastenedquiver","n":"Hastened Quiver","l":5,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":560,"ct":"1 bonus action","rg":"Touch","cp":"V, S, M (a quiver, belt, or container containing at least one piece of ammunition)","d":"Concentration, up to 1 minute","b":[["p","You transmute your quiver or ammunition belt so it produces an endless supply of nonmagical ammunition, which seems to leap into your hand when you reach for it."],["p","On each of your turns until the spell ends, you can use a bonus action to make two attacks with a weapon that uses ammunition of the same type from the same source. Each time you make such a ranged attack, that source magically replaces the piece of ammunition you used with a similar piece of nonmagical ammunition. Any pieces of ammunition created by this spell disintegrate when the spell ends. If the container leaves your possession, the spell ends."],["p","This spell can also be cast on a firearm with a capacity of at least 4 pieces of ammunition, and if so it does not need to be reloaded for the spell’s duration, as bullets magically appear within it each time it runs out."]],"con":1},{"k":"sp-hathoyurasfeatherdance","n":"Hathoyura’s Feather Dance","l":7,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":560,"ct":"1 bonus action","rg":"Touch","cp":"V, S, M (a raven’s skull with ruby eyes worth at least 200 gp, which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","The creature you touch gains a mantle of black feathers that are sharpened like blades. For the duration of the spell, they gain the following benefits:"],["li","They gain a fly speed of 60 feet."],["li","They cannot be charmed or frightened."],["li","They gain a bonus to their AC and Dexterity saving throws equal to half your proficiency bonus (rounded down)."],["li","As a bonus action, the creature can teleport up to 60 feet to an unoccupied space they can see and immediately make a melee weapon attack against a target within range. If you are the target you may do this as part of the same action used to cast the spell."],["p","While under the effects of this spell, the target may use a special reaction when they’re targeted by a weapon attack to teleport up to 15 feet away to an unoccupied space they can see. If they do, the attack made against them (which resolves before they teleport) is made with disadvantage and deals half damage if it hits. This reaction can be taken normally, but can be used without expending their reaction that round a number of times equal to half your proficiency bonus (rounded down) per instance of this spell."]],"con":1,"g":["Daemoturgy"]},{"k":"sp-heavenlyray","n":"Heavenly Ray","l":4,"s":"Evocation","sa":"EVO","c":["Cleric"],"bk":"ll","p":234,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","A golden pillar of celestial radiance shines down in a 10-foot radius, 60-foot-high cylinder centered on a point you can see within range. Until the spell ends, the cylinder is filled with bright light and sheds dim light for 10 feet in all directions from it."],["p","When a creature enters the spell’s area for the first time on a turn or starts its turn there, the celestial radiance infuses its body with positive energy. If the creature is not an undead or construct, it regains 2d8 hit points and gains 2d8 temporary hit points. If it is a construct, the light has no effect. If it is undead, it instead takes 2d8 radiant damage."],["p","The first time a creature is healed by this spell, it is healed without restriction; every subsequent time a creature is healed by this spell, it can't be healed above half its maximum hit points."],["p","As a bonus action, you can move the pillar up to 60 feet in any direction."],["p","Hostile Healing"],["p","This spell does not allow you to pick who gains the healing"],["p","effect of it. Place it wisely or you can risk enemies taking"],["p","advantage of your generosity."]],"con":1,"ms":["divine"]},{"k":"sp-heavyblow","n":"Heavy Blow","l":1,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Wizard"],"bk":"ll","p":234,"ct":"1 bonus action","rg":"Self","cp":"V, M (a weapon or unarmed strike that does bludgeoning damage)","d":"1 round","b":[["p","You impart great heft to an unarmed strike or weapon you are holding. The first time you hit with a melee weapon attack using that weapon before the start of your next turn, your blow strikes with great force, and the attack deals an extra 1d10 bludgeoning damage to the target and must succeed a Constitution saving throw, or becomes dazed until the start of its next turn. While dazed this way, it cannot take reactions, and attacks against it have advantage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the extra damage increases by 1d6 for each slot level above 2nd."]],"ms":["primal"]},{"k":"sp-hellfirepit","n":"Hellfire Pit","l":7,"s":"Transmutation","sa":"TRA","c":["Warlock","Wizard"],"bk":"ll","p":235,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You open a pit to hell beneath the feet of your foes. A supernatural void opens in a 10-foot radius, 10-foot deep pit opens around a point you can see within range."],["p","Creatures in the area must make a Dexterity saving throw. On success, they can move 5 feet outside the radius of the spell. If they cannot move 5 feet out of the radius of the spell (such as having no path or insufficient movement speed), they automatically fail the saving throw. Creatures that fall their saving throw fall to the bottom of the bit (taking 1d6 bludgeoning damage and falling prone). The floor of the pit is a blazing inferno of hell. Creatures that start their turn in the pit take 4d6 fire damage and 4d6 necrotic damage."],["p","The pit is difficult to escape, voraciously drawing creatures caught in to the depths of hell with strong winds, roaring fires, and infernal chains. A creature can spend 20 feet of movement (or 10 if they a flying or climbing speed) to attempt to escape the pit, making a Strength saving throw against your spell save DC. On success, they escape. On failure, fall back to the floor of the pit and their movement speed becomes 0 until the start of their next turn."],["p","When the spell ends, the supernatural void to hell closes, and all creatures in the pit are deposited on the ground where the pit opened prone."]],"con":1,"ms":["arcane"]},{"k":"sp-hideouslaughter","n":"Hideous Laughter","l":1,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":560,"ct":"1 action","rg":"30 feet","cp":"V, S, M (tiny tarts and a feather that is waved in the air)","d":"Concentration, up to 1 minute","b":[["p","A creature of your choice that you can see within range perceives everything as hilariously funny and falls into fits of laughter under this spell. The target must succeed on a Wisdom saving throw or fall prone, becoming incapacitated and unable to stand up for the duration. A creature with an Intelligence score of 4 or less isn’t affected."],["p","At the end of each of its turns, and each time it takes damage, the target can make another Wisdom saving throw. The target has advantage on the saving throw if it’s triggered by damage. On a success, the spell ends."]],"con":1},{"k":"sp-holdattacker","n":"Hold Attacker","l":3,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":561,"ct":"1 reaction, taken in response to a non-undead humanoid creature within the spell’s range missing you with an attack","rg":"30 feet","cp":"V, S, M (a small, straight piece of iron)","d":"Concentration, up to 1 minute","b":[["p","The creature who triggers this reaction must succeed on a Wisdom saving throw or be paralyzed for the duration. At the end of each of their turns, the target can make another Wisdom saving throw, ending the spell’s effects on a success."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you can use this spell to target any attacker regardless of their creature type. If you cast this spell at 8th level or higher, the target is paralyzed until the end of their turn regardless of the result of their saving throw."]],"con":1,"g":["Skulker’s Grimoire"]},{"k":"sp-hungeringvoid","n":"Hungering Void","l":3,"s":"Conjuration","sa":"CON","c":["Occultist","Warlock","Spellblade","Sorcerer","Wizard"],"bk":"ll","p":235,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Concentration, up to 1 minute.","b":[["p","You gesture at a point you can see within range and summon a 20-foot radius sphere of blackness, a void of magical darkness which attempts to devour whatever enters. Darkvision cannot penetrate it, and no light can illuminate the darkness unless caused by a spell of a higher level."],["p","A creature that starts its turn within the void must make a Constitution saving throw. On a failure, it takes 2d6 cold damage and 2d6 necrotic damage, and its speed is reduced by 5 feet to a minimum of 5 feet. This speed reduction stacks with successive failures, and ends once the creature starts its turn outside the void. On a success, the creature takes half as much damage and its speed is not reduced."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the necrotic and cold damage both increase by 1d6, and the speed reduction increases to 10 feet for each failed save."]],"con":1,"ms":["arcane"]},{"k":"sp-hungeringvortex","n":"Hungering Vortex","l":2,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":561,"ct":"1 action","rg":"120 feet","cp":"V, S, M (a glove soaked in fiendish blood)","d":"Concentration, up to 1 minute","b":[["p","A mote of purple haze appears at a point within range, then expands out to become a twisting 10-foot radius sphere filled with the ghostly echoes of lesser yokai from the Realm of Shadow. All creatures within this radius must make a Charisma saving throw, taking 2d10 psychic damage on a failed save or half as much on a successful one. This sphere is considered difficult terrain, and all Strength and Dexterity saving throws made by creatures within it suffer a penalty equal to half your proficiency bonus (rounded down)."],["p","When a creature enters this space for the first time on a turn or starts their turn there, they must make a saving throw against the same damage."],["p","On each of your turns after you cast this spell, you can use a bonus action to move the sphere to another point up to 30 feet away from where it is."],["p","When this spell ends, the area within its sphere stirs with yokai echoes and remains difficult terrain until the start of your next turn."]],"h":[["p","At Higher Levels. If you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d10 for each spell slot above 2nd, and the sphere’s radius increases by 5 feet for every two slot levels above 1st."]],"con":1,"g":["Daemoturgy"]},{"k":"sp-hungryblood","n":"Hungry Blood","l":2,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":294,"ct":"1 action","rg":"15 feet","cp":"S, M (a drop of your blood worth at least 2 hit points, which the spell consumes)","d":"Instantaneous","b":[["p","You animate a stream of blood, which forms into a fanged maw and bites a creature of your choice within range. Make a melee spell attack. On a hit, the target takes 2d6 piercing damage and 2d6 necrotic damage, and you regain 2d6 hit points."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the necrotic damage and hit points regained both increase by 1d6."]],"bm":1},{"k":"sp-hurricaneslash","n":"Hurricane Slash","l":2,"s":"Evocation","sa":"EVO","c":["Druid","Ranger","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":235,"ct":"1 action","rg":"Self (30-foot line)","cp":"V, S","d":"Instantaneous","b":[["p","You condense wind into a razor sharp blast that shreds a 30-foot-long 5-foot-wide line. Creatures in the area must make a Dexterity saving throw. A creature takes 3d8 slashing damage on a failed save or half as much on a success."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you can create an additional line of effect. A creature in the area of more than one slash is affected only once."]],"ms":["arcane","primal"],"also":[["cc",137]]},{"k":"sp-hydrocage","n":"Hydro Cage","l":4,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":561,"ct":"1 action","rg":"90 feet","cp":"V, S, M (a droplet of water)","d":"Concentration, up to 1 minute","b":[["p","You conjure up a sphere of water with a 5-foot radius at a point you can see within range. The sphere can hover but no more than 10 feet off the ground. The sphere remains for the spell’s duration."],["p","Any creature in the sphere’s space must make a Strength saving throw. On a successful save, a creature is ejected from that space to the nearest unoccupied space of the creature’s choice outside the sphere. Creatures larger than the sphere succeed on the saving throw automatically, and smaller creatures can choose to fail it. On a failed save, a creature is restrained by the sphere and is engulfed by the water. At the end of each of its turns, a restrained target can repeat the saving throw, ending the effect on themself on a success."],["p","The sphere can restrain as many as four Medium or smaller creatures or one Large creature. If the sphere restrains a creature that causes it to exceed this capacity, a random creature that was already restrained by the sphere falls out of it and lands prone in a space within 5 feet of it."],["p","As an action, you can move the sphere up to 30 feet in a straight line. If it moves over a pit, a cliff, or other drop-off, it safely descends until it is hovering 10 feet above the ground. Any creature restrained by the sphere moves with it. You can ram the sphere into creatures, forcing them to make the saving throw."],["p","When the spell ends, the sphere falls to the ground and extinguishes all normal flames within 30 feet of it. Any creature restrained by the sphere is knocked prone in the space where it falls. The water then vanishes."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can choose one of the following effects for each slot level above 4th:"],["li","The sphere’s radius increases by 10 feet."],["li","You can create additional spheres, dividing the total size of the singular sphere’s radius among all additional spheres. Spheres must have a radius that is a multiple of 5 feet. When you use an action to move a sphere, you can move any amount of your spheres - if multiple are in adjacent spaces, you can choose to combine them as part of their movement."]],"con":1,"leg":1},{"k":"sp-hydrowall","n":"Hydro Wall","l":3,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":561,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a drop of water)","d":"Concentration, up to 10 minutes","b":[["p","You create a wall of water on the ground at a point you can see within range. You can make the wall up to 30 feet long, 10 feet high, and 1 foot thick, or you can make a ringed wall up to 20 feet in diameter, 20 feet high, and 1 foot thick. The wall vanishes when the spell ends. The wall’s space is difficult terrain."],["p","Any ranged weapon attack that enters the wall’s space has disadvantage on the attack roll, and fire damage is halved if the fire effect passes through the wall to reach its target. Spells that deal cold damage that pass through the wall cause the area of the wall they pass through to freeze solid (at least a 5-foot square section is frozen). Each 5-foot square frozen section has AC 5 and 15 hit points. Reducing a frozen section to 0 hit points destroys it. When a section is destroyed, the wall’s water doesn’t fill it."],["p","If a creature occupies the same space as the wall and is Large or smaller, you can use your bonus action to move them up to 60 feet to another point within the wall by pulling them with the wall’s current. If the creature is unwilling to move this way, they must succeed a Strength saving throw to resist this effect. A creature who attempts to do so and fails is also restrained by the wall’s water until the start of your next turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the wall’s size increases as follows for each slot level above 3rd: the wall’s length increases by 10 feet, the diameter of its ring increases by 5 feet, and the wall’s height increases by 5 feet."]],"con":1},{"k":"sp-icearrow","n":"Ice Arrow","l":1,"s":"Evocation","sa":"EVO","c":["Druid","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":235,"ct":"1 action","rg":"120 feet.","cp":"V, S","d":"Instantaneous","b":[["p","You conjure a shard of ice before hurling it at a target you can see within range. Make a ranged spell attack. On hit, the target takes 2d8 + your spellcasting ability modifier cold damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."]],"ms":["arcane","primal"]},{"k":"sp-icespike","n":"Ice Spike","l":4,"s":"Evocation","sa":"EVO","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":236,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You create a lance of ice which shoots up from the ground to impale a creature you can see within range. The target must make a Dexterity saving throw. On a failure, it takes 4d8 piercing damage and 4d8 cold damage. On a success, it only takes the cold damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th or 7th level, you can create a second spike. When you cast this spell using a spell slot of 8th or 9th level, you can create a third spike. Additional spikes can target the same or different creatures."]],"ms":["arcane"],"also":[["cc",138]]},{"k":"sp-iceweapon","n":"Ice Weapon","l":0,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Warlock","Wizard"],"bk":"ll","p":236,"ct":"1 bonus action","rg":"Self","cp":"V, S, M (a drop of water that was once snow)","d":"1 minute","b":[["p","You conjure a weapon of magical ice in your hand, which takes the form of one of the weapons listed below. You are proficient with it, and while wielding it, you can change its form as a bonus action. If you lose or discard the weapon, you can reform it in your hand as a bonus action."],["tbl",[["Weapon","Damage","Properties"],["Ice Spear","1d6","Thrown (30/90)"],["Ice Sword","1d6","Versatile (1d8)"],["Ice Lance","1d8","Two-Handed, Reach"],["Ice Hammer","1d10","Two-Handed, Heavy"],["Ice Dagger","1d4","Finesse, Thrown (30/90)"]]],["p","Regardless of its form, the weapon deals cold damage. You can end the spell early, letting the weapon melt to a harmless splash of water (no action required). You can have up to three ice weapons formed from this spell at a time. If you form a fourth, the first melts away."]],"rv":1,"ms":["arcane","primal"]},{"k":"sp-ichorousblood","n":"Ichorous Blood","l":4,"s":"Necromancy","sa":"NEC","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":295,"ct":"1 action","rg":"Self","cp":"S, M (a splash of your blood worth at least 4 hit points, which the spell consumes)","d":"10 minutes","b":[["p","You transmute your blood into sluggish black ichor, which forms a layer of bloody armor. You gain 8 temporary hit points, and for the duration of the spell, you reduce any bludgeoning, piercing, or slashing damage you take by 4 (to a minimum of 1 damage). In addition, any time you are hit with a melee attack, the attacker takes 4 acid damage."]],"h":[["p","At Higher Levels. When you cast this spell with a 5th level or higher spell slot, both the damage reduction and the retaliatory acid damage increase by 1 for each slot level over 4th."]],"bm":1},{"k":"sp-ignitefire","n":"Ignite Fire","l":0,"s":"Conjuration","sa":"CON","c":["Druid","Occultist","Sorcerer","Warlock","Wizard"],"bk":"cc","p":138,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You ignite a magical fire that fills a 5-foot cube in a space you can see on the ground. A creature in the fire’s space when you cast the spell must suceeed a Dexterity saving throw or take 1d8 fire damage. A creature that enters the fire’s space for the first time or ends their turn there must repeat the saving throw against the effect. Flamable objects in the area that aren’t being worn or carried catch fire."],["p","The spell’s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)"]],"con":1},{"k":"sp-ignitingsmite","n":"Igniting Smite","l":1,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":562,"ct":"1 bonus action","rg":"Self","cp":"V","d":"Concentration, up to 1 minute","b":[["p","The next time you hit a creature with a melee weapon attack during the spell’s duration, your weapon flares with white-hot intensity, and the attack deals an extra 1d6 fire damage to the target, causing them to become ignited. The target takes 1d6 fire damage each turn while ignited this way. At the start of each of its turns until the spell ends, the target must make a Constitution saving throw to extinguish the fire, taking 1d6 fire damage on a failure or ending the effect on a success."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd level or higher, choose one of the following options for each slot level above 1st:"],["li","The initial damage and the damage from being ignited increases by 1d6."],["li","The effect persists on one additional attack after its effects would end."]],"con":1},{"k":"sp-illusionarydart","n":"Illusionary Dart","l":0,"s":"Illusion","sa":"ILL","c":["Bard","Occultist","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":236,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You create and throw an illusionary dart at a creature you can see within range. Make a ranged spell attack. On hit, they take 1d8 psychic damage."],["p","The number of darts you can throw with this spell increases when you reach 5th level (2 darts), 11th (3 darts), and 17th level (4 darts). You can direct the dart at the same target or at different ones. Make a separate attack roll for each dart."]],"ms":["arcane"]},{"k":"sp-illusionaryfireball","n":"Illusionary Fireball","l":3,"s":"Illusion","sa":"ILL","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"ll","p":236,"ct":"1 action","rg":"120 feet","cp":"V, S, M (something that looks like bat guano)","d":"Instantaneous","b":[["p","A bright streak flashes from your fingertip to a point you can see within range before blossoming into a 20-foot radius illusionary explosion. Each creature of your choice in the area must make a Wisdom saving throw. On a failure, a creature takes 6d6 psychic damage. On a success, a creature realizes the fire is illusionary and takes no damage."],["p","You can choose to make illusion an explosion of ice, lightning, or pure force energy."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd."],["p","Targets of your choice"],["p","Unlike a fireball of actual fire, the illusionary version only"],["p","hits targets of your choice, making it safe to use among"],["p","allies, though it deals less damage and does no damage on a"],["p","passed save (as the target realizes its illusory nature)."]],"ms":["arcane"]},{"k":"sp-illusorypit","n":"Illusory Pit","l":1,"s":"Illusion","sa":"ILL","c":["Bard","Occultist","Sorcerer","Warlock","Wizard"],"bk":"ll","p":237,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You create a 5-foot radius illusory pit at a point you can see on the ground. Each creature within the area when the spell is cast must succeed on a Wisdom saving throw or believe it has fallen into the pit. It falls prone, cannot stand up, and cannot see beyond the radius of the pit."],["p","A creature can spend its action to attempt to climb out of the pit, repeating its saving throw. On a success, it spends all of its movement to stand up and then realizes the pit is an illusion, ending the spell for it. On a failure, it continues to believe it is stuck in the pit. An affected creature can move within the spaces covered by the pit."],["p","A creature with a flying speed automatically succeeds on its saving throw. Each time a creature under the effect takes damage, it can repeat its saving throw."]],"h":[["p","At Higher Levels. When you cast the spell using a spell slot of 2nd level or higher, the radius of the pit increases by 5 feet for each level above 1st, to a maximum of a 20 feet with a 4th-level spell slot."]],"con":1,"ms":["arcane"]},{"k":"sp-ilsrabaesveil","n":"Ilsrabae’s Veil","l":1,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":562,"ct":"1 action","rg":"Self","cp":"V, S, M (a handful of water)","d":"1 hour","b":[["p","A protective magical force surrounds you, manifesting as a freezing cold veil that protects you and your gear. You gain 5 temporary hit points for the duration, and until the spell ends you are resistant to cold damage. If a creature hits you with a melee attack while you have these hit points, the creature takes 5 cold damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, both the temporary hit points and the cold damage increase by 5 for each slot level above 1st."]],"leg":1},{"k":"sp-imbueluck","n":"Imbue Luck","l":2,"s":"Transmutation","sa":"TRA","c":["Inventor"],"bk":"ll","p":237,"ct":"1 action","rg":"Touch","cp":"V, S, M (a four-leaf clover)","d":"1 hour","b":[["p","You touch a weapon or worn item and imbue luck into it for the duration. If you target a weapon, its wielder can roll an additional d20 when making an attack (deciding after the roll, but before the outcome is determined). The creature chooses which of the d20s to use."],["p","If you target a worn item, the wearer can roll a d20 when attacked, choosing whether the attack uses the original d20 result or this one."],["p","After the extra die is rolled, the spell ends."]],"ms":["arcane"],"also":[["cc",138]]},{"k":"sp-immutability","n":"Immutability","l":3,"s":"Transmutation","sa":"TRA","c":["Cleric","Wizard"],"bk":"ll","p":237,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You assume an immutable form. You become immune to other transmutation spells or magical effects that would alter your form."],["p","If you don’t move during your turn, you gain advantage on Strength or Constitution saving throws made before the start of your next turn, and cannot be moved or knocked down against your will."],["p","While the spell is active, as a reaction to taking bludgeoning, piercing, or slashing damage you can gain resistance to that damage type (Including the triggering damage) until the end of your next turn, but your movement speed becomes zero until the end of your next turn."]],"con":1,"ms":["arcane"]},{"k":"sp-impact","n":"Impact","l":0,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Warlock"],"bk":"ll","p":237,"ct":"1 action","rg":"Touch","cp":"V, S","d":"Instantaneous","b":[["p","You impart great force into a target you touch. Make a melee spell attack against the target. On hit, the target takes 1d10 bludgeoning damage, and is knocked 5 feet directly away from you."],["p","The spell’s damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10)."]],"ms":["arcane"]},{"k":"sp-incantation","n":"Incantation","l":0,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":562,"ct":"1 bonus action","rg":"Self","cp":"V","d":"1 round","b":[["p","This spell is ignored by all rules regarding how many spells you can cast in a single turn, as long as you have enough actions to cast it. The next time you cast a spell before the start of your next turn, you can choose to expend an additional spell slot. If you do, the slot level used to cast that spell is treated as if it was higher: it is increased by half the level of the additional slot you used (rounded down). This cannot increase the slot level above 9th."],["p","If you do not have the spell slots to cast a spell at its base level but have cast this spell, you can cast that spell as long as you use this spell’s effects to produce a slot level equal to or higher than the target spell level."],["p","You do not make an eidomantic burn check for this spell."],["p","Instead, you make one for the spell it affects, treating it as an eidomancy spell cast at the resulting heightened slot level."]],"g":["Eidomancy"]},{"k":"sp-incinerationtower","n":"Incineration Tower","l":8,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":562,"ct":"1 action","rg":"150 feet","cp":"V, S, M (an obsidian marble worth at least 100 gp, which the spell consumes)","d":"Instantaneous","b":[["p","You turn the spell’s component into a burning mote of white hot light, which flies to a point you can see within range. The point erupts into a pillar of fire with a radius of 10 to 30 feet, and a height that is three times greater than its radius. All creatures in range must make a Dexterity saving throw, taking 12d8 fire damage on a failure, or half as much damage on a success. Creatures reduced to 0 hit points by this spell are killed instantly, and their remains are reduced to ashes (except magical items)."],["p","Furthermore, any creature within twice the radius of the pillar (including its initial targets) must succeed on a Constitution saving throw or be blinded. Creatures blinded this way can repeat the saving throw at the end of each of their turns, ending the effect on a success."]],"g":["Blood of Cineris"]},{"k":"sp-induceheadache","n":"Induce Headache","l":1,"s":"Evocation","sa":"EVO","c":["Bard","Occultist","Wizard"],"bk":"ll","p":238,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a bad pun written on a scrap of parchment)","d":"Concentration, up to 1 minute","b":[["p","You inflict a splitting headache on one creature you can see within range. The target takes 1 psychic damage at the start each of its turns and has disadvantage on Constitution saving throws to maintain Concentration and Intelligence ability checks. Creatures with Intelligence 5 or less suffer no effects from this spell."]],"con":1,"ms":["arcane"]},{"k":"sp-infernalshackles","n":"Infernal Shackles","l":2,"s":"Conjuration","sa":"CON","c":["Spellblade","Warlock","Wizard"],"bk":"ll","p":238,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a link from a chain burned in a fire that killed at least one creature)","d":"Concentration, up to 1 minute","b":[["p","Chains of burning black iron spring from the ground and attempt to bind a creature you can see within range. The target must make a Strength saving throw. On a failure, it takes 3d6 fire damage and its speed is reduced to 0 for the duration. On a success, it takes half as much damage and is not bound."],["p","The target must repeat its saving throw at the end of each of its turns. On a success, the chains break and the spell ends for that target. On a failure, it remains bound and takes an additional 2d6 fire damage as it is seared by the chains."]],"h":[["p","At Higher Levels. When you cast this spell with a spell slot of 3rd level or higher, you can target an additional creature for each spell slot level above 2nd."]],"con":1,"ms":["arcane"]},{"k":"sp-infiniteedge","n":"Infinite Edge","l":1,"s":"Transmutation","sa":"TRA","c":["Ranger","Wizard"],"bk":"ll","p":238,"ct":"1 bonus action","rg":"Self","cp":"V, M (a weapon or natural weapon that deals piercing or slashing damage)","d":"1 round","b":[["p","You instill a magical sharpness to a weapon you're holding or a natural weapon you possess, which must deal piercing or slashing damage. You have advantage on the next attack roll you make with it before the start of your next turn, and if the attack hits it deals an additional 1d10 damage of the weapon's type."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the extra damage increases by 1d6 for each slot level above 2nd."]],"ms":["arcane"]},{"k":"sp-inflictterror","n":"Inflict Terror","l":1,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":563,"ct":"1 action","rg":"60 feet","cp":"V","d":"Instantaneous","b":[["p","You whisper a discordant threatening phrase that only one creature you choose within range can hear, filling them with dread. The target must make a Wisdom saving throw. On a failed save, they take 3d6 psychic damage and must immediately use their reaction (if available) to move as far as their speed allows away from you. The creature doesn’t move into obviously dangerous ground, such as a fire or a pit. On a successful save, the target takes half as much damage and doesn’t have to move away. A deafened creature automatically succeeds on the save."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd level or higher, you can choose one of the following effects for each slot level above 1st:"],["li","The spell deals an additional d6 of damage."],["li","(2 slot levels) You may choose one additional target within range."],["li","(2 slot levels) If a target fails their save, they are frightened of you until the end of your following turn. While frightened they must use their action to Dash and get as far away from you as possible. If they cannot move further away or their only choice is to move toward you, they take the Dodge action instead."]],"leg":1},{"k":"sp-infusedweapon","n":"Infused Weapon","l":1,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":563,"ct":"1 action","rg":"Touch","cp":"V, S","d":"Concentration, up to 1 hour","b":[["p","A weapon you touch is wreathed in elemental energy. Choose one of the following damage types: acid, cold, fire, lightning, or thunder. For the duration, the weapon gains an enhancement bonus of +1 (adding this bonus to its attack and damage rolls) and deals an extra 1d4 damage of the chosen type when it hits."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd level or higher, it gains one of the following effects for each slot level above 1st:"],["li","The extra damage it deals increases by 1d4."],["li","The weapon’s enhancement bonus becomes +2 (2 slot levels), it becomes +3 (4 slot levels), or +4 (6 slot levels)."],["li","(2 slot levels) You do not need to concentrate on this spell’s effects for the duration."]],"con":1,"leg":1},{"k":"sp-innerworld","n":"Inner World","l":8,"s":"Psionic","sa":"PSI","c":["Psion"],"bk":"cc","p":138,"ct":"1 action","rg":"Self (120 feet)","cp":"S","d":"Concentration, up to 1 minute","b":[["p","As an action, you create and enter an imaginary world. All other creatures within 120 feet are pulled this world with you. This world is centered on you, and extends in 120 feet in all directions."],["p","A creature that reaches the edge of this world can make a Charisma saving throw to attempt to exit, spending 5 feet of movement to return where they were before being pulled into the world on success, and being unable to move out the world until the start of their next turn on failure. A creature outside the world can attempt to enter it by moving to where you cast the spell (which is marked by a glowing psionic rift) and making a Charisma saving throw to enter the world. You can allow a creature to automatically pass their save to enter or exit the world."],["p","When you create this world, you can create obstacles and terrain of your choice, creating walls, pillars, and other obstacles that take up to twenty 5 by 5 square foot areas (stylistically, these can appear however you choose). These can be placed consecutively or spread out in any method of your choosing, but any area with a creature must contain a path that creature can fit through to both you and the edge of the of the world."],["p","You can additionally create up to five hazardous spaces on the ground that are 5 foot squares. These can be fires, spikes, biting mouthes, or whatever you choose, but regardless of its form if a creature takes 4d4 + 4 psychic damage when it enters the effect’s area for the first time on a turn or starts its turn there. Each of these hazards must be at least 20 feet from another hazard."],["p","While in this inner world, if you fail saving throw, you choose to succeed instead. You can do up to 3 times during the duration of the spell. All spells and powers have their psi point cost reduced by one."],["p","During the spell, as an action, you can attempt to destroy a creature within the world. The target must make an Intelligence saving throw. On failure, it takes 8d8 + 8 psychic damage and is removed from the imaginary world, returning to where they were before being pulled into it."],["p","The world can be brightly or dimly lit, and you control the weather within it."],["p","When the spell ends, you and any creature that remains in the world exit the world returning to space you entered the world from."],["p","Quickly Constructed Worlds"],["p","The casting time of this spell is 1 action, which is 6 seconds in"],["p","game. It is recommended that that you come up with a general"],["p","layout and any resources needed for this spell in collaboration"],["p","with your GM when you select the spell, and make at most minor"],["p","changes to the world when casting it."]],"con":1,"ci":1},{"k":"sp-instantbulwark","n":"Instant Bulwark","l":3,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Wizard"],"bk":"ll","p":238,"ct":"1 reaction, which you can take when a creature within range takes damage from a ranged attack or area effect","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You cause a 15-foot-long, 10-foot-tall, 6-inch thick wall of earth to erupt from the ground in an empty space you can see within range. The wall grants total cover and blocks any damage originating from the far side of the wall. It blocks ranged attacks and any area-ofeffect spells or magical effects with areas intersecting the wall."],["p","The wall has hit points equal to 4d10 + your spellcasting modifier. It takes all damage it blocks, even if that damage normally only affects creatures, but it only suffers the blocked damage one time even if it protects multiple creatures. If it is reduced to 0 hit points, it crumbles to dust and any excess damage is dealt as normal. If the wall is not destroyed, it crumbles at the start of your next turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the wall has 1d10 additional hit points and is 5 feet longer for each level above 3rd."]],"ms":["primal"]},{"k":"sp-instantcounter","n":"Instant Counter","l":2,"s":"Conjuration","sa":"CON","c":["Bard","Ranger","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":238,"ct":"1 reaction, which you take in response to being damaged by a creature within 30 feet of you that you can see","rg":"30 feet","cp":"V, S, M (a melee weapon worth at least 1 sp)","d":"Instantaneous","b":[["p","You vanish, teleporting to an empty space within 5 feet of the creature that damaged you, and immediately make a weapon attack against them with the weapon used in the spell’s casting."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, if your attack hits, it deals 1d8 additional force damage for each slot level above 2nd."]],"ms":["arcane"]},{"k":"sp-inuyarisbestialstride","n":"Inuyari’s Bestial Stride","l":6,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":563,"ct":"1 action","rg":"Touch","cp":"V, S, M (a wolf-head figurine worth at least 200 gp, which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","One creature you touch becomes infused with the bestial qualities of a yokai lord of wolves. For the duration of the spell they gain the following benefits:"],["li","They have advantage on Wisdom (Perception) and Wisdom (Survival) checks."],["li","They can track creatures by scent, and gain blindsight out to 60 feet."],["li","Their base movement speed increases to 60 feet (unless it was higher), and can also be used as climbing speed."],["li","They gain resistance to psychic and necrotic damage."],["li","They can conjure a wolf fang spear and attack with it on their turn. This weapon is a magical spear they have proficiency with, has the finesse and thrown (range 80/240 feet) properties, and deals piercing damage equal to 3d8 + your spellcasting ability modifier on a hit. It can appear and vanish in their hands with each attack as needed."],["li","They can use their bonus action to make one attack using the wolf fang spear or take the Dash or Disengage action."],["li","When the creature fails a saving throw, they can roll a d20 and use it in place of the one they rolled instead. If they succeed on a saving throw this way, they take no damage from the effect they were saving against even if they normally would take half. They can do this a number of times equal to half your proficiency bonus (rounded down)."],["li","During this period their shoulders and skin are covered in a thin layer of wisping black fur, their teeth sharpen, and their body language becomes more animalistic."]],"h":[["p","At Higher Levels. If cast at a higher level, the wolf fang spear deals an extra 1d8 damage if cast using an 8th-level slot, and can be thrown up to 500 feet without disadvantage caused by long range if cast at 9th level."]],"con":1,"g":["Daemoturgy"]},{"k":"sp-investlife","n":"Invest Life","l":3,"s":"Transmutation","sa":"TRA","c":["Cleric","Occultist","Wizard"],"bk":"ll","p":239,"ct":"1 action","rg":"Touch","cp":"S","d":"Instantaneous","b":[["p","You draw on your life force to invest some of your vital essence into another creature you can see within range. You take 4d8 necrotic damage, which can’t be reduced in any way, and one creature of your choice that you can see within range regains a number of hit points equal to twice the necrotic damage you take."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each slot level above 3rd."]],"ms":["arcane","primal","psionic"],"also":[["cc",139]]},{"k":"sp-investedcompetency","n":"Invested Competency","l":5,"s":"Psionic","sa":"PSI","c":["Psion"],"bk":"cc","p":139,"ct":"1 action","rg":"Touch","cp":"S","d":"Concentration, up to 1 hour","b":[["p","You touch a willing creature imbuing psionic competency into them. Until the spell ends, they gain expertise in on skill of your choice, adding double their proficiency bonus to that skill."]],"con":1,"ci":1},{"k":"sp-investitureoflightning","n":"Investiture of Lightning","l":7,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":563,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","Until the spell ends, lightning wraps around you and accelerates your senses and movement, giving you the following benefits:"],["li","Your movement speed is doubled."],["li","You are immune to lightning damage."],["li","When a creature hits you with a melee weapon attack from within 5 feet of you, they take 1d10 lightning damage."],["p","As a bonus action on your turn, you can summon a staff of lightning to strike a creature within 10 feet as a melee spell attack. On a hit, that target takes 6d10 lightning damage and must make a Constitution saving throw. On a failure they are sluggish until the start of your next turn."]],"h":[["p","At Higher Levels. If you cast this spell using a 9th level spell slot, you can make two attacks with the lightning staff instead of one, and if both attacks hit, the target must make a Constitution saving throw. On a failure they are stunned until the start of their next turn."]],"con":1,"g":["Sky-Keeper’s Arcana"]},{"k":"sp-irongarden","n":"Iron Garden","l":4,"s":"Transmutation","sa":"TRA","c":["Spellblade","Warlock","Wizard"],"bk":"ll","p":239,"ct":"1 action","rg":"Self (20-foot radius)","cp":"V, S","d":"Instantaneous","b":[["p","Iron spikes lance up from the ground, impaling every creature within 20 feet of you. Each creature in the area must make a Dexterity saving throw. On a failure, it takes 6d8 piercing damage and its speed drops to 0 until the end of its next turn. On a success, it takes half as much damage and its speed is not reduced."],["p","Until the start of your next turn, when a creature moves into or within the area, it takes 1d8 piercing damage for every 5 feet it travels. At the start of your next turn, the spikes rust away to dust."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the initial damage increases by 1d8 for each spell slot level above 4th."]],"ms":["arcane"]},{"k":"sp-ironwindstrike","n":"Iron Wind Strike","l":2,"s":"Conjuration","sa":"CON","c":["Ranger","Spellblade"],"bk":"ll","p":239,"ct":"1 action","rg":"Self (15-foot radius)","cp":"V, S, M (a melee weapon with which you are proficient worth at least 1 sp)","d":"Instantaneous","b":[["p","You flourish the weapon used in the casting and then vanish to strike like the wind. Choose up to three creatures you can see within range. Make a melee weapon attack against each target. On a hit, a target takes 3d8 damage of the weapon’s damage type."],["p","You can then teleport to an unoccupied space you can see within 5 feet of any of the targets."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd Level or higher, it deals an additional 1d8 damage to each target on hit for each slot level above 2nd."]],"ms":["arcane"]},{"k":"sp-irresistibledance","n":"Irresistible Dance","l":6,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":564,"ct":"1 action","rg":"30 feet","cp":"V","d":"Concentration, up to 1 minute","b":[["p","Choose one creature that you can see within range. The target begins a comic dance in place: shuffling, tapping their feet, and capering for the duration. Creatures that can’t be charmed are immune to this spell."],["p","A dancing creature must use all its movement to dance without leaving its space and has disadvantage on Dexterity saving throws and attack rolls. While the target is affected by this spell, other creatures have advantage on attack rolls against them. As an action, a dancing creature makes a Wisdom saving throw to regain control of themself. On a successful save, the spell ends."]],"con":1,"leg":1},{"k":"sp-jackalsluck","n":"Jackal’s Luck","l":1,"s":"Divination","sa":"DIV","c":[],"bk":"retia","p":564,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a peridot worth 50 gp or more, which the spell consumes)","d":"10 minutes","b":[["p","You grant a moment of luck to one willing creature you can see within range. When that creature makes an attack roll, ability check, or saving throw, they can spend this boon and roll one additional d20, then choose which of the d20 results they want to use to determine their result. Alternatively, when that creature is targeted by an attack, they can use this boon to roll one additional d20 and choose to use either their roll or the attacker’s d20 result for the attack. Once used the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, your target gains one additional use of this boon before the spell ends for every two slot levels above 1st."]],"g":["Skulker’s Grimoire"]},{"k":"sp-joyfultoxin","n":"Joyful Toxin","l":3,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":564,"ct":"1 action","rg":"Self","cp":"V, S, M (a dose of poison worth at least 100 gp)","d":"1 minute","b":[["p","For the spell’s duration you are immune to poison damage and cannot be poisoned. When you would have taken poison damage, you instead regain hit points equal to half the poison damage you would have taken (rounded down)."]]},{"k":"sp-jumpingjolt","n":"Jumping Jolt","l":4,"s":"Evocation","sa":"EVO","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":239,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You release an arc of lighting at a creature within range. Make a ranged spell attack roll against the target. On a hit, it takes 4d12 lightning damage, and you can cause the spell to jump to another target within 20 feet of the first, making a new attack roll for the new target. The spell cannot hit the same target twice, or jump to a target outside the spell's range. The spell can jump a maximum of five times."],["p","On a miss, a target takes half as much damage and the spell does not jump to a new target."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the starting damage increases by 1d12 for each slot level above 4th."]],"ms":["arcane"],"also":[["cc",139]]},{"k":"sp-karmaticresilience","n":"Karmatic Resilience","l":2,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":564,"ct":"1 reaction to failing a saving throw","rg":"Self","cp":"V","d":"1 minute","b":[["p","When you fail a saving throw that triggers this effect, you may re-roll the save with advantage (even if you had disadvantage before) and keep the new result. If this would cause you to succeed, you roll all subsequent saving throws using that ability score with disadvantage for the spell’s duration. The effect ends if you roll such a saving throw where all d20 results made for the save would have failed if taken individually (for example if you roll a Dexterity save with a DC of 15 and a +3 bonus where your d20 results are 11 and 9, the effect ends; if the results were 14 and 9 it continues)."]],"g":["Daemoturgy"]},{"k":"sp-karmicreflection","n":"Karmic Reflection","l":1,"s":"Enchantment","sa":"ENC","c":["Cleric","Occultist"],"bk":"ll","p":240,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a broken shard of a mirror)","d":"1 round","b":[["p","You place a magical binding on a creature you can see within range. Until the start of your next turn, anytime that creature deals damage with its action, bonus action, or reaction, it takes radiant damage equal to the damage dealt, up to a maximum of 10 damage."],["p","The target is aware of spell's effects. After reflecting 10 damage, spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the maximum damage increases by 10 for each spell slot level above 2nd."]],"ms":["divine"]},{"k":"sp-kelliasdeceptivemark","n":"Kellia’s Deceptive Mark","l":3,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":564,"ct":"1 bonus action","rg":"30 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","Choose one target within range. That creature must make a Wisdom saving throw or else be marked by this spell. For the duration, an invisible band appears over their eyes that only creatures who can see invisible objects are aware of, seeing it as a band of cloth wrapped around their head. Creatures marked by this spell cannot see you, treating you as if you were invisible."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature within range for every slot level above 3rd."]],"con":1,"g":["Skulker’s Grimoire"]},{"k":"sp-killingcurse","n":"Killing Curse","l":5,"s":"Necromancy","sa":"NEC","c":["Occultist"],"bk":"ll","p":240,"ct":"1 action","rg":"60 feet","cp":"V, S, M (something from the target creature—such as blood, hair, or scales—which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You curse a target to die. Its current and maximum hit points are reduced by 3d10 + 10. If this causes the creature to have 0 hit points, it dies."],["p","For the duration, the target cannot regain hit points except from a spell of a higher level than this one, and any death saving throw it rolls is automatically considered a 1."],["p","At the start of each of the target's turns, it makes a Charisma saving throw. On a failure, its current and maximum hit points are reduced by 1d10 + 10. On a success, the spell ends. A creature’s maximum hit points are restored when it finishes a long rest."]],"con":1,"ms":["arcane"],"also":[["cc",139]]},{"k":"sp-laboriousflight","n":"Laborious Flight","l":2,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":564,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"10 minutes","b":[["p","Up to 3 creatures you choose within range are granted the ability to fly through ethereal arcane wings that sprout from their back for the spell’s duration, though it is difficult to use them. These creatures gain a belabored flight speed of 20 feet. Additionally, if any creature targeted by this spell already has a belabored flight speed, that speed becomes fly speed for the duration (this new fly speed does not gain extra feet from this spell)."]],"h":[["p","At Higher Levels. When you cast this spell at 3rd level or higher, you can choose one of the following effects for each slot"],["p","level above 2nd:"],["li","The belabored flight speed granted by this spell increases by 10 feet."],["li","You can target one additional creature in range."],["li","The spell’s duration is doubled."]]},{"k":"sp-landsfury","n":"Land’s Fury","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":565,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You call out to the spirits of nature to rouse them against your enemies. Choose a point you can see within range. The spirits cause trees, rocks, and grasses in a 60-foot cube centered on that point to become animated until the spell ends."],["p","Grasses and Undergrowth. Any area of ground in the cube that is covered by grass or undergrowth is difficult terrain for your enemies."],["p","Trees. At the start of each of your turns, each of your enemies within 10 feet of any tree in the cube must succeed on a Dexterity saving throw or take 4d6 slashing damage from whipping branches."],["p","Roots and Vines. At the end of each of your turns, one creature of your choice that is in contact with the ground within the cube must succeed on a Strength saving throw or become restrained until the spell ends. A restrained creature can use an action to make a Strength (Athletics) check against your spell save DC, ending the effect on themself on a success."],["p","Rocks. As a bonus action on your turn, you can cause a loose rock in the cube to launch at a creature you can see that is in the cube. Make a ranged spell attack against the target. On a hit, the target takes 3d8 nonmagical bludgeoning damage, and they must succeed on a Strength saving throw or fall prone."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","The size of the cube increases by 30 feet."],["li","The range surrounding trees in which creatures are damaged increases by 5 feet."],["li","The damage for the trees effect and for the rocks effects increase by 1d6 and 1d8 respectively."],["li","When you use your bonus action to launch rocks, you can launch a rock at one additional target within range."]],"con":1,"leg":1},{"k":"sp-lashingwillow","n":"Lashing Willow","l":6,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":565,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a seed capable of growing a tree)","d":"Concentration, up to 1 minute","b":[["p","At a point you can see within 60 feet, a tree appears and occupies all of the surrounding spaces. The tree is a large object with AC equal to your spell save DC and hit points equal to the level you cast this spell at x 10. It is unaffected by effects that require an Intelligence, Wisdom or Charisma saving throw or check. The tree remains until the spell ends or it is destroyed, at which point it withers and dies."],["p","Each time a creature that is hostile to you starts their turn within 10 feet of the tree or moves into a space in that range for the first time on their turn, vines and roots lash out and attempt to bind them. The target must succeed a Strength saving throw or be restrained by the tree. Creatures that fail and are smaller than the tree are pulled into one of the tree’s spaces, where bark grows around them and holds them in place. One creature can be held this way per space the tree occupies, and bound creatures are able to breathe through the tree, but are blinded and deafened while inside it."],["p","A creature restrained by the tree can attempt a Strength check against your spell save DC to escape, requiring an action to do so. If they score a critical hit against the tree they also escape automatically. A creature that ends its turn restrained by the tree is bludgeoned by it, taking 3d10 bludgeoning damage."],["p","On your turn you can command the tree not to bludgeon creatures it captures, to bludgeon only specific creatures it captures, to bludgeon all creatures again, or to release specific creatures it is holding. As a bonus action you can command it to rearrange the position of any creature it has captured, moving any creatures smaller than it to a space that can fit them within 10 feet of it."]],"h":[["p","At Higher Levels. If you cast this spell using a 7th level spell slot or higher, you can choose one of the following effects for every slot level above 6th:"],["li","The size of the tree increases by one size category and it gains 5 extra hit points per slot level."],["li","The tree’s bludgeoning damage increases by 1d10."],["li","The tree’s armor class increases by 2."]],"con":1,"g":["Whisperwood Tome"]},{"k":"sp-launchobject","n":"Launch Object","l":1,"s":"Transmutation","sa":"TRA","c":["Inventor"],"bk":"cc","p":139,"ct":"1 action","rg":"60 feet","cp":"S","d":"Instantaneous","b":[["p","Choose one tiny object weighing 1 to 5 pounds within range that isn’t being worn or carried. The object flies in a line up to 90 feet in a direction of your choice before falling to the ground, stopping early if it impacts against a creature, object, or surface. If the object would strike a creature, that creature must make a Dexterity saving throw. On a failed save, the object strikes the target and stops moving. When the object strikes something, the object and what it strikes each take 3d8 bludgeoning damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the maximum weight of objects that you can target with this spell increases by 5 pounds, and the damage increases by 1d8, for each slot level above 1st."]]},{"k":"sp-legendaryprotection","n":"Legendary Protection","l":5,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":566,"ct":"1 action","rg":"Touch","cp":"V, S, M (a handful of gold dust worth at least 250 gp, which the spell consumes)","d":"10 minutes","b":[["p","One creature you touch is protected by a fate-altering ward. The next three times they make a saving throw, any d20 result on that save that is less than 15 is treated as a 15 instead."]],"h":[["p","At Higher Levels. When you cast this spell at 7th level or higher, the number of times the effect can trigger before the spell ends is increased by one for every two slot levels above 5th."]],"g":["Chromatic Convocation"]},{"k":"sp-lifelink","n":"Life Link","l":5,"s":"Abjuration","sa":"ABJ","c":["Cleric","Occultist","Warlock","Wizard"],"bk":"llb","p":295,"ct":"1 action","rg":"30 feet","cp":"S, M (a splash of your blood worth at least 5 hit points, which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You link the life of two creatures you can see within range. Choose either a Life Link or an Inverse Life Link when you cast the spell."],["li","Life Link. When either target regains hit points, the other target regains the same amount. When either target takes damage, the other target takes an equal amount of necrotic damage."],["li","Inverse Life Link. When either target loses hit points, the other is healed for an equal number of hit points. When either target regains hit points, the other takes an equal amount of necrotic damage."],["p","Damage or healing inflicted by this spell does not trigger the link's effects. The link lasts until the spell ends or it has inflicted 40 hit points of healing or damage."]],"h":[["p","At Higher Levels. When you cast this spell with a spell slot of 6th level or higher, the number of hit points the link can transfer increases by 10 for each slot level above 5th."]],"con":1,"bm":1},{"k":"sp-lifesupport","n":"Life Support","l":5,"s":"Necromancy","sa":"NEC","c":["Cleric","Occultist","Wizard"],"bk":"llb","p":295,"ct":"1 reaction, which you can take when a creature is reduced to 0 hit points within range","rg":"60 feet","cp":"S, M (a splash of your blood worth at least 5 hit points, which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","When a creature you can see within range is reduced to 0 hit points, you can sacrifice your own vitality to bolster its life force. For the duration, the target can continue acting while at 0 hit points and does not fall unconscious. Any damage it takes is transferred to you. If the target is healed above 0 hit points, the spell ends."]],"con":1,"bm":1},{"k":"sp-lightningcharged","n":"Lightning Charged","l":2,"s":"Evocation","sa":"EVO","c":["Inventor"],"bk":"ll","p":240,"ct":"1 action","rg":"Touch","cp":"V, S, M (a piece of metal once used in a lightning rod)","d":"10 minutes","b":[["p","You charge a creature you touch with sparking electricity, causing it no damage but making its touch dangerous for others. Every time the target hits another creature with a melee attack or a spell with a range of touch, is hit with a melee attack by another creature, or ends its turn while grappling or being grappled by another creature, the other creature takes 1d6 lightning damage."],["p","Once this spell has discharged 6 times (dealing up to 6d6 damage), the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the spell can discharge 2 additional times (dealing 2d6 more total damage) before the spell ends for each slot level above 2nd."]],"ms":["arcane"],"also":[["cc",139]]},{"k":"sp-lightninghurl","n":"Lightning Hurl","l":3,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":566,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","The next time you make a ranged weapon attack during the spell’s duration, the weapon’s ammunition (or the weapon itself if it’s a thrown weapon) transforms into a bolt of lightning. Make the attack roll as normal. The target takes 4d8 lightning damage on a hit, or half as much on a miss, instead of the weapon’s normal damage."],["p","Whether you hit or miss, each creature within 10 feet of the target must make a Dexterity saving throw. Each of these creatures takes 2d8 lightning damage on a failed save, or half as much on a successful one. The piece of ammunition or weapon then returns to its normal form."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, you can choose one of the following effects for each slot level above 3rd:"],["li","The spell’s damage increases by 1d8."],["li","The attack roll made as part of the spell’s attack gains a +1 bonus."],["li","The spell still deals the weapon’s normal damage on top of the lightning damage, but only on a hit."],["li","The range at which other creatures are affected around the target increases by 5 feet."]],"con":1,"leg":1},{"k":"sp-lightningshot","n":"Lightning Shot","l":3,"s":"Transmutation","sa":"TRA","c":["Ranger"],"bk":"ll","p":240,"ct":"1 bonus action","rg":"Touch","cp":"V, S, M (a piece of ammunition or a weapon worth at least 1 cp)","d":"1 round","b":[["p","You touch a piece of ammunition or a weapon with the thrown property, imbuing it with crackling lightning for the duration."],["p","The first time you attack with the empowered item, it transforms into a bolt of lightning, blasting out from you in a line 100 feet long and 5 feet wide. Make one weapon attack, applying the result against every creature in the line. This attack deals 4d8 lightning damage on a hit, and half as much damage on a miss. This damage roll doesn't add any modifiers or bonuses associated with weapon attacks. The lightning ignites flammable objects in the area that aren’t being worn or carried."],["p","Once an attack has been made with the piece of ammunition or weapon, the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each level above 3rd, up to a maximum of 6d8 at 5th level."]],"ms":["primal"]},{"k":"sp-lightningstorm","n":"Lightning Storm","l":3,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":566,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","A storm cloud appears in the shape of a cylinder that is 10 feet tall with a 60-foot radius, centered on a point you can see within range directly above you. The spell fails if you can’t see a point in the air where the storm cloud could appear (for example, if you are in a room that can’t accommodate the cloud)."],["p","When you cast the spell, choose a point you can see under the cloud. A bolt of lightning flashes down from the"],["p","cloud to that point. Each creature within 5 feet of that point must make a Dexterity saving throw. A creature takes 3d10 lightning damage on a failed save, or half as much damage on a successful one. On each of your turns until the spell ends, you can use your action to call down lightning in this way again, targeting the same point or a different one."],["p","If you are outdoors in stormy conditions when you cast this spell, the spell gives you control over the existing storm instead of creating a new one. Under such conditions, the spell’s damage increases by 1d10."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, you can choose one of the following effects for each slot level above 3rd:"],["li","The damage increases by 1d10."],["li","When you cast the spell and when you use your action to strike a point with lightning, you can choose an additional point for a lightning bolt to strike. Creatures only take damage from one bolt even if they overlap."]],"con":1,"leg":1},{"k":"sp-lightningtendril","n":"Lightning Tendril","l":1,"s":"Evocation","sa":"EVO","c":["Druid","Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":241,"ct":"1 bonus action","rg":"Self (20 feet)","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","Crackling beams of blue energy leap from your hands. For the duration of the spell, as an action, you can direct them toward a creature within range, dealing 1d12 lightning damage to that creature."]],"h":[["p","At Higher Levels. When you cast this spell using a 2nd- or 3rd-level spell slot, the damage increases to 2d12 and the range increases to 30 feet. When you cast it using a 4th- or 5th-level spell slot, the damage increases to 3d12 and the range increases to 60 feet. When you cast it using a spell slot of 6th level or higher, the damage increases to 4d12 and the range increases to 120 feet."]],"con":1,"ms":["arcane","primal"],"also":[["cc",140]]},{"k":"sp-linkspell","n":"Link Spell","l":1,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":566,"ct":"Special","rg":"Special","cp":"S","d":"Instantaneous","b":[["p","When you cast a spell with a casting time of 1 action, you may cast this spell before it to change that spell’s casting time to 1 bonus action. This spell must be cast at a level equal to half the level of the spell you are affecting with it (rounded up). When you make an eidomancy burn check for this spell, make it as if this spell was cast at the level of the spell you are affecting."],["p","Lycrothemia’s Lunar Devastation"]],"g":["Eidomancy","Epic of Duality"]},{"k":"sp-literalmanifest","n":"Literal Manifest","l":0,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":566,"ct":"1 action","rg":"Self","cp":"S","d":"Instantaneous","b":[["p","While touching a blank sheet of paper, you take a quick observation of everything within your field of vision. A complete documentary of what you see is copied onto the paper in expoentrum - arcane ink - written in text that may be too small to read. When another creature touches the sheet of paper, they can use their action to focus on it and visibly witness a perfect visual reproduction of what you could see, which blinds them to everything else for as long as they remain in contact with it."]]},{"k":"sp-lucielsgrandbolt","n":"Luciel’s Grandbolt","l":8,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":567,"ct":"1 bonus action","rg":"Self","cp":"V, S, M (a miniature metal lance)","d":"Concentration, up to 10 minutes","b":[["p","A radiant bolt of light gathers in your palm and bursts into the shape of a twisting white quartz spear. This spear remains in your possession for the spell’s duration. As a bonus action on your turn (and once when you cast this spell), you can charge the spear with radiant and celestial energy, and unleash their combined force in a 50-foot line originating from you. All creatures in that line must make a Dexterity saving throw, taking 8d6 radiant damage and 8d6 necrotic damage on a failed save, or half as much on a successful one."],["p","You can also use the spear to make a melee spell attack as an action, targeting any creature within 10 feet, dealing either 6d10 radiant damage or 6d10 necrotic damage (you choose when attacking) on a successful hit."],["p","If the spell ends because you unwillingly lose concentration on it, you may use your reaction to cause the spear to detonate, targeting the creature that ended your concentration with the same save and potential damage from the bonus action line effect."],["p","56 7"]],"con":1},{"k":"sp-lycrothemiaslunardevastation","n":"Lycrothemia’s Lunar Devastation","l":9,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":567,"ct":"1 action","rg":"120 feet","cp":"V, S, M (a handheld replica of Somnus Domina’s lesser moon Lycrothemia, with six gemstone slots ringing around it, worth at least 1000 gp. These slots must be filled each with a star ruby worth at least 750 gp each, which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","A massive network of arcane sigils and circles appear as high as 500 feet in the sky over a point within range, which collectively form a circle with a 120-foot radius. When it appears, the circles gather ambient eidomantic radiation and fire it as a lance of pure energy at any point beneath it that you choose, exploding in a 60-foot-radius sphere (you may reduce the sphere to as little as a 10-foot radius, should you wish to). All creatures in that space must make a Dexterity saving throw, taking 7d10 lightning damage and 7d10 radiant damage on a failed save, or half as much damage on a successful one."],["p","At the start of each of your turns, the massive circle gathers and generates 1d4 charges, which it retains until used or the spell ends. You can use them for the following features:"],["p","Abjuration Resistance. Creatures attempting to dispel this spell roll spellcasting ability checks to do so with disadvantage."],["p","Arcane Lance. On your turn you can use an action to spend any number of these charges and target an equal number of creatures within 240 feet of the spell’s center with a ranged spell attack each, launching lances of pure arcane power that deal 3d10 lightning damage and 3d10 radiant damage on a hit. These attacks ignore cover. You cannot target the same creature twice with the same action. If you choose to target only one creature with a lance you can do so as a bonus action."],["p","Decomposition. Any creature that is reduced to 0 hit points by this spell is completely destroyed, as though by the disintegrate spell."],["p","Intercept. If you are underneath the circle and are targeted by a ranged weapon attack while not incapacitated, you may spend 1 charge from this spell to intercept the attack with one of the arcane lances, applying a -10 penalty to the attack roll."],["p","Moonfall Barrage. You can use an action to spend 10 of these charges, ending the spell and targeting all creatures you choose within range with the same ranged spell attacks as described under Arcane Lance."],["p","Teleport. As a bonus action, you may spend 2 charges to teleport to any unoccupied space under the circle, as long as you aren’t incapacitated and can perform somatic components. After you do, you cannot take any movement until the start of your next turn."],["p","This spell’s material components are not consumed if one of the rubies in the moon replica is the primal gemstone of Vestias."]],"con":1,"g":["Eidomancy","Sky-Keeper’s Arcana"]},{"k":"sp-macabremarionette","n":"Macabre Marionette","l":4,"s":"Necromancy","sa":"NEC","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":295,"ct":"1 action","rg":"60 feet","cp":"S, M (a splash of your blood worth at least 4 hit points, which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You attempt to control a creature’s movements by using its to blood manipulate it like a puppet. The target must succeed on a Wisdom saving throw or become partially controlled. For the duration, you can use your bonus action to force the target to spend its reaction to move up to 20 feet (or its movement speed, whichever is less) and make a single weapon attack against a target of your choice."],["p","Until the target breaks free of the spell, it cannot take reactions normally. At the end of each of the target’s turns, it can repeat the saving throw, ending the spell on success."]],"con":1,"bm":1},{"k":"sp-magicaura","n":"Magic Aura","l":2,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":568,"ct":"1 action","rg":"Touch","cp":"V, S, M (a small square of silk)","d":"24 hours","b":[["p","You place an illusion on a creature or an object you touch so that divination spells reveal false information about it. The target can be a willing creature or an object that isn’t being carried or worn by another creature."],["p","When you cast the spell, choose one or both of the following effects. The effect lasts for the duration. If you cast this spell on the same creature or object every day for 30 days, placing the same effect on it each time, the illusion lasts until it is dispelled."],["p","False Aura. You change the way the target appears to spells and magical effects that detect magical auras (such as detect magic). You can make a nonmagical object appear magical, a magical object appear nonmagical, or change the object’s magical aura so that it appears to belong to a specific school of magic that you choose. When you use this effect on an object, you can make the false magic apparent to any creature that handles the item."],["p","Mask. You change the way the target appears to spells and magical effects that detect creature types, such as a paladin’s Divine Sense or the trigger of a symbol spell."],["p","You choose a creature type and other spells and magical effects treat the target as if it were a creature of that type or of that alignment."]],"leg":1},{"k":"sp-magnesiassmotheringvoice","n":"Magnesia’s Smothering Voice","l":3,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":568,"ct":"1 action","rg":"Self (20-foot radius)","cp":"V","d":"Concentration, up to 1 minute","b":[["p","You speak a phrase commanding silence, which is understood by all creatures within 20 feet of you. All creatures within that range must make a Wisdom saving throw. On a failure, they lose the ability to understand other creatures or read any written language for the spell’s duration except that which originates from you - all other language seems like gibberish to them. They can still understand and produce their own words."],["p","For the duration, you can speak telepathically to any creature under this effect as long as you are on the same plane."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the spell’s range doubles for every slot level above 3rd."]],"con":1,"g":["Skulker’s Grimoire"]},{"k":"sp-magnificentmansion","n":"Magnificent Mansion","l":7,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":568,"ct":"1 minute","rg":"300 feet","cp":"V, S, M (a miniature portal carved from ivory, a small piece of polished marble, and a tiny silver spoon, each item worth at least 5 gp)","d":"24 hours","b":[["p","You conjure an extradimensional dwelling in range that lasts for the duration and decide the location to its singular entrance, which shimmers faintly and is 5 feet wide and 10 feet tall. You and any creature you designate when you cast the spell can enter the dwelling as long as the portal remains open. You can open or close the portal if you are within 30 feet of it. While closed, the portal is invisible. Beyond the portal is a foyer with numerous chambers beyond. The atmosphere is clean, fresh, and warm."],["p","You can create any floor plan you like, but the space can’t exceed 50 cubes, the sides of each cube being 10 feet long. The dwelling is furnished and decorated as you choose. It contains sufficient food to serve a nine course banquet for up to 100 people, and a staff of 100 near-transparent servants attend all who enter, and are completely obedient to your orders - the visual appearance and attire of these servants are determined by yourself. Each servant can perform any task a normal human servant could perform, but they can’t attack or take any action that would directly harm another creature. Thus, the servants can fetch things, clean, mend, fold clothes, light fires, serve food, pour wine, and so on. They can go anywhere in the mansion but can’t leave it. Furnishings and other objects created by this spell dissipate into smoke if removed from the mansion. When the spell ends, any creatures or objects left inside the extradimensional space are expelled into the open spaces nearest to the entrance."]],"leg":1,"g":["Ossenheimer’s Memoirs"]},{"k":"sp-manipulateearth-ll","n":"Manipulate Earth","l":0,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":241,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Varies","b":[["p","You mold earth you can see within range, causing it to twist and buckle to your command. Select one of the following effects:"],["li","You can excavate a 5-foot cube of loose dirt or soil and move it along the ground to another unoccupied space within 5 feet."],["li","You can make minor alterations to dirt or stone, such as changing its color or carving small, simple shapes."],["li","You can turn a 5-foot square of earth or stone into difficult terrain for 1 hour. You can create up to three patches of difficult terrain this way; if you create additional patches, the first one you created returns to normal terrain."]],"ms":["arcane","primal"]},{"k":"sp-manipulateearth-retia","n":"Manipulate Earth","l":0,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":568,"ct":"1 action","rg":"30 feet","cp":"S","d":"Instantaneous or 1 hour (see below)","b":[["p","You choose a portion of dirt or stone that you can see within range and that fits within a 5-foot cube. You manipulate it in one of the following ways:"],["li","If you target an area of loose earth, you can instantaneously excavate it, move it along the ground, and deposit it up to 5 feet away. This movement doesn’t involve enough force to cause damage."],["li","You cause shapes, colors, or both to appear on the dirt or stone, spelling out words, creating images, or shaping patterns. The changes last for 1 hour."],["li","If the dirt or stone you target is on the ground, you cause it to become difficult terrain. Alternatively, you can cause the ground to become normal terrain if it is already difficult terrain. This change lasts for 1 hour."],["p","If you cast this spell multiple times, you can have no more than two of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action."],["p","56 8"]],"leg":1},{"k":"sp-manipulateego","n":"Manipulate Ego","l":0,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":569,"ct":"1 action","rg":"Self","cp":"S, M (a small amount of makeup applied to the face as this spell is cast)","d":"Concentration, up to 1 minute","b":[["p","For the duration, you have advantage on all Charisma checks directed at one creature of your choice that isn’t hostile towards you. When the spell ends, the creature realizes that you used magic to influence its mood and becomes hostile toward you."]],"con":1,"leg":1},{"k":"sp-manipulatefate","n":"Manipulate Fate","l":9,"s":"Divination","sa":"DIV","c":["Occultist","Wizard"],"bk":"ll","p":241,"ct":"1 action","rg":"Self","cp":"V, S, M (a spool of silk thread)","d":"Concentration, up to 1 minute","b":[["p","You reach out and grasp the imperceptible threads of fate, enabling yourself to subtly manipulate them. For the duration when a creature within 60 feet of you makes an attack roll, saving throw, or ability check, you can use your reaction to tweak its fate, altering the die result. You can choose to manipulate fate after the die is rolled, but before the outcome is determined."],["p","You can nudge the roll to your choice of adjacent faces on the die (potential outcomes listed below)."],["tbl",[["d20","Tweaked Fates"],["1","7, 13, or 19"],["2","12, 18, or 20"],["3","17, 16, or 19"],["4","11, 14, or 18"],["5","13, 15, or 18"],["6","9, 14, or 16"],["7","1, 15, or 17"],["8","10, 16, or 20"],["9","6, 11, or 19"],["10","8, 12, or 17"],["11","4, 9, or 13"],["12","2, 10, or 15"],["13","1, 5, or 11"],["14","4, 6, or 20"],["15","5, 7, 12"],["16","3, 6, or 8"],["17","3, 7, or 10"],["18","2, 4, or 5"],["19","1, 3, or 9"],["20","2, 8, or 14"]]],["p","Instead of nudging, you can instead choose to cast"],["p","aside subtlety and yank the thread of fate, selecting"],["p","any value on the d20 as the result. If you do so, you"],["p","suffer a backlash. Roll a number of d6 equal to the"],["p","difference between your selection and the original"],["p","result; you take that much necrotic damage, and the"],["p","spell immediately ends."],["p","Dice Mechanics Note"],["p","The numbers you can pick are the adjacent sides of a d20"],["p","to the number rolled. This represents literally nudging the"],["p","die of fate."]],"rv":1,"con":1,"ms":["arcane"]},{"k":"sp-manipulatefire","n":"Manipulate Fire","l":0,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":242,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Varies","b":[["p","You control a fire you can see within range, causing it to bend to your command. Select one of the following effects:"],["li","You can grant a creature of your choice within range resistance to fire damage until the start of your next turn."],["li","You can spark or spread fire in a 5-foot cube, as long as there is fuel that can be ignited within the area."],["li","You can douse fire within a 5-foot cube."],["li","You can adjust a flame's brightness (halving or doubling it), color (turning the flames to any color of your choice), or shape (forming simple shapes) within a 5-foot cube for 10 minutes."]],"ms":["arcane","primal"]},{"k":"sp-manipulatewater-ll","n":"Manipulate Water","l":0,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":242,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Varies","b":[["p","You shape water you can see within range, causing it to move at to your command. Select one of the following effects:"],["li","You can move or direct the flow of a 5-foot cube of"],["p","water in a direction of your choice, but the water will revert back to its natural flow at the start of your next turn unless you concentrate on keeping it in place."],["li","You can mold the water into small shapes or simple animations. This change lasts for 1 minute."],["li","You can change the color or opacity of a 5-foot cube of water. This change lasts for 1 hour."],["li","You can freeze up to a 5-foot cube of unoccupied water or thaw up to a 5-foot cube of ice. The water unfreezes or refreezes naturally based on the environmental conditions (usually taking an hour or more to completely melt or freeze unless in extreme conditions)."]],"ms":["arcane","primal"]},{"k":"sp-manipulatewater-retia","n":"Manipulate Water","l":0,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":569,"ct":"1 action","rg":"30 feet","cp":"S","d":"Instantaneous or 1 hour (see below)","b":[["p","You choose an area of water that you can see within range and that fits within a 5-foot cube. You manipulate it in one of the following ways:"],["li","You instantaneously move or otherwise change the flow of the water as you redirect it, up to 5 feet in any direction. This movement doesn’t have enough force to cause damage."],["li","You cause the water to form into simple shapes and animate at your direction. This change lasts for 1 hour."],["li","You change the water’s color or opacity. All water affected must be changed in the same way throughout. This change lasts for 1 hour."],["li","You freeze the water, provided that there are no creatures in it. The water unfreezes after 1 hour."],["p","If you cast this spell multiple times, you can have no more than two of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action."]]},{"k":"sp-manipulatewind","n":"Manipulate Wind","l":0,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":242,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"1 round","b":[["p","You create a small gust within range, causing the air to surge and swirl to your command. Select one of the following effects:"],["li","The next ranged weapon attack against a creature of your choice within range has disadvantage."],["li","One Large or smaller creature of your choice within range must succeed on a Strength saving throw or be pushed 5 feet or knocked prone (your choice)."],["li","You can increase the next jump made by a creature of your choice within range by 5 feet."],["li","You manipulate the wind in a minor way, such as pushing a light object up to 10 feet, rustling plants, slamming a door, or similar effects. These aren’t powerful enough to move creatures or deal damage."]],"ms":["arcane","primal"]},{"k":"sp-martialtransformation","n":"Martial Transformation","l":6,"s":"Transmutation","sa":"TRA","c":["Wizard"],"bk":"ll","p":242,"ct":"1 action","rg":"Self","cp":"V, S, M (a small statuette of a warrior)","d":"10 minutes","b":[["p","You empower yourself with the physical prowess and battle knowledge of famous warriors. Until the spell ends, you can't cast spells or concentrate on them, and you gain the following benefits:"],["li","You gain 50 temporary hit points for the duration."],["li","You have advantage on all weapon attacks, and when you hit a target with a weapon attack, it takes an extra 2d12 force damage."],["li","You have proficiency with all armor, shields, simple weapons, martial weapons, and Strength and Constitution saving throws."],["li","You can attack twice, instead of once, when you take the Attack action on your turn, unless you already have a feature (such as Extra Attack) which gives you extra attacks."],["li","You can conjure and equip (as part of the action used to cast the spell) any armor and any simple or martial weapon of your choice. These items have no strength requirements and are magical in nature, but otherwise have the same properties as their nonmagical counterparts. The equipment vanishes when the spell ends."],["p","Immediately after the spell ends, you must succeed on a DC 15 Constitution saving throw or suffer one level of exhaustion. You can end the spell as a bonus action."],["p","Wizardly Note: The Lost True Version"],["p","Another example of a great wizard’s spell being tragically and"],["p","incompletely copied from an ancient source. Lesser versions"],["p","clearly forgot to include the lines that equip the caster with"],["p","gear to accompany its transformation."]],"ms":["arcane"],"also":[["cc",140]]},{"k":"sp-massburdenedblood","n":"Mass Burdened Blood","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":569,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a flask of blood)","d":"Instantaneous","b":[["p","Up to 6 creatures you choose within range are given enhanced fortitude, gaining an amount of temporary hit points equal to 4d6 + your spellcasting ability modifier. These temporary hit points disappear after 1 minute."],["p","Every time one of these creatures makes an attack roll, they can choose to lose 5 of these temporary hit points to give that attack advantage, and/or 5 to negate any disadvantage they would have had."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the temporary hit points gained increases by 1d6 for each slot level above 5th."]],"g":["Daemoturgy"]},{"k":"sp-masscommand","n":"Mass Command","l":8,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":569,"ct":"1 action","rg":"60 feet","cp":"V","d":"1 round","b":[["p","You speak a one-word command to any number of creatures that can hear you within the spell’s range. Each target must succeed on a Wisdom saving throw or follow the command on their next turn. This spell has no effect if the target is undead, if they don’t understand your language, or if your command is directly harmful to it. Once it has accomplished whatever is described by the spell to the best of its abilities, it ends its turn."],["p","The command you give can be the same type described by the command spell, with the same examples described below. If the target is incapable of following your command, the spell’s effect on them ends."],["p","Approach. The target moves toward you by the shortest and most direct route, ending its turn if it moves within 5 feet of you."],["p","Drop. The target drops whatever it is holding and then ends its turn."],["p","Flee. The target spends its turn moving away by the fastest available means."],["p","Grovel. The target falls prone and then ends its turn."],["p","Halt. The target doesn’t move and takes no actions. A flying creature stays aloft, provided that it is able to do so. If it must move to stay aloft, it flies the minimum distance needed to remain in the air."]],"g":["Legacy of Gold"]},{"k":"sp-melt","n":"Melt","l":6,"s":"Transmutation","sa":"TRA","c":["Sorcerer","Wizard"],"bk":"ll","p":243,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You point at a creature or Large or smaller object that is not being worn or carried within range, and attempt to make it melt into a puddle of slag. If the target is a creature, it makes a Constitution saving throw. On a failure, it takes 10d10 fire damage. On a success, it takes half as much damage."],["p","If the target is an object, it takes 20d10 fire damage. If this reduces it to 0 hit points, it is melted into a puddle of slag."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 7th level or higher, the damage increases by 1d10 for each slot level above 6th."]],"ms":["arcane"]},{"k":"sp-meltingglob","n":"Melting Glob","l":1,"s":"Conjuration","sa":"CON","c":["Inventor","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":243,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"1 minute","b":[["p","You hurl a glob of acid at a creature within range, making a ranged spell attack. On a hit, the target takes 4d4 acid damage, and is covered in acid. For 1 minute, it takes 1d4 acid damage at the end of each of its turns. The target or another creature within 5 feet can end the effect early by using an action to clear off the acid."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the initial damage increases by 2d4 for each slot level above 1st."]],"ms":["arcane"]},{"k":"sp-mentalfortification","n":"Mental Fortification","l":3,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":569,"ct":"1 action","rg":"30 feet","cp":"V","d":"Concentration, up to 1 hour","b":[["p","For the duration, you or one willing creature you can see within range has resistance to psychic damage, as well as advantage on Intelligence, Wisdom, and Charisma saving throws. If a creature attempts to read the thoughts of this spell’s target while they are under this effect, the target become aware of it, and can choose to end the spell to automatically shut the creature out of their mind for 24 hours."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd. The creatures must be within 30 feet of each other when you target them."]],"con":1,"leg":1,"g":["Ossenheimer’s Memoirs"]},{"k":"sp-mentaltether","n":"Mental Tether","l":2,"s":"Divination","sa":"DIV","c":[],"bk":"retia","p":569,"ct":"1 action","rg":"60 feet","cp":"S","d":"Concentration, up to 1 hour","b":[["p","You reach into the mind of one creature you can see within range. The target must make a Wisdom saving throw, taking 3d8 psychic damage on a failed save, and their location is made known to you until the spell ends so long as your are both on the same plane of existence. While you have this knowledge, the target can’t become hidden from you, and if they are invisible, they gain no benefit from that condition against you. On a successful save, the target takes half as much damage and you are not made privy to their location."],["p","If anything causes this effect to break apart due to you unwillingly ending concentration (such as by moving to a different plane, you taking damage that results in a failed concentration check, or dispelling it using magic), the target takes the spell’s damage again."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you gain one of the following effects for each slot level above 2nd:"],["li","The damage increases by 1d8."],["li","You can target one additional creature within range (the spell’s effect ending as described causes it to affect all targets the connection is broken for)."]],"con":1,"leg":1},{"k":"sp-meteorjump","n":"Meteor Jump","l":3,"s":"Transmutation","sa":"TRA","c":["Spellblade","Sorcerer","Wizard"],"bk":"ll","p":243,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"Instantaneous","b":[["p","You drastically reduce your weight and immediately jump up to triple your maximum jump distance without spending any movement. When you reach the jump's maximum height, your weight and density are instantly increased, causing you to crash down with great force."],["p","Every creature within 10 feet of where you land must make a Strength saving throw. On a failure, a creature takes 2d10 bludgeoning damage and is knocked prone. On a success, it takes half as much damage and is not knocked prone. You take no falling damage if the fall was less than 100 feet."],["p","If you land directly on top of another creature that is no more than two sizes larger than you, it has disadvantage on its saving throw against the spell and is pushed to an adjacent empty space of your choice (regardless of its save result)."]],"ms":["arcane"]},{"k":"sp-mindblast","n":"Mind Blast","l":6,"s":"Psionic","sa":"PSI","c":["Psion"],"bk":"cc","p":140,"ct":"1 action","rg":"Self (60-foot cone)","cp":"S","d":"Instantaneous","b":[["p","You emit a blast of psychic energy. Each creature in a 60-foot cone must make an Intelligence saving throw. A creature takes 6d8 psychic damage and is stunned until the end of their next turn on a failed save. A creature takes half as much damage and is not stunned on a successful save."]],"ci":1},{"k":"sp-mindray","n":"Mind Ray","l":1,"s":"Enchantment","sa":"ENC","c":["Bard","Warlock","Sorcerer","Wizard"],"bk":"ll","p":244,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You launch a ray of mental energy from your mind at the mind of another creature within range. This ray ignores cover and passes through physical barriers. The target must make a Wisdom saving throw. On a failure, it takes 2d8 psychic damage and has disadvantage on its next attack roll or ability check before the start of your next turn. On a success, it takes half as much damage and suffers no additional effects."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each level above 1st."]],"ms":["arcane"]},{"k":"sp-mindwhip","n":"Mind Whip","l":2,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":570,"ct":"1 action","rg":"90 feet","cp":"V","d":"1 round","b":[["p","You psychically lash out at one creature you can see within range, forcing them to make an Intelligence saving throw. On a failed save, the target takes 3d6 psychic damage, and they can’t take a reaction until the end of their next turn. Moreover, on their next turn, they must choose whether they get movement, an action, or a bonus action (they get only one of the three). On a successful save, the target takes half as much damage and suffers none of the spell’s other effects."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, choose one of the following effects for each slot level above 2nd:"],["li","The spell’s psychic damage increases by 1d6."],["li","You can target one additional creature. The creatures must be within 30 feet of each other when you target them."]],"leg":1},{"k":"sp-minorgate","n":"Minor Gate","l":6,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":570,"ct":"1 action","rg":"500 feet","cp":"V, S","d":"Concentration, up to 10 minutes","b":[["p","You create linked teleportation portals that remain open for the duration."],["p","Choose two points on the ground that you can see: one point within 10 feet of you and one point within 500 feet of you. A circular portal, 10 feet in diameter, opens over each point. If the portal would open in the space occupied by a creature, the spell fails, and the casting is lost."],["p","The portals are two-dimensional glowing rings filled with mist, hovering inches from the ground and perpendicular to it at the points you choose. A ring is visible only from one side (your choice), which is the side that functions as a portal."],["p","Any creature or object entering the portal exits from the other portal as if the two were adjacent to each other; passing through a portal from the non portal side has no effect. The mist that fills each portal is opaque and blocks vision through it. On your turn, you can rotate the rings as a bonus action so that the active side faces in a different direction."]],"con":1,"leg":1},{"k":"sp-minutemeteors","n":"Minute Meteors","l":3,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":570,"ct":"1 action","rg":"Self","cp":"V, S, M (niter, sulfur, and pine tar formed into a bead)","d":"Concentration, up to 10 minutes","b":[["p","You create six tiny meteors in your space. They float in the air and orbit you for the spell’s duration. When you cast the spell - and as a bonus action on each of your turns thereafter - you can expend one or two of the meteors, sending them streaking toward a point or points you choose within 120 feet of you. Once a meteor reaches its destination or impacts against a solid surface, the meteor explodes. Any creature within 5 feet of the point where the meteor explodes must make a Dexterity saving throw, taking 2d6 fire damage on a failed save, or half as much damage on a successful one."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, choose one of the follow effects for each slot level above 3rd:"],["li","The number of meteors created increases by two."],["li","Each meteor deals an additional 1d6 fire damage."],["li","Creatures within an additional 5 feet of the meteor are caught in its effects."]],"con":1,"leg":1},{"k":"sp-miraculousevasion","n":"Miraculous Evasion","l":1,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":570,"ct":"1 action","rg":"30 feet","cp":"V, S, M a number of pearls equal to the level the spell is cast at, worth 50 gp each)","d":"10 minutes","b":[["p","You target a number of creatures within range that you can see equal to the level this spell is cast at. Those creatures gain 1 temporary hit point (this number cannot be changed by any effect) which remains until the spell ends. When any amount of damage would reduce their hit points while they have that temporary hit point, the creature rolls 1d100 plus your spellcasting ability. On a result of 51 or higher, the damage from that effect is reduced to 1 point, and their immunities, vulnerabilities, and resistances aren’t considered. Otherwise, the damage is reduced to half (rounded down)."]],"g":["Skulker’s Grimoire"]},{"k":"sp-mirrorarmy","n":"Mirror Army","l":4,"s":"Illusion","sa":"ILL","c":["Bard","Occultist","Sorcerer","Warlock","Wizard"],"bk":"ll","p":244,"ct":"1 action","rg":"Self (30 feet)","cp":"V, S","d":"1 minute","b":[["p","You create an illusory duplicate of every allied creature of your choice within 30 feet. Until the spell ends, the duplicates move alongside their real counterparts and mimic their actions, making it impossible to track which is real."],["p","Each time an affected creature is attacked, roll a d20 to determine whether the attack instead targets the duplicate. On a roll of 11 or higher, the attack targets the duplicate. A duplicate's AC equals 10 + the real creature’s Dexterity modifier. If a duplicate is hit by an attack, it is destroyed. Duplicates ignore all other damage and effects, and the spell ends once all duplicates have been destroyed."],["p","A creature is unaffected by this spell if it can’t see, if it relies on senses other than sight (such as blindsight), or if it has truesight or another means of automatically disbelieving illusions."]],"ms":["arcane"]},{"k":"sp-morbidpuppet","n":"Morbid Puppet","l":2,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":296,"ct":"1 action","rg":"60 feet","cp":"S, M (a drop of your blood worth at least 2 hit points, which the spell consumes)","d":"1 minute","b":[["p","You seize control of the blood within a freshly slain corpse or unconscious creature. The target must be Medium or smaller, and cannot have died more than 1 minute ago. For the duration, you can use your bonus action to make the target move up to 20 feet and make a single melee attack. It uses your spellcasting modifier for the attack roll. If the corpse is carrying a weapon or has a natural weapon, the attack deals the weapon’s damage (without any bonuses from the target's features). Otherwise, it makes a Slam attack which deal 1d6 (or 1 for a Tiny target) + your spellcasting modifier damage."],["p","If an unconscious target regains consciousness within the spell's duration, it can make a Charisma saving throw at the end of each of its turns to regain control of its body. You can end this spell at any time (no action required)."]],"h":[["p","At Higher Levels. When you cast this spell with a spell slot of 4th level or higher, the target can be Large."]],"bm":1},{"k":"sp-mountingparanoia","n":"Mounting Paranoia","l":3,"s":"Illusion","sa":"ILL","c":["Occultist","Warlock","Wizard"],"bk":"ll","p":244,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You shroud the mind of a creature you can see within range in shadow, twisting its view of the world. The target perceives everything beyond 15 feet as wreathed in shadow, indistinct in shape and sound. When the target attempts to target a creature wreathed in shadow with an attack or spell, it must pass a Wisdom saving throw, or it instead targets a random different target within range. When the target becomes able to see a creature that was previously wreathed in shadow, it must pass a Wisdom saving throw, or become frightened of that creature until the start of its next turn."],["p","At the end of each of the target's turns, it makes a Wisdom saving throw. On a failure, the shadows draw 5 feet closer, closing off the distance the target can see clearly. If the target’s entire vision becomes shrouded in shadow (after its third failure), it becomes paralyzed with fear until it succeeds on this save. If the target succeeds on this saving throw, the spell ends."]],"con":1,"ms":["arcane","shadow"]},{"k":"sp-multishot","n":"Multishot","l":1,"s":"Conjuration","sa":"CON","c":["Ranger"],"bk":"ll","p":244,"ct":"1 bonus action","rg":"Touch","cp":"V, S, M (a piece of ammunition or a weapon with the thrown property worth at least 1 cp)","d":"1 round","b":[["p","You touch a piece of ammunition or a weapon with the thrown property, conjuring a shadowy duplicate superimposed over it until the end of your next turn. The first time you attack with the empowered item before the end of your next turn, select a second target within the attack's range and make a separate ranged weapon attack. On a hit, the target is struck by the duplicate item and takes 2d8 force damage. This damage roll does not add any modifiers or bonus associated to weapon attacks."],["p","Once an attack has been made with the piece of ammunition or weapon, the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd Level or higher, you can select one additional target for each slot level above 1st."]],"ms":["primal"]},{"k":"sp-mutate","n":"Mutate","l":3,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Warlock","Wizard"],"bk":"ll","p":245,"ct":"1 action","rg":"Self","cp":"V, S, M (a butterfly's chrysalis)","d":"Concentration, up to 10 minutes","b":[["p","You significantly shift your form, magically modifying your body to give it up to three of the following properties:"],["li","You become malleable and amorphous. You gain advantage on saves and checks against becoming grappled or restrained, you do not suffer disadvantage from squeezing into smaller spaces, and you can squeeze through openings two sizes smaller than you."],["li","You grow one additional appendage. This appendage functions as an arm and a hand, though it can take the shape of an arm, tentacle, or similar appendage."],["li","You extend the length of your limbs, increasing the reach of your melee attacks, touch spells, and object interactions by 5 feet."],["li","Your flesh hardens. You can calculate your AC as 14 + your Dexterity modifier."],["li","You grow more resilient, adapting against one external threat. You gain advantage on saving throws with one ability of your choice."],["li","You adapt your body to an aquatic environment, sprouting gills and growing webbing between your fingers. You can breathe underwater and gain a swimming speed equal to your walking speed."],["li","Your body gains a regenerating carapace. You gain temporary hit points equal to your spellcasting ability modifier at the start of each of your turns."],["li","You can change your size by one category."],["li","You sprout wings, gaining a flying speed of 30 feet."],["li","You grow a natural weapon, which can have the statistics of any martial melee weapon without the thrown property, and takes on an appropriate form."],["p","You are proficient with this weapon and are considered to be wielding it. You can use your spellcasting modifier in place of your Strength modifier for attack and damage rolls with it. This natural weapon is magical and gains a +1 bonus to its attack and damage rolls."],["p","For the duration of the spell, you can use an action to change one or all of your selections, losing the benefits of your previously selected properties and gaining the benefits of the new ones."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th or higher, you can select 1 additional property from the list of options for each slot level above 3rd."]],"con":1,"ms":["arcane"],"also":[["cc",140]]},{"k":"sp-mythicaldouble","n":"Mythical Double","l":8,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":571,"ct":"1 bonus action","rg":"30 feet","cp":"V, S, M (a jeweled instrument worth at least 1000 gp, which must feature at least one bacchus peridot)","d":"Concentration, up to 1 round","b":[["p","Choose one willing creature within range. An illusory, heroic double of that creature is conjured into an unoccupied space you choose within 120 feet, where it remains until the start of your next turn. That creature shares its turn with you and, at your command, can take an action and bonus action, move up to its movement speed, and take a single reaction before it vanishes. The creature is capable of taking any action and using any feature as if it was the creature it is a copy of, including using their items and casting their spells. Its actions consume corrosponding uses/charges from magic items that the original creature holds, as well as using their spell slots."],["p","If in question, the creature cannot take legendary actions or lair actions."],["p","The double has the same armor class as the original, and if it takes any damage you must make a concentration check with a DC equal to the damage you take, or else the spell ends. The illusory clone is capable of concentrating on spells, but loses concentration when it vanishes (at which point you can choose to assume concentration for it, if you are able)."]],"con":1,"g":["Epic of Duality"]},{"k":"sp-nauseatingpoison","n":"Nauseating Poison","l":1,"s":"Necromancy","sa":"NEC","c":["Druid","Occultist","Warlock"],"bk":"ll","p":245,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"1 round","b":[["p","You shroud your hand, a weapon you are holding, or a natural weapon in dark and ichorous miasma. The next time you hit a creature with a melee attack (including a melee spell attack) before the start of your next turn, the attack deals an extra 1d12 poison damage and the target must succeed on a Constitution saving throw or be poisoned until the end of your next turn."],["p","The spell ends after dealing damage, or at the start of your next turn, whichever occurs first."]],"ms":["arcane"],"also":[["cc",141]]},{"k":"sp-necrosis","n":"Necrosis","l":0,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":571,"ct":"1 action","rg":"Touch","cp":"V, S","d":"Instantaneous","b":[["p","You touch one creature, rotting their body where you strike them. Make a melee spell attack against the target: on a hit, the target takes 1d10 necrotic damage. If the creature has their maximum amount of hit points and hasn’t taken any damage yet, they take an additional 1d10 damage."],["p","If this damage reduces a creature to 0 hit points, you gain temporary hit points equal to half the damage you dealt to them with that attack (rounded down)."],["p","Cantrip Upgrade. This spell’s base damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10)."]],"g":["Daemoturgy"]},{"k":"sp-nightmarecell","n":"Nightmare Cell","l":6,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":571,"ct":"1 action","rg":"60 feet","cp":"S","d":"Concentration, up to 1 minute","b":[["p","You attempt to bind a creature within an illusory cell that only they perceive. One creature you can see within range must make an Intelligence saving throw. The target succeeds automatically if it is immune to being charmed. On a successful save, the target takes 5d10 psychic damage, and the spell ends. On a failed save, the target takes 5d10 psychic damage, and you make the area immediately around the target’s space appear dangerous to them in some way. You might cause the target to perceive itself as being surrounded by fire, floating razors, or hideous maws filled with dripping teeth. Whatever form the illusion takes, the target can’t see or hear anything beyond it (they are treated as blinded to anything outside that area) and are restrained for the spell’s duration. If the target is moved out of the illusion, makes a melee attack through it, or reaches any part of their body through it, the target takes 10d10 psychic damage, and the spell ends."]],"con":1,"leg":1},{"k":"sp-nogistunesnegativeedge","n":"Nogistune’s Negative Edge","l":9,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":571,"ct":"1 bonus actin","rg":"Self","cp":"V, S","d":"1 minute","b":[["p","You conjure a floating blade of pure necromantic force that connects directly to the negative energy plane, appearing either as a glaive or uchigatana, which remains in your possession for the spell’s duration. When you cast the spell, you can make up to two melee spell attacks with it, each against a creature or object made of living material within 15 feet of you. On a hit, the target takes 4d12 necrotic damage. This attack scores a critical hit on an attack roll d20 result of 18 or higher, and on a critical hit it deals extra necrotic damage equal to 4d12, half of which the target’s maximum hit points are reduced by."],["p","As a bonus action on your turn, you can make another two melee spell attacks with this weapon, or can throw it as a single ranged spell attack against a target within 60 feet, after which it returns to your hand."]]},{"k":"sp-nogistunessoulboundvessel","n":"Nogistune’s Soulbound Vessel","l":8,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":571,"ct":"1 reaction, taken when a creature dies or is re-duced to 0 hit points within range.","rg":"120 feet","cp":"V, S, M (a container lined with black diamonds worth at least 5000 gp)","d":"Instantaneous","b":[["p","The target must make a Charisma saving throw. On a failure, their soul is captured and sealed within the spell’s material component, where it cannot escape unless you allow it to. The container cannot be destroyed by nonmagical means and is treated as having 30 AC, 150 hit points, immunity to nonmagical damage, and resistance to all damage types except force damage. At the dawn of every day, it regains all lost hit points and will restore its physical integrity. It automatically succeeds all saving throws it makes and takes half damage from spell attacks. This spell cannot be ended by effects that negate magic or spells."],["p","The soul cannot be resurrected, reincarnated, or otherwise be returned to another plane or body as long as it is sealed in this container. It cannot be opened by another creature except you unless you permit it."],["p","A creature that is in contact with the container can speak telepathically with the soul contained within."],["p","The container cannot be used as the material component for this spell again unless emptied."]]},{"k":"sp-notetakersgamble","n":"Notetaker’s Gamble","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":572,"ct":"1 bonus action","rg":"120 feet","cp":"V, S, M (a glass container with a topaz stopper worth at least 500 gp)","d":"Concentration, up to 24 hours","b":[["p","You can target one creature within range and describe one special action or spell you are aware the creature is capable of taking or casting (it must not be their Multiattack or a spell with a level higher than the slot level used to cast this spell). The target must make an Intelligence saving throw. On a failure, that creature takes 5d10 psychic damage and you copy a physical manifestation of that action, contained in this spell’s material component as a small wisp of magical energy."],["p","While you have that action contained, the creature cannot recharge or use it (unless it is a weapon attack, in which case they have disadvantage on attack rolls made using it). You immediately gain a full understanding of the action and its effects upon containing it. You can use that action once (as the action type it describes itself as), releasing the contained manifestation and targeting a creature within its range."],["p","When used against another creature the spell ends, and the action is carried out as if it were used by the creature it originated from."]],"con":1},{"k":"sp-nullifyeffect","n":"Nullify Effect","l":2,"s":"Psionic","sa":"PSI","c":["Psion"],"bk":"cc","p":141,"ct":"1 reaction, which you take when you are forced to make an Intelligence, Wisdom, or Charisma saving throw","rg":"Self","cp":"S","d":"1 round","b":[["p","You gain advantage on Intelligence, Wisdom, and Charisma saving throws (Including the triggering save) until the start of your next turn. You also gain resistance to Psychic and Force damage until the start of your next turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can roll an additional d20 as part of your advantage roll. If you cast this at the 5th level or higher, it grants immunity to Psychic and Force damage for the duration."]],"ci":1},{"k":"sp-okeisplaything","n":"Okei’s Plaything","l":9,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":572,"ct":"1 action","rg":"Touch","cp":"V, S, M (a featureless wooden figurine resembling the creature type of the target, which the spell consumes)","d":"Until dispelled","b":[["p","Swirling magic surrounds a target you choose within range, twisting and shifting their physical form. The target must make a Charisma saving throw, taking 8d8 psychic damage on a failed save as they begin to turn into a toy. They lose any movement speeds they have except swimming and walking speeds, and cannot make more than one attack each turn. At the end of each of their turns, they must make another Charisma saving throw against the effect, taking the damage again if they fail. After three failures, the target and all their possessions are turned into a toy. After three successes, the effect ends and they return to normal."],["p","A creature turned into a toy is cursed and remains that way until this spell is dispelled. If remove curse is cast on them it functions like dispel magic, requiring an ability check against this spell’s save DC. A creature turned into a toy is fully conscious, but loses all of its traits, features, and statistics except its Intelligence, Wisdom, and Charisma scores. They are treated as having no proficiencies, class levels, or creature type except being considered a Tiny"],["p","construct with 1 hit point and AC equal to this spell’s save DC. They cannot take actions or movement of any kind, and cannot take damage from spells or magical effects. They have blindsight out to 10 feet and can hear anything that occurs within 30 feet of them. They cannot speak, but if a creature communicates with them telepathically or reads their mind they can communicate through those methods. If the toy is destroyed the creature’s form is restored and the effect ends. The effects of this spell do not end due to effects like antimagic fields."],["p","If the toy possesses items you wish to retrieve, you may use an action to pull the item from the toy and return it to its original form. Doing so breaks any attunement the creature had with that item."],["p","If a creature is restored from being a toy, they resume the state, age, hit points, and condition they were in when transformed, and if they were restored by breaking the toy they take 10d10 psychic damage."]]},{"k":"sp-orbitalstones","n":"Orbital Stones","l":4,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":245,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You lift three inanimate Small or Medium sized rocks or similar objects from within 10 feet of you, causing them to defy gravity and slowly circle you. With all three stones orbiting, you have three-quarters cover. With at least one stone remaining, you have half cover."],["p","As a bonus action while at least one stone remains in orbit, you can magically fling it at a creature you can see within 60 feet. Make a ranged spell attack roll. On a hit, the target takes 3d10 bludgeoning damage and is knocked backward 5 feet."]],"con":1,"ms":["arcane","primal"],"also":[["cc",141]]},{"k":"sp-orbsofspelljamming","n":"Orbs of Spelljamming","l":2,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":572,"ct":"1 action","rg":"Self","cp":"V, S, M (a collection of gemstones worth at least 10 gp each, and equal in number to the number of orbs you create, which the spell consumes)","d":"10 minutes","b":[["p","You conjure four pristine orbs of clear ice, each invested with a small amount of magical energy that softly glows within it. For the duration, if you are targeted by a spell, you can expend a number of these orbs to absorb magical energy from the oncoming spell. This produces the following effects, applying them in this sequence:"],["li","If a number of orbs equal to the level the spell was cast at can be expended, the target spell fails and those orbs are destroyed."],["li","If you don’t have enough orbs to cancel the spell outright and if the target spell was cast at a level higher than its base level, the first orbs consumed reduce the spell slot used by one slot level each until the slot is equal to the spell’s base level."],["li","If the spell was not negated, is at base level, and would damage you, your remaining orbs are consumed and you roll 1d10 for each, then reduce the damage the spell deals to you by that amount. If this reduces the initial damage to 0, the spell has no further effect on you."],["li","If the spell was not negated, is at base level, and does not deal damage, each time you roll the save against it and fail then an orb is consumed. You then roll 1d20 and recalculate your save with the new result. This repeats until you succeed or run out of orbs."]],"h":[["p","At Higher Levels. When you cast this spell at 3rd level or higher, it creates one additional orb for each slot level above 2nd."]],"g":["Altissima-Cor’s Arcane Arts"]},{"k":"sp-ossenheimersarchive","n":"Ossenheimer’s Archive","l":4,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":573,"ct":"1 minute","rg":"10 feet","cp":"V, S, M (a book with enough blank pages to match the largest book within range)","d":"Until dispelled","b":[["p","You present the material component of this spell - a blank journal - and focus your magical energies on it. All books and text within the spell’s range (except spellbooks, spell scrolls and the contents of magical items or artifacts) are copied into the journal, all layered on top of one another. The page dimensions are adjusted to fit the dimensions of the blank book used, so the text might not appear on the same number of pages as its source. In doing so, the journal is transformed into a magical item."],["p","You and the creatures whose names you write onto the first page of the book can use an action to change the newly created archive’s contents, shifting all of its text to one of the sources it copied from. You may also use an action to cycle through an internally held list of them, organized by length from shortest to longest. This archive remains like this for 1 week, at which point you can maintain the effect for another week by casting the spell again. If you cast the spell on this book once a day for 30 days, the effect becomes permanent."],["p","If any of the sources of text contain more text than the blank book is capable of displaying, the information abruptly cuts off at the point where it would overflow."]],"rit":1,"g":["Ossenheimer’s Memoirs"]},{"k":"sp-otherworldlyguise","n":"Otherworldly Guise","l":6,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":573,"ct":"1 bonus action","rg":"Self","cp":"V, S, M (an object engraved with a symbol of the Outer Planes, worth at least 500 gp)","d":"Concentration, up to 1 minute","b":[["p","Uttering an incantation, you draw on the magic of the Lower Planes or Upper Planes (your choice) to transform yourself. You gain the following benefits until the spell ends:"],["li","You are immune to fire and poison damage (Lower Planes) or radiant and necrotic damage (Upper Planes)."],["li","You are immune to the poisoned condition (Lower Planes) or the charmed condition (Upper Planes)."],["li","Spectral wings appear on your back, giving you a flying speed of 40 feet."],["li","You have a +2 bonus to AC."],["li","All your weapon attacks are magical, and when you make a weapon attack, you can use your spellcasting ability modifier instead of Strength or Dexterity for the attack and damage rolls."],["li","You can attack twice instead of once when you take the Attack action on your turn. You ignore this benefit if you already have a feature (like Extra Attack) that lets you attack more than once when you take the Attack action on your turn."]],"con":1,"leg":1},{"k":"sp-pathtovictory","n":"Path to Victory","l":3,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":573,"ct":"1 action","rg":"Touch","cp":"V, S","d":"1 minute","b":[["p","One creature you touch has its natural combat abilities amplified. For the spell’s duration, when they take the Attack action they can make two attacks instead of one. If they already could make the number of attacks this spell would grant (such as by Extra Attack), their first weapon attack each turn has advantage instead."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, your target can make three attacks instead of one, and if they already could then they have advantage on all attacks they make."]],"g":["Legacy of Gold"]},{"k":"sp-perfectsilence","n":"Perfect Silence","l":4,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":573,"ct":"1 action","rg":"60 feet","cp":"S","d":"Concentration, up to 1 minute","b":[["p","When you cast this spell you attempt to inflict complete silence on a target you can see within range. If they are unwilling, they must make a Charisma saving throw, and are unaffected on a success. On a failed saving throw, choose one of the following effects, which remains until the spell ends:"],["p","Total Silence. The target is silenced entirely. They cannot hear other creatures, nor can anything except the incidental sounds of their movement, clothes, etc., be heard. While under this effect the target finds words hard to form, and cannot perform verbal components."],["p","You can choose to end this effect as a bonus action, causing the aura of silence to explode outward and releasing all the sound it has suffocated at once. The creature it bound must succeed on a Constitution saving throw, taking 4d8 thunder damage plus an additional 1d8 thunder damage for each turn they had been under the effect on a failure, or half as much damage on a successful save."],["p","Hushed Movements. The target is granted an enhanced state of silence that hushes their movements, except those they wish to hear it. For the spell’s duration they have advantage on Dexterity (Stealth) checks, do not produce vibrations or sound, and creatures attempting to locate them by sound automatically fail. The creature has advantage on attack rolls with Dexterity-based attacks."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can choose one of the following effects for each slot level above 4th:"],["li","The spell’s duration doubles."],["li","You can choose an additional target within range. You can select different effects for each. If you use a bonus action to end the total silence effect, you can choose which creatures it ends for at that time, and exclude others."]],"con":1,"g":["Epic of Duality"]},{"k":"sp-phantasmalshroud","n":"Phantasmal Shroud","l":3,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":574,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You create a mantle of energy that forms around you, pouring from your body and empowering your actions. Until the spell ends, any attack you make deals 1d8 extra damage when you hit a creature within 10 feet of you. This damage is radiant, necrotic, or cold (your choice when you cast the spell). Any creature that takes this damage can’t regain hit points until the start of your next turn."],["p","In addition, any creature of your choice that you can see that starts its turn within 10 feet of you has its speed reduced by 10 feet until the start of your next turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can choose one of the following effects for each slot level above 3rd:"],["li","The range for the spell’s extra damage and for selecting targets to decrease their speed is doubled."],["li","Creatures whose speed is reduced by this effect have it reduced by an additional 5 feet."],["li","(2 slot levels) The damage increases by 1d8."]],"con":1,"leg":1},{"k":"sp-phantomguardian","n":"Phantom Guardian","l":6,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":574,"ct":"1 action","rg":"Self","cp":"V, S, M (a diamond worth at least 1000 gp)","d":"1 hour","b":[["p","You manifest an ethereal guardian who watches over you, preventing you from being harmed. You gain 60 temporary hit points, which you lose when the spell ends (and conversely, the spell ends if you lose them). While this guardian watches over you, you can see invisible creatures and creatures hiding in the ethereal plane, you can take reactions against effects or attacks you cannot see, and you cannot be knocked prone or grappled."]],"h":[["p","At Higher Levels. If this spell is cast at 7th level or higher, you gain an additional 10 temporary hit points for every slot level above 6th."]],"g":["Ossenheimer’s Memoirs"]},{"k":"sp-phantomstep","n":"Phantom Step","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":574,"ct":"1 bonus action","rg":"Self","cp":"V","d":"Concentration, up to 1 minute","b":[["p","You teleport up to 60 feet to an unoccupied space you can see. On each of your turns before the spell ends, you can use a bonus action to teleport in this way again. Additionally, you gain a teleport speed equal to your movement speed as long as the spell is in effect."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you may choose one of the following effects for each slot level above 5th:"],["li","The duration of the spell increases to 10 minutes (1 slot level), 1 hour (2 slot levels) or 24 hours (3 slot levels)."],["li","The spell does not require concentration, but does end if you are incapacitated or finish a Short or Long Rest."]],"con":1,"leg":1,"g":["Epic of Duality"]},{"k":"sp-piercingcrystal","n":"Piercing Crystal","l":1,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":574,"ct":"1 action","rg":"60 feet","cp":"S, M (a drop of water or a piece of ice)","d":"Instantaneous","b":[["p","You create a shard of ice and fling it at one creature within range. Make a ranged spell attack against the target: on a hit, the target takes 1d10 piercing damage. Hit or miss, the shard then explodes. The target and each creature within 5 feet of the exploding shard must succeed on a Dexterity saving throw or take 2d6 cold damage."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd level or higher, choose one of the following options for each slot level above 1st:"],["li","The secondary cold damage increases by 1d6."],["li","The exploding shards range doubles."],["li","(2 slot levels) Creatures who fail their saving throw against this effect are frozen in place briefly, and are restrained until the start of your next turn. They may use their action to make a Strength check against your spell save DC to break free from the ice instead."]],"leg":1},{"k":"sp-pillaroffire","n":"Pillar of Fire","l":4,"s":"Evocation","sa":"EVO","c":["Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":246,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","You summon a towering column of flame in a 5-footradius, 30-foot-high cylinder centered on a point you can see within range. Each creature in the cylinder in the must make a Dexterity saving throw. A creature takes 10d6 fire damage on a failed save, or half as much on a successful save."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d6 for each slot level above 4th."]],"ms":["arcane"]},{"k":"sp-planardetection","n":"Planar Detection","l":3,"s":"Divination","sa":"DIV","c":[],"bk":"retia","p":574,"ct":"10 minutes","rg":"120 feet","cp":"V, S, M (a dream-catcher woven with silver thread worth at least 100 gp)","d":"8 hours","b":[["p","You weave a charm into the area, centered on your location when you complete casting the spell. As long as you are within the spell’s range, you become aware when there is a creature native to another plane present within it. You can designate specific creatures to be ignored by this effect when you cast it. If you are asleep when this occurs, you and anyone you choose when casting the spell are mentally alarmed in such a way that you are subtly awakened or stirred from rest."],["p","When detecting creatures this way, the subject knows what direction they are in, their numbers, and the size of them. They also can detect if the creatures are currently assuming a form that is not their true form."],["p","A creature can circumvent detection through this spell by succeeding on a Dexterity (Stealth) check against your spell save DC, but they make this check with disadvantage."]],"rit":1,"g":["Daemoturgy"]},{"k":"sp-platinumlances","n":"Platinum Lances","l":6,"s":"Evocation","sa":"EVO","c":["Cleric"],"bk":"ll","p":246,"ct":"1 action","rg":"150 feet","cp":"V, S","d":"Instantaneous","b":[["p","You conjure four giant lances of radiant energy that plummet down at four different points you can see. Each creature in a 10-foot-radius, 100-foot-high cylinder centered on each point must make a Dexterity saving throw."],["p","On a failed save, a creature takes 8d8 radiant damage and is knocked prone. On a successful save, it takes half as much damage and is not knocked prone. A creature in the area of more than one lance is affected only once."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 7th level or higher, the damage increases by 1d8 for each slot level above 6th."]],"ms":["divine"]},{"k":"sp-platinumshield","n":"Platinum Shield","l":6,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":574,"ct":"1 bonus action","rg":"60 feet","cp":"V, S, M (a platinum-plated dragon scale, worth at least 500 gp)","d":"Concentration, up to 1 minute","b":[["p","You create a field of silvery light that surrounds a creature of your choice within range (you can choose yourself). The field sheds dim light out to 5 feet. While surrounded by the field, the creature gains the following benefits:"],["p","Cover. The creature has half cover."],["p","Damage Resistance. The creature has resistance to acid, cold, fire, lightning, and poison damage."],["p","Evasion. If the creature is subjected to an effect that allows them to make a Dexterity saving throw to take only half damage, the creature instead takes no damage if they succeed on the saving throw, and only half damage if they fail."],["p","As a bonus action on subsequent turns, you can move the field to another creature within 60 feet of the field."]],"con":1,"leg":1},{"k":"sp-poisonblast","n":"Poison Blast","l":4,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Spellblade","Warlock","Wizard"],"bk":"ll","p":246,"ct":"1 action","rg":"Self (30-foot cone)","cp":"V, S","d":"1 round","b":[["p","You exhale a cloud of poison that magically expands to fill a 30 foot cone. Each creature in the area must make a Constitution saving throw. On a failure, it takes 4d12 poison damage and becomes poisoned until the start of its next turn. On a success, it takes half as much damage and is not poisoned."],["p","The area is lightly obscured until the start of your turn, and any creature that ends its turn within the area takes 2d4 poison damage."]],"ms":["arcane","primal"]},{"k":"sp-poisondart","n":"Poison Dart","l":2,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":246,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You conjure a dart of pure poison and hurl it at a creature you can see within range. Make a ranged spell attack. On a hit, the target takes 3d12 poison damage and must succeed a Constitution saving throw or become poisoned until the start of your next turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d12 for each slot level above 2nd."]],"ms":["arcane"],"also":[["cc",141]]},{"k":"sp-poisonpuff","n":"Poison Puff","l":4,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Warlock","Wizard"],"bk":"cc","p":141,"ct":"1 action","rg":"Self (30-foot cone)","cp":"V, S","d":"1 round","b":[["p","You exhale a cloud of poison that magically expands to fill a 30-foot cone. Creatures in that area must make a Constitution saving throw. On a failure, they take 4d12 poison damage and become poisoned until the start of their next turn. On a success, the target takes half as much damage and is not poisoned."],["p","The area is lightly obscured until the start of your turn, and any creature that ends their turn within the area takes 2d4 poison damage."]]},{"k":"sp-powertorrent","n":"Power Torrent","l":6,"s":"Evocation","sa":"EVO","c":["Sorcerer"],"bk":"ll","p":246,"ct":"1 action","rg":"Self (60-foot line)","cp":"V, S","d":"Instantaneous","b":[["p","You unleash a massive torrent of raw arcane energy, blasting a line 60 feet long and 15 feet wide with overwhelming power. This spell passes through all obstacles, walls, and all other non-magical barriers. All creatures in the area take 4d12 + 4 force damage."],["p","The torrent dispels all spells of 1st level or lower cast on creatures in its path, and any Constitution saving throws to maintain concentration triggered by this damage are made with disadvantage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 7th level or higher, the damage increases by 1d12 + 1 for each slot level above 6th."]],"ms":["arcane"]},{"k":"sp-powerwordbreak","n":"Power Word Break","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":575,"ct":"1 action","rg":"30 feet","cp":"V","d":"Instantaneous","b":[["p","You utter a word of power that destroys the weaponry and armor of others. Choose up to 6 targets within range, which must be nonmagical weapons, pieces of armor, doors, constructs, or other non-living objects. If the item is a creature or is being held or worn by a creature, they must make a Constitution saving throw, and if they are successful the item is unaffected. On a failure (or automatically if it didn’t need to make the save), the targets break and become useless, ripping apart violently. If the item had hit points, such as a creature, door, wall, etc., it takes 10d10 force damage on a failed save, or half as much damage on a successful one."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, it can target two additional targets and deals 1d10 additional force damage for every slot level after 5th. If this spell is cast at 7th level or higher, targets with 100 hit points or fewer automatically fail their"]]},{"k":"sp-powerwordclarity","n":"Power Word Clarity","l":7,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":575,"ct":"1 action","rg":"60 feet","cp":"V","d":"1 minute","b":[["p","You speak a word of power, targeting up to six creatures within range. Your targets gain truesight, allowing them to see secret doors, hidden switches, invisible creatures, see through illusions, and discern the true form of shapeshifters or creatures that have been transformed by magical means. The range of this truesight extends out to the range of any special vision type they have (such as darkvision, blindsight, devilsight, etc.,), with a minimum of 30 feet."]]},{"k":"sp-powerworddispel","n":"Power Word Dispel","l":7,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":575,"ct":"1 action","rg":"60 feet","cp":"V","d":"1 minute","b":[["p","You speak a cursed word of power and target one creature within 60 feet, who must make an Intelligence saving throw. On a failed save, all magical effects targeting them or that they are benefiting from end immediately. If they have 100 hit points or fewer, all such effects that originate from a spell of 7th level or lower end immediately even if they succeed. Additionally, if they fail, for 1 minute they cannot be targeted by any beneficial magical effects that do not have a duration of instantaneous, and cannot activate magical items that require attunement, nor can they attune to new items. The target may reattempt the Intelligence saving throw at the end of each of their turns, ending the effect on a success."],["p","Your DM may deliberate on what effects are considered beneficial, keeping in mind this spell’s nature is as a curse meant to discern what would be most detrimental."]],"h":[["p","At Higher Levels. If you cast this spell at 8th level or higher its duration changes. At 8th level: its effects last for 1 hour with subsequent saves to end the effect occurring every minute, and its duration becomes permanent. At 9th level: subsequent saves only take place at the end of every long rest."]]},{"k":"sp-powerwordforget","n":"Power Word Forget","l":5,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":575,"ct":"1 action","rg":"60 feet","cp":"V","d":"Instantaneous","b":[["p","Choose up to three creatures within range that you can see who are concentrating on spells or effects that require concentration. You speak a word of distortion and cloud their minds, forcing them to make an Intelligence saving throw. On a failure they lose concentration immediately, take 3d12 psychic damage, and if they were concentrating on a spell cannot cast that spell again. Every time that creature completes a long rest they can reattempt the Intelligence saving throw with advantage, ending the effect and regaining use of the spell on a success."],["p","If this spell is cast using a spell slot of 7th level or higher, creatures with 100 hit points or fewer automatically fail their initial Intelligence saving throw."]]},{"k":"sp-powerwordfury","n":"Power Word Fury","l":6,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":575,"ct":"1 action","rg":"60 feet","cp":"V","d":"10 minutes","b":[["p","One willing creature within range who can hear you gains 100 temporary hit points. While they have these temporary hit points they are enraged (as per the condition). Creatures enraged this way gain the following effects in addition to being enraged:"],["li","Their movement speed is doubled."],["li","They are immune to being charmed, frightened or enraged (except by this effect)."],["li","They gain a fury action on each of their turns, which can be used to make one weapon attack with a melee weapon, and that attack deals an additional d10 of damage. Their fury action must be used to attack the first creature that comes within melee range of them on their turn, including one within range when their turn starts."],["p","Each time the creature ends its turn without using its fury action, its remaining temporary hit points are reduced by half (rounded up), and if they’re reduced to fewer than 5 by this reduction they lose the remainder. The spell ends if the creature starts their turn without these temporary hit points."],["p","When the spell ends, the creature suffers one point of Combat Fatigue."],["p","A creature under this effect cannot benefit from the effects of the haste spell, or suffer the detrimental effects of the slow spell."]],"h":[["p","At Higher Levels. When you cast this spell at 7th level or higher, choose from one of the following effects for each slot level above 6th:"],["li","The fury action’s extra damage increases by an additional d10."],["li","The target gains an additional 15 temporary hit points."],["li","The creature’s fury action can be used to move up to the creature’s regular base movement speed, as long as it is not forcibly used to attack first."]],"g":["Chromatic Convocation"]},{"k":"sp-powerwordlethargy","n":"Power Word Lethargy","l":8,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":576,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","Choose up to six creatures within range who you speak a word of debilitating exhaustion to. Any of those creatures who has 100 hit points remaining or fewer must make a Constitution saving throw. If they fail, they immediately gain two levels of exhaustion. On a successful save they only take one. Creatures exhausted this way repeat the saving throw at the end of each of their turns, ending the effect on a success and remove exhaustion caused by this spell."],["p","If any of those creatures fail by 10 points or more, they immediately gain enough levels of exhaustion to cause them to have four total levels."]],"g":["Daemoturgy"]},{"k":"sp-powerwordmisfortune","n":"Power Word Misfortune","l":3,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":576,"ct":"1 reaction to a creature scoring a critical hit","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","When a creature scores a critical hit within range, you speak a word of power that causes them to lose traction and steals their good fortune. The critical hit is reduced to being a normal hit, and one other creature you choose within range receives their good luck, gaining a bonus on their next attack roll, saving throw, or ability check made within 1 minute equal to half the proficiency bonus (rounded down) of the creature who triggered this effect."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, one more creature you choose within range gains the bonus to their next attack roll, saving throw or ability check for every slot level above 3rd."]],"g":["Daemoturgy"]},{"k":"sp-powerwordrepel","n":"Power Word Repel","l":3,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":576,"ct":"1 action","rg":"30 feet","cp":"V","d":"Instantaneous","b":[["p","You speak a word of power, and one creature in range is hit by a burst of force, causing the target to make a Strength saving throw. On a failed save, they are pushed 30 feet in a direction you choose and are knocked prone. Creatures that are Huge or bigger have advantage on their Strength saving throw. If the target strikes a solid surface that stops them they must make a Constitution saving throw, taking 2d6 bludgeoning damage for every 10 feet they are stopped short, or half as much on a successful save. They do not take this damage unless they are pushed back at least 10 feet without stopping. If you choose to push a creature up off the ground, the distance they are pushed is halved."]],"h":[["p","At Higher Levels. When casting this spell at 4th level or higher, the distance the creature is forced back increases by 15 feet for every slot level above 3rd. If this spell is cast using a spell slot of 7th level or higher, creatures with 100 hit points or fewer automatically fail their initial Strength saving throw."]]},{"k":"sp-powerwordslow","n":"Power Word Slow","l":7,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":576,"ct":"1 action","rg":"60 feet","cp":"V","d":"Instantaneous","b":[["p","Choose up to six creatures you can see within range to whom you speak a word of debilitation to. Those creatures must then make a Charisma saving throw, having their movement speed reduced to 10 feet on a failure with no other effect capable of raising it above this amount. Creatures who are affected repeat the saving throw at the end of each of their turns, ending the effect on a success."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 8th level or higher, its effects change. If cast at 8th level it can target up to twelve targets, and if cast at 9th level it can target any number of creatures you choose within 60 feet instead. Additionally, any creature with 100 or fewer remaining hit points fails their first save against it automatically."]]},{"k":"sp-powerwordstillness","n":"Power Word Stillness","l":7,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":576,"ct":"1 action","rg":"60 feet","cp":"V","d":"Instantaneous","b":[["p","You speak a word of power that causes a creature to be made still, freezing not only physically, but also in space and time. If the target has 100 hit points or fewer, they are rendered still. Otherwise, this spell has no effect."],["p","While a creature is made still, their movement speed is reduced to 0 and they cannot take actions or reactions. They cease aging, cannot be moved, do not require air or food, and nothing on their body can be moved without moving the rest of the creature’s body - as if they were held relative to each other in space. The creature becomes resistant to all damage and cannot be made the target of any other spell or magical effect (the spell’s effects can be targeted, however, such as by dispel magic). Any magical effects the creature is currently affected by are suspended until the effects of this spell end."],["p","A target who has been made still can make a Charisma saving throw at the end of each of their turns, ending the effect on a success. If they fail these saving throws for 1 minute or more, they cease making them at the end of each turn and instead make them every 24 hours."]]},{"k":"sp-powerwordsuffer","n":"Power Word Suffer","l":7,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":577,"ct":"1 action","rg":"60 feet","cp":"V","d":"Instantaneous","b":[["p","You speak a word of power that causes waves of intense pain to assail one creature you can see within range. If the target has 100 hit points or fewer, they are subject to crippling pain. Otherwise, the spell has no effect. A target is also unaffected if they are immune to being charmed."],["p","While the target is affected by crippling pain, any speed it has can be no higher than 10 feet. The target also has disadvantage on attack rolls, ability checks, and saving throws, other than Constitution saving throws. Finally, if the target tries to cast a spell, it must first succeed on a Constitution saving throw, or the casting fails and the spell is wasted."],["p","A target suffering this pain can make a Constitution saving throw at the end of each of its turns. On a successful save, the pain ends."]],"h":[["p","At Higher Levels. When you cast this spell using a slot level of 8th level or higher, the spell’s range doubles for each slot level above 7th."]],"leg":1},{"k":"sp-powerwordtruth","n":"Power Word Truth","l":8,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":577,"ct":"1 action","rg":"Self (30-foot radius)","cp":"V","d":"Concentration, up to 1 minute","b":[["p","You speak a word of power that forces the world around you to drop all lies and obfuscations. All illusory effects and illusion spells in a 30-foot radius surrounding you are dispelled or suppressed for the spell’s duration. Furthermore, if a creature 57 7 within that range speaks and attempts to lie or mislead another creature, or to take a deliberately dishonest action, they must make a Charisma saving throw."],["p","On a failed save, they instead say the honest iteration of what they meant or take the honest version of that action. A creature who succeeds is free to tell the same lie or take the same dishonest action for the remainder of this spell without provoking this effect."]],"con":1},{"k":"sp-preservation","n":"Preservation","l":0,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":247,"ct":"1 action","rg":"5 feet","cp":"V, S","d":"24 hours","b":[["p","You touch a Small or smaller object or container, slowing the passage of time by half for that object and its contents. For example, food would take twice as long to spoil, or a lamp would burn twice as long on the same amount of oil."],["p","This effect lasts until you cast the spell again, the object is destroyed, or 24 hours pass. This does not affect the item's interactions with the world (for example, a preserved weapon would not swing any slower)."],["p","When you reach 5th level, the spell slows time to 1/3 its usual pace. When you reach 11th level, to 1/4 its usual pace. When you reach 11th level, to 1/5 its usual pace."]],"ms":["arcane"]},{"k":"sp-pressurecutter","n":"Pressure Cutter","l":5,"s":"Conjuration","sa":"CON","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":247,"ct":"1 action","rg":"Self (60-foot line)","cp":"V, S","d":"Instantaneous","b":[["p","You unleash a blast of highly pressurized water in a 60-foot-long 15-foot-wide line, slashing through everything in its path. Each creature in the line must make a Dexterity saving throw, taking 10d6 slashing damage on a failure. On a successful save, a creature takes half as much damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell lot of 6th level or higher, the damage increases by 1d6 for each level above 5th."]],"ms":["arcane"],"also":[["cc",141]]},{"k":"sp-primordialwarp","n":"Primordial Warp","l":3,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":577,"ct":"1 action","rg":"60 feet","cp":"S","d":"Instantaneous","b":[["p","You create an arcane sigil before you, and from it produce a burst of prismatic light that targets one creature or point within the spell’s range. Make a ranged spell attack against your initial target, dealing 6d10 force damage on a hit. Each creature within 5 feet of your target must succeed a Dexterity saving throw, taking the same force damage on a failure. If any targets hit by this spell have temporary hit points, an amount of this spell’s damage equal to their temporary hit points is doubled."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, you can choose one of the following effects for each slot level above 3rd:"],["li","The spell deals an additional 2d10 force damage."],["li","This spell’s range doubles."],["li","The range for considering secondary targets doubles."],["li","This spell is cast as a bonus action instead of as an action"]],"g":["Eidomancy"]},{"k":"sp-prismaticflash","n":"Prismatic Flash","l":1,"s":"Illusion","sa":"ILL","c":["Occultist","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":247,"ct":"1 action","rg":"Self (15-foot cone)","cp":"V, S, M (a prism)","d":"1 round","b":[["p","A vivid rainbow of prismatic lights springs out from your hand. Each creature in a 15-foot cone must make a Constitution saving throw. On a failure, a creature is blinded until the start of your next turn. On a success, a creature is not blinded but is disoriented by the brilliant flash and cannot make attacks of opportunity until the start of your next turn."],["p","Creatures that are already blinded or cannot see you aren’t Effected as they do not see the burst."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the size of the cone expands by 5 additional feet."]],"ms":["arcane"]},{"k":"sp-prismaticweapon","n":"Prismatic Weapon","l":3,"s":"Transmutation","sa":"TRA","c":["Inventor","Sorcerer","Wizard"],"bk":"cc","p":142,"ct":"1 action","rg":"Touch","cp":"V, S","d":"Concentration, up to 1 hour","b":[["p","A weapon you touch is infused with elemental power, becoming a magical weapon. Choose of the following damage types: acid, cold, fire, lightning, poison, or thunder. The weapon deals 1d6 damage of the chosen weapon type, and if it doesn’t already have a bonus to attack and damage, it gains a +1 bonus to attack and damage rolls."]],"h":[["p","At Higher Levels. When you cast this spell with a 4th- or 5th-level spell slot, the damage increases by 1d6 (to 2d6). When you use a spell slot of 6th level or higher, the damage increases by 2d6 (to 3d6)."]],"con":1},{"k":"sp-privatesanctum","n":"Private Sanctum","l":4,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":578,"ct":"10 minutes","rg":"120 feet","cp":"V, S, M (a thin sheet of lead, a piece of opaque glass, a wad of cotton or cloth, and powdered chrysolite)","d":"24 hours","b":[["p","You make an area within range magically secure. The area is a cube that can be as small as 5 feet to as large as 100 feet on each side. The spell lasts for the duration or until you use an action to dismiss it."],["p","When you cast the spell, you decide what sort of security the spell provides, choosing any or all of the following properties:"],["li","Sound can’t pass through the barrier at the edge of the warded area."],["li","The barrier of the warded area appears dark and foggy, preventing vision (including darkvision) through it."],["li","Sensors created by divination spells can’t appear inside the protected area or pass through the barrier at its perimeter."],["li","Creatures in the area can’t be targeted by divination spells."],["li","Nothing can teleport in or out of the warded area."],["li","Planar travel is blocked within the warded area."],["p","Casting this spell on the same spot every day for a year makes this effect permanent."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can increase the size of the cube by 100 feet for each slot level beyond 4th. Thus you could protect a cube that can be up to 200 feet on one side by using a spell slot of 5th level."]],"leg":1,"g":["Ossenheimer’s Memoirs"]},{"k":"sp-protectivegale","n":"Protective Gale","l":2,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":578,"ct":"1 action","rg":"Self","cp":"V","d":"Concentration, up to 10 minutes","b":[["p","A strong wind (20 miles per hour) blows around you in a 10-foot radius and moves with you, remaining centered on you. The wind lasts for the spell’s duration."],["p","The wind has the following effects:"],["li","It deafens you and other creatures in its area."],["li","It extinguishes unprotected flames in its area that are torch-sized or smaller."],["li","It hedges out vapor, gas, and fog that can be dispersed by strong wind."],["li","The area is difficult terrain for creatures other than you."],["li","The attack rolls of ranged weapon attacks have disadvantage if the attacks pass in or out of the wind."],["li","If you take falling damage you take half the damage you would normally take."],["li","If you shove a creature or knock them prone while they’re within the wind’s radius, they are pushed to a space outside the radius."]],"h":[["p","At Higher Levels. If you cast this spell using a spell slot of 3rd level or higher, it gains one of the following effects for each slot level above 2nd:"],["li","The wind’s radius increases by 5 feet."],["li","Your movement speed increases by 5 feet as the wind pushes you while you move."]],"con":1,"leg":1},{"k":"sp-pseudopodslam","n":"Pseudopod Slam","l":2,"s":"Conjuration","sa":"CON","c":["Druid","Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":247,"ct":"1 action","rg":"10 feet","cp":"V, S","d":"Instantaneous","b":[["p","You conjure a pseudopod of acidic ooze that slams a creature or object within range. Make a melee spell attack. On hit, the target takes 8d4 acid damage and is moved 5 feet in a direction of your choice."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 2d4 for each slot level above 2nd."]],"ms":["arcane","primal"]},{"k":"sp-psychiccleaver","n":"Psychic Cleaver","l":0,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":578,"ct":"1 bonus action","rg":"Self","cp":"S","d":"Instantaneous","b":[["p","When you take the Attack action or cast a spell that involves an attack roll, you may cast this spell to create a weapon in your other hand, made of psychic energy. You immediately make an attack using that weapon, making a melee spell attack against melee targets, or a ranged spell attack if you throw it. On a hit, the weapon deals 1d6 psychic damage to its target. The weapon then vanishes."],["p","The weapon is treated as having the light and thrown (20/60) properties."],["p","Cantrip Upgrade. The psychic damage this spell deals increases to 1d8 when you reach 5th level, to 1d10 at 11th level, then to 2d6 at 17th level."]]},{"k":"sp-psychicdrain","n":"Psychic Drain","l":2,"s":"Psionic","sa":"PSI","c":["Psion"],"bk":"cc","p":142,"ct":"1 action","rg":"60 feet","cp":"S","d":"Instantaneous","b":[["p","You draw on the psychic energy of another creature you can see to sustain yourself. The target must make a Charisma saving throw. On failure it takes 3d8 psychic damage and you gain temporary hit points equal to half the amount of psychic damage dealt and regain one expended psi point."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the spell deals an extra 1d8 psychic damage."]],"ci":1},{"k":"sp-psychiclance","n":"Psychic Lance","l":4,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":578,"ct":"1 action","rg":"120 feet","cp":"V","d":"Instantaneous","b":[["p","You unleash a shimmering lance of psychic power from your forehead at a creature that you can see within range. Alternatively, you can utter a creature’s name. If the named target is within range, it becomes the spell’s target even if you can’t see it. If the named target isn’t within range, the lance dissipates without effect."],["p","The target must make an Intelligence saving throw. On a failed save, the target takes 7d6 psychic damage and is incapacitated until the start of your next turn. On a successful save, the creature takes half as much damage and isn’t incapacitated."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d6 for each slot level above 4th."]],"leg":1},{"k":"sp-psychicsliver","n":"Psychic Sliver","l":0,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":578,"ct":"1 action","rg":"60 feet","cp":"V","d":"1 round","b":[["p","You drive a disorienting spike of psychic energy into the mind of one creature you can see within range. The target must succeed on an Intelligence saving throw or take 1d6 psychic damage and subtract 1d4 from the next saving throw it makes before the end of your next turn."],["p","Cantrip Upgrade. This spell’s damage increases by 1d6 when you reach certain levels: 5th level (2d6), 11th level (3d6), and 17th level (4d6)."],["p","57 8"]],"leg":1},{"k":"sp-punishinggleam","n":"Punishing Gleam","l":4,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":579,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Concentration, up to 10 minutes","b":[["p","Dim, greenish light spreads within a 30-foot radius sphere centered on a point you choose within range. The light spreads around corners, and it lasts until the spell ends."],["p","When a creature moves into the spell’s area for the first time on a turn or starts its turn there, that creature must succeed on a Constitution saving throw or take 4d10 radiant damage, suffer one level of exhaustion, and emit a dim, greenish light in a 5-foot radius. This light makes it impossible for the creature to benefit from being invisible. The light and any levels of exhaustion caused by this spell go away when the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can choose one of the following effects for each slot level above 4th:"],["li","The radius of the sphere increases by 5 feet."],["li","The spell’s damage increases by 1d10."],["li","(2 slot levels) Creatures that make a saving throw against the spell’s effects and succeed suffer a level of Combat Fatigue. These levels go away when the spell ends."]],"con":1,"leg":1,"g":["Blood of Cineris"]},{"k":"sp-pyroclasticlance","n":"Pyroclastic Lance","l":5,"s":"Conjuration","sa":"CON","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":248,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","You conjure a lance of blazing lava and hurl it at a creature you can see within range. Make a ranged spell attack. On a hit, the target takes 8d6 fire damage. Hit or miss, the lance then explodes in a 10-foot radius sphere of pyroclastic ash centered on the target. The ash lasts until the start of your next turn, and its area is heavily obscured. Any creature starting its turn within the ash cloud must succeed on a Constitution saving throw or take 4d6 fire damage and be blinded until the start of its next turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the initial damage increases by 1d6 for each slot level above 5th."]],"ms":["arcane"]},{"k":"sp-quicksand","n":"Quicksand","l":3,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Wizard"],"bk":"ll","p":248,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a pinch of sand)","d":"Concentration, up to 1 minute","b":[["p","You cause the ground in a 20-foot radius centered on a point you can see to turn to quicksand for the duration of the spell. A creature moving within or out of the area must spend 4 feet of movement for every foot it moves. A creature ending its turn in the area must succeed on a Strength saving throw or fall prone."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-quicksilversteps","n":"Quicksilver Steps","l":4,"s":"Transmutation","sa":"TRA","c":["Bard","Ranger","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":248,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You lighten your own steps with a spell of effortless quickness. For the duration of the spell, your movement does not provoke attacks of opportunity. When another creature you can see or hear ends its turn, you can move up to 10 feet (no action required). You can move in this way up to 4 times, regaining all uses at the start of your next turn. The first attack against you after each movement is made at disadvantage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the number of times you can move at the end of another creature’s turn increases by 1 for each slot level above 4th."]],"con":1,"ms":["arcane"]},{"k":"sp-quintillicbattery","n":"Quintillic Battery","l":5,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":579,"ct":"1 action","rg":"Self","cp":"V, S, M (a gemstone marble worth at least 25 gp, which the spell consumes. A marble is needed for each individual battery)","d":"1 minute","b":[["p","A crystal sphere with a 1-foot radius appears in an unoccupied space within 30 feet of you, radiating magical energy that freely pours from it. The spheres - batteries - each have 25 hit points and 15 AC, and a fly speed equal to your base movement speed. As a bonus action on your turn you can command one (or all) of them to move up to 30 feet. If a battery moves more than 30 feet from you it becomes inert and unusable until it comes back within range. If one is inert when your turn ends it is destroyed unless it is within 15 feet of another battery."],["p","The batteries are created with 0 charges. Each turn you can use your bonus action to give all of your batteries 1 charge, or to spend any number of charges from a battery to gain 1d8 temporary hit points per charge. You can also gain temporary hit points from a battery the same way as a reaction to taking damage, but doing so destroys the battery."],["p","57 9 You can spend 5 charges from a single battery as a bonus action to gain a surge of magical energy, destroying the battery in the process. When you do, you gain a bonus to attack rolls, ability checks, or saving throws (you choose when using this effect) which lasts until the spell ends. This bonus is equal to a d4, but if you already have a bonus from this spell to the type of roll gaining the benefit it increases to a d6, d8, d10, then to a d12."],["p","If you cast this spell while already under its effects, the previous iteration’s effects end."]],"h":[["p","At Higher Levels. When you cast this spell at 6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","One additional battery is summoned."],["li","All batteries gain 10 extra hit points."],["li","All batteries begin with 1 charge (each) for every time you take this effect."]],"g":["Chromatic Convocation","Eidomancy"]},{"k":"sp-radiantsmite","n":"Radiant Smite","l":3,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":579,"ct":"1 bonus action","rg":"Self","cp":"V","d":"Concentration, up to 1 minute","b":[["p","The next time you hit a creature with a melee weapon attack during this spell’s duration, your weapon flares with bright light, and the attack deals an extra 3d8 radiant damage to the target. Additionally, the target must succeed on a Constitution saving throw or be blinded until the spell ends."],["p","A creature blinded by this spell makes another Constitution saving throw at the end of each of its turns. On a successful save, it is no longer blinded."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, you may choose one of the following effects for each slot level above 3rd:"],["li","The effect persists on one additional attack after its effects would end."],["li","The radiant damage increases by 1d8."]],"con":1,"leg":1},{"k":"sp-rainofspiders","n":"Rain of Spiders","l":3,"s":"Conjuration","sa":"CON","c":["Druid","Occultist","Sorcerer","Warlock","Wizard"],"bk":"ll","p":248,"ct":"1 bonus action","rg":"60 feet","cp":"V, S, M (a spider leg)","d":"Concentration, up to 1 minute","b":[["p","A vertical column of spiders begins to rain down in 20 foot radius, 40 foot high cylinder, centered on a location you specify. A Swarm of Spiders (Basic Rules, pg. 391) descends onto each creature within the cylinder when the spell is cast."],["p","This swarm is considered to be climbing on the target creature and moves with it, even if they leave the affected area, and takes its turn immediately after that creature’s turn. A creature can make use its action to attempt to remove the spiders, making a Strength (Athletics) or Dexterity (Acrobatics) check against the spell save DC of the caster."],["p","The swarm uses the caster’s spell attack modifier when attacking (if it is higher than their attack modifier). A swarm will attack the creature it fell on if it can, or move to chase the creature if it has been knocked off of them. Any spiders that remain when the spell ends disappear."]],"con":1,"ms":["arcane","primal"],"also":[["cc",142]]},{"k":"sp-rainofswords","n":"Rain of Swords","l":7,"s":"Evocation","sa":"EVO","c":["Sorcerer","Wizard"],"bk":"ll","p":248,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","A rain of swords begins to fall in a 20-foot-radius, 40-foot high cylinder centered on a point within range. Any creatures starting its turn in the area or entering it for the first time on its turn must make a Dexterity saving throw. On a failure, it takes 6d10 slashing damage. On a success, it takes half as much damage."],["p","The swords are stuck upright in the ground and can be removed and used by anyone within 5 feet of the spell's area, functioning as nonmagical longswords. They vanish when the spell ends."]],"con":1,"ms":["arcane"]},{"k":"sp-redmanesfuriousyell","n":"Redmane’s Furious Yell","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":579,"ct":"1 action","rg":"30-foot radius sphere","cp":"V","d":"Instantaneous","b":[["p","A boisterous rising call to adventure fills a 30-foot radius sphere centered on you. All hostile creatures in range must make a Charisma saving throw while they are battered by this world-shaking spirited yell. Any creature that fails is knocked prone, takes 8d6 force damage, and if any of them were grappling another creature their grapple ends immediately."],["p","Within the same range, all non-hostile creatures gain 1d10 temporary hit points, unconscious creatures awaken, and any creatures with 0 hit points who are not dead regain 1d8 hit points."]],"h":[["p","At Higher Levels. When you cast this spell at 6th level or higher, the radius of the sphere increases by 10 feet for every slot level above 5th."]]},{"k":"sp-repair","n":"Repair","l":4,"s":"Transmutation","sa":"TRA","c":["Inventor"],"bk":"ll","p":249,"ct":"1 action","rg":"Touch","cp":"V, S","d":"Instantaneous","b":[["p","You touch a construct or inanimate object, causing it to regain 10d6 hit points. Any parts or material that has broken off is reattached, restoring it to the condition it was in before losing those hit points."],["p","If the target's damage is the result of aging, you can instead restore it to its condition as of 10d6 years ago. Its condition can only improve — if it was in worse condition previously, the spell has no effect."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the hit points restored or years of decay undone increase by 2d6 for each slot above 4th."]],"ms":["arcane"],"also":[["cc",142]]},{"k":"sp-resilientsphere","n":"Resilient Sphere","l":4,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":580,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a hemispherical piece of clear crystal and a matching hemispherical piece of gum arabic)","d":"Concentration, up to 1 minute","b":[["p","A sphere of shimmering force encloses a creature or object of Large size or smaller within range. An unwilling creature must make a Dexterity saving throw. On a failed save, the creature is enclosed for the duration."],["p","Nothing - not physical objects, energy, or other spell effects can pass through the barrier, in or out, though a creature in the sphere can breathe there. The sphere is immune to all damage, and a creature or object inside can’t be damaged by attacks or effects originating from outside, nor can a creature inside the sphere damage anything outside it."],["p","The sphere is weightless and just large enough to contain the creature or object inside. An enclosed creature can use its action to push against the sphere’s walls and thus roll the sphere at up to half the creature’s speed. Similarly, the globe can be picked"],["p","A disintegrate spell targeting the globe destroys it without harming anything inside it."]],"con":1,"leg":1},{"k":"sp-resonantweapon","n":"Resonant Weapon","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":580,"ct":"1 bonus action","rg":"Touch","cp":"V, S","d":"Concentration, up to 1 hour","b":[["p","You touch a weapon and infuse it with a living melody, which echoes out each time it’s swung. The weapon becomes magical for the duration, deals an additional 2d8 thunder damage on a hit, and any time a creature within 30 feet of it makes a concentration check (except this spell’s caster), they do so with disadvantage."],["p","When the spell ends, its wielder may use their reaction to make one final attack with it, swinging it toward a creature within 30 feet of them. A wave of sound assails that creature, forcing them to make a Constitution saving throw. On a failure they take 6d8 thunder damage and are deafened until the end of their next turn. On a success, they take no damage."]],"con":1,"g":["Epic of Duality"]},{"k":"sp-returningweapon","n":"Returning Weapon","l":1,"s":"Transmutation","sa":"TRA","c":["Inventor"],"bk":"ll","p":249,"ct":"1 action","rg":"Touch","cp":"V, S","d":"24 hours","b":[["p","You touch a weapon and grant it the thrown (20/60) property. If it already has the thrown property, its range increases by 20/60. For the duration, it reappears in the thrower's hand after it's thrown as part of an attack."]],"ms":["arcane"],"also":[["cc",142]]},{"k":"sp-reverberatingdash","n":"Reverberating Dash","l":2,"s":"Transmutation","sa":"TRA","c":["Bard"],"bk":"ll","p":249,"ct":"1 action","rg":"Self (5 feet)","cp":"V, S, M (a melee weapon worth at least 1 sp)","d":"Instantaneous","b":[["p","You imbue a resonating note of magic into a melee weapon you are holding. When you do so, you can immediately make one attack against a creature within 5 feet with the weapon used in the spell's casting. If the attack hits, the note reverberates and deals an additional 1d8 thunder damage, and you can immediately move up to 15 feet in a straight line in any direction without provoking opportunity attacks."],["p","If this movement leaves you within 5 feet of a creature you have not hit as part of this spell, you can immediately make another attack against this creature with the weapon used in the spell's casting. If the attack hits, the note reverberates even louder and deals an additional 2d8 thunder damage, and you can move repeat the movement and attack again. Each time you dash, the note grows louder, increasing its thunder damage by 1d8. You can move a maximum of 2 times after the initial attack (making up to 3 attacks in total). You can move again and potentially attack until you miss or there is no longer an eligible target you can reach. Each time you dash this way, the volume and tempo of the note increases, increasing the thunder damage dealt by 1d8."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the initial thunder damage increases by 1d8, and you can move-andattack 1 additional time for each slot level above 2nd, up to a maximum of 5 dashes (6 attacks) with a 5th-level spell slot."]],"ms":["arcane"]},{"k":"sp-reversegravity","n":"Reverse Gravity","l":7,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":580,"ct":"1 action","rg":"100 feet","cp":"V, S, M (a lodestone and iron filings)","d":"Concentration, up to 1 minute","b":[["p","This spell reverses gravity in a 50-foot radius, 100-foot high cylinder centered on a point within range. All creatures and objects that aren’t somehow anchored to the ground in the area fall upward and reach the top of the area when you cast this spell. A creature can make a Dexterity saving throw to grab onto a fixed object it can reach, thus avoiding the fall."],["p","If some solid object (such as a ceiling) is encountered in this fall, falling objects and creatures strike it just as they would during a normal downward fall. If an object or creature reaches the top of the area without striking anything, it remains there, oscillating slightly, for the duration."],["p","At the end of the duration, affected objects and creatures fall back down."],["p","Creatures with a 0-G acceleration speed can choose to be unaffected by this spell, and instead treat the area within its effects as a zero-gravity environment. However, if they use any ranged attacks or any item leaves their possession then it is affected by the spell as normal."],["p","At Hjigher Levels. When you cast this spell at 8th level or higher, the dimensions double to a 100-foot radius at 8th-level, and a 200-foot radius at 9th-level. The spell’s range increases at these levels to 200 feet and 400 feet respectively."]],"con":1,"leg":1},{"k":"sp-ribcage","n":"Ribcage","l":4,"s":"Necromancy","sa":"NEC","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"ll","p":249,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a rib bone)","d":"Concentration, up to 1 minute","b":[["p","You cause a series of giant bones to burst from the earth around a point you can see on the ground within range. The bones form a dome in a 10-foot radius around the target point. Small or larger creatures cannot pass through the cage, and attacks that deal bludgeoning or slashing damage cannot be made through it. The cage functions as half cover against other attacks or spells that pass through it."],["p","The cage has 40 hit points, AC 13, and is vulnerable to bludgeoning damage. If it is reduced to 0 hit points, it crumbles to dust and the spell ends."]],"h":[["p","At Higher Levels. When cast with a 5th level or higher spell slot, the cage has an additional 10 hit points for each level above 4th."]],"con":1,"ms":["arcane"]},{"k":"sp-rockslam","n":"Rock Slam","l":0,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":250,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","You fling a rock at a creature you can see within range. Make a ranged spell attack. On a hit, the target takes 1d10 bludgeoning damage. On a critical hit, the target is knocked prone or 10 feet backwards (your choice)."],["p","The spell’s damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10)."]],"ms":["primal"]},{"k":"sp-rottingcurse","n":"Rotting Curse","l":1,"s":"Necromancy","sa":"NEC","c":["Occultist"],"bk":"ll","p":250,"ct":"1 action","rg":"60 feet","cp":"V, S, M (something from the target creature—such as blood, hair, or scales—which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You inflict a curse of decay on a creature within range, causing it to begin to rot. For the duration, every time the target takes damage, it takes an additional 1d4 necrotic damage, and the effect of any healing it receives is halved."],["p","The target also has disadvantage on any Charisma checks for social interaction for the duration."]],"con":1,"ms":["arcane"],"also":[["cc",142]]},{"k":"sp-samarustraumaticaggravation","n":"Samaru’s Traumatic Aggravation","l":4,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":580,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","One creature you target within range experiences horrific variants of memories from their life that become twisted into scenes of carnage and traumatic imagery. The target must make an Intelligence saving throw. On a failure, they take 6d10 psychic damage and are stunned for 1 minute. On a success they take half as much damage and aren’t stunned. If the creature is dealt damage, forced to make any type of saving throw or ability check, or another creature uses an action to shake them, they snap out of being stunned."]],"h":[["p","At Higher Levels. When you cast this spell at 5th level or higher, you can choose one extra target for each slot level above 4th."]],"con":1,"g":["Daemoturgy"]},{"k":"sp-sanctifiedcharge","n":"Sanctified Charge","l":2,"s":"Transmutation","sa":"TRA","c":["Cleric","Paladin"],"bk":"ll","p":250,"ct":"1 bonus action","rg":"Self (20-foot line)","cp":"V, S","d":"Instantaneous","b":[["p","Fueled by a burst of divine strength, you move up to 20 feet in a straight line in a swift burst of movement. If you collide with a creature, the charge ends early, and the creature must make a Strength saving throw. On a failure, it takes 2d6 radiant damage and is knocked prone. On a success, it takes half as much damage and is not knocked prone."]]},{"k":"sp-sanguinedoom","n":"Sanguine Doom","l":6,"s":"Necromancy","sa":"NEC","c":["Cleric","Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":296,"ct":"1 action","rg":"120 feet","cp":"S, M (a splash of your blood worth at least 6 hit points, which the spell consumes)","d":"Instantaneous","b":[["p","You summon a shower of blood at a point you can see within range. Darkness washes over a 30-foot radius around the point, extinguishing all lights (including light from lower-level spells), and a rain of blood falls upon the area. Creatures and objects that are not being worn or carried within the area take 4d6 acid damage, and creatures must succeed on a Wisdom saving throw or suffer a doom curse. The next time a cursed creature is hit with an attack, it attack becomes a critical hit, after which the curse ends."]],"bm":1},{"k":"sp-sanguinespears","n":"Sanguine Spears","l":3,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":296,"ct":"1 action","rg":"60 feet","cp":"S, M (a splash of your blood worth at least 6 hit points, which the spell consumes)","d":"10 minutes","b":[["p","You crystallize some of your blood into three floating spears, which orbit you for the duration. You can use your action or your bonus action to launch one of the spears at a creature within range, making a ranged spell attack. On a hit, the target takes 2d6 piercing damage and 2d6 necrotic damage, and you regain 5 hit points. Once you've launched all the spears, the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can expend 2 additional hit points to create 1 more spear for each slot level above 3rd."]],"bm":1},{"k":"sp-seadwellersaspect","n":"Sea-Dweller’s Aspect","l":2,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":580,"ct":"1 action","rg":"Self","cp":"S, M (a string of seashells)","d":"1 hour","b":[["p","Your body is altered to be better suited to underwater activity. For the spell’s duration you can breathe both air and water, can walk on the surface of water (but not other liquids), gain a swim speed of 60 feet, and suffer no penalties related to deepsea temperatures, choppy or torrid water currents, or regular underwater combat penalties."],["p","While submerged you gain darkvision out to 240 feet, and when you speak your voice is carried by the water to creatures within 60 feet of you. You can perform verbal components underwater without issue."]],"g":["Altissima-Cor’s Arcane Arts"]},{"k":"sp-seekingorb","n":"Seeking Orb","l":2,"s":"Evocation","sa":"EVO","c":["Sorcerer","Wizard"],"bk":"ll","p":250,"ct":"1 action","rg":"5 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You create a tiny orb of arcane energy hovering within range, which slowly moves towards a target creature within 120 feet. At the end of each of your turns for the duration, the orb moves 30 feet directly toward its target. If it reaches the target, it detonates, dealing 6d4 force damage and ending the spell. If it doesn't reach the target, it intensifies, increasing its damage by 2d4 (up to a maximum of 10d4 force damage). If the spell ends before the orb can reach its target, it fades harmlessly away."]],"con":1,"ms":["arcane"],"also":[["cc",142]]},{"k":"sp-seekingprojectile","n":"Seeking Projectile","l":1,"s":"Transmutation","sa":"TRA","c":["Inventor","Ranger"],"bk":"ll","p":250,"ct":"1 action","rg":"Touch","cp":"V, S, M (a piece of ammunition or a weapon with the thrown property worth at least 1 cp)","d":"Concentration, up to 10 minutes","b":[["p","You touch a piece of ammunition or a weapon with the thrown property and imbue it with a seeking spell. The next time the item is used for a ranged attack, the attacker can add your spellcasting modifier to the d20 result. If that makes the value on the die a 20 or higher, the attack scores a critical hit. The spell ends after one attack."]],"con":1,"ms":["arcane"],"also":[["cc",143]]},{"k":"sp-seismicwave","n":"Seismic Wave","l":3,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":250,"ct":"1 action","rg":"Self (30-foot cone)","cp":"V, S","d":"Instantaneous","b":[["p","You slam the ground in front of you and cause the earth to explode violently in a 30-foot cone. Each creature on the ground in the area must make a Strength saving throw. On a failure, it takes 4d10 bludgeoning damage and falls prone. On a success, it takes half as much damage and does not fall prone."],["p","Large or larger objects and structures in the area automatically fail the save and take double damage. The ground becomes difficult terrain until cleared. Each 5-foot-square requires at least 1 minute to clear by hand."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d10 for each slot level above 2nd."]],"ms":["arcane","primal"]},{"k":"sp-seizingbolt","n":"Seizing Bolt","l":1,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":581,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a twig from a tree that has been struck by lightning)","d":"Concentration, up to 1 minute","b":[["p","A beam of crackling, blue energy lances out toward a creature within range, forming a sustained arc of lightning between you and the target. Make a ranged spell attack against that creature. On a hit, the target takes 1d12 lightning damage, and on each of your turns for the duration, you can use your action to deal an additional 1d12 lightning damage to the target automatically. The spell ends if you use your action to do anything else. The spell also ends if the target is ever outside the spell’s range or if it has total cover from you."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd level or higher, you may choose one of the following effects for each slot level above 1st:"],["li","The spell’s initial damage increases by 1d12."],["li","(2 slot levels) The spell’s initial and ongoing damage increase by 1d12."],["li","(2 slot levels) You may target one additional creature. Using your action to continue the effect deals damage to all targets."],["li","(2 slot levels) You may use your bonus action in place of your action to deal the spell’s secondary damage, but can only deal the extra damage once per turn."]],"con":1,"leg":1},{"k":"sp-selfcurse","n":"Self-Curse","l":1,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":581,"ct":"1 reaction to failing a saving throw","rg":"Self","cp":"V, S, M (a small blade capable of penetrating your skin","d":"Instantaneous","b":[["p","You may exchange your own blood and wellbeing for a brief increase to your abilities. You succeed on a saving throw that you would otherwise fail, but in exchange take 1d6 points of irreducible damage multiplied by the difference between your failed save result and the DC it failed to beat."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd level or higher, you can reduce the damage you take from this spell by 5 points for each slot level above 1st."]],"g":["Daemoturgy"]},{"k":"sp-sending","n":"Sending","l":3,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":581,"ct":"1 action","rg":"Unlimied","cp":"V, S, M (a short piece of fine copper wire)","d":"1 round","b":[["p","You send a short message of twenty-five words or less to a creature with which you are familiar. The creature hears the message in their mind, recognizes you as the sender if they know you, and can answer in a like manner immediately. The spell enables creatures with Intelligence scores of at least 1 to understand the meaning of your message."],["p","You can send the message across any distance and even to other planes of existence, but if the target is on a different plane than you, there is a 5 percent chance that the message doesn’t arrive."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, the number of words you and your target can each exchange increases for every slot level above 3rd: 50 at 4th, 100 at 5th, 250 at 6th, 500 at 7th, 1000 at 8th, and 2000 at 9th."]],"leg":1},{"k":"sp-senseblood","n":"Sense Blood","l":1,"s":"Divination","sa":"DIV","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":296,"ct":"1 action","rg":"Self","cp":"S, M (a drop of your blood worth at least 1 hit point, which the spell consumes)","d":"Concentration, up to 1 hour","b":[["p","You gain the ability to sense the blood of other creatures. For the duration, you have advantage on Wisdom (Perception) and Wisdom (Insight) checks against creatures with blood."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd or 4th level, the duration becomes 8 hours. When you use a spell slot of 5th level or higher, the duration becomes 24 hours."]],"con":1,"bm":1},{"k":"sp-shadedweapon","n":"Shaded Weapon","l":2,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":581,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You weave together threads of shadow to create a weapon of solidified gloom in your hand, which lasts until the spell ends. It counts as a simple melee weapon with which you are proficient. It deals 2d8 psychic damage on a hit and has the finesse, light, and thrown properties (range 20/60). In addition, when you use the weapon to attack a target that is in dim light or darkness, you make the attack roll with advantage."],["p","If you drop the weapon or throw it, it dissipates at the end of the turn. Thereafter, while the spell persists, you can use a bonus action to cause the weapon to reappear in your hand."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, you may choose one of the following effects for every 2 slot levels above 2nd:"],["li","The weapon deals an additional 1d8 psychic damage."],["li","You create a second shaded weapon in your other hand, which is identical to the first."],["li","The normal throwing range of the weapon increases by 30 feet, and its long range by 90 feet."]],"con":1,"leg":1},{"k":"sp-shadowbind","n":"Shadow Bind","l":1,"s":"Illusion","sa":"ILL","c":["Spellblade","Warlock","Wizard"],"bk":"ll","p":251,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You point at a Medium or smaller creature you can see within range and cause its shadow to leap up, forming solid tendrils to bind it. The target must succeed on a Strength saving throw or become restrained for the spell's duration. A restrained target can repeat its saving throw at the end of each of its turns, ending the effect on a success."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can either target one additional creature or increase the size category of creature the spell can affect one time for each slot level above 1st."]],"con":1,"ms":["arcane","shadow"]},{"k":"sp-shadowflame","n":"Shadow Flame","l":4,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":581,"ct":"1 action","rg":"Self","cp":"V, S, M (an undead eyeball encased in a gem worth at least 150 gp)","d":"Concentration, up to 1 minute","b":[["p","Flame-like shadows wreathe your body until the spell ends, causing you to become heavily obscured to others. The shadows turn dim light within 10 feet of you into darkness, and bright light in the same area to dim light."],["p","Until the spell ends, you have resistance to radiant damage. In addition, whenever a creature within 10 feet of you hits you with an attack, the shadows lash out at that creature, dealing it 2d8 necrotic damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can choose one of the following effects for each slot level above 4th:"],["li","The necrotic damage increases by 1d8."],["li","The range in which the shadows affect the light and will retaliate to attacks increases by 10 feet."]],"con":1,"leg":1},{"k":"sp-shadowflare","n":"Shadow Flare","l":7,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":582,"ct":"1 action","rg":"120 feet","cp":"V, S, M (a crystal sphere to concentrate the spell’s effects, worth at least 100 gp)","d":"Instantaneous","b":[["p","You choose a point you can see within range, where several small gates to various layers of hell open and their energies mix in a small orb of chromatic chaos. The orb of chaos appears and expands out like an explosion, filling a 40-foot radius sphere centered there. This explosion spreads around corners and through cracks in surfaces larger than 1 inch wide. All creatures caught in this negative energy blast must make a Charisma saving throw, taking 8d10 + 30 necrotic damage on a failed save, or half as much damage on a successful one."],["p","Any creature that fails the saving throw is dazed and besieged by necrotic energy. For 1 minute they have disadvantage on attack rolls and ability checks. At the end of each of their turns they make the saving throw again, ending the effect on a success. It also ends if they receive more than 20 points of healing in one turn or if a spell such as remove curse or lesser restoration is cast on them. A creature that ends the effect by succeeding the saving throw cannot be affected by its debilitating effects again for 24 hours."]],"g":["Chromatic Convocation"]},{"k":"sp-shadowgate","n":"Shadow Gate","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":582,"ct":"1 action","rg":"30 feet","cp":"V, S, M (any object from the Realm of Shadows, or one that had been there for an unbroken year at some point)","d":"Instantaneous","b":[["p","You and up to eight willing creatures within range create a path to the Realm of Shadows, vanishing in an impressive visual display of fog and wind. If there are creatures native to the Realm of Shadows within the spell’s range who you wish to bring as well, (so long as they are willing) they do not count against the eight you may choose. Creatures who are not native to the Realm of Shadows who teleport this way cannot rest while there due to the toll this spell takes on one’s mind."],["p","You and the creatures you select reappear in the Realm of Shadows at a location you are familiar with or know of. The spell will take you within the general vicinity of the area you wish to arrive at or to an area like it, unless you have been there before, in which case you are teleported directly to the location you wish to arrive at."],["p","If you are within the Realm of Shadows, you may cast this spell to teleport to the last plane you used it. You appear within 1 mile of the location you last cast the spell, choosing up to eight willing creatures to come with you again."],["p","Alternatively, when you cast this spell you may instead target any number of creatures you wish within its range. If any of those creatures are natives to the Realm of Shadows they must make a Charisma saving throw. On a failure, they are all banished to the same random location in the Realm of Shadows and cannot return to the plane you are on by any means for 24 hours. If a creature casts dispel magic on you they may target this effect, ending it if they succeed. Likewise, if you enter an anti-magic field you are not considered to be on the plane for the purposes of this restriction."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you may double the number of creatures you choose to teleport with you for each slot level above 5th (16 at 6th, 32 at 7th, 64 at 8th, 128 at 9th). If you use it to banish natives to the Realm of Shadows, the spell’s range doubles for each slot level above 5th, and the time before they can return increases to 1 week at 6th level, 1 month at 7th level, 1 year at 8th level, and it becomes a permanent effect as long as you are alive at 9th level."]],"rit":1,"g":["Daemoturgy"]},{"k":"sp-shadowlash","n":"Shadow Lash","l":0,"s":"Illusion","sa":"ILL","c":["Warlock","Wizard"],"bk":"ll","p":251,"ct":"1 action","rg":"10 feet","cp":"V, S","d":"Instantaneous","b":[["p","You form a whip of shadows that lashes out toward a creature within range. Make a melee spell attack, on hit, the target takes 2d4 psychic damage. In addition, if the target is in dim light or darkness, you make the attack roll with advantage."],["p","The spell’s damage increases by 2d4 when you reach 5th level (4d4), 11th level (6d4), and 17th level (8d4)."]],"ms":["arcane","shadow"]},{"k":"sp-shamwoodstakeout","n":"Shamwood Stakeout","l":3,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":582,"ct":"1 minute","rg":"10 feet","cp":"V, S","d":"8 hours","b":[["p","A spectral watchman appears in a space within the spell’s range, invisibly watching over the area. You may describe criteria to it for anything it should watch out for while it exists. While it remains, as long as you are within 1 mile of the invisible watchman, it will alert you to anything suspicious it sees in the most basic terms possible, such as “enemy”, “lurker”, “monster”, etc,. It rolls Wisdom (Perception) checks using your spellcasting ability modifier plus your proficiency bonus as its modifier for the skill check and has a passive Perception equal to your spell save DC. It has darkvision out to 120 feet, and is blind beyond that range."],["p","If you are sleeping when you are alerted by it, you are instantly awoken. If you would be surprised by enemies normally but are awoken by this spell, you may act normally instead."],["p","If any creature can see invisible creatures, it can attack the invisible watchman as if it had an AC equal to your spell save DC, and all saving throws it makes are made using your spellcasting ability plus your proficiency bonus. It never takes damage from effects that it succeeds saves against. If it takes any damage the spell ends prematurely."]]},{"k":"sp-shatteringshield","n":"Shattering Shield","l":2,"s":"Conjuration","sa":"CON","c":["Druid","Occultist","Sorcerer","Spellblade","Warlock"],"bk":"ll","p":251,"ct":"1 reaction, which you can take when a creature within range is hit by a melee attack","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You cause a shield of ice to erupt and block the triggering attack. The attack's damage is reduced by 1d8 + your spellcasting modifier. If the attack damage is not completely blocked, the shield shatters, dealing the amount of blocked damage as cold damage to the attacker. If the shield is not broken, it melts away after blocking the damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the amount of damage blocked increases by 1d8 for each slot level above 2nd."]],"ms":["arcane"]},{"k":"sp-shieldmaidens","n":"Shield Maidens","l":4,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":582,"ct":"1 action","rg":"Self","cp":"V, S, M (a small figure of yourself with two crystal shields tied to it worth 100 gp each, which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You conjure two phantom shield maidens who stay at your side for the spell’s duration, granting disadvantage on attacks made against you from within 30 feet. Furthermore, while under this spell’s effect you can use your reaction to replicate the effects of the shield spell, but those effects end at the end of the turn you invoke it."]],"h":[["p","At Higher Levels. If you cast this spell at 5th level or higher, the range of the spell doubles for each slot level above 4th (60 feet at 5th, 120 feet at 6th, 240 feet at 7th, etc.,)."]],"con":1,"g":["Ossenheimer’s Memoirs"]},{"k":"sp-shieldofsummer","n":"Shield of Summer","l":1,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":583,"ct":"1 reaction, which you take when you are hit by an attack","rg":"Self","cp":"V, S","d":"1 round","b":[["p","A multi-layered near-invisible shield of force appears and protects you. Until the start of your next turn you have a +5 bonus to your armor class, including against the triggering attack. If you are hit by an attack while this spell is in effect you can choose to end it early to reduce the damage that attack deals to you by 5 points."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd level or higher, you can choose one of the following effects for each spell level above 1st:"],["li","The bonus to your armor class increases by 1."],["li","The amount of damage this spell reduces increases by 10."],["li","This spell can reduce the damage from one extra source of damage before the spell ends."]],"g":["Whisperwood Tome"]},{"k":"sp-shockwave-cc","n":"Shockwave","l":5,"s":"Psionic","sa":"PSI","c":["Psion"],"bk":"cc","p":143,"ct":"1 action","rg":"Self (30-foot radius)","cp":"S","d":"Instantaneous","b":[["p","You unleash a burst of telekinetic force in all directions. Each creature of your choice within 30 feet of you is knocked 5 feet back and must succeed on a Strength saving throw or take 8d6 damage bludgeoning damage and be knocked prone. A creature that succeeds on its saving throw takes half as much damage and isn’t knocked prone."]],"ci":1},{"k":"sp-shockwave-retia","n":"Shockwave","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":583,"ct":"1 action","rg":"Self (30-foot radius)","cp":"V","d":"Instantaneous","b":[["p","You strike the ground, creating a burst of divine energy that ripples outward from you. Each creature you choose within 30 feet of you must succeed on a Constitution saving throw or take 5d6 thunder or force damage (your choice), as well as 5d6 radiant or necrotic damage (your choice)."],["p","If a target fails they suffer a secondary effect based on the damage type you picked between thunder and force: if thunder, they are knocked prone; if force, they are pushed 30 feet back from you, and take an additional 1d6 bludgeoning damage if they collide with a solid surface that stops them before the full 30 feet."],["p","A creature that succeeds on its saving throw takes half as much damage and isn’t knocked prone or pushed back."]],"h":[["p","At Higher Levels. If you cast this spell at 6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","The thunder or force damage increases by 2d6."],["li","The spell’s radius increases by 15 feet."],["li","(3 slot levels) The spell deals an additional 5d6 damage of either thunder or force (it must be the one you didn’t pick), and targets who fail are both pushed back and knocked prone."]],"leg":1},{"k":"sp-shriekingmars","n":"Shrieking Mars","l":2,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":583,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You call up an intimidating war cry and can target all creatures within 30 feet of you. Those creatures must make a Wisdom saving throw. On a failed save they are frightened for 1 minute, and while frightened this way they cannot make more than a single weapon attack on any turn regardless of features, magic items, or spell effects."]],"h":[["p","At Higher Levels. When you cast this spell at 5th level or higher, you can exclude any creatures you choose from this spell’s effect when you cast it."]],"con":1},{"k":"sp-silencingsmite","n":"Silencing Smite","l":1,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":583,"ct":"1 bonus action","rg":"Self","cp":"V","d":"Concentration, up to 1 minute","b":[["p","The next time you hit with a melee weapon attack during this spell’s duration, your attack deals an extra 1d6 thunder damage. Additionally, if the target is a creature, it must make a Wisdom saving throw or be silenced until the spell ends. While silenced, the creature cannot speak or vocally produce noise; if they attempt to cast a spell that requires verbal components they fail to produce them. Each time the creature attempts to cast a spell and at the end of each of their turns they repeat the Wisdom saving throw, ending the effect on a success."]],"con":1},{"k":"sp-skyburst","n":"Sky Burst","l":5,"s":"Evocation","sa":"EVO","c":["Druid","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":251,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","Five bolts of lightning strike five points of your choice that you can see within range. Each creature within 5 feet of a bolt must make a Dexterity saving throw, taking 4d12 + 4 lightning damage on a failure or half as much damage on a success. A creature in the area of more than one lightning burst is affected only once."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you can call down an additional bolt for each slot level above 5th."]],"ms":["arcane","primal"],"also":[["cc",143]]},{"k":"sp-slashwind","n":"Slash Wind","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":583,"ct":"1 action","rg":"30 feet","cp":"S, M (a melee weapon worth at least 1 sp)","d":"Instantaneous","b":[["p","You flourish the weapon used in the casting and then vanish to strike like the wind. Choose up to five creatures you can see within range. Make a melee spell attack against each target. On a hit, a target takes 6d10 force damage."],["p","These attacks do not count as weapon attacks for the purposes of features such as divine smite, sneak attack, etc., - even if the weapon use would qualify for the effect."],["p","You can then teleport to an unoccupied space you can see within 5 feet of one of the targets you hit or missed."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","You can choose two additional targets within range."],["li","The damage increases by 1d10."],["li","The spell’s range increases by 20 feet."]],"leg":1},{"k":"sp-snapfreeze","n":"Snap Freeze","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":583,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"1 minute","b":[["p","The body of one creature within range is shrouded in cold, freezing from the inside out to an extent that they may not be able to move. They must make a Constitution saving throw. On a failed save they take 7d10 + 10 cold damage and are restrained for 1 minute as their body locks up, or take half as much damage and aren’t restrained on a success. Creatures immune to cold damage are not restrained."],["p","A restrained target may reattempt the saving throw at the end of each of their turns. Each time they take fire damage they may also reattempt the save with advantage. Succeeding either save ends both effects early."]],"h":[["p","At Higher Levels. When you cast this spell at 6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","You may target one additional creature within range."],["li","The spell’s cold damage against its target(s) increases by 1d10."]],"g":["Altissima-Cor’s Arcane Arts"]},{"k":"sp-snowballstorm","n":"Snowball Storm","l":2,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":584,"ct":"1 action","rg":"90 feet","cp":"V, S, M (a piece of ice or a small white rock chip)","d":"Instantaneous","b":[["p","A flurry of magic snowballs erupts from a point you choose within range. Each creature in a 5-foot radius sphere centered on that point must make a Dexterity saving throw. A creature takes 3d6 cold damage on a failed save, or half as much damage on a successful one."]],"h":[["p","At Higher Levels. When you cast this spell at 3rd level or higher, you may choose one of the following effects for each slot level above 2nd:"],["li","The spell’s radius increases by 5 feet."],["li","The cold damage increases by 1d6."],["li","(3 slot levels) Each creature who fails the save has their movement reduced by half until the end of their next turn."]],"leg":1},{"k":"sp-solarimplosion","n":"Solar Implosion","l":3,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":584,"ct":"1 action","rg":"120 feet","cp":"S, M (a red glove, gauntlet or coating of some kind on your hand)","d":"Instantaneous","b":[["p","You raise your hand toward a point you can see within range and clench it into a fist, causing a gravitational detonation followed by an immediate implosion to erupt in a 20-foot radius sphere centered there. All creatures in that space are blasted outward then pulled swiftly inward, and must make a Strength saving throw. On a failure a creature takes 4d8 force damage and is knocked prone. Creatures that fail are also pulled 10 feet toward the center of the implosion, stopping if they collide with anything solid. Creatures who succeed their save take half damage and are not knocked prone or pulled."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, you can choose one of the following options for each spell level above 3rd:"],["li","The force damage increases by 1d8."],["li","The radius of the sphere increases by 10 feet, and the distance creatures are pulled increases by 5 feet."]],"g":["Legacy of Gold"]},{"k":"sp-somaticlattice","n":"Somatic Lattice","l":1,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":584,"ct":"Special","rg":"Self","cp":"S","d":"Special","b":[["p","When you cast a spell that isn’t from the eidomancy school, you reorient your connection to the Eidomantic Web and reprogram it. You cast this spell as you cast the target spell. That spell’s attacks and damage becomes eidolic until its effects end. If any creature attempts to use their reaction to negate your spell (such as through counterspell or dispel magic) and must roll an ability check to do so, that ability check is made with disadvantage. Spell attacks you make through the targeted spell have advantage."],["p","You do not have to make an eidomantic check for this spell, but must make one for the target spell as if it was eidomantic."],["p","When you cast this spell to target another spell being cast at 4th level or higher, this spell must be cast at a level equal to one third (rounded up) of the target spell’s level (2nd level for a 4th, 5th and 6th-level target, and 3rd level for 7th, 8th and 9th-level target)."]],"g":["Eidomancy"]},{"k":"sp-songofharmony","n":"Song of Harmony","l":7,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":584,"ct":"1 action","rg":"15 feet","cp":"V, S","d":"Isntantaneous","b":[["p","A rejuvenating melody washes over all creatures you choose within range. These creatures all regain 8d10 hit points, and are cured of any exhaustion or poison that is plaguing them. Any creature who is prone and receives this healing can use their reaction to stand immediately. This spell has no effect on undead or constructs."]],"g":["Epic of Duality"]},{"k":"sp-songofinspiration","n":"Song of Inspiration","l":2,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":584,"ct":"1 action","rg":"Self (30-foot radius)","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","A pleasing melody follows you for the spell’s duration, protecting those around you from despair. All friendly creatures within 30 feet of you that can hear the song cannot have disadvantage on attack rolls, ability checks, or saving throws. If any effect or condition would give them disadvantage, however, they cannot gain advantage on that roll either."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the spell affects creatures within an additional 10 feet for each level slot level above 2nd. If cast using a spell slot of 5th level or higher, creatures affected by this spell can gain advantage even if they would have had disadvantage on their rolls."]],"con":1,"g":["Epic of Duality"]},{"k":"sp-sonicshriek","n":"Sonic Shriek","l":5,"s":"Evocation","sa":"EVO","c":["Bard","Occultist","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":252,"ct":"1 action","rg":"Self (120-foot cone)","cp":"V, S","d":"Instantaneous","b":[["p","You emit a sonic blast across a huge area. Each creature in a 120-foot cone must make a Constitution saving throw. It takes 6d8 thunder damage on a failure or half as much damage on a success. A creature automatically succeeds on its saving throw if it is more than 60 feet from you."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th."]],"ms":["arcane"],"also":[["cc",143]]},{"k":"sp-spacialhoist","n":"Spacial Hoist","l":6,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":585,"ct":"1 action","rg":"300 feet","cp":"V, S, M (a loop of rope with at least 10 feet of length or a whip)","d":"Instantaneous","b":[["p","You attempt to pull one target (either a creature or a Huge or smaller object) you can see within range close to you. Choose one target, and one unoccupied space that is closer to you than they are which they can fit in: the target must succeed a Wisdom saving throw or be pulled into that space through an arcane gate that opens beside them. You can choose to immediately grapple them if they move within your range and you are capable of doing so. Otherwise, if they are raised higher than 10 feet above the ground, they are held in the air until the start of your next turn, at which point they plummet."],["p","If the target is being mounted by another creature or is restrained/grappled/held by another creature or effect, they have advantage on their saving throw against this effect."]],"g":["Eidomancy"]},{"k":"sp-spatialmanipulation","n":"Spatial Manipulation","l":5,"s":"Conjuration","sa":"CON","c":["Sorcerer","Wizard"],"bk":"cc","p":143,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","You can swap the position two creatures you can see within range. An unwilling creature can make a Charisma saving throw, preventing the swap on success."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you can swap an additional set of creatures of each level about 5th."]]},{"k":"sp-spatialswap","n":"Spatial Swap","l":4,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Wizard"],"bk":"ll","p":252,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","You switch locations with a creature you can see. If there is insufficient space for either creature at the other's location, the spell fails. If the target is unwilling, it can make a Charisma saving throw. On a success, the spell fails."]],"ms":["arcane"]},{"k":"sp-spelltrap","n":"Spelltrap","l":2,"s":"Abjuration","sa":"ABJ","c":["Bard","Sorcerer","Warlock","Wizard"],"bk":"ll","p":252,"ct":"1 minute","rg":"Self","cp":"V, S","d":"8 hours","b":[["p","You mark a spelltrap on yourself, creating a small glowing mark on your skin. The next time you make a saving throw against a spell of 1st level or lower, the spell is harmlessly absorbed and none of its effects take place."],["p","On your next turn afterward, you can cast the spell absorbed by the spelltrap without expending a spell slot. If you do not cast it within that turn, the spell trap fades and the trapped spell is lost."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the highest level of spell it can absorb increases by 1 for each slot level above 2nd."]],"ms":["arcane"]},{"k":"sp-spiderbite","n":"Spider Bite","l":3,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Spellblade","Warlock","Wizard"],"bk":"ll","p":252,"ct":"1 action","rg":"Touch","cp":"V, S","d":"Instantaneous","b":[["p","You stab at a target with a venomous fang. Make a melee spell attack against a creature within reach. On a hit, the target takes 4d12 poison damage and must succeed on a Constitution saving throw or be poisoned for 1 minute. At the end of each of its turns, the target can repeat the save, ending the condition on a success."],["p","If you miss on the initial attack, you can concentrate (as if concentrating on a spell) to maintain the spell for another attempt on a subsequent turn. You may continue to do so until you either hit with the spell or lose concentration."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d12 for each slot level above 3rd."]],"ms":["arcane","primal"],"also":[["cc",143]]},{"k":"sp-spiritecho","n":"Spirit Echo","l":2,"s":"Conjuration","sa":"CON","c":["Occultist","Ranger","Wizard"],"bk":"ll","p":252,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You summon a ghostly echo of yourself. It shares your space and acts automatically, mirroring your actions. The first time on your turn you make a weapon attack, it attacks the same target. It makes a separate attack roll using your attack modifier. On a hit, roll your attack's normal damage; the target takes force damage equal to half the result."]],"con":1,"ms":["arcane"]},{"k":"sp-spiritualconsultation","n":"Spiritual Consultation","l":1,"s":"Necromancy","sa":"NEC","c":["Occultist"],"bk":"ll","p":253,"ct":"1 minute","rg":"Self","cp":"V, S, M (1 gp worth of incense, which the spell consumes)","d":"10 minutes","b":[["p","You call forth a spirit to aid you with your ability checks. Choose one skill out of Arcana, Animal Handling, History, Investigation, Medicine, Nature, Perception, Religion, or Survival. The spirit is proficient in the chosen skill. It is ethereal and ephemeral and cannot interact with physical objects, but can provide guidance on matters relating to chosen skill."],["p","For the duration, you can treat any check you make in the skill as if you have proficiency with it so long as the spirit can communicate with you. Alternatively, the spirit can make Intelligence or Wisdom checks itself, with a +5 modifier. The spirit will follow you, staying within of you at all times. You can choose to release it early, dismissing it back from whence it came."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the spirit’s bonus on making ability checks directly increases by 1 for each slot level above 1st, up to a maximum of +9."]],"ms":["arcane"]},{"k":"sp-splitranks","n":"Split Ranks","l":6,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":585,"ct":"1 action","rg":"30 feet","cp":"V","d":"Instantaneous","b":[["p","The air quivers around up to five creatures of your choice that you can see within range. You teleport each affected target to an unoccupied space which must be on the ground or a floor that you can see within 120 feet of you. An unwilling creature must succeed on a Wisdom saving throw to resist this spell."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 7th level or higher, you can choose one of the following effects for each slot level above 6th:"],["li","The spell’s range increases by 30 feet."],["li","The targets can be moved to a space within an additional 60 feet you can see."],["li","You may target up to three additional targets."]],"leg":1,"g":["Epic of Duality"]},{"k":"sp-splittimeline","n":"Split Timeline","l":4,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Wizard"],"bk":"ll","p":253,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"1 round","b":[["p","You choose a willing creature in range and split its timeline in two. At the start of that creature’s next turn, a temporal duplicate of them appears in a space adjacent to it. The duplicate lasts until the end of the target's turn or it drops to 0 hit points (whichever comes first). Their temporal duplicate shares the target's statistics, abilities, and resources, and is under the target's control. Any abilities, items, or spells with limited uses deplete the equivalent resources for the target."],["p","At the end of the target's turn, the temporal duplicate disappears."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the temporal duplicate lasts for 1 additional round for each slot level above 4th."]],"ms":["arcane"]},{"k":"sp-springmoonsholyshield","n":"Springmoon’s Holy Shield","l":7,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":585,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You produce the effects of a holy barrier which serves to protect you when attacked. You gain resistance to all damage for the spell’s duration, and when you make a saving throw you may use your reaction to roll an additional d20 and choose which result you want to keep between your original roll and the new one."]],"con":1,"g":["Skulker’s Grimoire"]},{"k":"sp-sprouttree","n":"Sprout Tree","l":2,"s":"Transmutation","sa":"TRA","c":["Druid"],"bk":"ll","p":253,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","You point at an empty 5-foot space on the ground you can see within range, and a tree sprouts there, rapidly growing to a height of 20 feet with a 2-foot radius trunk. The tree must grow on dirt, sand, or another appropriate surface. At the DM's discretion, it can burst through up to 6 inches of hard material. The tree stops growing if it would hit a ceiling or other object."],["p","Any creature in this space must make a Dexterity saving throw. On a failure, it is lifted 20 feet into the air in the branches of the tree. On a success, it moves 5 feet to an unoccupied space of its choice (if there is no empty space to which it can move, it automatically fails). A Large or smaller creature can choose to fail this save, while a Huge or larger creature automatically succeeds."],["p","The tree provides as half cover to any creature within its branches, and three-quarters cover from effects originating on the other side of its trunk. The tree has 50 hit points and AC 13."],["p","The tree remains after the spell ends, but may die rapidly if sprouted in an unsuitable location or environment. Its wood is flammable only when dried, and serves no useful purpose except as firewood."]],"ms":["primal"]},{"k":"sp-stardust","n":"Star Dust","l":2,"s":"Evocation","sa":"EVO","c":["Sorcerer","Spellblade","Wizard"],"bk":"ll","p":254,"ct":"1 action","rg":"Self (30-foot cone)","cp":"V, S","d":"Instantaneous","b":[["p","You evoke a burst of brilliant power sweeping out in a 30-cone originating from you. Each in the radius takes 3d4 force damage, and the next attack roll made against it before the start of your next turn has advantage."]],"ms":["arcane"],"also":[["cc",144]]},{"k":"sp-starscry","n":"Star Scry","l":2,"s":"Divination","sa":"DIV","c":["Druid","Occultist","Sorcerer","Wizard"],"bk":"ll","p":254,"ct":"1 minute","rg":"Self (60-foot radius)","cp":"V, S","d":"Instantaneous","b":[["p","You describe a location, person, or object during the casting of the spell. Afterward, an illusion of a starry night sky forms above your head, showing the night sky at midnight above the target. You can then make an Intelligence (Navigator’s Tools) check to determine the general region of the described target. The DC is 10 if you’ve been to the area before, 15 if you’ve been within 100 miles, and 20 if you’ve never been within 100 miles of the location."],["p","The spell fails if you give an inaccurate description or false name for the target, or if you cast it on the same target more than once within 24 hours."]],"ms":["arcane","primal"]},{"k":"sp-starfall","n":"Starfall","l":4,"s":"Evocation","sa":"EVO","c":["Druid","Occultist","Sorcerer","Wizard"],"bk":"ll","p":253,"ct":"1 action","rg":"Self (60-foot radius)","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You create a false sky above you, filled with gleaming stars, which immediately begin to rain down. When you cast the spell, 3 stars immediately fall, with 1 additional star falling at the start of each of your turns for the duration. For each falling star, choose a creature within 60 feet of you. That creature must make a Dexterity saving throw, taking 4d8 radiant damage on a failure or half as much on a success. A creature cannot be targeted by more than one falling star in a turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the number of stars that fall in the initial cast and on subsequent turns increases by 1 for each slot level above 4th."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-starfallmantle","n":"Starfall Mantle","l":7,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":585,"ct":"1 action","rg":"Self","cp":"V, S","d":"1 hour","b":[["p","Seven star-like motes of light appear and orbit you until the spell ends. You can use a bonus action to send one of the motes streaking toward one creature or object within 120 feet of you. When you do so, make a ranged spell attack. On a hit, the target takes 4d12 radiant damage. Whether you hit or miss, the mote is expended. The spell ends early if you expend the last mote."],["p","If you have four or more motes remaining, they shed bright light in a 30-foot radius and dim light for an additional 30 feet. If you have one to three motes remaining, they shed dim light in a 30-foot radius."],["p","When a creature hits you with a melee attack from within 5 feet, you can force that creature to make a Dexterity saving throw. On a failure you may treat them as if hit with one of the motes, expending one in the process."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 8th level or higher, you can choose one of the following effects for each slot level above 7th:"],["li","The number of motes increases by two."],["li","The damage of each mote increases by 1d12."],["li","Each time a mote strikes a creature, they must succeed a Constitution saving throw or be blinded until the end of their next turn."],["li","You can launch an additional mote with each bonus action you use to fire one. They must target different creatures, and each make their own ranged spell attack."]],"leg":1},{"k":"sp-staticfield","n":"Static Field","l":3,"s":"Transmutation","sa":"TRA","c":["Inventor","Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":254,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","A visible field of static energy crackles to life in a 20-foot radius around a point you can see within range. If a creature takes an action, reaction, or moves at least 5 feet within the field, it takes 1d12 lightning damage. A creature can take damage from each trigger once per turn (taking an action, a reaction, or moving)."]],"con":1,"ms":["arcane"]},{"k":"sp-stingingswarm","n":"Stinging Swarm","l":4,"s":"Conjuration","sa":"CON","c":["Druid","Occultist","Warlock","Wizard"],"bk":"ll","p":254,"ct":"1 action","rg":"60 feet (5-foot cube)","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You conjure a magical swarm of flying insects that fill a 5-foot cube within range. The swarm cannot be damaged or destroyed. For the duration, you can use a bonus action to command it to move up to 30 feet. If the swarm enters another creature’s space, it stops and stings the creature repeatedly, and cannot be moved until the start of your next turn. The creature takes 2d4 piercing damage and must succeed on a Constitution saving throw or take 6d4 poison damage."]],"con":1,"ms":["arcane","primal"],"also":[["cc",144]]},{"k":"sp-stirgeswarm","n":"Stirge Swarm","l":6,"s":"Conjuration","sa":"CON","c":["Occultist","Warlock","Wizard"],"bk":"llb","p":296,"ct":"1 action","rg":"60 feet","cp":"S, M (a splash of your blood worth at least 10 hit points, which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You conjure a swirling swarm of magical Stirges that hover in a 20-foot radius of a point you can see within range. A creature starting its turn in the area or entering it for the first time on a turn must make a Dexterity saving throw. On a failure, the stirges drain its blood, reducing its hit points by 4d4 + 12 and restoring 4 hit points to you. On a successful save, a creature takes half as much damage and you regain 2 hit points. The swarm ignores you and any creatures without blood."],["p","You can move the swarm up to 30 feet in any direction as a bonus action. When the spell ends, the stirges disappear."]],"con":1,"bm":1},{"k":"sp-stonecoffin","n":"Stone Coffin","l":4,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Wizard"],"bk":"ll","p":254,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You cause a surge of stone to attempt to encase a Large or smaller creature. The target must make a Dexterity saving throw. On a failure, it becomes trapped in the coffin, causing it to be blinded and restrained. A creature can choose to fail their save. While trapped within the coffin, a creature has total cover against all sources. The coffin has an AC of 15 and 50 hit points, and resistance to all damage beside bludgeoning and thunder damage. When the spell ends or the coffin is reduced to 0 hit points, it crumbles to fragments and the creature within is no longer restrained and blinded."],["p","For the duration of the spell you can use your bonus action to crush a creature encased in the coffin, dealing 1d10 bludgeoning damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the stone coffin gains 10 additional hit points for each level above 5th."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-stonefist","n":"Stone Fist","l":1,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Warlock","Wizard"],"bk":"ll","p":255,"ct":"1 action","rg":"Self","cp":"V, S","d":"1 round","b":[["p","You turn your hand and forearm (or similar appendage) to stone until the start of your next turn. As part of casting the spell, you can make a melee spell attack against one creature you can reach. On a hit, the target takes 2d10 bludgeoning damage."],["p","Until the start of your next turn, you can use your reaction when you take slashing or piercing damage from an attack to gain resistance to damage from that attack."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d10 for each slot level above 1st."]],"ms":["arcane","primal"],"also":[["cc",144]]},{"k":"sp-stoneforming","n":"Stone Forming","l":0,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Warlock"],"bk":"ll","p":255,"ct":"1 bonus action","rg":"Touch","cp":"V, S","d":"1 hour","b":[["p","You lay your hand on dirt or rock and call on the stone to shape itself to your command. You can make any roughly shaped Small or Tiny item from the stone, including functional simple or martial melee weapons. Created items possess magical durability to resist shattering or breaking. This spell can't be used to carve significant amounts of material away from stone walls, doors, or other large objects."],["p","Alternatively you can encase your limbs in stone, causing your unarmed strikes to deal 1d8 bludgeoning damage for the duration of the spell."],["p","Items made this way lose any magical durability after one hour, and become easily broken if they would not normally be functional in that shape. You can have three items or effects created by this cantrip at a time, and upon creating a fourth the oldest one loses its magical durability and becomes easily broken."]],"ms":["arcane","primal"]},{"k":"sp-stonepillar","n":"Stone Pillar","l":2,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Wizard"],"bk":"ll","p":255,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You cause a pillar of stone to rise from the ground in a space you can see within range. The pillar occupies a 5-foot space and rises up to 30 feet into the air. The ground where it appears must have space to accommodate it, and you can't target a space under a Large or larger creature."],["p","If a pillar is created under a Medium or smaller creature, that creature must succeed on a Dexterity saving throw or be lifted by the pillar. A creature can choose to fail its save. If a pillar is prevented from reaching its full height because of a ceiling or other obstacle, a creature on the pillar takes 3d8 bludgeoning damage and is restrained, crushed between the pillar and the obstacle. The restrained creature can use an action to make a Strength (Athletics) or Dexterity (Acrobatics) check (the creature’s choice) against the spell save DC. On a success, the creature is no longer restrained and must either move off the pillar or fall."],["p","The pillar has AC 5 and 30 hit points. When reduced to 0 hit points, it crumbles into rubble, creating an area of difficult terrain in a 15-foot square centered on the pillar, which lasts until the rubble is cleared. Each 5-foot-square in the area requires at least 1 minute to clear by hand."]],"ms":["arcane","primal"]},{"k":"sp-stormshot","n":"Storm Shot","l":5,"s":"Transmutation","sa":"TRA","c":["Ranger"],"bk":"ll","p":255,"ct":"1 bonus action","rg":"Touch","cp":"V, S, M (a piece of ammunition or a weapon with the thrown property worth at least 1 cp)","d":"1 round","b":[["p","You touch a piece of ammunition or weapon with the thrown property, imbuing it with a crackling storm of power for the duration. The first time you attack with the weapon, it explodes into a raging storm on reaching its destination. On a hit, the target takes an additional 4d8 lightning damage. On a miss, the target takes half as much damage."],["p","Hit or miss, the target and all creatures within 20"],["p","feet of it must make a Strength saving throw against"],["p","the raging storm unleashed by the attack. On a failed,"],["p","a creature is thrown 20 feet straight up (falling"],["p","immediately if not otherwise held aloft) and takes 2d8"],["p","lightning damage. On a successful save, it is not"],["p","thrown into the air and takes half as much lightning"],["p","damage."]],"ms":["primal"]},{"k":"sp-suddenhazards","n":"Sudden Hazards","l":5,"s":"Illusion","sa":"ILL","c":["Bard","Occultist","Sorcerer","Wizard"],"bk":"ll","p":256,"ct":"1 action","rg":"Self (60-foot cube)","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You cause illusions of deadly traps or other hazards to spring up, filling a 60 foot cube originating from you. Swinging blades, lava flows, or other phantom hazards fill the minds of each creature of your choice within the area. An affected creature can move at half speed to evade the dangers, or move at its normal speed and take 1d8 psychic damage for each 5 feet it moves within the area. Any affected creature ending its turn in the area must make a Dexterity saving throw. It takes 5d8 psychic damage on a failure or half as much on a success."],["p","Each time a creature ends its turn in the area, it can make a Wisdom saving throw. On a success, it realizes the traps are fake, and the spell ends for that creature."]],"con":1,"ms":["arcane"]},{"k":"sp-suffocate","n":"Suffocate","l":4,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":256,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You create a whirling sphere of air around a creature that causes them to struggle to breathe. The target must make a Constitution saving throw. On a failure, it loses 5d8 hit points due to lack of air, has disadvantage on all ability checks, and cannot speak. On a success, the target takes half as much damage and suffers no other effects. For the duration, as an action, you can force the creature to repeat this saving throw."],["p","If a target fails its saving throw against this spell 3 times in a row, it becomes incapacitated until it succeeds on a save or the spell ends. If you don’t use your action to force the target to make a save, it automatically attempts the save and succeeds at the end of its next turn."],["p","A creature that does not need to breathe is unaffected by this spell."]],"con":1,"ms":["arcane"],"also":[["cc",144]]},{"k":"sp-summonarchon","n":"Summon Archon","l":2,"s":"Conjuration","sa":"CON","c":["Cleric","Paladin","Warlock"],"bk":"ll","p":256,"ct":"1 action","rg":"90 feet","cp":"V, S, M (an ornate relic worth at least 200 gp)","d":"Concentration, up to 1 hour","b":[["p","You call forth a minor celestial archon, which manifests in an unoccupied space that you can see within range. It uses the Archon spirit stat block, and you select either the Hound, Lantern, or Trumpet option when you cast the spell. The creature disappears when it drops to 0 hit points or when the spell ends."],["p","The creature is an ally to you and your companions. In combat, it shares your initiative count, and its turn immediately after yours. It obeys your verbal commands (no action required by you). if you don’t issue any command, it takes the Dodge action and uses its moves only to avoid hazards."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, certain values increase in its stat block."]],"con":1,"ms":["divine"]},{"k":"sp-summondragon","n":"Summon Dragon","l":5,"s":"Conjuration","sa":"CON","c":["Wizard","Sorcerer"],"bk":"ll","p":256,"ct":"1 action","rg":"90 feet","cp":"V, S, M (a dragon statuette worth at least 500 gp)","d":"Concentration, up to 1 hour","b":[["p","You call forth a magical dragon spirit, which manifests in an unoccupied space that you can see within range. It uses the dragon spirit stat block, and you select one dragon color from the table below when you cast the spell. The creature resembles a dragon of that color, which determines certain traits in its stat block. The creature disappears when it drops to 0 hit points or when the spell ends."],["p","The creature is an ally to you and your companions. In combat, it shares your initiative count, and takes its turn immediately after yours. It obeys your verbal commands. If you don’t issue any command, it takes the Dodge action and moves only to avoid hazards."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, certain values increase in its stat block."],["p","Dragon Table Elemental Dragon Breath Weapon Area Damage"],["tbl",[["Black","Acid","5 by 60 ft. line (Dex. save)"],["Blue","Lightning","5 by 60 ft. line (Dex. save)"],["Brass","Fire","5 by 60 ft. line (Dex. save)"],["Bronze","Lightning","5 by 60 ft. line (Dex. save)"],["Copper","Acid","5 by 60 ft. line (Dex. save)"],["Gold","Fire","30 ft. cone (Dex. save)"],["Green","Poison","30 ft. cone (Con. save)"],["Red","Fire","30 ft. cone (Dex. save)"],["Silver","Cold","30 ft. cone (Con. save)"],["White","Cold","30 ft. cone (Con. save)"]]],["p","Dragon Spirit Large dragon, unaligned Armor Class 12 + the level of the spell (natural armor)"],["p","Hit Points 50 + 10 for each spell level above 5th Speed 30 ft., fly 40 ft."],["p","STR DEX CON INT WIS CHA 18 (+4) 10 (+0) 18 (+4) 14 (+2) 16 (+3) 18 (+4)"],["p","Damage Immunities the dragon's elemental damage type Senses blindsight 30 ft., darkvision 120 ft., passive Perception 13 Languages Draconic, understands the languages you speak Challenge — Actions Multiattack. The dragon makes a number of attacks equal to half this spell’s level (rounded down). It can only attack with its bite or tail once each per turn."],["p","Bite. Melee Weapon Attack: your spell attack modifier to hit, reach 10 ft., one target. Hit: 1d6 + 4 + the spell’s level piercing damage + 1d6 of the dragon’s elemental damage."],["p","Claw. Melee Weapon Attack: your spell attack modifier to hit, reach 5 ft., one target. Hit: 1d4 + 4 + the spell’s level slashing damage."],["p","Tail. Melee Weapon Attack: your spell attack modifier to hit, reach 15 ft., one target. Hit: 1d8 + 4 + the spell’s level bludgeoning damage."],["p","Breath Weapon (1/Day). The dragon exhales elemental power in its breath weapon area from the dragon table. Each creature in that area must make a Dexterity saving throw with a DC equal to your spell save DC, taking 5d8 + the spell's level elemental damage on a failed save, or half as much damage on a successful one."],["p","Archon Spirit Medium (Small for Lantern) celestial, unaligned Armor Class 11 + the level of the spell (natural armor)"],["p","Hit Points 20 (Lantern or Trumpet only) or 30 (Hound Only) + 5"],["p","for each spell level above 2nd Speed 30 ft., fly 30 ft. (Trumpet and Lantern only)"],["p","STR DEX CON INT WIS CHA 14 (+2) 10 (+0) 14 (+2) 10 (+0) 13 (+1) 14 (+2)"],["p","Damage Resistances radiant Senses darkvision 60 ft., passive Perception 11 Languages Celestial, understands the languages you speak Challenge — Keen Hearing and Smell (Hound only). The archon has advantage on Wisdom (Perception) checks that rely on hearing or smell."],["p","Lantern’s Light (Lantern only). The archon sheds bright light in a 30-foot radius and dim light for an additional 30 feet."],["p","Rallying Call (Trumpet only). Once per turn when the archon deals damage, it grants one creature of its choice within 60 feet temporary hit points equal to half the damage dealt."],["p","Actions Multiattack. The archon makes a number of attacks (or Trumpet uses) equal to half this spell’s level (rounded down)."],["p","Greatsword (Hound Only). Melee Weapon Attack: your spell attack modifier to hit, reach 5 ft., one target. Hit: 2d6 + 2 + the spell’s level slashing damage."],["p","Radiant Bolt (Lantern Only). Ranged Spell Attack: your spell attack modifier to hit, range 60 ft., one target. Hit: 1d8 + 2 + the spell’s level radiant damage."],["p","Trumpet (Trumpet Only). One creature of the archon’s choice within 60 feet must succeed on a Constitution saving throw with a DC equal to your spell save or take 1d6 + 2 + the spell’s level thunder damage."]],"rv":1,"con":1,"ms":["arcane"]},{"k":"sp-summonhorror","n":"Summon Horror","l":4,"s":"Conjuration","sa":"CON","c":["Occultist","Warlock","Wizard"],"bk":"cc","p":144,"ct":"1 action","rg":"90 feet","cp":"V, S, M (a book with an ornate cover filled with the records of madmen worth at least 400 gp)","d":"Concentration, up to 1 hour","b":[["p","You call forth a twisted horror. It manifests in an unoccuptied space that you can see within Range. This manifested form uses the Horror Spirit stat block. When you cast the spell, choose Star, Sea, or Void. The creature takes on elements of the selected type, which determine certain traits in its stat block. The creature disappears when it drops to 0 hit points or the spell ends."],["p","The creature is an ally to you and your companions. In combat, the creature shares your initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don’t issue any, it takes the Dodge action and uses its move to avoid danger."]],"h":[["p","At Higher Levels. When you cast this spell using a spell of 5th level or higher, use the higher level whenever the spell’s level appears in the stat block."],["p","Horror Spirit"],["p","Medium aberration, unaligned"],["p","Armor Class 11 + the level of the spell (natural armor)"],["p","Hit Points 25 + 5 for each spell level above 4th"],["p","Speed 30 ft., swim 30 ft., fly 30 ft. (Star and Void Only; hover)."],["p","STR DEX CON INT WIS CHA"],["p","16 (+3) 12 (+1) 15 (+2) 16 (+3) 8 (−1) 6 (−2)"],["p","Damage Resistances bludgeoning, piercing, and slashing from"],["p","nonmagical attacks"],["p","Damage Immunities poison, psychic"],["p","Condition Immunities blinded, charmed,, frightened"],["p","Senses darkvision 60 ft., passive Perception 9"],["p","Languages understands the languages you speak"],["p","Challenge — Proficiency Bonus equals your bonus"],["p","Grasping Tentacles (Sea Only). If the aberration hits the same"],["p","creature two or more times on its turn, the target is grappled (escape"],["p","DC your spell save DC). Creatures that start their turn grappled by"],["p","the aberration take 7 (2d6) acid damage. It can grapple a number of"],["p","creatures this way equal to your proficiency bonus."],["p","Fatal Destiny (Star Only). Creatures of your choice that start their"],["p","turn within 5 feet of the abherration must succeed on a Wisdom"],["p","saving throw against your spell save DC or become transfixed by the"],["p","abherration, unable to move away, and with disadvantage on attacks"],["p","against creatures other than the aberration."],["p","Actions"],["p","Multiattack. The aberration makes a number of attacks equal to half"],["p","this spell’s level (rounded down). The aberration can use Fold Space in"],["p","place of one attack (Void Only)."],["p","Tentacle. Melee Weapon Attack: your spell attack modifier to hit, reach"],["p","10 ft., one target. Hit: 1d8 + 3 + the spell’s level bludgeoning damage."],["p","Fold Space (Void Only). The abherration teleports up to 30 feet."],["p","Creatures within 5 feet of its destination take 7 (2d6) force damage. It"],["p","can bring one willing creature within 5 feet of it with it when teleporting"],["p","this way, but that creature takes 1d6 psychic damage when it does so."]],"rv":1,"con":1},{"k":"sp-summonmonstrosity","n":"Summon Monstrosity","l":3,"s":"Conjuration","sa":"CON","c":["Sorcerer","Wizard"],"bk":"ll","p":257,"ct":"1 action","rg":"90 feet","cp":"V, S, M (a statuette carved from a monster bone or fang worth at least 300 gp)","d":"Concentration, up to 1 hour","b":[["p","You call forth a magical monstrosity spirit, which manifests in an occupied space that you can see within range. It uses the Monstrosity Spirit stat block, and you select either the Blinker, Burrower, or Displacer option when you cast the spell. The"],["p","creature disappears when it drops to 0 hit points or"],["p","when the spell ends."],["p","The creature is an ally to you and your companions."],["p","In combat, it shares your initiative count, and takes"],["p","its turn immediately after yours. It obeys your verbal"],["p","commands. If you don’t issue any command, it takes"],["p","the Dodge action and moves only to avoid hazards."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, certain values increase in its stat block."],["p","Monstrosity Spirit"],["p","Medium monstrosity, unaligned"],["p","Armor Class 11 + the level of the spell (natural armor)"],["p","Hit Points 35 + 15 for each spell level above 3rd"],["p","Speed 40 ft., burrow 40 ft. (burrower only)"],["p","STR DEX CON INT WIS CHA"],["p","16 (+3) 12 (+1) 16 (+3) 4 (−3) 16 (+3) 5 (−3)"],["p","Senses darkvision 60 ft., tremorsense 30 ft. (burrower only),"],["p","passive Perception 13"],["p","Languages understands the languages you speak"],["p","Challenge —"],["p","Blink (Blinker Only). As a bonus action, the monstrosity can"],["p","magically teleport up to 30 feet to an unoccupied space it can see."],["p","Displace (Displacer Only). Attack rolls against the monstrosity"],["p","have disadvantage. If the monster is hit by an attack, this trait"],["p","ceases to work until the start of the monster’s next turn."],["p","Evasion (Displacer and Blinker Only). If the monstrosity is"],["p","subjected to an effect that allows it to make a saving throw to take"],["p","only half damage, it instead takes no damage if it succeeds on the"],["p","saving throw, and only half damage if it fails."],["p","Actions"],["p","Multiattack. The monstrosity makes a number of attacks equal to"],["p","half this spell’s level (rounded down)."],["p","Chomp. Melee Weapon Attack: your spell attack modifier to hit, reach"],["p","5 ft., one target. Hit: 1d10 + 3 + the spell’s level piercing damage."],["p","Lash (Displacer only). Melee Weapon Attack: your spell attack"],["p","modifier to hit, reach 10 ft., one target. Hit: 1d4 + 3 + the spell’s"],["p","level slashing damage."]],"rv":1,"con":1,"ms":["arcane"]},{"k":"sp-summonooze","n":"Summon Ooze","l":1,"s":"Conjuration","sa":"CON","c":["Wizard"],"bk":"ll","p":258,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a gold vial worth at least 100 gp)","d":"Concentration, up to 1 hour","b":[["p","You call forth a magical ooze, which manifests in an unoccupied space that you can see within range. It uses the Ooze Spirit stat block, and you select either the Green, Red, or Yellow option when you cast the spell. The creature disappears when it drops to 0 hit points or when the spell ends."],["p","The creature is an ally to you and your companions. In combat, it shares your initiative count, and takes its turn immediately after yours. It obeys your verbal commands. If you don’t issue any command, it takes the Dodge action and moves only to avoid hazards."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, certain values increase in its stat block."],["p","Ooze Spirit"],["p","Small ooze, unaligned"],["p","Armor Class 6 + the level of the spell (natural armor)"],["p","Hit Points 5 + 10 for each spell level above 1st"],["p","Speed 10 ft."],["tbl",[["STR","DEX","CON","INT","WIS","CHA"],["12 (+3) 6 (−2)","12 (+1) 1 (−5)","1 (−5) 1 (−5)"]]],["p","Damage Immunities acid, fire (Red only), lightning (Yellow only),"],["p","Poison (Green only)"],["p","Damage Resistances bludgeoning, piercing, and slashing from"],["p","nonmagical attacks"],["p","Senses blindsight 10 ft. (blind beyond this radius), passive"],["p","Perception 5"],["p","Languages understands the languages you speak"],["p","Challenge —"],["p","Actions"],["p","Multiattack. The ooze makes a number of attacks equal to half this"],["p","spell’s level (rounded down)."],["p","Pseudopod. Melee Weapon Attack: your spell attack modifier to hit,"],["p","reach 5 ft., one target. Hit: 1d4 + 3 + the spell’s level acid damage."]],"rv":1,"con":1,"ms":["arcane"],"also":[["cc",145]]},{"k":"sp-summonplant","n":"Summon Plant","l":3,"s":"Conjuration","sa":"CON","c":["Druid","Ranger"],"bk":"ll","p":258,"ct":"1 action","rg":"90 feet","cp":"V, S, M (a carved wooden figurine worth at least 300 gp)","d":"Concentration, up to 1 hour","b":[["p","You call forth a magical plant, which manifests in an unoccupied space that you can see within range. It uses the Plant Spirit stat block, and you select either the Dryad, Shambling Mound, or Treant option when you cast the spell. The creature disappears when it drops to 0 hit points or when the spell ends."],["p","The creature is an ally to you and your companions. In combat, it shares your initiative count, and takes its turn immediately after yours. It obeys your verbal commands. If you don’t issue any command, it takes the Dodge action and moves only to avoid hazards."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, certain values increase in its stat block."],["p","Plant Spirit"],["p","Large (Medium for Dryad) plant, unaligned"],["p","Armor Class 12 + the level of the spell (natural armor)"],["p","Hit Points 35 + 10 for each spell level above 3rd"],["p","Speed 20 ft."],["tbl",[["STR","DEX","CON","INT","WIS","CHA"],["16 (+3) 8 (−1)","14 (+2) 10 (+0) 16 (+3) 10 (+0)"]]],["p","Damage Vulnerabilities fire"],["p","Damage Resistances bludgeoning"],["p","Senses darkvision 60 ft., blindsight 60 ft. (Shambling Mound only),"],["p","passive Perception 10"],["p","Languages Sylvan, understand the languages you speak"],["p","Challenge —"],["p","Engulf (Shambling Mound Only). If the plant hits a target that it"],["p","is grappling, that target becomes restrained until the grapple ends."],["p","Tree Stride (Dryad Only). Once on its turn, the plant can use 10"],["p","feet of its movement to step magically into one living tree within"],["p","its reach and emerge from a second living tree within 60 feet of the"],["p","first tree, appearing in an unoccupied space within 5 feet of the"],["p","second tree. Both trees must be Large or larger."],["p","Actions"],["p","Multiattack. The plant makes a number of attacks equal to half"],["p","this spell’s level (rounded down)."],["p","Entangling Slam (Treant or Shambling Mound Only). Melee"],["p","Weapon Attack: your spell attack modifier to hit, reach 5 ft., one"],["p","target. Hit: 1d10 + 3 + the spell’s level bludgeoning damage and the"],["p","target is grappled (escape DC equals your spell save DC). Until this"],["p","grapple ends, plant spirit can’t use this attack on another target"],["p","Vine Lash (Treant or Dryad Only). Melee Weapon Attack: your"],["p","spell attack modifier to hit, reach 15 ft., one target. Hit: 1d8 + 3 +"],["p","the spell’s level slashing damage and the target is grappled (escape"],["p","DC equals your spell save DC). Until this grapple ends, plant can’t"],["p","use this attack on another target"]],"rv":1,"con":1,"ms":["primal"]},{"k":"sp-summonswarm","n":"Summon Swarm","l":2,"s":"Conjuration","sa":"CON","c":["Druid","Occultist","Wizard"],"bk":"ll","p":259,"ct":"1 action","rg":"90 feet","cp":"V, S, M (a golden insect worth at least 200 gp)","d":"Concentration, up to 1 hour","b":[["p","You call forth a magical swarm, which manifests in an unoccupied space that you can see within range. It uses the Swarm Spirit stat block, and you select either the Quippers, Spiders, or Wasps option when you cast the spell. The creature disappears when it drops to 0 hit points or when the spell ends."],["p","The creature is an ally to you and your companions. In combat, it shares your initiative count, and takes its turn immediately after yours. It obeys your verbal commands. If you don’t issue any command, it takes the Dodge action and moves only to avoid hazards."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, certain values increase in its stat block."],["p","Swarm Spirit"],["p","Medium swarm of Tiny beasts, unaligned"],["p","Armor Class 10 + the level of the spell (natural armor)"],["p","Hit Points 10 + 5 for each spell level above 2nd"],["p","Speed (Spiders only) 30 ft., climb 30 ft."],["p","Speed (Quippers only) 5 ft., swim 30 ft."],["p","Speed (Wasps only) 5 ft., fly 30 ft."],["tbl",[["STR","DEX","CON","INT","WIS","CHA"],["3 (−4) 13 (+1) 10 (+0) 1 (−5)","7 (−2) 1 (−5)"]]],["p","Damage Resistances bludgeoning, piercing, slashing"],["p","Senses blindsight 10 ft., passive Perception 8"],["p","Languages understands the languages you speak"],["p","Challenge —"],["p","Spider Climb (Spider Only). The swarm can climb difficult"],["p","surfaces, including upside down on ceilings, without needing to"],["p","make an ability check."],["p","Swarm. The swarm can occupy another creature’s space and vice"],["p","versa, and the swarm can move through any opening large enough"],["p","for a Tiny creature. The swarm can’t regain hit points or gain"],["p","temporary hit points."],["p","Web Walker (Spider Only). The swarm ignores movement"],["p","restrictions caused by webbing."],["p","Actions"],["p","Multiattack. The swarm makes a number of attacks equal to half"],["p","this spell’s level (rounded down)."],["p","Bite (Quipper Only). Melee Weapon Attack: your spell attack"],["p","modifier to hit, reach 0 ft., one target in the swarm's space. Hit:"],["p","3d4 + the spell’s level piercing damage."],["p","Sting (Spider and Wasp Only). Melee Weapon Attack: your spell"],["p","attack modifier to hit, reach 0 ft., one target in the swarm's space."],["p","Hit: 2d4 + the spell’s level piercing damage + 1d4 poison damage."]],"rv":1,"con":1,"ms":["arcane","primal"]},{"k":"sp-sunlightcrest","n":"Sunlight Crest","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":586,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a sunburst pendant worth at least 100 gp)","d":"Concentration, up to 1 minute","b":[["p","The light of dawn shines down on a location you specify within range. Until the spell ends, a 30-foot radius, 40-foot-high cylinder of bright light glimmers there. This light is sunlight."],["p","When the cylinder appears, each creature in it must make a Constitution saving throw, taking 4d10 radiant damage on a failed save, or half as much damage on a successful one. A creature must also make this saving throw whenever it ends its turn in the cylinder."],["p","If you’re within 60 feet of the cylinder, you can move it up to 60 feet as a bonus action on your turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","The cylinder’s radius and height increase by 5 feet and 10 feet respectively."],["li","The radiant damage increases by 1d10."],["li","You can choose to fire the spell’s effects in a cone of sunlight originating from you, equal in length and twice the cylinder’s height. Creatures in range make the saving throw immediately, taking twice as many dice of radiant damage on a failure, or half as much on a success. The effect then ends."]],"con":1,"leg":1,"g":["Legacy of Gold"]},{"k":"sp-supernova","n":"Supernova","l":9,"s":"Evocation","sa":"EVO","c":["Sorcerer","Wizard"],"bk":"ll","p":260,"ct":"1 action","rg":"Sight","cp":"V, S, M (a lump of starforged iron)","d":"Instantaneous","b":[["p","You form a fist-sized star at a point you can see within range, which then explodes into a cataclysmic supernova. All creatures within 60 feet of the point must make a Constitution saving throw. On a failure, a creature takes 30d8 radiant damage and is blinded for 1 minute. On a success, it takes half as much damage and is not blinded. A blinded creature can repeat this saving throw at the end of each of its turns, ending the effect on a success."]],"ms":["arcane"]},{"k":"sp-supremehand","n":"Supreme Hand","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":586,"ct":"1 action","rg":"120 feet","cp":"V, S, M (an eggshell and a snake-skin glove)","d":"Concentration, up to 1 minute","b":[["p","You create a Large hand of shimmering, translucent force in an unoccupied space that you can see within range. The hand lasts for the spell’s duration, and it moves at your command, mimicking the movements of your own hand."],["p","The hand is an object that has AC 20 and hit points equal to your hit point maximum. If it drops to 0 hit points, the spell ends. It has a Strength of 26 (+8) and a Dexterity of 10 (+0). The hand doesn’t fill its space."],["p","When you cast the spell and as a bonus action on your subsequent turns, you can move the hand up to 60 feet and then cause one of the following effects with it."],["p","Clenched Fist. The hand strikes one creature or object within 5 feet of it. Make a melee spell attack for the hand using your game statistics. On a hit, the target takes 4d8 force damage."],["p","Forceful Hand. The hand attempts to push a creature within 5 feet of it in a direction you choose. Make a check with the hand’s Strength contested by the Strength (Athletics) check of the target. If the target is Medium or smaller, you have advantage on the check. If you succeed, the hand pushes the target up to 5 feet plus a number of feet equal to five times your spellcasting ability modifier. The hand moves with the target to remain within 5 feet of it."],["p","Grasping Hand. The hand attempts to grapple a Huge or smaller creature within 5 feet of it. You use the hand’s Strength score to resolve the grapple. If the target is Medium or smaller, you have advantage on the check. While the hand is grappling the target, you can use a bonus action to have the hand crush it. When you do so, the target takes bludgeoning damage equal to 2d6 + your spellcasting ability modifier."],["p","Interposing Hand. The hand interposes itself between you and a creature you choose until you give the hand a different command. The hand moves to stay between you and the target, providing you with half cover against that creature. The target can’t move through the hand’s space if its Strength score is less than or equal to the hand’s Strength score. If its Strength score is higher than the hand’s Strength score, the target can move toward you through the hand’s space, but that space is difficult terrain for the target."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the damage from the clenched fist option increases by 2d8 and the damage from the grasping hand increases by 2d6 for each slot level above 5th."]],"con":1,"leg":1},{"k":"sp-swappingcurse","n":"Swapping Curse","l":5,"s":"Enchantment","sa":"ENC","c":["Occultist"],"bk":"ll","p":260,"ct":"1 action","rg":"60 feet","cp":"V, S, M (something from each creature —such blood, hair, or scales—the spell is targeting, which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You cast a curse targeting two individuals. Both targets must make a Charisma saving throw (which they can choose to fail). If both targets fail their saving throws, their souls are swapped for the duration. A soul controls the body it inhabits. It uses the ability scores and actions of its new body (except legendary actions or legendary resistance), but retains its own spellcasting (if any), and has disadvantage on attack rolls and Strength, Dexterity, and Constitution saving throws for 1d4 turns after swapping bodies."],["p","At the end of a swapped creature's turn, it can choose to repeat the saving throw, ending the effect on a success. If its challenge rating (or character level if it has no challenge rating) is higher than that of its current body, it has advantage on the save."],["p","If a creature dies while its soul is swapped, both souls return to their original bodies. After a soul returns from a dying creature to a living body, it takes 5d10 necrotic damage."]],"con":1,"ms":["arcane"]},{"k":"sp-swordofthearchmage","n":"Sword of the Archmage","l":7,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":586,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a miniature platinum sword with a grip and pommel of copper and zinc, worth 250 gp)","d":"Concentration, up to 1 minute","b":[["p","You create a sword-shaped plane of force that hovers within range. It lasts for the duration."],["p","When the sword appears, you make two melee spell attacks against a target of your choice within 5 feet of the sword. On a hit the target takes 2d10 force damage plus half your level (accounting for the class you learned this spell through) rounded down."],["p","On subsequent turns until the spell ends, you can use a bonus action on each of your turns to move the sword up to 30 feet to a spot you can see and make two attacks with it as described above. You can trade one of those attacks to have it move up to an additional 30 feet and make its remaining attack with advantage."],["p","Each time you have the sword attack a target, it must use all its attacks on that target that turn."],["p","When a creature moves into a space within 5 feet of the sword or leaves such a space, you can use your reaction to make an opportunity attack as described above using the sword against that creature."]],"con":1,"leg":1,"g":["Ossenheimer’s Memoirs"]},{"k":"sp-synchraldisjunction","n":"Synchral Disjunction","l":9,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":587,"ct":"1 action","rg":"30 feet","cp":"V","d":"24 hours","b":[["p","One target within range that you choose is assailed with magical energy that reduces their magical items to their most basic components. The target must make a Charisma saving throw: if they fail, all magic items they are carrying or attuned to are rendered mundane and lose their magical properties for 24 hours, and all spells they are benefiting from or concentrating on end. If any of the items on their person is an artifact or of legendary rarity, they have advantage on the saving throw and may reattempt the Charisma saving throw at the start of each of their turns. On a success, those specific items regain their magical properties."],["p","This spell can be cast even within an antimagic field or similar magic-suppressing effect, but if it is then its target has advantage on their saving throw."]],"g":["Ossenheimer’s Memoirs"]},{"k":"sp-systemflush","n":"System Flush","l":1,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":587,"ct":"1 action","rg":"30 feet","cp":"M (a healer’s kit or item that restores hit points when used, which one use of is consumed)","d":"Instantaneous","b":[["p","Choose one creature within range who is suffering from the effects of being poisoned or diseased. One of those effects ends, including whatever other effects are causing that condition. The creature gains 1d8 temporary hit points, which they lose after 1 minute."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd-level or higher, you can choose one of the following effects for each slot level above 1st:"],["li","Choose one additional creature within range to target."],["li","One additional effect ends on the target(s)."],["li","The creature gains an additional 1d8 temporary hit points."]]},{"k":"sp-tamamosarrowfall","n":"Tamamo’s Arrowfall","l":4,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":587,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You conjure a series of bolts of energy which drift around you in a circular pattern. As a bonus action on each of your turns, you can command up to three clusters of these bolts to become a particular type of energy and fire them at a number of targets within 60 feet of you that you can see, each as an individual ranged spell attack. Multiple clusters can attack the same target in the same turn but remain as separate attacks. Each arrow cluster that hits deals 2d10 damage of its chosen energy type."],["p","When you take the action to fire the clusters you must choose one of the following damage types, which all of the bolts assume: fire, lightning, cold, acid, or thunder. You can change the damage type each time you fire the clusters."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can fire one additional cluster each turn for each slot level above 4th."]],"con":1,"g":["Skulker’s Grimoire"]},{"k":"sp-telepathicbond","n":"Telepathic Bond","l":5,"s":"Divination","sa":"DIV","c":[],"bk":"retia","p":587,"ct":"1 action","rg":"30 feet","cp":"V, S, M (pieces of eggshell from two different kinds of creatures)","d":"1 hour","b":[["p","You forge a telepathic link among up to eight willing creatures of your choice within range, psychically linking each creature to all the others for the duration."],["p","Creatures with Intelligence scores of 2 or less aren’t affected by this spell."],["p","Until the spell ends, the targets can communicate telepathically through the bond whether or not they have a common language. The communication is possible over any distance, though it can’t extend to other planes of existence."]],"rit":1,"leg":1},{"k":"sp-telepathiccord","n":"Telepathic Cord","l":8,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":587,"ct":"1 action","rg":"Unlimited","cp":"V, S, M (a pair of linked silver rings)","d":"24 hours","b":[["p","You create a telepathic link between yourself and a willing creature with which you are familiar. The creature can be anywhere on the same plane of existence as you. The spell ends if you or the target are no longer on the same plane."],["p","Until the spell ends, you and the target can instantaneously share words, images, sounds, and other sensory messages with one another through the link, and the target recognizes you as the creature it is communicating with. The spell enables a creature with an Intelligence score of at least 1 to understand the meaning of your words and take in the scope of any sensory messages you send to it."]],"leg":1},{"k":"sp-terrifyingvisions","n":"Terrifying Visions","l":1,"s":"Illusion","sa":"ILL","c":["Bard"],"bk":"cc","p":145,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You instil a vision of terrifying hallucinations into the mind of a target you can see. The target must make a Wisdom saving throw. On failure, it takes 3d6 psychic damage and must immediately use its reaction to move directly its movement speed directly away from you. This movement does not force the creature to move into hazardous terrain or to take movements that cause it to take damage (such as jumping off a cliff or moving into a spell effect). On a successful save, the target takes half as much damage and isn't forced to move."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st."]]},{"k":"sp-therpientisstunningmimicry","n":"Therpientis’ Stunning Mimicry","l":5,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":587,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You target one creature within the spell’s range who must make an Intelligence saving throw. On a failed save they briefly forget your exact appearance and characteristics, and begin hallucinating that they see dozens of other iterations of you spread around the area, all with slightly varying descriptions. For the spell’s duration, they have disadvantage on all attacks they make against you, and cannot willingly target you with ranged attacks, spells, or special effects that don’t require a melee attack."],["p","The first time on each turn you force them to make a saving throw or hit them with an attack then they may reattempt the Intelligence save, ending the effect on a success."]],"con":1},{"k":"sp-thoughtshard","n":"Thought Shard","l":0,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":588,"ct":"1 action","rg":"Self","cp":"S","d":"Up to 8 hours","b":[["p","Putting a finger to your head, you pull a memory, an idea, or a message from your mind and transform it into a tangible string of glowing energy called a thought shard, which persists for the duration or until you cast this spell again. The thought shard appears in an unoccupied space within 5 feet of you as a Tiny, weightless, semisolid object that can be held and carried like a ribbon. It is otherwise stationary."],["p","Alternatively, you can imbue the thought shard into a Small or Tiny object, where it remains for the duration."],["p","If you cast this spell while concentrating on a spell or an ability that allows you to read or manipulate the thoughts of others (such as detect thoughts or modify memory), you can transform the thoughts or memories you read, rather than your own, into a thought shard."],["p","Casting this spell while holding a thought shard allows you to instantly receive whatever memory, idea, or message the thought strand contains (casting detect thoughts on the strand has the same effect). Alternatively, a creature who knows it is a thought shard while in contact with it can attempt an Arcana check (DC equal to your spell save DC), and on a success may read the shard’s contents."]],"leg":1},{"k":"sp-throesofmortality","n":"Throes of Mortality","l":3,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":588,"ct":"1 action","rg":"60 feet","cp":"V, S, M (glass rings strung together on an iron chain, each ring worth at least 50 gp. A ring is consumed by the spell for every target affected)","d":"1 hour","b":[["p","Choose up to five creatures you can see within range: each of those creatures must make a Charisma saving throw. A twisting ring of glyphs appear around the necks and foreheads of any creature who fails, causing them intense pain for the spell’s duration - during this time they are cursed. While cursed by these glyphs, any healing those creatures receive is reduced to half (rounded down), and if they have immunities or resistances to any chromatic energy types, they become resistances or are ignored respectively for the spell’s duration. Creatures who begin their turn under this spell’s effects take 1d6 psychic damage."],["p","If the creature that cast this spell is reduced to 0 hit points or is knocked unconscious this spell immediately ends. Additionally, if a creature cursed by this spell is reduced to 0 hit points they immediately fail one death saving throw, then the spell effects end for them."]],"h":[["p","At Higher Levels. When this spell is cast at 4th level or higher, it gains one of the following effects for each slot level above 3rd:"],["li","The spell’s range doubles."],["li","The spell can target one additional creature."],["li","(2 slot levels) The spell’s psychic damage increases by 1d6."]],"g":["Chromatic Convocation"]},{"k":"sp-throwimage","n":"Throw Image","l":2,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":588,"ct":"Special","rg":"120 feet","cp":"Special","d":"Special","b":[["p","When you cast another spell, you can choose to also cast this spell on top of it. When you do, a projection of you appears within this spell’s range in an unoccupied space you can see, and can act as the caster of the spell in regards to the spell’s range and effects. If the spell would normally affect the area around you, it centers on that projection. If it has a range, that range treats the projection as if it were originating from it. Your senses do not project into it, and so if it requires line of sight or to see spaces you target, you must be able to see them."],["p","At the start of your next turn the projection vanishes, and the spell switches back to considering you the caster or center of its effects again. If it cannot continue due to your new proximity to its effects, they end."],["p","If you are unable to perform somatic components but are conscious, you may use this spell to have your projection perform the verbal and/or somatic components of the spell in your place."]],"g":["Epic of Duality"]},{"k":"sp-thundernote","n":"Thunder Note","l":0,"s":"Evocation","sa":"EVO","c":["Bard"],"bk":"ll","p":261,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Instantaneous","b":[["p","You emit a crashing bang at the location of a creature you can see within range. The target must succeed on a Constitution saving throw or take 1d8 thunder damage and become deafened until the start of its next turn. If this damage forces it to make a Constitution saving throw to maintain concentration on a spell, it makes that save at disadvantage."],["p","This spell’s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."]],"ms":["arcane"],"also":[["cc",146]]},{"k":"sp-thunderpulse","n":"Thunder Pulse","l":3,"s":"Evocation","sa":"EVO","c":["Bard","Sorcerer","Wizard"],"bk":"ll","p":260,"ct":"1 action","rg":"Self (15-foot cone)","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You gather sonic energy and expel it as a shock wave in a 15-foot cone. Each creature in the area must make a Constitution saving throw. On a failure, a creature takes 3d8 thunder damage and is knocked 10 feet back. On a success, it takes half as much damage and it not knocked back."],["p","On your subsequent turns for the duration, you can use your action to create a new shock wave."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 3rd."]],"con":1,"ms":["arcane"],"also":[["cc",146]]},{"k":"sp-thunderpunch","n":"Thunder Punch","l":1,"s":"Evocation","sa":"EVO","c":["Bard","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":261,"ct":"1 action","rg":"Touch","cp":"V, S","d":"Instantaneous","b":[["p","You charge your hand (or similar appendage) with thunderous power. Make a melee spell attack against a creature within 5 feet. On a hit, the target takes 3d8 thunder damage and is knocked 10 feet back. A mighty boom rings out, which is audible from up to 300 feet away."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."]],"ms":["arcane"],"also":[["cc",146]]},{"k":"sp-thunderspiral","n":"Thunder Spiral","l":4,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":588,"ct":"1 action","rg":"Self (60-foot cone)","cp":"V, S, M (a handheld mirror that is cracked)","d":"Isntantaneous","b":[["p","A wave of thunderous sound erupts from your hands, echoing forward in a 60-foot cone. Each creature within range must make a Constitution saving throw. On a failed save a creature takes 6d10 thunder damage, or half as much on a successful one. A creature that fails this save is knocked prone."]],"h":[["p","At Higher Levels. When you cast this spell at 5th level or higher, the damage increases by 1d8 for each slot level above 4th."]]},{"k":"sp-thunderburstmine","n":"Thunderburst Mine","l":2,"s":"Abjuration","sa":"ABJ","c":["Inventor"],"bk":"ll","p":260,"ct":"1 minute","rg":"Touch","cp":"V, S, M (a tiny nonmagical item, which is destroyed when the spell ends)","d":"8 hours","b":[["p","You set a magical trap, infusing thunderous magic into an object. You can set the item to detonate when someone comes within 5 feet of it, or at a verbal command by you. You can issue this command as an action or as a reaction when you see a creature move within 20 feet of a mine, detonating every mine keyed to the verbal command simultaneously."],["p","When the magic trap detonates, each creature in a 10-foot-radius sphere centered on the item must make a Constitution saving throw. A creature takes 3d8 thunder damage on a fail, or half as much damage on a success. If a creature is in the area of effect of more than one thunderburst mine during a turn, it takes half damage from any mines beyond the first."],["p","A magical mine must be set at least 5 feet away from every other mine, and cannot be moved once placed; any attempt to move it results in it detonating. The caster can permanently disarm a mine as an action."]],"ms":["arcane"],"also":[["cc",146]]},{"k":"sp-thunderousleap","n":"Thunderous Leap","l":3,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":588,"ct":"1 action","rg":"90 feet","cp":"V","d":"Instantaneous","b":[["p","You teleport yourself to an unoccupied space you can see within range. Immediately after you disappear, a thunderous boom sounds, and each creature within 10 feet of the space you left must make a Constitution saving throw, taking 3d10 thunder damage on a failed save, or half as much damage on a successful one. The thunder can be heard from up to 300 feet away."],["p","You can bring along objects as long as their weight doesn’t exceed what you can carry. You can also teleport one willing creature of your size or smaller who is carrying gear up to their carrying capacity. The creature must be within 5 feet of you when you cast this spell, and there must be an unoccupied space within 5 feet of your destination space for the creature to appear in. Otherwise, the creature is left behind."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can choose one of the following effects 58 8 for each slot level above 3rd:"],["li","The damage increases by 1d10."],["li","The spell’s range increases by 40 feet."],["li","The range within which a creature can be selected to come with you, the range they can be deposited, and the range within which creatures may take damage all increase by 5 feet."]],"leg":1},{"k":"sp-timeanchor","n":"Time Anchor","l":8,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Wizard"],"bk":"ll","p":261,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a shattered hourglass)","d":"1 year","b":[["p","You place a temporal marker on an object. For the duration, you can activate that marker, bringing the object to your hand and calling it forward in time from the moment you cast the spell. When you do so, the current timeline is unaltered, except that the object disappears from its present location."],["p","The object appears in the its exact state from the time the spell was cast, including its condition, charges, and other properties. The object appears even if it has been consumed or destroyed in the intervening time."],["p","You can only have one object anchored to you at a time. Once this spell has been cast on an object, it can never be cast on the same object again."]],"ms":["arcane"]},{"k":"sp-timebubble","n":"Time Bubble","l":8,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Wizard"],"bk":"ll","p":261,"ct":"1 action","rg":"60 feet","cp":"V, S, M (something from the past or future)","d":"Special","b":[["p","You create a bubble of accelerated time in a 20-foot radius around a point you can see within range. When you cast the spell, initiative (including your current turn) is interrupted, and all creatures within the bubble can take an additional turn immediately (following the initiative order). Nothing inside the bubble can reach outside it or affect creatures outside. Any attacks passing through the bubble miss and any spells passing through it fail. If a creature exits the bubble, its additional turn immediately ends."],["p","If any creature is only partly within the bubble when you cast the spell, the spell fails."],["p","After every creature inside the bubble has acted, the spell ends and you resume your turn, with initiative proceeding as normal."]],"h":[["p","At Higher Levels. When you cast this spell with a 9th-level spell slot, the creatures inside the bubble take two rounds of turns before the spell ends."]],"ms":["arcane"]},{"k":"sp-timeloop","n":"Time Loop","l":4,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Wizard"],"bk":"ll","p":262,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a detailed list of the actions and movement that the target creature took on its last turn, which the spell consumes)","d":"1 round","b":[["p","You force a creature within range to repeat its last turn. The target must succeed on a Wisdom saving throw or have its personal timeline adjusted so that it repeats its last action in a preordained loop on its next turn. As the rest of the world may have changed, it attempts to repeat its last action to the best of its ability, including moving the same distance in the same direction, attacking the same target, or taking the same action."],["p","If the target's attempts to repeat its turn conflict, the caster decides which part of the turn takes precedence. While a creature is compelled to repeat its turn, it cannot be compelled to move into obviously dangerous ground, such as a fire or a pit."],["p","Note Taking"],["p","Unlike most material components, for convenience sake,"],["p","this spell’s material components is required by the player"],["p","in addition to their character (whose detailed list does"],["p","not need to by a physical object, simply the knowledge of"],["p","their target’s actions), and consequently requires some"],["p","preparation and attention to detail on the player’s part to"],["p","avoid making the DM having to keep track of such details."]],"ms":["arcane"]},{"k":"sp-timeskip","n":"Time Skip","l":2,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":262,"ct":"1 action","rg":"Touch","cp":"V, S, M (a small symbol made up of two connected triangles)","d":"1 round","b":[["p","You touch a willing creature, sending it six seconds into the future. The target vanishes, reappearing at the same location (or the nearest unoccupied space) at the start of its next turn."]],"h":[["p","At Higher Levels. When you cast this spell with a spell slot of 3rd level or higher, the duration increases by 1 additional round for each slot level above 2nd. If you cast this spell with a 9th-level spell slot, the duration increases to 24 hours."]],"ms":["arcane"]},{"k":"sp-timeslip","n":"Time Slip","l":2,"s":"Transmutation","sa":"TRA","c":["Sorcerer","Wizard"],"bk":"ll","p":262,"ct":"1 action","rg":"Self","cp":"V, S, M (an small ornate hourglass worth at least 25 gold pieces)","d":"Concentration, up to 1 minute","b":[["p","You surround yourself with a film of distorted time, setting yourself slightly off from time's normal flow. While you are in this bubble of distorted time, you have a +2 bonus to AC. If you would take damage from an attack or fail a saving throw against a spell of 2nd level or lower, you can use your reaction to revert your personal timeline and negate the effect — causing the attack to miss or the save to succeed. Afterward, this spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the maximum level of a spell you can negate increases to be equal to the level of the spell slot used."]],"con":1,"ms":["arcane"]},{"k":"sp-timetrap","n":"Time Trap","l":2,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":262,"ct":"1 action","rg":"60 feet","cp":"V, S, M (handful of sand from an hourglass)","d":"1 hour","b":[["p","You disrupt time in an empty 5-foot cube you can see within range. The first time a creature enters the area, it must make a Wisdom saving throw. On a failure, a creature that is completely inside the cube is stunned, while a creature that is only partly within the cube (e.g. a Large or larger creature) is restrained, as part of its body becomes frozen in time. On a success, the creature’s speed is halved instead. Any affected creature recovers at the start of its next turn. The trap can only be sprung once, and the spell ends at the start of the trapped creature’s next turn."],["p","The trapped area is subtly distorted, and any creature that can’t see the area at the time the spell is cast must make a Wisdom (Perception) check against your spell save DC to detect the trap."]],"ms":["arcane"]},{"k":"sp-tormentedscream","n":"Tormented Scream","l":9,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":589,"ct":"1 action","rg":"90 feet","cp":"S","d":"Instantaneous","b":[["p","You unleash the power of your mind to blast the intellect of up to ten creatures of your choice that you can see within range. Creatures that have an Intelligence score of 2 or lower are unaffected."],["p","Each target must make an Intelligence saving throw. On a failed save, a target takes 14d6 psychic damage and is stunned. On a successful save, a target takes half as much damage and isn’t stunned. If a target is killed by this damage, its head explodes (assuming it has one)."],["p","A stunned target can make an Intelligence saving throw at the end of each of its turns. On a successful save, the stunning effect ends."],["p","You may focus this effect on a single creature you can touch, making them the only target. The full force of the spell is poured into their mind alone, and if they fail their saving throw they take 20d6 psychic damage instead. The effects are otherwise as above."]],"leg":1},{"k":"sp-tornado","n":"Tornado","l":5,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":263,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","A whirling tornado erupts, filling a 20-foot-radius, 40-foot-high cylinder centered on a point you can see within range."],["p","Any creature starting its turn within the tornado must make a Strength saving throw. On a failure, it takes 4d8 bludgeoning damage and is thrown 10 feet in a random horizontal direction and 40 feet up (taking normal falling damage when it comes back down). On a success, the creature takes half as much damage and isn’t thrown."],["p","As a bonus action, you can move the tornado up to 30 feet in any direction. All ranged attacks passing through the tornado automatically miss, and ranged weapon attacks against targets within 20 feet of the tornado are made at disadvantage."]],"con":1,"ms":["arcane","primal"],"also":[["cc",146]]},{"k":"sp-tranquilmoment","n":"Tranquil Moment","l":1,"s":"Transmutation","sa":"TRA","c":["Occultist","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":263,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"Instantaneous","b":[["p","You slow your personal perception of time, giving you a moment to think. As part of the bonus action used to cast the spell, you can make a Wisdom or Intelligence ability check that would normally require an action (such as the Search action). If that action would be at disadvantage due to time or pressure, you do not have disadvantage on the check."]],"ms":["arcane"]},{"k":"sp-transfervice","n":"Transfer Vice","l":1,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":589,"ct":"1 reaction to a creature being killed","rg":"120 feet","cp":"V, S, M (a wicker figurine)","d":"Instantaneous","b":[["p","When one creature within range is killed or reduced to 0 hit points while suffering from a detrimental effect (such as being poisoned, suffering from ongoing damage from a spell, etc.,) you may choose one other creature within range to try to transfer those effects to. The new target must make a Charisma saving throw. On a failure, all of the detrimental effects you choose from the first target are moved to the second, including their remaining durations. Effects with an indefinite duration that can last longer than 1 hour cannot be transferred this way, nor can effects that are unable to target the new creature."]],"h":[["p","At Higher Levels. If you cast this spell using a spell slot of 3rd level or higher, the effects are copied instead of transferred, and both creatures still suffer from them. If any require concentration from another creature or can only target one creature at a time, you must choose which is targeted."]],"g":["Daemoturgy"]},{"k":"sp-translocatingshot","n":"Translocating Shot","l":4,"s":"Conjuration","sa":"CON","c":["Inventor","Ranger","Wizard"],"bk":"cc","p":146,"ct":"1 bonus action","rg":"5 feet","cp":"V, S, M (a piece of ammunition worth at least 1 cp)","d":"Concentration, up to 1 minute","b":[["p","You magically bind a willing creature within range into a piece of ammunition. When the piece of ammunition is fired, the creature bound to the piece of ammunition is teleported to the target destination. You can fire the ammunition at a creature, object, or point within the normal range of the weapon. When attacking a creature or object, the target is teleported to within 5 feet of the target hit or miss."],["p","When you cast this spell, if you cast it a Large or larger piece of ammunition, you can bind up to 4 creatures to the piece of ammunition."]],"h":[["p","At Higher Levels. When you using 6th-level slot or higher, you can cast it on a Huge piece of ammunition, binding up to nine creatures to the piece of ammunition."]],"con":1},{"k":"sp-trarysterrifictransposition","n":"Trary’s Terrific Transposition","l":3,"s":"Conjuration","sa":"CON","c":["Inventor","Occultist","Wizard"],"bk":"cc","p":147,"ct":"10 minutes","rg":"Self (10-foot-radius hemisphere)","cp":"V, S, M (an ornate brass key worth at least 100 gp, and a satchel or bag worth at least 1 sp)","d":"Instantaneous","b":[["p","You weave an enchantment that conjures compresses all objects of your choice within range into a the satchel or bag used in casting the spell. The contents become harmlessly compressed and stored in an magical state of miniaturized suspension within the container. The weight of miniaturized stored items is the weight of the item divided by one hundred. The bag can store all items that fit in the radius when the spell is cast, but can’t store any individual item larger than Medium. Items can’t be individually removed from the bag, but the process can be reversed by casting the spell again, at which point all items are deposited from the bag in the arrangement they were before being stored."],["p","If the bag is destroyed or placed into an interdimensional space, the contents of the bag are instantly emptied onto the ground in a chaotic manner, each item taking 4d4 force damage, but dealing no damage to anything else. If the bag is broken, the key used as a material in casting the spell breaks."]],"rit":1},{"k":"sp-treatieshellgate","n":"Treaties’ Hellgate","l":9,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":589,"ct":"1 action","rg":"120-foot radius sphere","cp":"V, S, M (an item forged in the fourth circle of hell)","d":"Concentration, up to 10 minutes","b":[["p","You are immune to any effect produced by this spell that requires a saving throw or ability check."],["p","The area within the spell’s range, centered on you, is briefly exposed to the conditions of the fourth circle of hell. Each creature within that space that is not immune to fire damage must make a Constitution saving throw when you cast this spell, suffering from one level of exhaustion and 5d10 fire damage on a failure. Following this, the spell has the following effects: Burning Air For the spell’s duration, each time a creature starts their turn within this area they must make another Constitution saving throw, taking 3d10 fire damage and suffering one point of Combat Fatigue on a failed save - this damage increases to 5d10 if they start their turn within 10 feet of you. If they fail by 10 points or more they suffer a level of exhaustion instead of Combat Fatigue."],["p","Domain Expansion At the end of each of your turns the effects of this spell's effects and range spread out another 60 feet in every direction. Hellfire Aura While the spell is in effect, your weapon attacks deal an additional 2d12 fire damage, and fire damage you deal cannot be reduced by resistances or spell effects. You deal this extra damage even if you leave the spell’s range."],["p","Instant Evaporation Within the spell’s range, all cold damage dealt is reduced to 0, and all liquids (including frozen ones) exposed to open air evaporate instantly with no effect. When a creature attempts to drink a potion or apply an ointment or salve they must succeed a Dexterity check against your spell save DC, and on a failure they apply it too slowly and it burns up without taking effect. Nature Killer Plants and oozes have disadvantage on all saving throws made against this spell’s effects. All nonmagical fauna and flora with fewer than 30 hit points within range immediately die when this spell is cast (or you may choose that they fail a saving throw against it instead). Spell effects that produce wood or plants (such as entangle) immediately end within its range unless they are produced by a 6th level or higher spell slot. Final Burden When this spell ends, you can use your reaction to gather its energies into a single burst of demonic power, centered on one target within the spell’s range. That creature must succeed a Dexterity saving throw, taking 10d8 fire damage and 10d8 poison damage on a failed save, or half as much on a successful one. You may also choose to end the spell early to use this effect as a bonus action. If you are reduced to 0 hit points but not killed outright you can use this effect before falling unconscious."]],"con":1,"g":["Daemoturgy","Eidomancy"]},{"k":"sp-trudgingcircle","n":"Trudging Circle","l":4,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":590,"ct":"1 action","rg":"Self","cp":"V, S, M (a hand-held time piece)","d":"Concentration, up to 1 minute","b":[["p","You create a field of magical energy that soaks up effects that increase the movement speed of creatures within it. This field is a 50-foot radius sphere centered on you, that moves with you. Any creature within it (including you) who attempt to take the Dash action must succeed on a Charisma saving throw, otherwise they do not gain extra movement by taking it. All effects that increase the base movement speed of creatures fail and have no effect when within this radius."]],"h":[["p","At Higher Levels. When you cast this spell using a 7th level or higher spell slot, you may pick and choose who is affected by this field as you wish. If cast at 9th level, the movement speed of all creatures within it (except those you exclude) is reduced to 10 feet and no creature can take the Dash action."]],"con":1,"g":["Daemoturgy"]},{"k":"sp-truestrike","n":"True Strike","l":0,"s":"Divination","sa":"DIV","c":[],"bk":"retia","p":590,"ct":"1 bonus action","rg":"30 feet","cp":"S","d":"Concentration, up to 1 minute","b":[["p","You extend your hand and point at a target in range, who must make a Charisma saving throw. On a failure, you recognize an opening that you can exploit, and choose one more creature within range (which can include you). Until the second creature hits the primary target, they gain advantage on attack rolls against them, after which the spell ends."],["p","Cantrip Upgrade. As you level, you can choose additional secondary creatures to benefit from this spell, and the spell ends for them all when any of them hit. You can choose two secondary creatures at 5th level, three at 11th, and four at 17th."]],"con":1,"leg":1},{"k":"sp-tunnelknot","n":"Tunnel Knot","l":5,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":590,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a feather pen with a diamond tip, worth at least 1000 gp)","d":"Concentration, up to 1 round","b":[["p","A 1-foot-thick section of wall closes in on a passage made of nonmagical, unliving materials; it emerges from the walls on either side and forms a new wall. Every corner of the wall you create must be within the spell’s range. This new wall takes 1 round to form, finishing the process at the start of your next turn. If your concentration is broken during this time, the effect fails to take hold. Any creatures in the wall’s space when it finishes forming are shunted to one side or another, but if they are larger than the wall then the spell fails and the wall does not form around them."],["p","Once the wall is created it has the durability of the material it is made out of, is resistant to all damage except by siege weapons, and has AC equal to your spell save DC (unless it was higher already). The entire wall section has 5d10 hit points, and when reduced to 0 hit points the wall entirely collapses. If the wall is made of a brittle or unstable material (like snow, ice, dirt, etc.,) it has half as many hit points and no resistance to damage."],["p","The wall this spell can create can be up to 10 feet wide and 10 feet high, filling the passage it is created in. After 1 hour the wall will crumble on its own, and you cannot create a second wall using this spell within 30 feet of another without the material of the first being pulled to make the second."]],"h":[["p","At Higher Levels. When you cast this spell at 6th level or higher, the maximum horizontal and vertical dimensions of the wall can be doubled for every slot level above 5th if the space can accommodate it, with its thickness doubling for every two slot levels above 5th, and the wall gains 5d10 additional hit points. When cast at 9th level, the wall appears instantly and does not require a full round to form."]],"con":1},{"k":"sp-turbulentwarp","n":"Turbulent Warp","l":3,"s":"Psionic","sa":"PSI","c":["Psion"],"bk":"cc","p":147,"ct":"1 action","rg":"90 feet","cp":"S","d":"Instantaneous","b":[["p","You teleport yourself to an unoccupied space you can see within range, leaving behind a spatial distortion. Each creature within 10 feet of the space you left must make a Charisma saving throw. On a failure, they take 5d4 force damage and are teleported to an empty space of your choice within 5 feet of where they were. On success they take half as much damage and are not teleported."],["p","You can also teleport one willing creature of your size or smaller who is carrying gear up to its carrying capacity. The creature must be within 5 feet of you when you cast this spell, and there must be an unoccupied space within 5 feet of your destination space for the creature to appear in; otherwise, the creature is left behind."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 2d4 for each slot level above 3rd."]],"ci":1},{"k":"sp-turningsurge","n":"Turning Surge","l":4,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":590,"ct":"1 bonus action","rg":"Self","cp":"V, S, M (a skull fragment from a unicorn and a skull fragment from a nightmare)","d":"Concentration, up to 1 minute","b":[["p","An undulating aura of fiendish energy coats your body for the spell’s duration. While bathed in this aura you cannot benefit from positive effects of any other spell or magical effect that targets you, including bonus to your armor class, attack rolls, saving throws, effects that grant hit points or temporary hit points, extra actions of any kind, or benefits to your movement speed. You still gain the benefits of nonmagical traits and effects."],["p","Furthermore, while bathed in this aura you may take a second Attack or Multiattack action on each of your turns. If you have another feature that would grant a similar benefit - such as Action Surge - you cannot use it on the same turn you take this spell’s additional action. Your attacks cannot have advantage or disadvantage while under this spell’s effects."],["p","Each time you take this spell’s additional Attack or Multiattack action, you suffer a point of Combat Fatigue."]],"rv":1,"con":1,"g":["Chromatic Convocation","Eidomancy"]},{"k":"sp-twintalent","n":"Twin Talent","l":3,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":590,"ct":"1 action","rg":"Self (30 feet) or touch","cp":"V, S","d":"Concentration, up to 1 hour","b":[["p","You create an illusory clone of yourself or a willing Medium-sized creature you can touch. The clone appears within 30 feet of you, and you can immediately order it to perform any action the original could perform that requires an ability check or skill check, using the modifier the original would use, such as attempting to pick a lock, grapple a creature, or clean a space. When it moves it provokes the same physical reactions you would. The clone has an armor class equal to your spell save DC, the same saving throws as the original, and if it takes any damage it vanishes. Once commanded to perform an action it continues to act, taking an action and moving up to 30 feet at the end of each of your turns (including on the first) to do so. If it fails to meet the DC of a check associated with the activity you assigned to it two turns in a row, it vanishes."]],"h":[["p","At Higher Levels. When you cast this spell using a 4th level or higher spell slot, you create one additional illusory clone for each slot level above 3rd, and you can give a different task to each (or command any given clone to use the Help action to aid another)."]],"con":1,"g":["Epic of Duality"]},{"k":"sp-twistingeruption","n":"Twisting Eruption","l":7,"s":"Conjuration","sa":"CON","c":["Occultist"],"bk":"ll","p":263,"ct":"1 action","rg":"120 feet","cp":"V, S, M (a handful of dead plants)","d":"Concentration, up to 1 minute","b":[["p","You gesture at a point you can see within range and call forth gnarled roots of dark energy, which erupt from the ground in a 60-foot radius. Each creature of your choice in the area must succeed on a Dexterity saving throw or be restrained as the shadowy plant tendrils grasp and drain the life from it."],["p","At the start of a restrained creature’s turn, it takes 2d10 bludgeoning damage and 2d10 necrotic damage. Each time a creature takes necrotic damage from this spell, you regain 1d4 hit points."],["p","A restrained creature can use its action to make a Strength (Athletics) or Dexterity (Acrobatics) check (its choice) against your spell save DC. On a success, it frees itself. A creature can also be freed by destroying the tendril that grips it. The tendrils have AC 10 and 20 hit points, and are immune to all damage except radiant and fire. Spells that deal radiant or fire damage to creatures in the area of effect also affect any tendrils gripping them."],["p","Any creature ending its turn within the radius while not restrained must make a Dexterity saving throw or become restrained by the tendrils."]],"con":1,"ms":["arcane"]},{"k":"sp-unburden","n":"Unburden","l":1,"s":"Transmutation","sa":"TRA","c":["Inventor"],"bk":"ll","p":263,"ct":"1 action","rg":"Touch","cp":"V, S","d":"1 hour","b":[["p","You touch a creature and relieve the weight it carries. The target can ignore penalties to movement speed or to Dexterity (Stealth) checks due to wearing medium or heavy armor, and can carry twice as much weight as normal before suffering encumbrance penalties."]],"ms":["arcane"],"also":[["cc",147]]},{"k":"sp-unholywave","n":"Unholy Wave","l":2,"s":"Necromancy","sa":"NEC","c":["Cleric","Paladin"],"bk":"ll","p":264,"ct":"1 action","rg":"Self (30-foot cone)","cp":"V, S","d":"Concentration, up to 1 minute.","b":[["p","A wave of necrotic energy pours out from your outstretched hand in a 30-foot cone. Each creature in the area must make a Constitution saving throw as it is burned by unholy fire. On a failure, it takes 4d6 necrotic damage and becomes wreathed in black fire for the duration. Once per turn when it is hit by an attack, its wounds flare and it takes an additional 1d6 necrotic damage. On a successful save, the target takes half as much damage and is not enveloped in black fire."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd."]],"con":1,"ms":["divine"]},{"k":"sp-unlockedpotential","n":"Unlocked Potential","l":1,"s":"Psionic","sa":"PSI","c":["Psion"],"bk":"cc","p":147,"ct":"1 action","rg":"60 feet","cp":"S","d":"Concentration, up to 1 minute","b":[["p","You unlock the potential of a creature’s mind, allowing it to fully reach its limits. For the duration, once per turn the creature can add 1d4 to any attack roll, damage roll, or saving throw it makes. Each time it adds the extra 1d4, it takes 1 psychic damage as it pushes beyond its natural limitations."]],"con":1,"ci":1},{"k":"sp-unlore","n":"Unlore","l":9,"s":"Divination","sa":"DIV","c":[],"bk":"retia","p":591,"ct":"1 hour","rg":"Touch","cp":"V, S, M (incense worth at least 1000 gp, which the spell consumes, and a tome with at least 1000 pages with a metallic lock binding it)","d":"Permanent","b":[["p","Choose one creature, object, or place you are in contact with. If a place, it can be of a size of up to 1 square mile, but the location must have a unified name or theme (such as a guide hall, castle, hoard, etc.,) that your GM determines qualifies as a subject that a spell like legend lore may target. You spend the spell’s casting time stripping that target of its historic identity. If it is a creature, they make a Charisma saving throw every 10 minutes during the casting time, and if they succeed three times the spell fails."],["p","Once the spell is complete, the tome used in the casting of the spell is filled with all knowledge possible about the target, and which updates in the future as developments occur. Whomever is in possession of this book may lay their hand on it and think of any information they wish to find to become psychically aware of the answer."],["p","As long as this tome exists, all records taken about this target will vanish after 1 hour; writers and historians researching it find themselves casually losing interest in the subject. All attempts to divine their past or future will fail automatically, revealing that there is nothing and never will be anything to know about them. Creatures that have second-hand knowledge of the subject are fuzzy on details about it, but those with first-hand accounts are unaffected and remember their own experiences clearly. Creatures who use spells to try to identify the target or divine information about it make a Wisdom saving throw in place of their results, and on a success become aware that a spell is obscuring the truth of the matter."],["p","If the tome’s lock is ever undone, the spell ends and the target’s lore is restored. The tome is immune to effects that negate or dispel magic, and will simply not relay information to others while within those effects, but resume function once removed. Breaking or picking the lock requires a DC 30 Strength or Dexterity (Thieves Tools) check, and any attempt to destroy it treats it has having AC equal to your spell save DC, resistant to all damage, is unaffected by spells requiring saving throws, and has 50 hit points that are restored every hour."]],"g":["Sky-Keeper’s Arcana"]},{"k":"sp-unsealedbravery","n":"Unsealed Bravery","l":4,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":591,"ct":"1 bonus action","rg":"Self","cp":"S","d":"Concentration, up to 1 minute","b":[["p","When you cast this spell, any light, medium, or heavy armor or shields you are wearing are magically cast from your body in a burst of red and gold light. If an item is magical or has an enhancement bonus it is merely discarded, but if your armor is nonmagical it is destroyed instead. For the spell’s duration the air around you glows with a crackling golden aura, and you gain the following benefits:"],["li","Your armor class is calculated as 10 + your Dexterity modifier + your spellcasting ability modifier, or as equal to your spell save DC (whichever is higher)."],["li","You are resistant to one of piercing, slashing, or bludgeoning damage (your choice when casting the spell)."],["li","You have advantage on Concentration checks, as well as saving throws made to resist being frightened or charmed."],["li","Once per turn, you can negate any disadvantage you have on a melee weapon attack, and/or gain advantage on it instead."],["p","If you don any type of armor or shield or calculate your armor class using another method during the spell’s duration, the spell ends immediately."]],"h":[["p","At Higher Levels. If you cast this spell at 5th level or higher, you can choose one of the following options for each slot level above 4th:"],["li","You gain resistance to one additional damage type, choosing from piercing, slashing or bludgeoning."],["li","You gain immunity to one of the damage types this spell gives you resistance to, but only from nonmagical attacks."],["li","The duration of the spell increases to 10 minutes (1 slot level), 1 hour (2 slot levels), 8 hours (3 slot levels), 24 hours (4 slot levels), or 1 week (5 slot levels). During the period of this effect you do not require sleep."]],"con":1,"g":["Legacy of Gold"]},{"k":"sp-unstableexplosion","n":"Unstable Explosion","l":2,"s":"Evocation","sa":"EVO","c":["Sorcerer","Warlock","Wizard"],"bk":"ll","p":264,"ct":"1 action","rg":"60 ft (10-ft radius)","cp":"V, S","d":"Instantaneous","b":[["p","You cause an unstable explosion to erupt at a point of your choice within range. Roll 3d6. For each die that rolls a 6, the spell's radius expands by 5 feet, and you can roll an additional d6. Each creature within the final area of the spell must make a Dexterity saving throw. On a failure, a creature takes fire damage equal to the total value of the rolled dice. On a success, it takes half as much damage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, roll another d6 for each slot level above 2nd."]],"ms":["arcane"],"also":[["cc",147]]},{"k":"sp-unveilinggaze","n":"Unveiling Gaze","l":3,"s":"Divination","sa":"DIV","c":[],"bk":"retia","p":592,"ct":"1 action","rg":"Self (30 feet)","cp":"V","d":"Concentration, up to 10 minutes","b":[["p","Your eyes become discerning. For the spell’s duration, you are aware if a creature is not assuming its true form when you look at them and they are within the spell’s range (such as if they have polymorphed, shape changed, or used another feature to change their form), though you do not learn what their true form is."],["p","At any time during this spell’s effects, if you see a creature that is not assuming its true form you can use your bonus action to force it to make a Charisma saving throw. On a failure, this spell ends and the target is compelled to use their reaction to return to their true form, unless something is preventing them from doing so (such as a curse, or if the transformation was induced by a wish spell). If they succeed they are not compelled, and become aware that something attempted to force them to change their form."]],"con":1,"g":["Nine Branch Arts"]},{"k":"sp-unweave","n":"Unweave","l":7,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":592,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a bound ball of dried thorns)","d":"10 minutes","b":[["p","You create a 20-foot radius sphere of fiendish influence centered on a point within range, causing a corrupted replication of the eidomantic web to attempt to overtake the web within that space. This field can be seen to any creature with truesight or who is able to see magical aura. This field remains in place for the duration of the spell, and any time a creature attempts to cast a non-demonology spell within that sphere or targeting anything within it, they must make a Charisma saving throw, expending the spell slot to no effect on a failure. Spells that fail this way do not consume their materials. If the spell being cast was gained through the paladin, cleric, or petal knight spell list, they have disadvantage on their save against this effect."],["p","If this spell is cast in the same spot once every 24 hours for 1 month, the effect becomes permanent unless dispelled."]],"h":[["p","At Higher Levels. When you cast this spell with a higher level spell slot, its duration increases to 1 hour at 8th level and 1 day at 9th level."]],"g":["Daemoturgy"]},{"k":"sp-vacuumpull","n":"Vacuum Pull","l":2,"s":"Evocation","sa":"EVO","c":["Druid","Ranger","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":264,"ct":"1 bonus action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","You create a howling blast of wind, attempting to pull a Huge or smaller creature that you can see within range toward you. The target must succeed a Strength saving throw or be yanked off its feet and pulled to you, landing within 5 feet of you and falling prone. Flying creatures make this save at disadvantage."]],"h":[["p","At Higher Levels. When you cast this spell using a spell lot of 3rd level or higher, the range of the spell increases by 10 feet."]],"ms":["arcane"]},{"k":"sp-valkyriestrike","n":"Valkyrie Strike","l":1,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":592,"ct":"1 bonus action","rg":"Self","cp":"V","d":"Concentration, up to 1 minute","b":[["p","You move like the wind. Until the spell ends, your movement doesn’t provoke opportunity attacks."],["p","Once before the spell ends, you can give yourself advantage on one weapon attack roll on your turn. That attack deals an extra 1d8 force damage on a hit. Whether you hit or miss, your walking speed increases by 30 feet until the end of that turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can choose one of the following effects for each slot level above 1st:"],["li","The damage increases by 1d8."],["li","The bonus to your walking speed increases by 10 feet."],["li","(2 slot levels) The extra damage applies to one additional hit, which must be taken on the same turn as the first."]],"con":1,"leg":1},{"k":"sp-valkyriesbindingrings","n":"Valkyrie’s Binding Rings","l":3,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":592,"ct":"1 bonus action","rg":"Self","cp":"V, M (two silver or gold rings large enough to fit around your wrists, worth at least 300 gp each)","d":"Concentration, up to 10 minutes","b":[["p","The rings used as this spell’s components create large loops of radiant energy dotted with Celestial writing. Once when you cast this spell, and then as a bonus action on subsequent turns, you can target one creature within 60 feet to cast these rings at in an attempt to bind the target in place. The target must succeed on a Dexterity saving throw or be restrained until the start of your next turn."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature within range when you use this spell’s effect for each slot level above 3rd."]],"con":1},{"k":"sp-valkyrieswrath","n":"Valkyrie’s Wrath","l":4,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":592,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a spear, javelin, shortspear, great arrow, or similar weapon which can be thrown at a target, which is then destroyed if it is not magical)","d":"Instantaneous","b":[["p","The material component for this spell becomes an arc of light, which you use to make a ranged spell attack against a creature within range, hurling it toward them. If it hits, instead of dealing the weapon’s regular damage or effects, the target is hoisted off the ground and pelted by dozens of beams of radiant power dealing 8d8 radiant damage, and if the creature is no more than two size categories larger than you they are knocked prone."]],"h":[["p","At Higher Levels. When you cast this spell at 5th level or higher, it deals an extra 1d8 radiant damage for each slot level above 4th. If cast at 7th level or higher you can make this attack with advantage."]]},{"k":"sp-valmsirritatingquestion","n":"Valm’s Irritating Question","l":5,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":593,"ct":"1 minute","rg":"Touch","cp":"V, S, M (a blank page, which records the question and answer)","d":"Instantaneous","b":[["p","You ask a question of a creature you can touch, and if they can understand your words they are compelled to answer, though not necessarily in a language you understand. If they give an honest answer to the question you become aware they have spoken the truth; if they tell a misleading answer or attempt to lie they must make an Intelligence saving throw, taking 8d10 psychic damage on a failure as their mind is wracked with guilt and pain, indicating their lie outwardly. If they succeed the save, the spell recognizes them as having spoken the truth."],["p","If the spell’s target would have no idea how to answer truthfully or is compelled by another effect to lie against their will, the spell reveals this fact and they suffer no consequence regardless of their answer."]],"h":[["p","At Higher Levels. If cast at 6th level or higher, you may ask one additional question for every slot level above 5th, and no two questions can be identical or the same question with different wording. When you do, the target must make the saving throw the first time they attempt to mislead or lie, and take the full 8d10 psychic damage the first time they fail. If they fail and continue to lie, each subsequent lie provokes another Intelligence save, except only dealing 2d10 psychic damage on a failure."]]},{"k":"sp-vampiricblade","n":"Vampiric Blade","l":3,"s":"Necromancy","sa":"NEC","c":["Occultist","Sorcerer","Warlock","Wizard"],"bk":"llb","p":297,"ct":"1 bonus action","rg":"Self","cp":"S, M (a melee weapon worth at least 1 sp and a splash of your blood worth up to 10 hit points, which the spell consumes)","d":"10 minutes","b":[["p","You drain your own life essence to empower the weapon used in the casting of the spell. When you hit with the weapon, you deal an additional 1d8 necrotic damage and regain hit points equal to the necrotic damage dealt. The spell ends when it has dealt necrotic damage equal to twice the hit points expended to cast the spell."]],"bm":1},{"k":"sp-vampiricbrand","n":"Vampiric Brand","l":5,"s":"Necromancy","sa":"NEC","c":["Occultist","Warlock","Wizard"],"bk":"llb","p":297,"ct":"1 action","rg":"30 feet","cp":"S, M (a splash of your blood worth at least 5 hit points, which the spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You force a creature within range to make a Wisdom saving throw. On a failure, a vampiric brand appears on its flesh. Until the spell ends, any time the target takes damage, it takes an additional 2d6 necrotic damage, and you regain hit points equal to half the necrotic damage dealt. Any time the branded creature regains hit points, you regain half as much."],["p","The branded creature can repeat its saving throw at the end of each of its turns, ending the spell on a success."]],"con":1,"bm":1},{"k":"sp-vampiricmist","n":"Vampiric Mist","l":7,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":593,"ct":"1 action","rg":"Self (20-foot radius)","cp":"S","d":"Instantaneous","b":[["p","A cloud of frost appears in a 20-foot radius centered on you, biting into all other creatures in this area. All creatures within that range must make a Constitution saving throw, taking 10d6 cold damage on a failed save, or half as much on a successful one. You absorb a fragment of the lifeforce of those creatures, regaining 2d12 hit points for each creature in range who fails their saving throw. This spell has no effect on undead or constructs."]],"g":["Altissima-Cor’s Arcane Arts"]},{"k":"sp-vampiricmosquito","n":"Vampiric Mosquito","l":1,"s":"Conjuration","sa":"CON","c":["Occultist","Wizard"],"bk":"llb","p":297,"ct":"1 action","rg":"Self (30 feet)","cp":"S, M (a drop of your blood worth at least 1 hit point, which the spell consumes)","d":"1 minute","b":[["p","You create a buzzing mosquito, formed of your blood. At the end of each of your turns for the duration, it bites a random hostile creature within 30 feet of you, dealing 1d4 necrotic damage. When the spell ends, the blood mosquito returns to you and gives you the stolen blood. You regain 1 hit point for each time the mosquito did damage, up to a maximum of 10 hit points. You can end the spell early as an action."]],"bm":1},{"k":"sp-vanquishmagic","n":"Vanquish Magic","l":5,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":593,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","Choose one creature, object or magical effect within range. For each spell that is affecting the target, make an ability check using your spellcasting ability. The DC equals 10 + the spell’s level. On a successful check, the spell ends on the target and any other additional targets being affected by that spell from the same source."]],"h":[["p","At Higher Levels. When you cast this spell at 6th level or higher, you can choose one additional object, creature, or effect within range for every slot level above 5th."]],"g":["Sky-Keeper’s Arcana"]},{"k":"sp-vengefulbeckoning","n":"Vengeful Beckoning","l":6,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":593,"ct":"1 action","rg":"30 feet","cp":"V, S, M (a ruby ring worth at least 300 gp, which this spell consumes)","d":"Concentration, up to 1 minute","b":[["p","You pull the spirit of one dead or dying creature within range from its body and grant it a vengeful spirit form. A twisted yokai form of the creature (which must be a creature who has 0 hit points or is dead) is manifested in a space within 30 feet of its body in an unoccupied space. This spirit body then acts with its previous initiative (or rolls for initiative, if it hadn’t before) as it sees fit. If the creature was dead, they cannot have been dead for longer than 1 hour."],["p","The spirit has the statistics of the original creature, with the following exceptions:"],["li","The creature has 0 hit points, but gains temporary hit points equal to (1d6 + your spellcasting ability modifier) multiplied by your proficiency bonus. It dies and the spell ends if it loses these temporary hit points. It cannot gain hit points any other way."],["li","The creature ignores difficult terrain."],["li","The creature cannot gain any bonuses to its attack roll modifiers or saving throws."],["li","The creature’s type is considered to be fiend (yokai), in addition to its usual type(s)."],["li","The creature cannot move more than 60 feet away from their corpse."],["li","If their corpse is attacked, the creature may use their reaction to shift the damage to their spirit form instead."],["li","The creature has advantage on attack rolls against the enemy who reduced its living body to 0 hit points."],["li","The creature has a spectral copy of all of their equipment and items, but if they use these versions they are considered to be using their real counterpart. If an item is removed from their physical body it vanishes from their yokai spirit form."],["p","While their spirit form is active, the creature’s body does not make death saving throws (but can still fail them if their body takes damage). If the creature’s body dies, its spirit does not disappear until the spell ends. If the caster loses concentration on this spell, the spirit body vanishes immediately."],["p","Once a creature is given this vengeful form it cannot be granted one again for 24 hours."]],"h":[["p","At Higher Levels. If you cast this spell using a spell slot of 7th or higher level, the spirit body gains 5 additional temporary hit points and a cumulative +1 bonus to their saving throws for each slot level above 6th."]],"con":1,"g":["Daemoturgy"]},{"k":"sp-vesseloftransportation","n":"Vessel of Transportation","l":5,"s":"Conjuration","sa":"CON","c":["Inventor","Sorcerer","Wizard"],"bk":"ll","p":264,"ct":"1 hour","rg":"30 feet","cp":"V, S","d":"Concentration, up to 8 hours","b":[["p","You weave together creation magic and conjure a vehicle of your choice within range, which uses the Magical Vessel stat block. The vehicle can take any shape you wish, but is no more than 10 feet on any side."],["p","When you cast the spell, you can designate any number of creatures you can see as pilots. A pilot inside the vehicle can attempt to mentally control it as an action, unless another pilot is already controlling it. The pilot can end this control at will (no action required), or its control ends automatically if it exits the vehicle."],["p","While in control of the vehicle, the pilot is deaf and blind to its surroundings. Instead, it sees and hears through an invisible sensor that follows the vehicle and hovers 5 feet outside of it at all times. The pilot move the sensor as a bonus action to another location within 5 feet of the vehicle."],["p","If a pilot is mentally controlling the vehicle, you can terminate its control as an action. As part of the same action, you can choose to become the new pilot of the vehicle."],["p","Credit"],["p","Spell created and contributed by Roguish."],["p","Magical Vessel"],["p","Large vehicle (10 ft. by 10ft.)"],["p","Creature Capacity: 1 crew, 8 passengers"],["p","Cargo Capacity: 1 ton"],["p","Armor Class: 15"],["p","Hit Points: Special"],["p","Speed: 150 ft."],["tbl",[["STR","DEX","CON","INT","WIS","CHA"],["15 (+2) 21 (+5) 12 (+1) 0 (−5)","0 (−5) 0 (−5)"]]],["p","Damage Immunities: poison, psychic"],["p","Condition Immunities: blinded, charmed, deafened, exhaustion,"],["p","frightened, incapacitated, paralyzed, petrified, prone, poisoned,"],["p","stunned, unconscious"],["p","Magical Swiftness. The vessel is extraordinarily quick. It can"],["p","move at up to 15 miles an hour at a regular pace or 20 miles at a"],["p","fast pace."],["p","Levitating Movement. The vessel gently hovers up to 3 feet off"],["p","the ground at all times. It move across uneven terrain, over water,"],["p","or up or down stairs and slopes, but it can't traverse hazardous"],["p","liquids such as lava or move over elevation changes greater"],["p","than 10 feet."],["p","Comfortable Interior. So long as the interior is not exposed"],["p","directly to the elements, the atmosphere within the vessel is"],["p","considered comfortable and dry regardless of the weather outside."],["p","Psychic Link. When the vehicle would take any damage, the caster"],["p","instead loses the same amount of hit points. The caster can choose"],["p","to end the spell instead of losing these hit points."],["p","Limited Capacity. The vessel's speed becomes 0 if any of the"],["p","following conditions are met:"],["li","There are greater than 9 creatures within the vessel."],["li","There is a Large or larger creature within the vessel."],["li","The vessel is carrying or towing a combined 2,000 lbs. or more."],["p","Actions"],["p","Pilot. Drive and steer the Magical Vessel."]],"rv":1,"con":1,"ms":["arcane"]},{"k":"sp-vibrancesap","n":"Vibrance Sap","l":1,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":594,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","A burst of energy in the shape of a lesser yokai fires at one target within range as a ranged spell attack. On a hit, the target takes 2d8 necrotic damage and must make a Constitution saving throw. On a failure, the target can take either an action or a bonus action on their next turn, but not both."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, its damage increases by 1d8 for each spell slot above the 1st. If cast at 5th level or higher, the creature can only make 1 weapon attack on their next turn if they fail the Constitution save regardless of their features or magic items."]],"g":["Daemoturgy"]},{"k":"sp-vicioushound","n":"Vicious Hound","l":2,"s":"Illusion","sa":"ILL","c":["Bard","Occultist","Sorcerer","Warlock","Wizard"],"bk":"ll","p":265,"ct":"1 action","rg":"120 feet","cp":"V, S, M (a spiked collar)","d":"Concentration, up to 1 minute.","b":[["p","You summon an illusion of a particularly vicious hound that chases a target within range. Only the target can see the hound. On each of its turns for the duration of the spell, if it moves less than 40 feet from where it started their turn, it takes 3d8 psychic damage as it gets mauled by the illusionary hound. At the end of each of its turns, regardless if took damage or not, it makes a Wisdom saving throw. On a success, it discerns the hound is an illusion and the spell ends."]],"con":1,"ms":["arcane"]},{"k":"sp-viciousvapors","n":"Vicious Vapors","l":2,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Warlock","Wizard"],"bk":"ll","p":265,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You conjure a swirling poisonous miasma around yourself. For the duration of the spell, you are lightly obscured. When you cast the spell, and as a bonus action on each subsequent turn, you can cause the vapors to surge out and swirl around up to three creatures of your choice within range. Each creature must make a Constitution saving throw. On a failed save, it takes 1d12 poison damage and becomes poisoned until the start of your next turn. On a successful save, it takes half as much poison damage and is not poisoned."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d12 for each slot level above 2nd."]],"con":1,"ms":["arcane","primal"],"also":[["cc",147]]},{"k":"sp-violentcrush","n":"Violent Crush","l":4,"s":"Transmutation","sa":"TRA","c":["Sorcerer","Wizard"],"bk":"ll","p":265,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","You attempt to magically crush a Large or smaller creature or object within range. The target must make a Strength saving throw. On a failure, it takes 6d12 bludgeoning damage and falls prone. On a success, it takes half as much damage and does not fall prone."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d12 for each slot level above 4th."]],"ms":["arcane"]},{"k":"sp-violentpillar","n":"Violent Pillar","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":594,"ct":"1 action","rg":"60 feet","cp":"S, M (a metal rod at least three feet long, or a spear, javelin or quarterstaff which the spell consumes)","d":"Concentration, up to 10 minutes","b":[["p","You hold the spell’s material component aloft and send it hurling at a target you can see within range. That creature must succeed a Strength saving throw or take 8d10 bludgeoning damage and be knocked back 15 feet, falling prone and ending the spell."],["p","If there is a wall or solid surface within that 15 feet, they slam into it instead and the spear keeps them bound to that surface where they are restrained. They - or another creature adjacent to them - can attempt a Strength check against your spell save DC as an action to pull the spear free from them, ending the effect on a success."],["p","This spell is only capable of restraining creatures up to one size category larger than you."]],"con":1,"g":["Nine Branch Arts"]},{"k":"sp-violentupdraft","n":"Violent Updraft","l":1,"s":"Transmutation","sa":"TRA","c":["Druid","Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":266,"ct":"1 action","rg":"120 feet","cp":"V, S","d":"Instantaneous","b":[["p","You create a violent burst of wind, attempting to toss a Large or smaller creature into the air. The target must make a Strength saving throw, which it can choose to fail. On a failure, it is knocked 20 feet straight up into the air. If the target cannot hold onto anything or fly, it immediately falls, taking normal falling damage (2d6 bludgeoning damage) and falling prone."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the target is knocked 10 additional feet higher for each slot level above 1st."]],"ms":["primal"]},{"k":"sp-vitalsurge","n":"Vital Surge","l":4,"s":"Transmutation","sa":"TRA","c":["Cleric","Druid","Occultist"],"bk":"ll","p":266,"ct":"1 minute","rg":"30 feet","cp":"V, S","d":"8 hours","b":[["p","You infuse a vital surge of life into up to 4 creatures of your choice within range. Once during the spell's duration, a target can trigger this vital surge as a bonus action, regaining 4d8 hit points. When it does so, it can choose to expend up to 4 hit dice, rolling them and healing for the result (adding its Constitution modifier to each die as normal)."],["p","Once a creature triggers its healing surge, the spell ends for that creature."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the maximum number of targets and the maximum number of hit dice a target can expend both increase by 1 for each slot level above 4th."]],"ms":["primal","divine"]},{"k":"sp-vitalitybalance","n":"Vitality Balance","l":3,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":594,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","You sacrifice some of your health to mend another creature’s injuries. You take 4d8 necrotic damage, which cannot be reduced in any way, and one creature of your choice that you can see within range regains a number of hit points equal to twice the necrotic damage you take. If this spell would reduce you to 0 hit points, the necrotic damage you take is reduced so that you have 1 hit point remaining (the healing is adjusted accordingly as well)."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can choose one of the following effects for each slot level above 3rd:"],["li","The damage increases by 1d8."],["li","Before taking your necrotic damage, you gain 2d8 temporary hit points. The number of d8s increases by 1d8 each time you choose this effect. These temporary hit points vanish once you take the necrotic damage."]],"leg":1},{"k":"sp-voidofendlessdepth","n":"Void of Endless Depth","l":8,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":594,"ct":"1 action","rg":"150 feet","cp":"V, M (a drop of pitch mixed with a drop of mercury)","d":"Concentration, up to 10 minutes","b":[["p","Magical darkness spreads from a point you choose within range to fill a 60-foot radius sphere until the spell ends, and can spread around corners if the space requires it. A creature with darkvision can’t see through this darkness. Nonmagical light, as well as light created by spells of 8th level or lower, can’t illuminate the area."],["p","Shrieks, gibbering, and mad laughter can be heard within the sphere. Whenever a creature starts its turn in the sphere, it must make a Wisdom saving throw, taking 8d8 psychic damage on a failed save, or half as much damage on a successful one."]],"con":1,"leg":1},{"k":"sp-volcanicash","n":"Volcanic Ash","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":594,"ct":"1 action","rg":"60 feet (20-foot radius)","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","A cloud of hot volcanic ash spews forth from a point you choose within range, filling a 20-foot radius sphere. This cloud of ash remains for the spell’s duration. Any creature within the cloud when it appears must make a Constitution saving throw, taking 8d6 fire damage on a failed save or half as much on a successful one. Any creature that ends their turn within the cloud of ash or enters it for the first time on their turn must make this save again, and take the damage again depending on their result."],["p","On your turn, you can move the center of the cloud of ash up to 30 feet as a bonus action."],["p","Creatures that are not resistant to fire damage are blinded and cannot breathe when in the cloud of ash, and everything within it is heavily obscured. You are not blinded by your own cloud, and when you make a save against your own cloud of ash you take no damage on a success and half damage on a failure."]],"h":[["p","At Higher Levels. When casting this spell using a spell slot of 6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","The spell’s radius increases by 5 feet."],["li","The spell’s fire damage increases by 1d6."]],"con":1},{"k":"sp-volcanicburst","n":"Volcanic Burst","l":6,"s":"Transmutation","sa":"TRA","c":["Druid","Warlock","Sorcerer","Wizard"],"bk":"ll","p":266,"ct":"1 action","rg":"120 feet","cp":"V, S, M (a piece of obsidian)","d":"Instantaneous","b":[["p","You call fiery forces from below the earth to violently erupt, designating a point you can see within range to explode with magma. The ground in a 10-foot radius around the point explodes in a shower of fire and rock, raining down in a 20-foot radius. Every creature in the 20-foot radius must make a Dexterity saving throw. On a failure, it takes 4d10 bludgeoning damage and 4d6 fire damage. If a creature in the inner 10-foot radius fails its save, it is additionally flung 10 feet up into the air, taking normal falling damage (1d6 bludgeoning damage) and falling prone when it lands. On a successful save, a creature takes half damage and suffers no additional effects."],["p","The inner 10-foot radius becomes difficult terrain until cleared by hand. Each 5-foot-square portion of the area requires at least 1 minute to clear by hand."]],"ms":["primal"]},{"k":"sp-vorpalflames","n":"Vorpal Flames","l":3,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":595,"ct":"1 bonus action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You call upon flames to join together in the form of an uchigatana which solidifies in your hand. This magic uchigatana (greatsword) lasts until the spell ends. It counts as a martial melee weapon that you are proficient with, has the heavy and reach properties, gives off 20 feet of bright light and 20 feet of dim light beyond that, and deals 3d8 fire damage on a hit. You can drop the sword and make it vanish freely, and can recall it to your hand as a bonus action while the spell persists. When you attack with it you may use either your Strength or your spellcasting ability for its attack and damage rolls."],["p","When this sword strikes a creature that is a Plant or Undead, it deals an extra d8 of fire damage to them."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, your proficiency with this weapon increases. Using a slot of 5th level or higher, you can make two attacks instead of one with it as part of an Attack action. At 7th level or higher this increases to three instead of one. If cast using a 9th-level spell slot, this weapon scores a critical hit on a d20 result of 18, 19 or 20."]],"con":1,"g":["Nine Branch Arts"]},{"k":"sp-vorpalshot","n":"Vorpal Shot","l":5,"s":"Transmutation","sa":"TRA","c":["Inventor","Ranger"],"bk":"ll","p":266,"ct":"1 bonus action","rg":"Touch","cp":"V, S, M (a piece of ammunition or a weapon with the thrown property worth at least 1 cp)","d":"1 round","b":[["p","You touch a piece of ammunition or a weapon with the thrown property, granting it a razor-sharp edge. The first time a creature attacks with the empowered item, it adds +3 to its attack and damage rolls, and ignores all resistances and immunities to the weapon's damage type. On a hit, the creature takes 6d8 additional damage. If this damage reduces the target to 0 hit points, it receives a mortal wound and immediately dies."],["p","Once an attack has been made with the piece of ammunition or weapon, the spell ends."]],"ms":["arcane"]},{"k":"sp-vorpalweapon","n":"Vorpal Weapon","l":5,"s":"Transmutation","sa":"TRA","c":["Inventor"],"bk":"ll","p":267,"ct":"1 action","rg":"Touch","cp":"V, S, M (a melee weapon worth at least 1 sp)","d":"Concentration, up to 1 hour","b":[["p","You touch a weapon and grant it a merciless edge. For the duration the weapon becomes unbelievably sharp. Its attacks ignore resistance to slashing damage and t gains the Siege property, dealing double damage to inanimate objects and structures. If the weapon is nonmagical or is magical and has a bonus of +2 or less, its bonus becomes a +3 to attack and damage rolls."],["p","Additionally, if the wielder scores a critical hit with this weapon which would leave a target with less than 50 hit points, it is decapitated and instantly killed."]],"con":1,"ms":["arcane"],"also":[["cc",148]]},{"k":"sp-vortexblast","n":"Vortex Blast","l":3,"s":"Evocation","sa":"EVO","c":["Druid","Occultist","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":267,"ct":"1 action","rg":"Self (30-foot cone)","cp":"V, S","d":"Instantaneous","b":[["p","You create a sudden vortex that expands outward in a 30-foot cone, tossing characters and objects within the area. Each creature in the area takes 3d6 bludgeoning damage and must succeed on a Strength saving throw or be knocked 30 feet backward and 30 feet upward, taking normal falling damage (3d6 bludgeoning damage) as it falls back down unless it has a means to stay aloft."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd."]],"ms":["arcane","primal"],"also":[["cc",148]]},{"k":"sp-vortexquiver","n":"Vortex Quiver","l":3,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":595,"ct":"1 bonus action","rg":"Touch","cp":"V, S","d":"Concntration, up to 1 minute","b":[["p","You imbue a weapon with a swirling whirlwind. When you make a ranged attack with that weapon, its hits deal an extra 1d8 force damage, and if the target is no more than one size category larger than the size of creature the weapon is intended for, they must make a Strength saving throw. On a failure, one of the following two effects occurs (your choice):"],["li","The target is shoved back 10 feet, stopping if they collide with a solid surface. For every 10 feet they are stopped short, they take 1d6 bludgeoning damage."],["li","The target is knocked prone."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, choose one of the following effects for each slot level above 3rd:"],["li","The size of creatures that the Strength save can target increases by one category."],["li","The target is pushed back 10 additional feet."],["li","For every two slot levels above 3rd, the extra force damage also increases by 1d8."]],"g":["Epic of Duality"]},{"k":"sp-wakefieldssuffocatingdarkness","n":"Wakefield’s Suffocating Darkness","l":7,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":595,"ct":"1 action","rg":"30 feet","cp":"V, S, M (an unlit lamp that darkness emerges from)","d":"Concentration, up to 1 minute","b":[["p","You conjure up horrific darkness that reaches out toward one target within range and covers their body aggressively, leaving them a blackened and muted husk. The target must make an Intelligence saving throw."],["p","On a failed save they are darkened for 1 minute, during which time they are blinded, deafened, their voice is distorted in such a way that they cannot communicate or perform verbal components to spells, and they take 3d8 psychic damage at the start of each of their turns."],["p","While covered in shadow this way, you can use your action on each of your turns to force all creatures under this effect to make another Intelligence saving throw. On a failure, the creature moves up to half its movement speed toward a creature you choose and is puppeteered to attack a creature within their reach as a melee spell attack (they are not considered blinded for this as long as you can see the target). On a successful hit, their target must make an Intelligence saving throw or also be affected by this spell and be coated in the same darkness until this spell ends."],["p","If an affected creature begins their turn in the radius of magical light or is subjected to a magical effect that briefly causes a large flash of light (such as a fireball, prismatic spray, etc.,) they may reattempt the Intelligence saving throw, ending the effect on themself on a successful save."]],"h":[["p","At Higher Levels. When you cast this spell at 8th level or higher, you may target one additional creature for each slot level above 7th."]],"con":1},{"k":"sp-wallofbloodsms","n":"Wall of BloodSMS","l":4,"s":"Conjuration","sa":"CON","c":["Sorcerer","Warlock","Wizard"],"bk":"llb","p":297,"ct":"1 action","rg":"60 feet","cp":"S, M (a splash of your blood worth at least 4 hit points, which the spell consumes)","d":"Concentration, up to 10 minutes","b":[["p","You manifest some of your blood into a barrier on a solid surface you can see within range. You can make the wall up to 60 feet long, 20 feet high, and 5 feet thick, or in a ring up to 20 feet in diameter, 20 feet high, and 5 feet thick. The wall is opaque and lasts for the duration. Moving through the wall costs 3 feet of movement for each foot traveled."],["p","Any creature entering the wall must make a Constitution saving throw, suffering 3d8 necrotic damage on a failure or half as much on a success. When a creature enters the wall, you can expend 2 hit points to increase the necrotic damage it would take by 2d8."],["p","SMS Credit"],["p","Wall of Blood is drawn from somanyrobot's So Many Spells."]],"con":1},{"k":"sp-wallofradiance","n":"Wall of Radiance","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":595,"ct":"1 action","rg":"120 feet","cp":"V, S, M (a hand mirror)","d":"Concentration, up to 10 minutes","b":[["p","A shimmering wall of bright light appears at a point you choose within range. The wall appears in any orientation you choose: horizontally, vertically, or diagonally. It can be free floating, or it can rest on a solid surface. The wall can be up to 60 feet long, 10 feet high, and 5 feet thick. The wall blocks line of sight, but creatures and objects can pass through it. It emits bright light out to 120 feet and dim light for an additional 120 feet."],["p","When the wall appears, each creature in its area must make a Constitution saving throw. On a failed save, a creature takes 4d8 radiant damage and is blinded for 1 minute; on a successful save, they take half as much damage and aren’t blinded. A blinded creature can make a Constitution saving throw at the end of each of their turns, ending the effect on themself on a success."],["p","A creature that ends their turn in the wall’s area takes 4d8 radiant damage."],["p","Until the spell ends, you can use an action to launch a beam of radiance from the wall at one creature you can see within 60 feet of it. Make a ranged spell attack: on a hit, the target takes 4d8 radiant damage. Whether you hit or miss, reduce the length of the wall by 10 feet. If the wall’s length drops to 0 feet, the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","The damage increases by 1d8."],["li","When you fire a blast from the wall, each creature within 5 feet of your target must make a Dexterity saving throw. On a failure they take half as much damage as the initial damage."],["li","The length of the wall increases by 10 feet and its height increases by 5 feet."]],"con":1,"leg":1},{"k":"sp-waspbarrage","n":"Wasp Barrage","l":3,"s":"Conjuration","sa":"CON","c":["Druid","Occultist","Ranger","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":267,"ct":"1 action","rg":"Self (40-foot cone)","cp":"V, S","d":"Instantaneous","b":[["p","You conjure a swarm of magical wasps, which zip out to sting creatures of your choice within a 40-foot cone. Make a ranged spell attack against each individual target. On a hit, a creature takes 1 piercing damage + 4d12 poison damage. After they attack, the magic wasps fade away."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the poison damage increases by 1d12 for each second slot level above 3rd."]],"ms":["primal"]},{"k":"sp-waterblast","n":"Water Blast","l":1,"s":"Conjuration","sa":"CON","c":["Druid","Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":267,"ct":"1 action","rg":"30 feet","cp":"V, S","d":"Instantaneous","b":[["p","You conjure a ball of water and hurl it at a target. Make a ranged spell attack. On a hit, the target takes 3d6 bludgeoning damage, and if it is Large or smaller, must succeed on a Strength saving throw or be knocked prone."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each level above 1st."]],"ms":["arcane","primal"],"also":[["cc",148]]},{"k":"sp-waterbullet","n":"Water Bullet","l":0,"s":"Conjuration","sa":"CON","c":["Druid","Occultist","Sorcerer","Spellblade","Warlock","Wizard"],"bk":"ll","p":267,"ct":"1 action","rg":"90 feet","cp":"V, S","d":"Instantaneous","b":[["p","You create a compressed bead of water and fire it at a creature you can see within range. Make a ranged spell attack. On a hit, the target takes 1d6 + your spellcasting ability modifier piercing damage."],["p","This spell’s damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6)."]],"ms":["arcane","primal"]},{"k":"sp-watercannon","n":"Water Cannon","l":3,"s":"Evocation","sa":"EVO","c":["Druid","Sorcerer","Spellblade","Wizard"],"bk":"ll","p":268,"ct":"1 action","rg":"Self (60-foot line)","cp":"V, S","d":"Instantaneous","b":[["p","You unleash a spout of water that blasts out in a 60-foot long, 5-foot wide line. Each creature in the line must make a Strength saving throw. On a failed save, a creature takes 6d6 bludgeoning damage and is pushed to an unoccupied space at the far end of the line. If there is no available space at the end of the line, it is pushed to the closest open space, takes an additional 2d6 bludgeoning damage, and is knocked prone. On a successful save, a target takes half as much damage and is not pushed."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each level about 3rd."]],"ms":["arcane","primal"],"also":[["cc",148]]},{"k":"sp-waterspout","n":"Waterspout","l":3,"s":"Conjuration","sa":"CON","c":["Druid","Occultist","Sorcerer","Warlock","Wizard"],"bk":"ll","p":268,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You conjure a large mass of water and form it into a whirling funnel around a point on the ground you can see. The funnel fills a 10-foot radius, 30-foot high cylinder. If a creature enters the waterspout on its turn or the waterspout moves into the creature's space, the creature must make a Strength saving throw. On a failure, it takes 2d8 bludgeoning damage and is blinded, deafened, and cannot speak. At the start of its next turn, it is expelled from the waterspout to the nearest empty space. On a success, it takes half as much damage and suffers none of the spell’s other effects."],["p","On your turn, you can use a bonus action to move the waterspout up to 20 feet in any direction along the ground, engulfing any creatures in its path. A creature that fails its save after being engulfed by the waterspout in this way is carried along with its movement until they it is ejected at the start of its turn."],["p","If the center point of this spell is over a Huge or larger body of water, the size of the waterspout is doubled."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-weaponofdomination","n":"Weapon of Domination","l":2,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":596,"ct":"1 bonus action","rg":"Self","cp":"S","d":"Instantanteous","b":[["p","One melee weapon that you are wielding is briefly turned into a gargantuan golden version of itself made of arcane force. It is many times larger than yourself, and you may use it to make a single weapon attack (ignoring the usual considerations for weapon size) against one creature within twice the weapon’s reach. If you hit, you deal the weapon’s regular damage dice, but must roll those damage dice again and add that much force damage to the result. This extra force damage does not benefit from critical hits. The weapon then returns to its regular state."]],"h":[["p","At Higher Levels. When you cast this spell at 3rd level or higher, for each slot level above 2nd you roll the weapon’s damage dice an additional time and add the result to the force damage dealt. For every two slot levels above 2nd, the weapon’s size and reach doubles again. If cast at 9th level, the extra force damage is doubled."]],"g":["Legacy of Gold"]},{"k":"sp-whirlingconflagration","n":"Whirling Conflagration","l":3,"s":"Transmutation","sa":"TRA","c":["Ranger"],"bk":"ll","p":268,"ct":"1 action","rg":"Self (15-foot radius)","cp":"V, S, M (a melee weapon with which you are proficient worth at least 1 sp)","d":"Instantaneous","b":[["p","You flourish the weapon used in the casting and whirl it around, setting it ablaze. Make one weapon attack, applying the roll to each creature within 15 feet. Each target takes 6d6 fire damage on hit, or half as much on a miss."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th Level or higher, the damage increases by 1d6 for each slot level above 3rd."]],"ms":["primal"]},{"k":"sp-whirlpool","n":"Whirlpool","l":5,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":596,"ct":"1 action","rg":"120 feet","cp":"V, S, M (paper or leaf in the shape of a funnel)","d":"Concentration, up to 1 minute","b":[["p","A swirling mass of 5-foot-deep water appears in a 30-foot radius centered on a point you can see within range. The point must be on the ground or in a body of water. Until the spell ends, that area is difficult terrain, and any creature that starts their turn there must succeed on a Strength saving throw or take 6d6 bludgeoning damage and be pulled 10 feet toward the center."],["p","Creatures who are in a space touching the point the spell is centered on have disadvantage on their Strength saving throw."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 6th level or higher, choose one of the following effects for each slot level above 5th:"],["li","The radius of the swirling water increases by 5 feet, as does the distance creatures are pulled toward the center."],["li","The bludgeoning damage increases by 1d6."],["li","The spell’s depth increases by 5 feet, and creatures who are pulled inward are pulled half as far down."]],"con":1,"leg":1},{"k":"sp-windcutter","n":"Wind Cutter","l":2,"s":"Transmutation","sa":"TRA","c":["Druid","Inventor","Occultist","Ranger","Spellblade","Wizard"],"bk":"ll","p":268,"ct":"1 bonus action","rg":"Self (30 feet)","cp":"V, S, M (a melee weapon with which you are proficient worth at least 1 sp)","d":"Concentration, up to 1 minute","b":[["p","You infuse the weapon used in the spell’s casting with tempestuous power. For the duration, when you make an attack on your turn with the weapon, it gains a reach of 30 feet, releasing slashes of razor sharp wind against your foes. When hitting targets beyond its normal reach, it deals slashing damage."],["p","Additionally, the weapon's attacks deal an additional 1d4 damage, and if there is another creature within 5 feet of the target, it is struck by the slashing wind. Apply the same attack roll to the second creature, dealing half as much damage as the initial attack on a hit."]],"con":1,"ms":["arcane","primal"]},{"k":"sp-windborneweapon","n":"Windborne Weapon","l":0,"s":"Transmutation","sa":"TRA","c":["Druid","Sorcerer","Wizard"],"bk":"ll","p":268,"ct":"1 action","rg":"150 feet","cp":"V, S, M (a piece of ammunition or a weapon with the thrown property worth at least 1 cp)","d":"Instantaneous","b":[["p","You wrap a weapon or piece of ammunition in swirling wind. Make a ranged spell attack against a target within range, using the spell’s material component. This attack ignores cover. On a hit, it deals 1d10 damage of the weapon’s damage type."],["p","This spell’s damage increases by 1d8 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10)."]],"ms":["arcane","primal"],"also":[["cc",148]]},{"k":"sp-windsense","n":"Windsense","l":2,"s":"Transmutation","sa":"TRA","c":["Druid","Ranger"],"bk":"ll","p":269,"ct":"1 bonus action","rg":"Self","cp":"V","d":"1 round","b":[["p","You cast your senses out into the wind. Until the start of your next turn, you gain blindsight within 60 feet and have advantage on Wisdom (Perception) checks. Additionally, when you make ranged weapon attacks, you do not require line of sight as long as the target is within your blindsight, and the target does not benefit from cover."]],"ms":["primal"]},{"k":"sp-wingsofsharptransition","n":"Wings of Sharp Transition","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":596,"ct":"1 action","rg":"Self","cp":"V, S","d":"Concentration, up to 1 minute","b":[["p","You create refractive wings made of pale red energy, which grant you a fly (hover) speed of 60 feet, as well as a 0-G acceleration speed of 180 feet. While you have these wings, your movement using these modes do not provoke opportunity attacks, and you deal an additional 1d8 force damage to one target the first time you deal damage to a creature using an attack or spell each turn ."],["p","As a bonus action, on your turn you can attempt to make a melee spell attack against a creature within 5 feet of you, striking them with one of these energy wings. On a hit your target takes 2d8 force damage."],["p","If you lose or drop concentration on this spell, you can teleport to an unoccupied space you can see within a range equal to the fly (hover) speed this spell grants you."]],"h":[["p","At Higher Levels. When you cast this spell at 6th level or higher, you can choose one of the following effects for each slot level above 5th:"],["li","Your fly and 0-G acceleration speed increase by 10 feet"],["p","and 30 feet respectively."],["li","Both the extra damage you deal and the wing attack damage you deal increase by 1d8."],["li","The spell’s duration increases to 10 minutes (1 slot level), 1 hour (2 slot levels), 8 hours (3 slot levels) or 24 hours (4 slot levels)"],["p","For every two slot levels above 5th you cast this spell, you can make one additional wing attack as part of the same bonus action. If cast at 9th level this spell does not require concentration."]],"con":1,"g":["Blood of Cineris"]},{"k":"sp-wingweight","n":"Wingweight","l":2,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":596,"ct":"1 action","rg":"300 feet","cp":"V","d":"Concentration, up to 10 minutes","b":[["p","Choose up to three creatures you can see within range. An arcane symbol appears above them, which is only visible when the creature is flying through the air. The target must succeed on a Strength saving throw. On a failure, any fly or fly (hover) speeds they have become belabored flight speeds instead (this effect only occurs as of the start of their next turn)."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, it can target up to two additional creatures for each slot level above 2nd."]],"con":1},{"k":"sp-wither","n":"Wither","l":3,"s":"Necromancy","sa":"NEC","c":["Occultist","Spellblade","Warlock"],"bk":"ll","p":269,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a pinch of powdered bone and sand)","d":"1 round","b":[["p","Dark energy pulls the moisture out of a body, sapping it of life and vitality. The target must make a Constitution saving throw. On a failure, it takes 4d10 + 4 necrotic damage and becomes withered until the start of your next turn. A withered creature that has resistance to fire loses it, or gains vulnerability to fire damage if it did not have resistance. On a successful save, a creature takes half as much damage and is not withered."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d10 for each slot level above 3rd."],["p","Art: Reggy Azmat Art: Trung Tin Shinji"]],"ms":["arcane"]},{"k":"sp-wordsofazharul","n":"Words of Azharul","l":8,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":597,"ct":"1 action","rg":"60 feet","cp":"V, S, M (a pound of ground bone from the skeleton of an ancient black dragon)","d":"24 hours","b":[["p","When you cast this spell you choose one creature you can see within 60 feet that can see and hear you. You channel the dying words of an ancient slain dragon, invoking a death curse upon them. The target creature must make a Charisma saving throw: on a failed save the creature is cursed for 24 hours. While cursed this way any time the creature rolls an attack roll, ability check, or saving throw the caster of this spell may use a strike to ignore the result and replace it with a 1 (still accounting for their modifiers and not causing an automatic failure, even on attack rolls). The caster has five strikes to use, then the curse ends. At the end of the 24 hours the creature takes 5d10 damage for each unused strike."],["p","If a creature casts this spell a second time on a creature they have already affected with it, the previous curse ends immediately without causing damage. The strikes from another instance of this spell cannot be used to cause them to fail a save against this spell."]],"g":["Chromatic Convocation","Eidomancy"]},{"k":"sp-writblock","n":"Writ Block","l":2,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":597,"ct":"1 action","rg":"60 feet","cp":"S","d":"Concentration, up to 1 minute","b":[["p","You write a line of arcane text describing one target you can see within 60 feet; you describe their current state and enforce that text to prevent them from changing. Choose one of the following options when you cast this spell:"],["li","Attack rolls"],["li","Armor class"],["li","Saving throws"],["li","Ability checks"],["p","The target must make an Intelligence saving throw (which they may willingly fail). On a failure, any effects that would change or alter your target, e.g., effects that give advantage or disadvantage, grant AC, reduce or improve attack bonuses, etc., do not affect the type of roll you picked, and they make those rolls as if nothing was improving or penalizing them."]],"h":[["p","At Higher Levels. When you cast this spell at 3rd level or higher, you may choose one additional target within range for every slot level above 2nd."]],"con":1},{"k":"sp-writbombardment","n":"Writ Bombardment","l":2,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":597,"ct":"1 action","rg":"60 feet","cp":"S","d":"Instantaneous","b":[["p","You write a line of arcane text that describes projectiles appearing and hurtling towards up to 3 targets you can see within 60 feet. The projectiles fire toward them, and the targets must each make a Dexterity saving throw. On a failed save they each take 4d6 bludgeoning damage, or half as much on a success."],["p","59 7 Any creature who fails by 5 points or more is sluggish until the end of their next turn."]],"h":[["p","At Higher Levels. When you cast this spell at 3rd level or higher you may choose one of the following two options: the spell’s damage increases by 1d6, or choose one additional target within range. You make this choice for each slot level above 2nd."]]},{"k":"sp-writbookmark","n":"Writ Bookmark","l":1,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":597,"ct":"1 action","rg":"1 mile","cp":"S","d":"Concentration, up to 1 round","b":[["p","You create an invisible beacon that resembles a floating bookmark to those who can see invisible objects. At any time before the spell ends you can use your reaction to teleport yourself and anything you are carrying back to the space where you left the bookmark, which cannot be moved or touched as long as that space is unoccupied. Spells that remove magical effects may target the bookmark if the caster is aware it is there. You must be within 1 mile and on the same plane as the bookmark to do so, and you become aware if it is no longer possible to move there. Once you use this effect to teleport back to that space, the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd level or higher the spell’s duration increases to 1 minute at 2nd level, 10 minutes at 3rd, 1 hour at 4th, 10 hours at 5th, 1 day at 6th, 1 month at 7th, 1 year at 8th, and becomes permanent until used at 9th. If cast at 5th level or higher it no longer requires concentration."]],"con":1},{"k":"sp-writcannon","n":"Writ Cannon","l":5,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":597,"ct":"1 action","rg":"60 feet","cp":"S","d":"Concentration, up to 1 minute","b":[["p","You describe a cannon in great detail, summoning the barrel of one into the air behind you. The cannon barrel floats near you, armed with three rounds of ammunition. Once when you conjure it, then again on subsequent turns as a bonus action, you can command it verbally to fire while pointing at a space you can see within 60 feet where it aims and fires one of its rounds. All creatures in a 15-foot-cube centered on that space must make a Dexterity saving throw, taking 2d8 fire damage and 2d8 psychic damage on a failed save. Once all of its rounds have been fired, the cannon vanishes and the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell at 6th level or higher, you create two more rounds per slot level above 5th."]],"con":1},{"k":"sp-writconsecration","n":"Writ Consecration","l":4,"s":"Evocation","sa":"EVO","c":[],"bk":"retia","p":597,"ct":"1 action","rg":"30 feet","cp":"S","d":"Instantaneous","b":[["p","You write out a line of sacred text and choose up to 6 creatures within 30 feet of you. Those creatures hear the growling chants of celestial beings, wracking them with celestial power. Your targets must make a Charisma saving throw, taking 6d8 radiant damage on a failed save or half as much on a successful one. If they are fiends the radiant damage increases by 2d10."]],"h":[["p","At Higher Levels. When you cast this spell at 5th level or higher, you can either increase the radiant damage by 1d8 or target one additional creature for each slot level above 4th."]]},{"k":"sp-writentropy","n":"Writ Entropy","l":3,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":598,"ct":"1 action","rg":"60 feet","cp":"S","d":"Instantaneous","b":[["p","You write a passage describing a blast of eldritch energy and choose a point within 60 feet, causing an otherworldly illusion of an eruption of cosmic power. All creatures in a 15-foot radius surrounding that point must make an Intelligence saving throw, taking 8d6 psychic damage on a failed save. Any creatures who fail also feel slowed by a cold void-like presence hanging over them, and cannot take the Dash action or make more than one weapon attack (regardless of features) on a given turn until the start of your next turn. Creatures who can see through illusions (such as creatures with truesight) automatically succeed their saving throw against this effect."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, the radius of the sphere increases by 5 feet, and the psychic damage increases by 1d6 for every slot level above 3rd."]]},{"k":"sp-writerase","n":"Writ Erase","l":2,"s":"Necromancy","sa":"NEC","c":[],"bk":"retia","p":598,"ct":"1 action","rg":"60 feet","cp":"S","d":"Isntantaneous","b":[["p","You copy down a passage describing the exact health of a creature you can see within 60 feet, and that passage attempts to enforce that state. The target must make an Intelligence saving throw. If they fail, they lose all temporary hit points they currently have and take 2d8 psychic damage."]],"h":[["p","At Higher Levels. When you cast this spell at 3rd level or higher, the spell’s psychic damage increases by 1d8 and you can target one additional creature for each slot level above 2nd."]]},{"k":"sp-writforensic","n":"Writ Forensic","l":3,"s":"Divination","sa":"DIV","c":[],"bk":"retia","p":598,"ct":"1 minute","rg":"Touch","cp":"S","d":"Concentration, up to 10 minutes","b":[["p","You write a line of arcane text describing the beginning of a flashback as if recounting an effect you had witnessed. Choose a 10-foot radius centered on a point you touch, then choose a period of time within the last week. Illusory projections of creatures, objects, and events that occurred in the 10 minutes following your chosen time play out in the radius chosen, including sounds that originated from that radius. Creatures that were protected from divination for any reason do not appear in the projection. While watching the projection, you may speed up or rewind the projection as if scrubbing through footage, but it cannot project anything outside of the 10 minutes it recorded even if you speed it up."]],"h":[["p","At Higher Levels. When you cast this spell at 4th level or higher, the spell’s duration and amount of time recorded increases. It becomes 1 hour when cast using a 4th-level slot and 1 day using a 5th-level slot. If cast using a 6th-level slot it can replay events from up to a month ago, up to half a year at 7th, 5 years at 8th, and up to 100 years at 9th. Furthermore, the radius of the projection increases by 5 feet for every slot level above 3rd."]],"con":1},{"k":"sp-writheroism","n":"Writ Heroism","l":1,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":598,"ct":"1 action","rg":"30 feet","cp":"S","d":"Concentration, up to 1 minute","b":[["p","You write a short phrase describing the heroic antics of an allied creature you can see within 30 feet, and you gain three points of ascribed heroism corresponding to your target."],["p","Any time before the spell ends, if you witness that creature make a saving throw you may spend one point of ascribed heroism and write a short addendum to the phrase, allowing them to roll another d20 and use it in place of the d20 result that they rolled if the result is higher. You may only do so once per failed save and must choose to do so before the DM announces if the save failed or succeeded. When you run out of ascribed heroism the spell ends."]],"h":[["p","At Higher Levels. When you cast this spell at 2nd level or higher, you gain 1 extra point of ascribed heroism and can target 1 additional creature within range for each slot level above 1st. You must split the total number of points among your targets as you see fit."]],"con":1},{"k":"sp-writhorror","n":"Writ Horror","l":4,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":598,"ct":"1 action","rg":"60 feet","cp":"S","d":"Instantaneous","b":[["p","You write a passage about a creature you can see within 60 feet finding you terrifying. The creature must then make an Intelligence saving throw. On a failure, they become frightened of you for 1 minute. While frightened of you, you may use a bonus action to write another passage about terrorizing them while they can see you, causing them to make another Intelligence save. If they fail this additional save, they take 2d12 psychic damage and must use their reaction to move their movement speed away from you. The creature may reattempt the Intelligence save at the end of each of their turns, ending the effect on a success."]],"h":[["p","At Higher Levels. When you cast this spell at 5th level or higher, you can target one additional creature for each slot level above 4th. You may choose between using your bonus action to terrorize a single target or your action to terrorize them all, but not both on the same turn."]]},{"k":"sp-writreappropriation","n":"Writ Reappropriation","l":3,"s":"Conjuration","sa":"CON","c":[],"bk":"retia","p":599,"ct":"1 minute","rg":"30 feet","cp":"V, S, M (a mythril ring worth at least 1000 gp, which the spell consumes)","d":"Concentration, up to 1 hour","b":[["p","Target one magical item you can see within range. You write a description of that item, allowing you to recreate it and its effects in your possession. If you are wearing a piece of equipment that would share its space, the existing item is sent to a harmless demiplane until the spell ends, after which it is returned. You are treated as attuned to the item for the spell’s duration if it requires it, and this attunement does not count against your regular limit of attuned items, nor can it be attuned to by another creature. You are considered proficient with the item while it is in your possession. When the spell ends, the item and its ongoing effects vanish."],["p","The item you copy cannot activate any of its effects that require an action or bonus action, nor can it produce the effects of spells. The item must be a rare, uncommon, or common item."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can recreate a rarer item. When cast at 5th level or higher it can recreate a very rare item. At 8th-level, it can recreate an item of legendary rarity."]],"con":1},{"k":"sp-writrecollection","n":"Writ Recollection","l":1,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":599,"ct":"1 minute","rg":"60 feet","cp":"S","d":"1 hour","b":[["p","On a still surface within range, you create an animated 2d projection that has dimensions of 5 feet by 5 feet and glows lightly, allowing it to be seen in the dark. The projection does not have sound, but reflects your perspective from memory and shows what you saw in a 1-minute-long period of time within the last month. You can scrub through the visuals of the recollection: pausing it, slowing it down, and allowing it to play freely at will. Anything you were visually uncertain of and small details you might not have noticed may be inaccurate, blurred, or absent. This projection remains for the spell’s duration or vanishes when you choose."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 2nd-level or higher, you can choose one of the following effects for each slot level above 1st:"],["li","The dimensions of the projection are doubled."],["li","The duration of the memory becomes 10 minutes, then at higher levels becomes 1 hour, then 12 hours, then 1 day."],["li","The spell’s duration becomes 12 hours, then at higher levels becomes 1 day, then 1 week."],["li","The memory’s auditory effects are included and can be heard by everyone within a range equal to twice the projection’s dimensions."],["li","The memory can be drawn from up to 6 months ago, then at higher levels becomes 1 year, 5 years, 10 years, then any time during your life."],["p","If this spell is cast using a 9th-level spell slot, you can alter the projection to show anything you’d like as if it were a memory, including the bonuses above from casting it at a heightened spell level. When modified this way it does not benefit from the details of your memory."]]},{"k":"sp-writseizure","n":"Writ Seizure","l":0,"s":"Illusion","sa":"ILL","c":[],"bk":"retia","p":599,"ct":"1 action","rg":"30 feet","cp":"S","d":"Instantaneous","b":[["p","You conjure a narrative in the mind of a target within range, forcing them to experience the sensation of physical pain. That target must make an Intelligence saving throw, taking 1d10 psychic damage on a failed save."],["p","Cantrip Upgrade. The spell’s damage increases to 2d10 when you reach 5th level, 3d10 when you reach 11th level, then 4d10 when you reach 17th level. When casting the spell you can seperate these d10s to target additional creatures within range at the same time, doing the d10s you assigned to each target as psychic damage if they fail their saves."]]},{"k":"sp-writslumber","n":"Writ Slumber","l":2,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":599,"ct":"1 action","rg":"120 feet","cp":"S","d":"Concentration, up to 1 minute","b":[["p","You write a line of arcane text and choose one creature within 120 feet that you can see. That creature must make an Intelligence saving throw. On a failed save, they are Incapacitated for 1 minute, during which time they fall into a waking slumber. While under this effect all attacks made against them have advantage, and they automatically fail all Dexterity saves and Perception checks."],["p","The creature is not unconscious and does not fall, but they become unfocused and weary. They can be communicated with, but are capable only of short sentences which are mostly incoherent. At the end of the target’s turn, they can repeat the Intelligence save, ending the effect on a success."],["p","If the creature takes damage or is shaken as an action, this effect ends immediately. When the creature recovers from this effect they remember everything they witnessed."]],"h":[["p","At Higher Levels. When casting this spell at 3rd level or higher, you can target one additional creature for each slot level above 2nd."]],"con":1},{"k":"sp-wyrmsbreath","n":"Wyrm’s Breath","l":2,"s":"Transmutation","sa":"TRA","c":[],"bk":"retia","p":599,"ct":"1 bonus action","rg":"Touch","cp":"V, S, M (a hot pepper)","d":"Concentration, up to 1 minute","b":[["p","You touch one willing creature and imbue it with the power to spew magical energy from its mouth, provided it has one. Choose acid, cold, fire, lightning, or poison. Until the spell ends, the creature can use an action to exhale energy of the chosen type in a 15-foot cone. Each creature in that area must make a Dexterity saving throw, taking 3d6 damage of the chosen type on a failed save, or half as much damage on a successful one."]],"h":[["p","At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you can choose one of the following effects for each slot level above 2nd:"],["li","The damage increases by 1d6."],["li","The cone’s length increases by 10 feet."],["li","(2 slot levels) the target may use the breath weapon as an action or bonus action, but only once each turn."],["li","The creature granted this breath weapon also becomes resistant to the breath weapon’s damage type."]],"con":1,"leg":1},{"k":"sp-yokaipossession","n":"Yokai Possession","l":9,"s":"Enchantment","sa":"ENC","c":[],"bk":"retia","p":600,"ct":"1 action","rg":"60 feet","cp":"V, S","d":"Concentration, up to 1 hour","b":[["p","You conjure a yokai spirit by trapping traumatic emotional energies within a magical shell (which exists only as an extension of the spell you’re casting) and try to bind it to the body of a target within range. The target must succeed on a Charisma saving throw or be charmed for the duration. If the creature has a lower Charisma score than half of your spell save DC (rounded down) they fail their save automatically."],["p","When charmed like this the creature gains temporary hit points equal to your spell save DC multiplied by 5, and you may choose to immediately expend another spell slot of 8th level or lower, giving the target 1d12 temporary hit points for each level of the spell. All of these temporary hit points disappear when the spell ends."],["p","While the target is charmed this way, their mind is suppressed and the yokai spirit takes control of their body. The creature will follow your orders explicitly, and you can issue commands to them telepathically. The creature’s statistics change in the following way while charmed:"],["li","The creature’s alignment becomes yours."],["li","The creature becomes immune to any charm effect except this one."],["li","The creature gains a natural weapon attack which they can make twice each round as an action. This melee weapon attack uses your spell attack modifier, and deals magical piercing or slashing damage equal to your spellcasting ability modifier plus 1d6 for every size category they are above Small."],["li","The creature’s AC becomes equal to your spell save DC unless it was already higher."],["li","The creature cannot regain hit points (or temporary hit points)."],["li","Their creature type becomes fiend (yokai) in addition to their usual type."],["li","The creature can cast any spells it knows, but uses your spell slots to do so."],["li","The creature gains one of the following movement types, which you choose when you cast the spell, with a speed equal to their base movement speed: flying, swimming,"],["p","or climbing. Their anatomy changes to accommodate the change for the duration of the spell."],["p","Once the temporary hit points granted by this spell are reduced to 0 and the creature still has 1 hit point remaining, the target begins making a Charisma saving throw with advantage at the end of each of their turns and each time they take damage. On a successful save the spell ends, and the yokai spirit within them is destroyed. Otherwise, the spell does not end until its duration elapses even if the creature is reduced to 0 hit points. If a creature succeeds their initial or ongoing save against this effect, they become immune to charm effects from its caster for 24 hours."],["p","This spell cannot target undead, fiends, celestials, or constructs. If dispel evil and good or banishment are cast on the target creature, the spell ends immediately and the creature is treated as having failed their saving throw against the effect."]],"con":1,"g":["Daemoturgy"]},{"k":"sp-zoneofimprisonment","n":"Zone of Imprisonment","l":5,"s":"Abjuration","sa":"ABJ","c":[],"bk":"retia","p":600,"ct":"1 action","rg":"Self (20-foot radius)","cp":"V, S, M (a foot of chain links with draconic arcane symbols for “prisoner” and “captive” burned into them)","d":"Concentration, up to 1 hour","b":[["p","You create several layers of arcane energy that spread around you, filling a 20-foot radius sphere centered on you with a magical ward. It has the following effects:"],["p","Binding Radius. Any creature that enters this space for the first time on their turn or begins their turn within it must make a Strength saving throw. On a failed save they are bound by chains crackling with arcane power that burst forth from the ground (or the air around you) and bind the target in place. Such a creature is restrained and can attempt a Strength check against your spell save DC as an action, breaking free on a success. If the bound creature makes the saving throw outside the radius of your ward or is a Huge or larger creature they have advantage on their check to break free."],["p","Protective Chains. When you are targeted by an attack you can see, you can use your reaction to manifest protective wards and chains to block the attack, adding your spellcasting ability modifier to your armor class until the end of that turn. If this causes a weapon attack from a weapon within the sphere’s radius to miss, that weapon is bound in place, making it unusable until the end of the turn."],["p","Grappling Chains. You can use your bonus action to project this spell’s chains toward a creature you can see within 100 feet as a ranged spell attack. If they hit, that creature is restrained as though by the Binding Radius effect and you may pull them up to 50 feet in a straight line toward you."],["p","Move Creature. You may use your bonus action to move any creatures restrained by this spell’s effects up to 25 feet each in any direction you wish, including into the air. If raised off the ground they are suspended in place."]],"con":1,"g":["Chromatic Convocation"]}]};
